-- ===== Decal: cắt vuông + zoom vào chi tiết chính =====
-- Library.DecalZoom  : >= 1, càng lớn càng zoom sát chi tiết chính
-- Library.DecalFocus : điểm tâm cần zoom (0..1, 0.5/0.5 = giữa ảnh)
Library.DecalZoom = 1.3
Library.DecalFocus = Vector2.new(0.5, 0.5)

function Library:ApplyDecal(ImageGui: any, Icon: any, Zoom: number?, Focus: Vector2?): boolean
    if not ImageGui or not Icon or not Icon.Url then
        return false
    end

    -- icon lucide (có RectSize) giữ nguyên, chỉ xử lý ảnh/decal thường
    if Icon.ImageRectSize and Icon.ImageRectSize ~= Vector2.zero then
        return false
    end

    Zoom = math.max(Zoom or Library.DecalZoom or 1, 1)
    Focus = Focus or Library.DecalFocus or Vector2.new(0.5, 0.5)

    local PosX = math.clamp(0.5 - Focus.X * Zoom, 1 - Zoom, 0)
    local PosY = math.clamp(0.5 - Focus.Y * Zoom, 1 - Zoom, 0)

    ImageGui.Image = ""
    ImageGui.BackgroundTransparency = 1
    ImageGui.ClipsDescendants = true

    if not ImageGui:FindFirstChildOfClass("UICorner") then
        New("UICorner", {
            CornerRadius = UDim.new(0, 8),
            Parent = ImageGui,
        })
    end

    local Inner = ImageGui:FindFirstChild("DecalInner")
    if not Inner then
        Inner = New("ImageLabel", {
            Name = "DecalInner",
            BackgroundTransparency = 1,
            ImageColor3 = Color3.new(1, 1, 1),
            ScaleType = Enum.ScaleType.Crop, -- cắt vuông từ giữa ảnh ngang
            ZIndex = ImageGui.ZIndex,
            Parent = ImageGui,
        })
    end

    Inner.Image = Icon.Url
    Inner.Size = UDim2.fromScale(Zoom, Zoom)
    Inner.Position = UDim2.fromScale(PosX, PosY)
    return true
end

