			local function spamNetOwner(part, cf, times)
				local setNet = getSetNet()
				if not setNet or not part then
					return
				end
				local cf2 = cf or part.CFrame
				for _ = 1, (times or 6) do
					pcall(function()
						setNet:FireServer(part, cf2)
					end)
				end
			end
			local function breakFollowWelds(pcld, root)
				pcall(function()
					for _, w in ipairs(pcld:GetDescendants()) do
						if w:IsA("WeldConstraint") or w:IsA("Weld") or w:IsA("Motor6D") then
							local a, b = w.Part0, w.Part1
							if a == root or b == root then
								w:Destroy()
							end
						end
					end
					if root then
						for _, w in ipairs(root:GetChildren()) do
							if (w:IsA("WeldConstraint") or w:IsA("Weld")) and (w.Part0 == pcld or w.Part1 == pcld) then
								w:Destroy()
							end
						end
					end
				end)
			end
