					on = true
				else
					pcall(function()
						if tbl12.WaitForRuntimeToggle("LockPCLD") then
							on = true
						end
					end)
				end
				if not on then
					if wasOn then
						wasOn = false
						lockCf = nil
						local pcld = getPcld(localPlayer.Character)
						if pcld then
							pcall(function()
								pcld.Anchored = false
								local bp = pcld:FindFirstChild("BEO_LockPCLD_BP")
								if bp then
									bp:Destroy()
								end
							end)
						end
					end
					task.wait(0.2)
				else
					wasOn = true
					local char = localPlayer.Character
					if char then
						local hum = char:FindFirstChildOfClass("Humanoid")
						local root = char:FindFirstChild("HumanoidRootPart")
						if hum then
							pcall(function()
								hum:SetAttribute("BrokenPCLD", true)
							end)
						end
						local pcld = getPcld(char)
						if pcld and pcld:IsA("BasePart") then
							if not lockCf then
								if root then
									lockCf = root.CFrame * CFrame.new(0, -3, 0)
								else
									lockCf = pcld.CFrame
								end
								if fn18 then
									fn18("PCLD lock + spam NetOwner", "PCLD")
								end
							end
							breakFollowWelds(pcld, root)
							pcall(function()
								pcld.Anchored = true
								pcld.CFrame = lockCf
								pcld.AssemblyLinearVelocity = Vector3.zero
								pcld.AssemblyAngularVelocity = Vector3.zero
							end)
							spamNetOwner(pcld, lockCf, 8)
							pcall(function()
								local bp = pcld:FindFirstChild("BEO_LockPCLD_BP")
								if not bp then
									bp = Instance.new("BodyPosition")
									bp.Name = "BEO_LockPCLD_BP"
									bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
									bp.P = 1e6
									bp.D = 1500
									bp.Parent = pcld
								end
								bp.Position = lockCf.Position
							end)
							for _ = 1, 3 do
								RunService.Heartbeat:Wait()
								local still = tbl8.LockPCLD
								if not still then
									break
								end
								if pcld and pcld.Parent then
									pcall(function()
										pcld.CFrame = lockCf
										pcld.Anchored = true
									end)
									spamNetOwner(pcld, lockCf, 4)
								end
							end
						else
							task.wait(0.05)
						end
					else
						task.wait(0.05)
					end
				end
			end
		end)

