		-- ===== Anti Toy Lag: FPS tụt đột ngột -> xóa toys của người khác (toys của mình giữ nguyên) =====
		do
			local startedAt = os.clock()
			local lastTrigger = 0
			local wiping = false

			local function wipeOthersToys()
				local myFolderName = localPlayer.Name .. "SpawnedInToys"
				local removed = 0

				for _, folder in ipairs(workspace:GetChildren()) do
					-- chỉ đụng vào folder toys của người khác, bỏ qua folder của mình
					if folder.Name ~= myFolderName and string.find(folder.Name, "SpawnedInToys$") then
						for _, toy in ipairs(folder:GetChildren()) do
							if pcall(toy.Destroy, toy) then
								removed += 1
							end
						end
					end
				end

				return removed
			end

			RunService.Heartbeat:Connect(function(deltaTime)
				if flag11 or wiping or not tbl8.AntiToyLag or os.clock() - startedAt < 2.5 then
					return
				end
				if deltaTime <= 0 or 1 / deltaTime > (tbl9.AntiToyLagFPS or 5) then
					return
				end
				if os.clock() - lastTrigger < 4 then
					return
				end

				lastTrigger = os.clock()
				wiping = true

				task.spawn(function()
					local removed = wipeOthersToys()
					fn18(string.format("Anti Toy Lag || FPS dropped, removed %d toys of other players", removed), "Anti Toy Lag")

					-- quét lại thêm vài giây để dọn toys mới spawn trong lúc đang lag
					for _ = 1, 12 do
						task.wait(0.25)
						if flag11 or not tbl8.AntiToyLag then
