		-- ===== Black Hole Model: 1. Big Black Hole (neon parts + trails + sound) =====
		do
			local TweenService = game:GetService("TweenService")

			local BIG = {
				SoundId = "rbxassetid://72594294649022", -- ~5s
				Duration = 5,
				RiseTime = 1.3,
				FallTime = 1.5,
				RiseHeight = 0, -- 0 = tâm đứng yên đúng tại hố đen server (player nằm ở giữa). Tăng lên nếu muốn bay cao
				CoreRadius = 9,
				DiskInner = 13,
				DiskOuter = 46,
				Orbiters = 40,
				CoreTransparency = 0.8, -- lõi hơi trong suốt để vẫn thấy player ở giữa (0 = đen đặc)
			}

			local function easeOutQuad(u) return 1 - (1 - u) * (1 - u) end
			local function easeInQuad(u) return u * u end
			local function easeInCubic(u) return u * u * u end
			local function easeOutBack(u)
				local c1, c3 = 1.70158, 2.70158
				return 1 + c3 * (u - 1) ^ 3 + c1 * (u - 1) ^ 2
			end

			local function mk(parent, props)
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanTouch = false
				p.CanQuery = false
				p.CastShadow = false
				p.Massless = true
				p.TopSurface = Enum.SurfaceType.Smooth
				p.BottomSurface = Enum.SurfaceType.Smooth
				for k, v in pairs(props) do
					p[k] = v
				end
				p.Parent = parent
				return p
			end

			local function seq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = NumberSequenceKeypoint.new(k[1], k[2])
				end
				return NumberSequence.new(kps)
			end

			local function cseq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = ColorSequenceKeypoint.new(k[1], k[2])
				end
				return ColorSequence.new(kps)
			end

			-- vòng bằng các segment neon, nằm trong mặt phẳng XZ rồi xoay theo orient
			local function ring(model, name, radius, segs, thick, color, transparency, orient)
				local arc = (2 * math.pi * radius / segs) * 1.12
				for i = 1, segs do
					local a = (i / segs) * math.pi * 2
					local pos = Vector3.new(math.cos(a) * radius, 0, math.sin(a) * radius)
					local tan = Vector3.new(-math.sin(a), 0, math.cos(a))
					local cf = orient * CFrame.lookAt(pos, pos + tan)
					mk(model, {
						Name = name,
						Size = Vector3.new(thick, thick, arc),
						Color = color,
						Material = Enum.Material.Neon,
						Transparency = transparency,
						CFrame = cf,
					})
				end
			end

			local function buildStatic()
				local m = Instance.new("Model")
				m.Name = "NT_BigBlackHole"
				local R = BIG.CoreRadius
				local flat = CFrame.Angles(0, 0, math.pi / 2)

				-- event horizon
				local core = mk(m, {
					Name = "Core",
					Shape = Enum.PartType.Ball,
					Size = Vector3.one * R * 2,
					Color = Color3.new(0, 0, 0),
					Material = Enum.Material.SmoothPlastic,
					Transparency = BIG.CoreTransparency,
					CFrame = CFrame.new(),
				})
				m.PrimaryPart = core

				-- glow shells
				mk(m, { Name = "Glow1", Shape = Enum.PartType.Ball, Size = Vector3.one * R * 2.25, Color = Color3.fromRGB(255, 120, 30), Material = Enum.Material.Neon, Transparency = 0.82, CFrame = CFrame.new() })
				mk(m, { Name = "Glow2", Shape = Enum.PartType.Ball, Size = Vector3.one * R * 3.3, Color = Color3.fromRGB(150, 60, 255), Material = Enum.Material.Neon, Transparency = 0.93, CFrame = CFrame.new() })

				-- accretion disk: các đĩa neon xếp chồng, phần giữa bị lõi đen che => thành vòng
				local bands = {
					{ BIG.DiskOuter, Color3.fromRGB(150, 35, 20), 0.82 },
					{ BIG.DiskOuter * 0.82, Color3.fromRGB(235, 75, 25), 0.65 },
					{ BIG.DiskOuter * 0.62, Color3.fromRGB(255, 140, 40), 0.45 },
					{ BIG.DiskOuter * 0.44, Color3.fromRGB(255, 205, 110), 0.28 },
					{ BIG.DiskInner * 1.12, Color3.fromRGB(255, 248, 230), 0.1 },
				}
				for i, b in ipairs(bands) do
					mk(m, {
						Name = "Disk" .. i,
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(0.25, b[1] * 2, b[1] * 2),
						Color = b[2],
						Material = Enum.Material.Neon,
						Transparency = b[3],
						CFrame = CFrame.new(0, (i - 1) * 0.06, 0) * flat,
					})
				end

				-- photon ring + 2 vòng lensing dọc
				ring(m, "PhotonRing", R * 1.1, 40, 0.45, Color3.fromRGB(255, 245, 230), 0.05, CFrame.new())
				ring(m, "LensA", R * 1.5, 40, 0.7, Color3.fromRGB(255, 170, 60), 0.25, CFrame.Angles(math.pi / 2, 0, 0))
				ring(m, "LensB", R * 1.9, 44, 0.5, Color3.fromRGB(200, 120, 255), 0.4, CFrame.Angles(0, 0, math.pi / 2))

				-- polar jets
				local up = CFrame.Angles(0, 0, math.pi / 2)
				mk(m, { Name = "JetTop", Shape = Enum.PartType.Cylinder, Size = Vector3.new(80, 3.2, 3.2), Color = Color3.fromRGB(140, 110, 255), Material = Enum.Material.Neon, Transparency = 0.6, CFrame = CFrame.new(0, R + 40, 0) * up })
				mk(m, { Name = "JetBottom", Shape = Enum.PartType.Cylinder, Size = Vector3.new(80, 3.2, 3.2), Color = Color3.fromRGB(140, 110, 255), Material = Enum.Material.Neon, Transparency = 0.6, CFrame = CFrame.new(0, -(R + 40), 0) * up })
				mk(m, { Name = "JetTopCore", Shape = Enum.PartType.Cylinder, Size = Vector3.new(80, 1.2, 1.2), Color = Color3.fromRGB(230, 220, 255), Material = Enum.Material.Neon, Transparency = 0.3, CFrame = CFrame.new(0, R + 40, 0) * up })
				mk(m, { Name = "JetBottomCore", Shape = Enum.PartType.Cylinder, Size = Vector3.new(80, 1.2, 1.2), Color = Color3.fromRGB(230, 220, 255), Material = Enum.Material.Neon, Transparency = 0.3, CFrame = CFrame.new(0, -(R + 40), 0) * up })

				-- tia lửa bị hút vào hố đen
				local sucker = mk(m, { Name = "Sucker", Shape = Enum.PartType.Ball, Size = Vector3.one * R * 7, Transparency = 1, CFrame = CFrame.new() })
				local pe = Instance.new("ParticleEmitter")
				pe.Shape = Enum.ParticleEmitterShape.Sphere
				pe.ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface
				pe.ShapeInOut = Enum.ParticleEmitterShapeInOut.Inward
				pe.Rate = 90
				pe.Lifetime = NumberRange.new(1.2, 1.8)
				pe.Speed = NumberRange.new(14, 22)
				pe.Size = seq({ 0, 2.2 }, { 1, 0 })
				pe.Transparency = seq({ 0, 1 }, { 0.15, 0.2 }, { 1, 1 })
				pe.Color = cseq({ 0, Color3.fromRGB(255, 200, 120) }, { 0.5, Color3.fromRGB(255, 90, 40) }, { 1, Color3.fromRGB(150, 60, 255) })
				pe.LightEmission = 1
				pe.LightInfluence = 0
				pe.Rotation = NumberRange.new(0, 360)
				pe.RotSpeed = NumberRange.new(-120, 120)
				pe.Parent = sucker

				local light = Instance.new("PointLight")
				light.Color = Color3.fromRGB(255, 140, 60)
				light.Brightness = 4
				light.Range = 60
				light.Parent = core

				return m
			end

			local function buildOrbiters()
				local m = Instance.new("Model")
				m.Name = "NT_BigBlackHoleOrbiters"
				local list = {}
				local rng = Random.new()
				local palette = {
					Color3.fromRGB(255, 235, 200),
					Color3.fromRGB(255, 170, 70),
					Color3.fromRGB(255, 110, 40),
					Color3.fromRGB(190, 110, 255),
					Color3.fromRGB(120, 170, 255),
				}
				local inner = BIG.DiskInner * 1.05

				for i = 1, BIG.Orbiters do
					local r = inner + (BIG.DiskOuter - inner) * (rng:NextNumber() ^ 1.4)
					local size = 0.9 + rng:NextNumber() * 1.1
					local col = palette[rng:NextInteger(1, #palette)]
					local p = mk(m, { Name = "Orb", Shape = Enum.PartType.Ball, Size = Vector3.one * size, Color = col, Material = Enum.Material.Neon })

					local function attach(y)
						local a = Instance.new("Attachment")
						a.Position = Vector3.new(0, y, 0)
						a.Parent = p
						return a
					end

					local tr = Instance.new("Trail")
					tr.Attachment0 = attach(size * 0.9)
					tr.Attachment1 = attach(-size * 0.9)
					tr.Lifetime = 0.55 + rng:NextNumber() * 0.5
					tr.MinLength = 0.05
					tr.FaceCamera = true
					tr.LightEmission = 1
					tr.LightInfluence = 0
					tr.Color = cseq({ 0, col }, { 0.35, Color3.fromRGB(255, 120, 40) }, { 0.7, Color3.fromRGB(190, 60, 200) }, { 1, Color3.fromRGB(40, 10, 90) })
					tr.Transparency = seq({ 0, 0.05 }, { 0.6, 0.5 }, { 1, 1 })
					tr.WidthScale = seq({ 0, 1 }, { 1, 0 })
					tr.Parent = p

					if i % 3 == 0 then
						local gl = Instance.new("Trail")
						gl.Attachment0 = attach(size * 2.6)
						gl.Attachment1 = attach(-size * 2.6)
						gl.Lifetime = tr.Lifetime * 1.4
						gl.MinLength = 0.05
						gl.FaceCamera = true
						gl.LightEmission = 1
						gl.LightInfluence = 0
						gl.Color = cseq({ 0, Color3.fromRGB(255, 160, 70) }, { 0.5, Color3.fromRGB(220, 70, 180) }, { 1, Color3.fromRGB(60, 20, 140) })
						gl.Transparency = seq({ 0, 0.6 }, { 1, 1 })
						gl.WidthScale = seq({ 0, 1 }, { 1, 0.2 })
						gl.Parent = p
					end

					list[i] = {
						part = p,
						r = r,
						a = rng:NextNumber() * math.pi * 2,
						w = (136 / r ^ 1.5) * (0.9 + rng:NextNumber() * 0.2), -- Kepler
						ph = rng:NextNumber() * math.pi * 2,
					}
				end

				return m, list
			end

			local function shock(position, color, maxDiameter, time)
				local p = mk(workspace, {
					Name = "NT_BigBHShock",
					Shape = Enum.PartType.Cylinder,
					Size = Vector3.new(0.4, 4, 4),
					Color = color,
					Material = Enum.Material.Neon,
					Transparency = 0.2,
					CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.pi / 2),
				})
				TweenService:Create(p, TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Size = Vector3.new(0.4, maxDiameter, maxDiameter),
					Transparency = 1,
				}):Play()
				task.delay(time + 0.2, function()
					p:Destroy()
				end)
			end

			-- ẩn hố đen gốc + tắt âm thanh gốc khi dùng model
			tbl12.HideOriginalBlackHole = function(child, hole, billboardGui)
				hole.Transparency = 1
				billboardGui.Enabled = false

				for _, d in ipairs(child:GetDescendants()) do
					if d:IsA("Sound") then
						d.Volume = 0
						pcall(d.Stop, d)
					end
				end
			end

			tbl12.PlayBigBlackHole = function(hole)
				if not hole or not hole:IsA("BasePart") then
					return
				end

				-- tâm = vị trí hố đen của server, không dính theo player
				local origin = hole.Position
				local pos = origin
				local groundOffset = Vector3.new(0, BIG.RiseHeight == 0 and 3 or 0, 0)
				local static = buildStatic()
				local orb, list = buildOrbiters()
				static.Parent = workspace
				orb.Parent = workspace

				local snd = Instance.new("Sound")
				snd.SoundId = BIG.SoundId
				snd.Volume = 3
				snd.RollOffMode = Enum.RollOffMode.InverseTapered
				snd.RollOffMinDistance = 60
				snd.RollOffMaxDistance = 700
				snd.Parent = static.PrimaryPart
				snd:Play()

				shock(origin - groundOffset, Color3.fromRGB(255, 150, 60), 90, 0.9)

				local fallStart = BIG.Duration - BIG.FallTime
				local tt, clk, spin = 0, 0, 0
				local falling = false
				local lastScale = -1
				local conn

				local function finish(abort)
					if conn then
						conn:Disconnect()
						conn = nil
					end
					static:Destroy()
					orb:Destroy()
					if not abort then
						shock(pos - groundOffset, Color3.fromRGB(220, 190, 255), 140, 0.8)
					end
				end

				conn = RunService.RenderStepped:Connect(function(dt)
					if flag11 then
						finish(true)
						return
					end

					if hole.Parent then
						pos = hole.Position
					end

					tt += dt
					clk += dt

					-- Blackhole Staying: giữ ở trên cao cho tới khi tắt
					if not falling and tt > fallStart then
						if tbl8.BlackholeStaying then
							tt = fallStart
						else
							falling = true
						end
					end

					if tt >= BIG.Duration then
						finish(false)
						return
					end

					local h, s, k = 0, 1, 0
					if tt < BIG.RiseTime then
						local u = tt / BIG.RiseTime
						h = BIG.RiseHeight * easeOutQuad(u)
						s = 0.05 + 0.95 * easeOutBack(u)
					elseif tt <= fallStart then
						h = BIG.RiseHeight + (BIG.RiseHeight > 0 and math.sin(clk * 2.2) * 1.8 or 0)
					else
						local u = (tt - fallStart) / BIG.FallTime
						h = BIG.RiseHeight * (1 - easeInQuad(u))
						s = 1 - 0.95 * easeInCubic(u)
						k = u * u
					end

					local sc = math.max(s * (1 + 0.025 * math.sin(clk * 7)), 0.03)
					if sc ~= lastScale then
						lastScale = sc
						pcall(function()
							static:ScaleTo(sc)
							orb:ScaleTo(sc)
						end)
					end

					spin += dt * 0.35
					local base = CFrame.new(pos + Vector3.new(0, h, 0)) * CFrame.Angles(math.rad(16), 0, math.rad(9))
					static:PivotTo(base * CFrame.Angles(0, spin, 0))

					for _, o in ipairs(list) do
						o.a += o.w * dt * (1 + k * 2.5)
						local rr = o.r * (1 - 0.55 * k)
						local lp = Vector3.new(math.cos(o.a) * rr, math.sin(o.a * 3 + o.ph) * rr * 0.035, math.sin(o.a) * rr) * sc
						o.part.CFrame = CFrame.new(base * lp)
					end
				end)
			end
		end

		-- ===== Black Hole Model: 2. Ban Hammer v2 (titan chui đất / lao từ trời, búa trắng đen neon + trail, chữ BAN 3D neon đỏ) =====
		do
			local PlayersSvc = game:GetService("Players")
			local TweenService = game:GetService("TweenService")
			local LightingSvc = game:GetService("Lighting")

			local BAN = {
				SoundId = "rbxassetid://133057229986188", -- ~4s
				SpawnSoundId = "rbxassetid://134263165995764", -- âm thanh lúc spawn
				Scale = 14, -- titan: to gấp bao nhiêu lần avatar thường
				StartDistance = 240, -- đứng xa bao nhiêu studs
				RunSpeed = 130,
				-- chui đất (hố đen ở dưới đất)
				RumbleTime = 1.0, -- đất rung + nứt
				RiseTime = 1.8, -- trồi lên
				RoarTime = 0.9, -- gầm
				-- lao từ trời (hố đen ở trên cao)
				PortalTime = 0.5,
				DiveTime = 1.3,
				LandTime = 0.8,
				SkyHeight = 480,
				SkyThreshold = 40, -- hố đen cao hơn mặt đất bao nhiêu studs thì coi là "trên cao"
				-- đòn đánh
				WindupTime = 1.0,
				SmashTime = 0.26,
				HoldTime = 1.3, -- đứng yên sau cú đập rồi mới tan rã
				DisFade = 1.0, -- mỗi bộ phận tan trong bao lâu
				DisSpread = 1.3, -- các bộ phận bắt đầu tan lệch nhau tối đa bao lâu
				TotalAfterImpact = 4.0, -- khớp độ dài âm thanh
				HandleLength = 5,
				TextLife = 2.7,
			}

			local RED = Color3.fromRGB(255, 25, 25)
			local WHITE = Color3.fromRGB(255, 255, 255)
			local BLACK = Color3.fromRGB(14, 14, 16)
			local DARK = Color3.fromRGB(38, 38, 44)

			local TEX_SMOKE = "rbxasset://textures/particles/smoke_main.dds"
			local TEX_SPARK = "rbxasset://textures/particles/sparkles_main.dds"
			local TEX_FIRE = "rbxasset://textures/particles/fire_main.dds"

			local function clamp(x, a, b) return math.max(a, math.min(b, x)) end
			local function lerp(a, b, u) return a + (b - a) * u end
			local function easeOutQuad(u) return 1 - (1 - u) * (1 - u) end
			local function easeInQuad(u) return u * u end
			local function easeOutCubic(u) return 1 - (1 - u) ^ 3 end
			local function easeOutBack(u)
				local c1 = 1.70158
				local c3 = c1 + 1
				return 1 + c3 * (u - 1) ^ 3 + c1 * (u - 1) ^ 2
			end
			local function smooth(u) return u * u * (3 - 2 * u) end
			local function rnd(a, b) return a + math.random() * (b - a) end

			local S = BAN.Scale
			local FX = S * 0.35 -- hệ số phóng to hiệu ứng
			local SK = math.sqrt(FX)

			local function seq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = NumberSequenceKeypoint.new(k[1], k[2])
				end
				return NumberSequence.new(kps)
			end

			local function cseq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = ColorSequenceKeypoint.new(k[1], k[2])
				end
				return ColorSequence.new(kps)
			end

			local function mkPart(parent, name, size, color, material)
				local p = Instance.new("Part")
				p.Name = name
				p.Size = size
				p.Color = color
				p.Material = material or Enum.Material.SmoothPlastic
				p.Anchored = false
				p.CanCollide = false
				p.CanTouch = false
				p.CanQuery = false
				p.CastShadow = false
				p.Massless = true
				p.TopSurface = Enum.SurfaceType.Smooth
				p.BottomSurface = Enum.SurfaceType.Smooth
				p.Parent = parent
				return p
			end

			local function weld(p0, p1, c0)
				local w = Instance.new("Weld")
				w.Part0 = p0
				w.Part1 = p1
				w.C0 = c0
				w.Parent = p0
				return w
			end

			-- part hiệu ứng đứng yên (anchored)
			local function fxPart(name, size, color, material, transparency, cf, shape, parent)
				local p = Instance.new("Part")
				p.Name = name
				p.Anchored = true
				p.CanCollide = false
				p.CanTouch = false
				p.CanQuery = false
				p.CastShadow = false
				if shape then
					p.Shape = shape
				end
				p.Size = size
				p.Color = color
				p.Material = material or Enum.Material.Neon
				p.Transparency = transparency or 0
				p.CFrame = cf
				p.Parent = parent or workspace
				return p
			end

			local function track(bag, o)
				if bag then
					bag[#bag + 1] = o
				end
				return o
			end

			-- thanh nối 2 điểm (block hoặc cylinder)
			local function segPart(parent, a, b, thick, color, mat, transp, cyl)
				local dir = b - a
				local d = dir.Magnitude
				if d < 0.01 then
					d = 0.01
					dir = Vector3.new(0, 0, 1)
				end
				local up = Vector3.yAxis
				if math.abs(dir.Unit.Y) > 0.98 then
					up = Vector3.xAxis
				end
				local cf = CFrame.lookAt((a + b) / 2, (a + b) / 2 + dir.Unit, up)
				local p
				if cyl then
					p = fxPart("NT_Seg", Vector3.new(d, thick, thick), color, mat, transp, cf * CFrame.Angles(0, math.pi / 2, 0), Enum.PartType.Cylinder, parent)
				else
					p = fxPart("NT_Seg", Vector3.new(thick, thick, d), color, mat, transp, cf, nil, parent)
				end
				return p
			end

			local function mkEmitter(parent, o)
				local pe = Instance.new("ParticleEmitter")
				pe.Texture = o.tex or TEX_SMOKE
				pe.Rate = o.rate or 0
				pe.Lifetime = o.life or NumberRange.new(1, 1.5)
				pe.Speed = o.speed or NumberRange.new(5, 10)
				pe.SpreadAngle = o.spread or Vector2.new(180, 180)
				pe.Size = o.size or seq({ 0, 1 }, { 1, 2 })
				pe.Transparency = o.transp or seq({ 0, 0.3 }, { 1, 1 })
				pe.Color = o.color or ColorSequence.new(WHITE)
				pe.LightEmission = o.emit or 0
				pe.LightInfluence = o.light or 0
				pe.Acceleration = o.accel or Vector3.zero
				pe.Rotation = o.rot or NumberRange.new(0, 360)
				pe.RotSpeed = o.rotSpeed or NumberRange.new(-90, 90)
				pe.Drag = o.drag or 0
				if o.shape then
					pcall(function()
						pe.Shape = o.shape
						pe.ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface
						pe.ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward
					end)
				end
				pe.Parent = parent
				return pe
			end

			local function smokeEmitter(parent)
				return mkEmitter(parent, {
					life = NumberRange.new(0.8, 1.4),
					speed = NumberRange.new(2 * SK, 7 * SK),
					size = seq({ 0, 1.2 * FX }, { 1, 3.2 * FX }),
					transp = seq({ 0, 0.4 }, { 1, 1 }),
					color = cseq({ 0, Color3.fromRGB(150, 150, 155) }, { 1, Color3.fromRGB(40, 40, 45) }),
					accel = Vector3.new(0, 5, 0),
					light = 0.5,
				})
			end

			-- bộ khói / tia lửa / than hồng cho 1 điểm nổ
			local function burstSet(parent)
				local set = {}
				set.smoke = mkEmitter(parent, {
					life = NumberRange.new(1.4, 2.4),
					speed = NumberRange.new(12 * SK, 26 * SK),
					spread = Vector2.new(75, 75),
					size = seq({ 0, 3 * FX }, { 0.4, 9 * FX }, { 1, 14 * FX }),
					transp = seq({ 0, 0.35 }, { 0.6, 0.6 }, { 1, 1 }),
					color = cseq({ 0, Color3.fromRGB(175, 172, 168) }, { 1, Color3.fromRGB(35, 35, 38) }),
					drag = 4,
					light = 0.5,
				})
				set.linger = mkEmitter(parent, {
					life = NumberRange.new(1.2, 2),
					speed = NumberRange.new(4 * SK, 9 * SK),
					spread = Vector2.new(60, 60),
					size = seq({ 0, 4 * FX }, { 1, 11 * FX }),
					transp = seq({ 0, 0.5 }, { 1, 1 }),
					color = cseq({ 0, Color3.fromRGB(120, 120, 124) }, { 1, Color3.fromRGB(30, 30, 33) }),
					accel = Vector3.new(0, 5, 0),
					light = 0.5,
				})
				set.sparks = mkEmitter(parent, {
					tex = TEX_SPARK,
					life = NumberRange.new(0.6, 1.2),
					speed = NumberRange.new(30 * SK, 70 * SK),
					spread = Vector2.new(70, 70),
					size = seq({ 0, 1.4 * FX }, { 1, 0 }),
					transp = seq({ 0, 0 }, { 1, 1 }),
					color = cseq({ 0, WHITE }, { 0.4, Color3.fromRGB(255, 120, 110) }, { 1, RED }),
					emit = 1,
					accel = Vector3.new(0, -45 * SK, 0),
					drag = 0.6,
				})
				set.embers = mkEmitter(parent, {
					tex = TEX_FIRE,
					life = NumberRange.new(1.5, 3),
					speed = NumberRange.new(8 * SK, 24 * SK),
					spread = Vector2.new(85, 85),
					size = seq({ 0, 0.9 * FX }, { 0.5, 0.7 * FX }, { 1, 0 }),
					transp = seq({ 0, 0.1 }, { 0.8, 0.4 }, { 1, 1 }),
					color = cseq({ 0, Color3.fromRGB(255, 160, 150) }, { 1, RED }),
					emit = 1,
					accel = Vector3.new(0, 10 * SK, 0),
					drag = 1.5,
				})
				return set
			end

			-- ===== hiệu ứng world =====
			local function ring(bag, position, color, d0, d1, time, thick, tr0, tr1, style, mat)
				local p = fxPart("NT_BanRing", Vector3.new(thick, d0, d0), color, mat or Enum.Material.Neon, tr0, CFrame.new(position) * CFrame.Angles(0, 0, math.pi / 2), Enum.PartType.Cylinder)
				track(bag, p)
				TweenService:Create(p, TweenInfo.new(time, style or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Size = Vector3.new(thick, d1, d1),
					Transparency = tr1,
				}):Play()
				task.delay(time + 0.2, function()
					p:Destroy()
				end)
				return p
			end

			local function shock(bag, position, color, maxD, time, thick, startD, tr0)
				return ring(bag, position, color, startD or 4, maxD, time, thick or 0.4, tr0 or 0.15, 1)
			end

			local function dome(bag, position, color, maxD, time, tr0)
				local p = fxPart("NT_BanDome", Vector3.new(4, 4, 4), color, Enum.Material.ForceField, tr0 or 0.3, CFrame.new(position), Enum.PartType.Ball)
				track(bag, p)
				TweenService:Create(p, TweenInfo.new(time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
					Size = Vector3.new(maxD, maxD, maxD),
					Transparency = 1,
				}):Play()
				task.delay(time + 0.2, function()
					p:Destroy()
				end)
			end

			local function pillar(bag, position, color, height, d, time)
				local p = fxPart("NT_BanPillar", Vector3.new(height, d, d), color, Enum.Material.Neon, 0.2, CFrame.new(position + Vector3.new(0, height / 2, 0)) * CFrame.Angles(0, 0, math.pi / 2), Enum.PartType.Cylinder)
				track(bag, p)
				TweenService:Create(p, TweenInfo.new(time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Size = Vector3.new(height, d * 0.06, d * 0.06),
					Transparency = 1,
				}):Play()
				task.delay(time + 0.2, function()
					p:Destroy()
				end)
			end

			local function bolt(bag, origin, dir, length, segs, thick, color, life)
				local side = dir:Cross(Vector3.yAxis)
				if side.Magnitude < 0.1 then
					side = Vector3.xAxis
				end
				side = side.Unit
				local up2 = side:Cross(dir).Unit
				local pts = { origin }
				for i = 1, segs do
					local base = origin + dir * (length * i / segs)
					local j = length / segs * 0.45
					if i < segs then
						base = base + side * rnd(-j, j) + up2 * rnd(-j, j)
					end
					pts[#pts + 1] = base
				end
				for i = 1, #pts - 1 do
					local core = track(bag, segPart(workspace, pts[i], pts[i + 1], thick, WHITE, Enum.Material.Neon, 0))
					local glow = track(bag, segPart(workspace, pts[i], pts[i + 1], thick * 3.4, color, Enum.Material.Neon, 0.55))
					local info = TweenInfo.new(life, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					TweenService:Create(core, info, { Transparency = 1 }):Play()
					TweenService:Create(glow, info, { Transparency = 1 }):Play()
					task.delay(life + 0.1, function()
						core:Destroy()
						glow:Destroy()
					end)
				end
			end

			-- vết nứt đất phát sáng lan ra từ tâm
			local function spawnCracks(bag, center, floorY, count, length, thick, life)
				for i = 1, count do
					local ang = (i / count) * math.pi * 2 + rnd(-0.25, 0.25)
					local dir = Vector3.new(math.cos(ang), 0, math.sin(ang))
					local side = Vector3.new(-dir.Z, 0, dir.X)
					local len = length * rnd(0.55, 1)
					local steps = 6
					local last = Vector3.new(center.X, floorY + 0.25, center.Z)
					for s = 1, steps do
						local nxt = Vector3.new(center.X, floorY + 0.25, center.Z) + dir * (len * s / steps) + side * rnd(-1, 1) * len * 0.06
						local a, b = last, nxt
						task.delay(s * 0.045, function()
							local scar = track(bag, segPart(workspace, a - Vector3.new(0, 0.1, 0), b - Vector3.new(0, 0.1, 0), thick * 2.6, BLACK, Enum.Material.SmoothPlastic, 0))
							local glow = track(bag, segPart(workspace, a, b, thick, RED, Enum.Material.Neon, 0.05))
							local info = TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
							task.delay(life, function()
								TweenService:Create(glow, info, { Transparency = 1 }):Play()
								TweenService:Create(scar, info, { Transparency = 1 }):Play()
								task.delay(1.2, function()
									glow:Destroy()
									scar:Destroy()
								end)
							end)
						end)
						last = nxt
					end
				end
			end

			local function camShake(duration, mag, center)
				local cam = workspace.CurrentCamera
				if not cam then
					return
				end
				local dist = (cam.CFrame.Position - center).Magnitude
				mag = mag * clamp(1 - dist / 700, 0.15, 1)
				local t0 = os.clock()
				local name = "NT_BanShake" .. tostring(t0) .. tostring(math.random(1, 99999))
				RunService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 1, function()
					local e = os.clock() - t0
					if e >= duration or flag11 then
						RunService:UnbindFromRenderStep(name)
						return
					end
					local k = (1 - e / duration) ^ 2 * mag
					cam.CFrame = cam.CFrame * CFrame.new((math.random() - 0.5) * k, (math.random() - 0.5) * k, 0) * CFrame.Angles(0, 0, (math.random() - 0.5) * k * 0.02)
				end)
			end

			local function fovPunch(amount, duration)
				local cam = workspace.CurrentCamera
				if not cam then
					return
				end
				local base = cam.FieldOfView
				local t0 = os.clock()
				local name = "NT_BanFov" .. tostring(t0) .. tostring(math.random(1, 99999))
				RunService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 2, function()
					local e = os.clock() - t0
					if e >= duration or flag11 then
						cam.FieldOfView = base
						RunService:UnbindFromRenderStep(name)
						return
					end
					cam.FieldOfView = base + amount * (1 - e / duration) ^ 2
				end)
			end

			local function screenFlash(brightness, time)
				pcall(function()
					local cc = Instance.new("ColorCorrectionEffect")
					cc.Name = "NT_BanFlash"
					cc.Brightness = brightness
					cc.Contrast = 0.15
					cc.Parent = LightingSvc
					TweenService:Create(cc, TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Brightness = 0, Contrast = 0 }):Play()
					task.delay(time + 0.1, function()
						cc:Destroy()
					end)
				end)
			end

			local function bloomOn(life)
				pcall(function()
					local b = Instance.new("BloomEffect")
					b.Name = "NT_BanBloom"
					b.Intensity = 0
					b.Size = 34
					b.Threshold = 0.85
					b.Parent = LightingSvc
					TweenService:Create(b, TweenInfo.new(0.15), { Intensity = 1.3 }):Play()
					task.delay(life - 0.7, function()
						TweenService:Create(b, TweenInfo.new(0.7), { Intensity = 0 }):Play()
					end)
					task.delay(life + 0.1, function()
						b:Destroy()
					end)
				end)
			end

			-- ===== chữ BAN 3D neon đỏ (ống neon ghép từ part) =====
			local LETTER_DEFS = (function()
				local function arc(cx, cy, rx, ry, a0, a1, n)
					local pts = {}
					for i = 0, n do
						local a = math.rad(a0 + (a1 - a0) * i / n)
						pts[#pts + 1] = { cx + rx * math.cos(a), cy + ry * math.sin(a) }
					end
					return pts
				end
				local function cat(...)
					local out = {}
					for _, l in ipairs({ ... }) do
						for _, p in ipairs(l) do
							out[#out + 1] = p
						end
					end
					return out
				end
				return {
					B = {
						cat({ { 0, 1.6 } }, arc(0.5, 1.2, 0.42, 0.4, 90, -90, 6), { { 0, 0.8 } }),
						cat({ { 0, 0.8 } }, arc(0.55, 0.4, 0.45, 0.4, 90, -90, 6), { { 0, 0 } }),
						{ { 0, 0 }, { 0, 1.6 } },
					},
					A = {
						{ { 0, 0 }, { 0.5, 1.6 }, { 1, 0 } },
						{ { 0.172, 0.55 }, { 0.828, 0.55 } },
					},
					N = {
						{ { 0, 0 }, { 0, 1.6 }, { 1, 0 }, { 1, 1.6 } },
					},
				}
			end)()

			local function build3DText(bag, center, ts, life)
				local word = { "B", "A", "N" }
				local gap = 0.45
				local totalW = 3 + 2 * gap
				local thick = 0.13 * ts
				local layers = {
					{ k = 1.9, color = BLACK, mat = Enum.Material.SmoothPlastic, z = -0.11 * ts, tr = 0, role = "back" },
					{ k = 2.7, color = RED, mat = Enum.Material.Neon, z = 0, tr = 0.8, role = "glow" },
					{ k = 1.0, color = RED, mat = Enum.Material.Neon, z = 0.035 * ts, tr = 0.25, role = "tube" },
					{ k = 0.4, color = Color3.fromRGB(255, 225, 225), mat = Enum.Material.Neon, z = 0.05 * ts, tr = 0, role = "core" },
				}

				local letters = {}
				for i, ch in ipairs(word) do
					local m = Instance.new("Model")
					m.Name = "NT_BanLetter_" .. ch
					local x0 = -totalW / 2 + (i - 1) * (1 + gap)
					local lc = Vector3.new((x0 + 0.5) * ts, 0, 0)
					local pivot = fxPart("Pivot", Vector3.new(1, 1, 1), WHITE, Enum.Material.SmoothPlastic, 1, CFrame.new(center + lc), nil, m)
					m.PrimaryPart = pivot
					local L = { model = m, pivot = pivot, parts = {}, glowParts = {}, lc = lc, landed = false, scaledFinal = false, last = true }

					local function P(pt, z)
						return center + Vector3.new((x0 + pt[1]) * ts, (pt[2] - 0.8) * ts, z)
					end
					local function reg(p, lay)
						L.parts[#L.parts + 1] = { p = p, base = lay.tr }
						if lay.role ~= "back" then
							L.glowParts[#L.glowParts + 1] = { p = p, base = lay.tr }
						end
					end

					for _, stroke in ipairs(LETTER_DEFS[ch]) do
						for _, lay in ipairs(layers) do
							for j = 1, #stroke - 1 do
								reg(segPart(m, P(stroke[j], lay.z), P(stroke[j + 1], lay.z), thick * lay.k, lay.color, lay.mat, lay.tr, true), lay)
							end
							for j = 1, #stroke do
								reg(fxPart("NT_Joint", Vector3.one * thick * lay.k, lay.color, lay.mat, lay.tr, CFrame.new(P(stroke[j], lay.z)), Enum.PartType.Ball, m), lay)
							end
						end
					end

					L.spark = mkEmitter(pivot, {
						tex = TEX_SPARK,
						life = NumberRange.new(0.5, 1.1),
						speed = NumberRange.new(30 * SK, 70 * SK),
						spread = Vector2.new(180, 180),
						size = seq({ 0, 1.5 * FX }, { 1, 0 }),
						transp = seq({ 0, 0 }, { 1, 1 }),
						color = cseq({ 0, WHITE }, { 1, RED }),
						emit = 1,
						accel = Vector3.new(0, -30 * SK, 0),
					})
					m:PivotTo(CFrame.new(0, 100000, 0))
					m.Parent = workspace
					track(bag, m)
					letters[i] = L
				end

				local light = Instance.new("PointLight")
				light.Color = RED
				light.Range = 60
				light.Brightness = 0
				light.Parent = letters[2].pivot

				local ctl = {}
				local born = os.clock()

				function ctl.update()
					local e = os.clock() - born
					if e >= life then
						return false
					end
					local cam = workspace.CurrentCamera
					local dirv = Vector3.new(0, 0, -1)
					if cam then
						local d = Vector3.new(center.X - cam.CFrame.Position.X, 0, center.Z - cam.CFrame.Position.Z)
						if d.Magnitude > 1 then
							dirv = d.Unit
						end
					end
					local base = CFrame.lookAt(Vector3.zero, dirv) * CFrame.Angles(0, math.sin(e * 1.6) * 0.3, 0)
					local fadeA = clamp((e - (life - 0.8)) / 0.8, 0, 1)

					for i, L in ipairs(letters) do
						local ta = (i - 1) * 0.14
						if e >= ta then
							local k = clamp((e - ta) / 0.3, 0, 1)
							local drop = (1 - easeOutBack(k)) * 2.4 * ts
							local flip = (1 - easeOutCubic(k)) * math.pi * 1.2
							local bob = math.sin(e * 3 + i * 1.3) * 0.05 * ts
							L.model:PivotTo(CFrame.new(center) * base * CFrame.new(L.lc.X, bob + drop, 0) * CFrame.Angles(0, flip, 0))

							if k < 1 then
								pcall(function()
									L.model:ScaleTo(0.35 + 0.65 * k)
								end)
							elseif not L.scaledFinal then
								L.scaledFinal = true
								pcall(function()
									L.model:ScaleTo(1)
								end)
							end

							if k >= 1 and not L.landed then
								L.landed = true
								L.spark:Emit(30)
								camShake(0.3, 1.2 * SK, center)
							end

							if fadeA > 0 then
								for _, r in ipairs(L.parts) do
									r.p.Transparency = r.base + (1 - r.base) * fadeA
								end
							elseif k >= 1 then
								-- neon bật chớp tắt khi mới đáp xuống
								local on = (math.sin(e * 70 + i * 3) > -0.1) or (e > ta + 0.85)
								if on ~= L.last then
									L.last = on
									for _, r in ipairs(L.glowParts) do
										r.p.Transparency = on and r.base or 0.93
									end
								end
							end
						end
					end

					light.Brightness = (e < 0.5 and e * 8 or (4 + math.sin(e * 8))) * (1 - fadeA)
					return true
				end

				function ctl.destroy()
					for _, L in ipairs(letters) do
						L.model:Destroy()
					end
					light:Destroy()
				end

				return ctl
			end

			-- ===== rig R6 =====
			local function buildManualRig()
				local m = Instance.new("Model")
				m.Name = "NT_BanAvatar"
				local char = localPlayer.Character
				local bc = char and char:FindFirstChildOfClass("BodyColors")
				local skin = Color3.fromRGB(245, 205, 48)
				local function col(n)
					return bc and bc[n] or skin
				end

				local hrp = mkPart(m, "HumanoidRootPart", Vector3.new(2, 2, 1), skin)
				hrp.Transparency = 1
				local torso = mkPart(m, "Torso", Vector3.new(2, 2, 1), col("TorsoColor3"))
				local head = mkPart(m, "Head", Vector3.new(2, 1, 1), col("HeadColor3"))
				local mesh = Instance.new("SpecialMesh")
				mesh.MeshType = Enum.MeshType.Head
				mesh.Scale = Vector3.new(1.25, 1.25, 1.25)
				mesh.Parent = head
				local oldHead = char and char:FindFirstChild("Head")
				local face = oldHead and oldHead:FindFirstChildOfClass("Decal")
				if face then
					face:Clone().Parent = head
				end
				local la = mkPart(m, "Left Arm", Vector3.new(1, 2, 1), col("LeftArmColor3"))
				local ra = mkPart(m, "Right Arm", Vector3.new(1, 2, 1), col("RightArmColor3"))
				local ll = mkPart(m, "Left Leg", Vector3.new(1, 2, 1), col("LeftLegColor3"))
				local rl = mkPart(m, "Right Leg", Vector3.new(1, 2, 1), col("RightLegColor3"))

				local function joint(name, p0, p1)
					local j = Instance.new("Motor6D")
					j.Name = name
					j.Part0 = p0
					j.Part1 = p1
					j.Parent = p0
				end
				joint("RootJoint", hrp, torso)
				joint("Neck", torso, head)
				joint("Right Shoulder", torso, ra)
				joint("Left Shoulder", torso, la)
				joint("Right Hip", torso, rl)
				joint("Left Hip", torso, ll)

				local hum = Instance.new("Humanoid")
				hum.RigType = Enum.HumanoidRigType.R6
				hum.Parent = m

				if char then
					for _, c in ipairs(char:GetChildren()) do
						if c:IsA("Shirt") or c:IsA("Pants") or c:IsA("ShirtGraphic") then
							c:Clone().Parent = m
						elseif c:IsA("Accessory") then
							pcall(function()
								hum:AddAccessory(c:Clone())
							end)
						end
					end
				end

				m.PrimaryPart = hrp
				return m
			end

			local function getJoints(model)
				local hrp = model:FindFirstChild("HumanoidRootPart")
				local torso = model:FindFirstChild("Torso")
				if not (hrp and torso) then
					return nil
				end
				local J = {
					root = hrp:FindFirstChild("RootJoint"),
					neck = torso:FindFirstChild("Neck"),
					rs = torso:FindFirstChild("Right Shoulder"),
					ls = torso:FindFirstChild("Left Shoulder"),
					rh = torso:FindFirstChild("Right Hip"),
					lh = torso:FindFirstChild("Left Hip"),
				}
				for _, j in pairs(J) do
					if not j then
						return nil
					end
				end
				for _, n in ipairs({ "Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }) do
					if not model:FindFirstChild(n) then
						return nil
					end
				end
				return J
			end

			local function createRig()
				local model
				pcall(function()
					local desc = PlayersSvc:GetHumanoidDescriptionFromUserId(localPlayer.UserId)
					model = PlayersSvc:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R6)
				end)

				local J = model and getJoints(model)
				if not J then
					if model then
						model:Destroy()
					end
					model = buildManualRig()
					J = getJoints(model)
				end
				if not J then
					return nil
				end

				model.Name = "NT_BanAvatar"

				-- khung joint chuẩn để animation tính toán dễ
				J.root.C0, J.root.C1 = CFrame.new(), CFrame.new()
				J.neck.C0, J.neck.C1 = CFrame.new(0, 1, 0), CFrame.new(0, -0.5, 0)
				J.rs.C0, J.rs.C1 = CFrame.new(1, 0.5, 0), CFrame.new(-0.5, 0.5, 0)
				J.ls.C0, J.ls.C1 = CFrame.new(-1, 0.5, 0), CFrame.new(0.5, 0.5, 0)
				J.rh.C0, J.rh.C1 = CFrame.new(0.5, -1, 0), CFrame.new(0, 1, 0)
				J.lh.C0, J.lh.C1 = CFrame.new(-0.5, -1, 0), CFrame.new(0, 1, 0)

				local hum = model:FindFirstChildOfClass("Humanoid")
				if hum then
					pcall(function()
						hum.EvaluateStateMachine = false
					end)
					hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
					hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
				end

				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("BasePart") then
						d.Anchored = false
						d.CanCollide = false
						d.CanTouch = false
						d.CanQuery = false
						d.Massless = true
					elseif d:IsA("Script") or d:IsA("LocalScript") then
						d:Destroy()
					end
				end
				model.HumanoidRootPart.Anchored = true

				return model, J
			end

			-- ===== búa trắng đen neon =====
			local function buildHammer(rig)
				local L = BAN.HandleLength
				local arm = rig["Right Arm"]
				local H = { handleParts = {}, headParts = {}, orbs = {} }
				local function addHandle(p)
					H.handleParts[#H.handleParts + 1] = p
					return p
				end
				local function addHead(p)
					H.headParts[#H.headParts + 1] = p
					return p
				end

				local handle = addHandle(mkPart(rig, "HammerHandle", Vector3.new(0.5, L, 0.5), BLACK, Enum.Material.Metal))
				handle.Reflectance = 0.08
				local grip = Instance.new("Motor6D")
				grip.Name = "RightGrip"
				grip.Part0 = arm
				grip.Part1 = handle
				grip.C0 = CFrame.new(0, -1, 0) * CFrame.Angles(math.pi, 0, 0)
				grip.C1 = CFrame.new(0, -L / 2 + 1.3, 0)
				grip.Parent = arm

				-- quấn tay cầm trắng
				for i = 0, 4 do
					local w = addHandle(mkPart(rig, "HammerWrap", Vector3.new(0.58, 0.2, 0.58), WHITE, Enum.Material.SmoothPlastic))
					weld(handle, w, CFrame.new(0, -L / 2 + 0.55 + i * 0.42, 0))
				end
				-- 4 đường neon dọc cán
				for _, o in ipairs({ { 0.255, 0 }, { -0.255, 0 }, { 0, 0.255 }, { 0, -0.255 } }) do
					local line = addHandle(mkPart(rig, "HammerSeam", Vector3.new(0.07, L - 1.2, 0.07), WHITE, Enum.Material.Neon))
					weld(handle, line, CFrame.new(o[1], 0.2, o[2]))
				end
				-- vòng neon cổ búa
				for _, y in ipairs({ L / 2 - 1.5, L / 2 - 1.9 }) do
					local r = addHandle(mkPart(rig, "HammerCollar", Vector3.new(0.14, 0.85, 0.85), WHITE, Enum.Material.Neon))
					r.Shape = Enum.PartType.Cylinder
					weld(handle, r, CFrame.new(0, y, 0) * CFrame.Angles(0, 0, math.pi / 2))
				end
				-- đuôi búa
				local pommel = addHandle(mkPart(rig, "HammerPommel", Vector3.new(0.95, 0.95, 0.95), BLACK, Enum.Material.Metal))
				pommel.Shape = Enum.PartType.Ball
				weld(handle, pommel, CFrame.new(0, -L / 2 - 0.1, 0))
				local pomRing = addHandle(mkPart(rig, "HammerPommelRing", Vector3.new(0.12, 1.15, 1.15), WHITE, Enum.Material.Neon))
				pomRing.Shape = Enum.PartType.Cylinder
				weld(handle, pomRing, CFrame.new(0, -L / 2 - 0.1, 0) * CFrame.Angles(0, 0, math.pi / 2))
				local pomTip = addHandle(mkPart(rig, "HammerPommelTip", Vector3.new(0.5, 0.5, 0.5), WHITE, Enum.Material.Neon))
				pomTip.Shape = Enum.PartType.Ball
				weld(handle, pomTip, CFrame.new(0, -L / 2 - 0.75, 0))

				-- đầu búa
				local head = addHead(mkPart(rig, "HammerHead", Vector3.new(1.9, 1.9, 2.7), BLACK, Enum.Material.Metal))
				head.Reflectance = 0.12
				H.head = head
				H.handle = handle
				H.grip = grip
				H.headWeld = weld(handle, head, CFrame.new(0, L / 2 - 0.4, 0))

				for _, z in ipairs({ -1.575, 1.575 }) do
					local plate = addHead(mkPart(rig, "HammerPlate", Vector3.new(2.15, 2.15, 0.45), WHITE, Enum.Material.SmoothPlastic))
					weld(head, plate, CFrame.new(0, 0, z))
					local core = addHead(mkPart(rig, "HammerPlateCore", Vector3.new(1.5, 1.5, 0.5), WHITE, Enum.Material.Neon))
					weld(head, core, CFrame.new(0, 0, z))
					local eye = addHead(mkPart(rig, "HammerPlateEye", Vector3.new(0.7, 0.7, 0.56), BLACK, Enum.Material.Metal))
					weld(head, eye, CFrame.new(0, 0, z))
				end
				-- dải giữa đen + 4 thanh neon góc
				local band = addHead(mkPart(rig, "HammerBand", Vector3.new(2.1, 2.1, 0.4), BLACK, Enum.Material.SmoothPlastic))
				weld(head, band, CFrame.new(0, 0, 0))
				for _, c in ipairs({ { 0.95, 0.95 }, { -0.95, 0.95 }, { 0.95, -0.95 }, { -0.95, -0.95 } }) do
					local rail = addHead(mkPart(rig, "HammerRail", Vector3.new(0.09, 0.09, 2.7), WHITE, Enum.Material.Neon))
					weld(head, rail, CFrame.new(c[1], c[2], 0))
				end
				for _, x in ipairs({ -0.5, 0.5 }) do
					local stripe = addHead(mkPart(rig, "HammerStripe", Vector3.new(0.07, 0.07, 2.7), WHITE, Enum.Material.Neon))
					weld(head, stripe, CFrame.new(x, 0.96, 0))
				end
				-- gai trên đầu búa
				local sp1 = addHead(mkPart(rig, "HammerSpire1", Vector3.new(1.2, 0.45, 1.2), BLACK, Enum.Material.Metal))
				weld(head, sp1, CFrame.new(0, 1.15, 0))
				local sp2 = addHead(mkPart(rig, "HammerSpire2", Vector3.new(0.7, 0.5, 0.7), BLACK, Enum.Material.Metal))
				weld(head, sp2, CFrame.new(0, 1.6, 0))
				local sp3 = addHead(mkPart(rig, "HammerSpire3", Vector3.new(0.22, 0.9, 0.22), WHITE, Enum.Material.Neon))
				weld(head, sp3, CFrame.new(0, 2.2, 0))
				local spBase = addHead(mkPart(rig, "HammerSpireBase", Vector3.new(1.0, 0.4, 1.0), BLACK, Enum.Material.Metal))
				weld(head, spBase, CFrame.new(0, -1.1, 0))

				-- chữ BAN trắng khắc hai bên đầu búa
				for _, face in ipairs({ Enum.NormalId.Right, Enum.NormalId.Left }) do
					local sg = Instance.new("SurfaceGui")
					sg.Face = face
					sg.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
					sg.CanvasSize = Vector2.new(300, 190)
					sg.LightInfluence = 0
					pcall(function()
						sg.Brightness = 4
					end)
					sg.Parent = head
					local tl = Instance.new("TextLabel")
					tl.BackgroundTransparency = 1
					tl.Size = UDim2.fromScale(1, 1)
					tl.Text = "BAN"
					tl.Font = Enum.Font.Bangers
					tl.TextScaled = true
					tl.TextColor3 = WHITE
					tl.Parent = sg
				end

				-- 2 quả cầu neon quay quanh đầu búa
				for i = 1, 2 do
					local orb = addHead(mkPart(rig, "HammerOrb", Vector3.new(0.55, 0.55, 0.55), WHITE, Enum.Material.Neon))
					orb.Shape = Enum.PartType.Ball
					local w = weld(head, orb, CFrame.new(1.9 * (i == 1 and 1 or -1), 0, 0))
					H.orbs[#H.orbs + 1] = { part = orb, weld = w, r = 2.0, z = (i == 1) and 0.4 or -0.4, phase = (i - 1) * math.pi }
				end

				return H
			end

			-- gắn trail / ánh sáng / particle cho búa (làm SAU khi rig:ScaleTo để kích thước tuyệt đối)
			local function decorateHammer(rig, H)
				local fx = { trails = {}, emitters = {}, lights = {}, guis = {} }
				local function att(part, x, y, z)
					local a = Instance.new("Attachment")
					a.Position = Vector3.new(x * S, y * S, z * S)
					a.Parent = part
					return a
				end
				local function mkTrail(a0, a1, life, trA, trB, w0, w1, color)
					local tr = Instance.new("Trail")
					tr.Attachment0 = a0
					tr.Attachment1 = a1
					tr.Lifetime = life
					tr.Color = color or cseq({ 0, WHITE }, { 1, Color3.fromRGB(190, 190, 195) })
					tr.Transparency = seq({ 0, trA }, { 1, trB })
					tr.WidthScale = seq({ 0, w0 }, { 1, w1 })
					tr.LightEmission = 1
					tr.LightInfluence = 0
					tr.FaceCamera = true
					tr.MinLength = 0.05
					tr.Parent = a0.Parent
					fx.trails[#fx.trails + 1] = tr
					return tr
				end

				-- vệt chém lớn: từ mũi gai đến đuôi cán
				local aSpire = att(H.head, 0, 2.5, 0)
				local aPommel = att(H.handle, 0, -BAN.HandleLength / 2 - 0.8, 0)
				mkTrail(aSpire, aPommel, 0.5, 0.45, 1, 1, 0.3)
				-- vệt đầu búa sáng
				local aTop = att(H.head, 0, 1.05, 0)
				local aBot = att(H.head, 0, -1.05, 0)
				mkTrail(aTop, aBot, 0.4, 0.05, 1, 1, 0.2)
				-- vệt 2 cạnh đập (hai mặt ±Z)
				local aF1 = att(H.head, 0, 1.0, 1.9)
				local aF2 = att(H.head, 0, -1.0, 1.9)
				mkTrail(aF1, aF2, 0.3, 0.1, 1, 1, 0.1)
				local aB1 = att(H.head, 0, 1.0, -1.9)
				local aB2 = att(H.head, 0, -1.0, -1.9)
				mkTrail(aB1, aB2, 0.3, 0.1, 1, 1, 0.1)

				-- trail cho 2 quả cầu quay
				for _, o in ipairs(H.orbs) do
					local a0 = att(o.part, 0, 0.3, 0)
					local a1 = att(o.part, 0, -0.3, 0)
					mkTrail(a0, a1, 0.45, 0.1, 1, 1, 0.1)
				end

				-- ánh sáng trắng
				local light = Instance.new("PointLight")
				light.Color = WHITE
				light.Range = 40
				light.Brightness = 1.2
				light.Parent = H.head
				fx.light = light
				fx.lights[#fx.lights + 1] = light

				-- lấp lánh quanh đầu búa
				local glint = mkEmitter(H.head, {
					tex = TEX_SPARK,
					rate = 10,
					life = NumberRange.new(0.6, 1.1),
					speed = NumberRange.new(1 * SK, 4 * SK),
					size = seq({ 0, 0.7 * FX }, { 0.5, 0.4 * FX }, { 1, 0 }),
					transp = seq({ 0, 0.1 }, { 1, 1 }),
					color = ColorSequence.new(WHITE),
					emit = 1,
					shape = Enum.ParticleEmitterShape.Box,
				})
				fx.emitters[#fx.emitters + 1] = glint

				-- hút năng lượng vào đầu búa khi gồng
				local charge = mkEmitter(H.head, {
					tex = TEX_SPARK,
					rate = 0,
					life = NumberRange.new(0.5, 0.7),
					speed = NumberRange.new(-60 * SK, -40 * SK),
					size = seq({ 0, 0.9 * FX }, { 1, 0 }),
					transp = seq({ 0, 0 }, { 1, 1 }),
					color = cseq({ 0, WHITE }, { 1, Color3.fromRGB(160, 160, 165) }),
					emit = 1,
					shape = Enum.ParticleEmitterShape.Sphere,
				})
				fx.charge = charge
				fx.emitters[#fx.emitters + 1] = charge

				-- khói trắng/đen nhẹ bay ra từ đầu búa
				local aura = mkEmitter(H.head, {
					rate = 6,
					life = NumberRange.new(1, 1.6),
					speed = NumberRange.new(1 * SK, 3 * SK),
					size = seq({ 0, 1.2 * FX }, { 1, 2.4 * FX }),
					transp = seq({ 0, 0.7 }, { 1, 1 }),
					color = cseq({ 0, Color3.fromRGB(235, 235, 240) }, { 1, Color3.fromRGB(30, 30, 34) }),
					emit = 0.4,
					accel = Vector3.new(0, 3, 0),
					shape = Enum.ParticleEmitterShape.Box,
				})
				fx.emitters[#fx.emitters + 1] = aura

				for _, d in ipairs(H.head:GetChildren()) do
					if d:IsA("SurfaceGui") then
						fx.guis[#fx.guis + 1] = d
					end
				end

				function fx.kill()
					for _, tr in ipairs(fx.trails) do
						tr.Enabled = false
					end
					for _, e in ipairs(fx.emitters) do
						e.Enabled = false
					end
					for _, l in ipairs(fx.lights) do
						l.Enabled = false
					end
					for _, g in ipairs(fx.guis) do
						g.Enabled = false
					end
				end

				return fx
			end

			-- vị trí tâm đầu búa (trong không gian root) theo góc tay + độ ngả người
			local function headLocalPos(theta, lean)
				local L = BAN.HandleLength
				local torso = CFrame.Angles(lean, 0, 0)
				local rs = CFrame.new(1, 0.5, 0) * CFrame.Angles(theta, 0, 0)
				local arm = torso * rs * CFrame.new(-0.5, 0.5, 0):Inverse()
				local handle = arm * (CFrame.new(0, -1, 0) * CFrame.Angles(math.pi, 0, 0)) * CFrame.new(0, -L / 2 + 1.3, 0):Inverse()
				return (handle * CFrame.new(0, L / 2 - 0.4, 0)).Position
			end

			local function solveHit(lean)
				local best, bestErr = math.rad(40), math.huge
				for d = 15, 95 do
					local th = math.rad(d)
					local err = math.abs(headLocalPos(th, lean).Y + 2.1)
					if err < bestErr then
						best, bestErr = th, err
					end
				end
				return best, headLocalPos(best, lean)
			end

			-- tư thế (có làm mượt giữa các pha)
			local PK = { "rs", "rsz", "ls", "lsz", "rh", "lh", "lean", "bounce", "neck", "twist", "roll" }

			local function applyPose(J, p)
				local lean = p.lean or 0
				local twist = p.twist or 0
				J.root.C0 = CFrame.new(0, (p.bounce or 0) * S, 0) * CFrame.Angles(lean, twist, p.roll or 0)
				J.rs.C0 = CFrame.new(1 * S, 0.5 * S, 0) * CFrame.Angles(p.rs or 0, 0, p.rsz or 0)
				J.ls.C0 = CFrame.new(-1 * S, 0.5 * S, 0) * CFrame.Angles(p.ls or 0, 0, p.lsz or 0)
				J.rh.C0 = CFrame.new(0.5 * S, -1 * S, 0) * CFrame.Angles((p.rh or 0) - lean, 0, 0)
				J.lh.C0 = CFrame.new(-0.5 * S, -1 * S, 0) * CFrame.Angles((p.lh or 0) - lean, 0, 0)
				J.neck.C0 = CFrame.new(0, 1 * S, 0) * CFrame.Angles(p.neck or (-lean * 0.7), -twist * 0.8, 0)
			end

			-- ===== nhóm bộ phận để tan rã =====
			local function buildGroups(rig, J, H)
				local groups = {}
				local function newGroup(joint, post, parts)
					local g = {
						joint = joint,
						post = post,
						base = (not post) and joint.C0 or nil,
						parts = parts,
						items = {},
						delay = rnd(0, BAN.DisSpread),
						dir = Vector3.new(rnd(-1, 1), rnd(0.3, 1), rnd(-1, 1)).Unit * rnd(3, 7) * S * 0.6,
						spin = Vector3.new(rnd(-2, 2), rnd(-2, 2), rnd(-2, 2)),
						emitted = false,
					}
					groups[#groups + 1] = g
					return g
				end

				local gRoot = newGroup(J.root, true, { rig.Torso })
				local gHead = newGroup(J.neck, true, { rig.Head })
				newGroup(J.rs, true, { rig["Right Arm"] })
				newGroup(J.ls, true, { rig["Left Arm"] })
				newGroup(J.rh, true, { rig["Right Leg"] })
				newGroup(J.lh, true, { rig["Left Leg"] })
				local gHandle = newGroup(H.grip, false, H.handleParts)
				local gHam = newGroup(H.headWeld, false, H.headParts)
				gHandle.delay = BAN.DisSpread * 0.9
				gHam.delay = BAN.DisSpread

				-- phụ kiện đi theo đầu hoặc thân
				for _, acc in ipairs(rig:GetChildren()) do
					if acc:IsA("Accessory") then
						local target = gRoot
						local h = acc:FindFirstChild("Handle")
						if h then
							for _, w in ipairs(h:GetChildren()) do
								if w:IsA("Weld") or w:IsA("WeldConstraint") then
									local other = (w.Part0 == h) and w.Part1 or w.Part0
									if other and other.Name == "Head" then
										target = gHead
									end
								end
							end
						end
						for _, d in ipairs(acc:GetDescendants()) do
							if d:IsA("BasePart") then
								table.insert(target.parts, d)
							end
						end
					end
				end

				for _, g in ipairs(groups) do
					for _, p in ipairs(g.parts) do
						g.items[#g.items + 1] = { obj = p, orig = p.Transparency }
						for _, d in ipairs(p:GetDescendants()) do
							if d:IsA("Decal") or d:IsA("Texture") then
								g.items[#g.items + 1] = { obj = d, orig = d.Transparency }
							end
						end
					end
					g.emitter = smokeEmitter(g.parts[1])
					g.embers = mkEmitter(g.parts[1], {
						tex = TEX_FIRE,
						life = NumberRange.new(1, 2),
						speed = NumberRange.new(3 * SK, 9 * SK),
						size = seq({ 0, 0.7 * FX }, { 1, 0 }),
						transp = seq({ 0, 0.1 }, { 1, 1 }),
						color = cseq({ 0, WHITE }, { 0.5, Color3.fromRGB(255, 110, 100) }, { 1, RED }),
						emit = 1,
						accel = Vector3.new(0, 8 * SK, 0),
					})
					g.sparks = mkEmitter(g.parts[1], {
						tex = TEX_SPARK,
						life = NumberRange.new(0.5, 1),
						speed = NumberRange.new(8 * SK, 18 * SK),
						size = seq({ 0, 0.8 * FX }, { 1, 0 }),
						transp = seq({ 0, 0 }, { 1, 1 }),
						color = ColorSequence.new(WHITE),
						emit = 1,
					})
				end

				return groups
			end

			tbl12.PlayBanHammer = function(hole)
				if not hole or not hole:IsA("BasePart") then
					return
				end

				task.spawn(function()
					local rig, J = createRig()
					if not rig then
						return
					end
					if flag11 then
						rig:Destroy()
						return
					end

					local target = hole.Position
					local bag = { rig } -- mọi thứ cần dọn
					local textCtl

					-- mặt đất dưới hố đen (cao quá = coi như hố đen ở trên trời)
					local ignore = { rig, hole.Parent }
					for _, pl in ipairs(PlayersSvc:GetPlayers()) do
						if pl.Character then
							ignore[#ignore + 1] = pl.Character
						end
					end
					local rp = RaycastParams.new()
					rp.FilterType = Enum.RaycastFilterType.Exclude
					rp.FilterDescendantsInstances = ignore
					local hit = workspace:Raycast(target + Vector3.new(0, 6, 0), Vector3.new(0, -600, 0), rp)
					local airMode = (not hit) or (target.Y - hit.Position.Y > BAN.SkyThreshold)
					local groundY = (not airMode) and hit.Position.Y or (target.Y - 3)

					local function groundAt(x, z)
						local r = workspace:Raycast(Vector3.new(x, groundY + 120, z), Vector3.new(0, -500, 0), rp)
						return r and r.Position.Y or nil
					end

					-- hướng chạy tới: phía trước tầm nhìn camera, lệch nhẹ 20 độ
					local cam = workspace.CurrentCamera
					local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
					look = Vector3.new(look.X, 0, look.Z)
					if look.Magnitude < 0.1 then
						look = Vector3.new(0, 0, -1)
					end
					local dirAway = CFrame.Angles(0, math.rad(20), 0) * look.Unit
					local f = -dirAway
					local faceRot = CFrame.lookAt(Vector3.zero, f)

					-- tính tư thế đập để đầu búa chạm đúng chỗ hố đen
					local leanHit = -0.45
					local thetaHit, Hh = solveHit(leanHit)
					Hh = Hh * S
					local off = faceRot * Hh
					local impactY = clamp(groundY + 0.9 * S - Hh.Y, groundY + 2.3 * S, groundY + 3.5 * S)
					local impactRoot = Vector3.new(target.X - off.X, impactY, target.Z - off.Z)
					local sx = impactRoot.X + dirAway.X * BAN.StartDistance
					local sz = impactRoot.Z + dirAway.Z * BAN.StartDistance
					local startFloor = (not airMode) and (groundAt(sx, sz) or groundY) or groundY
					local runDist = (Vector3.new(impactRoot.X, 0, impactRoot.Z) - Vector3.new(sx, 0, sz)).Magnitude
					local runDur = runDist / BAN.RunSpeed

					local skyStart = Vector3.new(sx + dirAway.X * 150, groundY + 3 * S + BAN.SkyHeight, sz + dirAway.Z * 150)
					local startAir = Vector3.new(sx, groundY + 3 * S, sz)
					local underY = startFloor - 4.6 * S

					local H = buildHammer(rig)
					pcall(function()
						rig:ScaleTo(S) -- phóng to cả rig + búa + phụ kiện + khung joint
					end)
					local fxH = decorateHammer(rig, H)
					local groups = buildGroups(rig, J, H)

					local hrp = rig.HumanoidRootPart
					local firstRoot = airMode and skyStart or Vector3.new(sx, underY, sz)
					hrp.CFrame = CFrame.lookAt(firstRoot, firstRoot + f)
					applyPose(J, { rs = math.rad(172), ls = math.rad(160), lean = airMode and -1.05 or -0.1 })
					rig.Parent = workspace

					-- trail lao xuống từ trời (gắn vai)
					local torsoTrail
					do
						local a0 = Instance.new("Attachment")
						a0.Position = Vector3.new(1 * S, 0.9 * S, 0)
						a0.Parent = rig.Torso
						local a1 = Instance.new("Attachment")
						a1.Position = Vector3.new(-1 * S, 0.9 * S, 0)
						a1.Parent = rig.Torso
						torsoTrail = Instance.new("Trail")
						torsoTrail.Attachment0 = a0
						torsoTrail.Attachment1 = a1
						torsoTrail.Lifetime = 0.9
						torsoTrail.Color = cseq({ 0, WHITE }, { 0.35, Color3.fromRGB(255, 90, 80) }, { 1, RED })
						torsoTrail.Transparency = seq({ 0, 0.1 }, { 1, 1 })
						torsoTrail.WidthScale = seq({ 0, 1 }, { 1, 0.1 })
						torsoTrail.LightEmission = 1
						torsoTrail.LightInfluence = 0
						torsoTrail.FaceCamera = true
						torsoTrail.Enabled = false
						torsoTrail.Parent = rig.Torso
					end
					local diveFire = mkEmitter(rig.Torso, {
						tex = TEX_FIRE,
						life = NumberRange.new(0.5, 0.9),
						speed = NumberRange.new(2 * SK, 8 * SK),
						size = seq({ 0, 2.2 * FX }, { 1, 0 }),
						transp = seq({ 0, 0.1 }, { 1, 1 }),
						color = cseq({ 0, WHITE }, { 0.4, Color3.fromRGB(255, 90, 80) }, { 1, RED }),
						emit = 1,
					})
					local diveSparks = mkEmitter(rig.Torso, {
						tex = TEX_SPARK,
						life = NumberRange.new(0.6, 1.2),
						speed = NumberRange.new(0, 2),
						size = seq({ 0, 1.2 * FX }, { 1, 0 }),
						transp = seq({ 0, 0 }, { 1, 1 }),
						color = cseq({ 0, WHITE }, { 1, RED }),
						emit = 1,
					})

					-- bụi chân
					local feet = Instance.new("Part")
					feet.Name = "NT_BanFeet"
					feet.Anchored = true
					feet.CanCollide = false
					feet.CanTouch = false
					feet.CanQuery = false
					feet.Transparency = 1
					feet.Size = Vector3.new(2 * S, 0.2, 2 * S)
					feet.CFrame = CFrame.new(sx, startFloor + 0.2, sz)
					feet.Parent = workspace
					track(bag, feet)
					local dust = smokeEmitter(feet)
					dust.Speed = NumberRange.new(3 * SK, 8 * SK)
					dust.SpreadAngle = Vector2.new(35, 35)
					dust.Size = seq({ 0, 1.6 * FX }, { 1, 4.5 * FX })
					dust.Transparency = seq({ 0, 0.5 }, { 1, 1 })
					dust.Color = cseq({ 0, Color3.fromRGB(190, 180, 165) }, { 1, Color3.fromRGB(110, 105, 100) })
					local airSparks = mkEmitter(feet, {
						tex = TEX_SPARK,
						life = NumberRange.new(0.5, 1),
						speed = NumberRange.new(10 * SK, 25 * SK),
						spread = Vector2.new(60, 60),
						size = seq({ 0, 1.2 * FX }, { 1, 0 }),
						transp = seq({ 0, 0 }, { 1, 1 }),
						color = cseq({ 0, WHITE }, { 1, RED }),
						emit = 1,
						accel = Vector3.new(0, -20 * SK, 0),
					})

					-- điểm xuất hiện (khói + tia lửa lúc chui lên / lao xuống)
					local startFx = Instance.new("Part")
					startFx.Name = "NT_BanStart"
					startFx.Anchored = true
					startFx.CanCollide = false
					startFx.CanTouch = false
					startFx.CanQuery = false
					startFx.Transparency = 1
					startFx.Size = Vector3.new(6 * FX, 0.5, 6 * FX)
					startFx.CFrame = CFrame.new(sx, startFloor + 0.3, sz)
					startFx.Parent = workspace
					track(bag, startFx)
					local startSet = burstSet(startFx)

					-- điểm va chạm: part ẩn + âm thanh + khói
					local fx = Instance.new("Part")
					fx.Name = "NT_BanImpact"
					fx.Anchored = true
					fx.CanCollide = false
					fx.CanTouch = false
					fx.CanQuery = false
					fx.Transparency = 1
					fx.Size = Vector3.new(6 * FX, 0.5, 6 * FX)
					fx.CFrame = CFrame.new(target.X, groundY + 0.3, target.Z)
					fx.Parent = workspace
					track(bag, fx)

					local snd = Instance.new("Sound")
					snd.SoundId = BAN.SoundId
					snd.Volume = 4
					snd.RollOffMode = Enum.RollOffMode.InverseTapered
					snd.RollOffMinDistance = 300
					snd.RollOffMaxDistance = 3000
					snd.Parent = fx

					local impactSet = burstSet(fx)

					-- âm thanh lúc dummy xuất hiện (chui đất / lao từ trời)
					local spawnSnd = Instance.new("Sound")
					spawnSnd.Name = "NT_BanSpawnSound"
					spawnSnd.SoundId = BAN.SpawnSoundId
					spawnSnd.Volume = 4
					spawnSnd.RollOffMode = Enum.RollOffMode.InverseTapered
					spawnSnd.RollOffMinDistance = 300
					spawnSnd.RollOffMaxDistance = 3000
					spawnSnd.Parent = hrp
					spawnSnd:Play()
					local flash = Instance.new("PointLight")
					flash.Color = Color3.fromRGB(255, 90, 80)
					flash.Range = 60
					flash.Brightness = 0
					flash.Parent = fx

					-- mốc thời gian
					local T1
					if airMode then
						T1 = BAN.PortalTime + BAN.DiveTime + BAN.LandTime
					else
						T1 = BAN.RumbleTime + BAN.RiseTime + BAN.RoarTime
					end
					local T2 = T1 + runDur
					local T3 = T2 + BAN.WindupTime
					local T4 = T3 + BAN.SmashTime -- impact
					local TD = T4 + BAN.HoldTime -- bắt đầu tan rã
					local TEND = T4 + BAN.TotalAfterImpact
					local kA = BAN.WindupTime / (BAN.WindupTime + BAN.SmashTime) -- đỉnh cú nhảy

					local t = 0
					local impacted = false
					local lastStep = -1
					local lastQuake = -1
					local debris = {}
					local ev = {}
					local freeze = 0
					local conn
					local ph = 0
					local orbSpin = 0
					local floorNow = startFloor
					local runYEnd = groundY + 3 * S
					local lastRoot = firstRoot
					local hammerKilled = false

					-- trạng thái pose đã làm mượt
					local cur = {}
					for _, k in ipairs(PK) do
						cur[k] = 0
					end
					cur.rs = math.rad(172)
					cur.ls = math.rad(160)
					cur.lean = airMode and -1.05 or -0.1
					cur.neck = -cur.lean * 0.7
					local function blendPose(tp, rate, dt)
						if tp.neck == nil then
							tp.neck = -(tp.lean or 0) * 0.7
						end
						local a = (rate >= 1000) and 1 or (1 - math.exp(-rate * dt))
						for _, k in ipairs(PK) do
							cur[k] += ((tp[k] or 0) - cur[k]) * a
						end
						return cur
					end

					local function cleanup()
						if conn then
							conn:Disconnect()
							conn = nil
						end
						if textCtl then
							pcall(textCtl.destroy)
							textCtl = nil
						end
						for _, o in ipairs(bag) do
							pcall(o.Destroy, o)
						end
					end

					local function spawnDebris(center, count, spd, sizeMul, floorY, life)
						for i = 1, count do
							local s = rnd(0.5, 1.3) * S * 0.5 * sizeMul
							local roll = math.random()
							local p = Instance.new("Part")
							p.Name = "NT_BanDebris"
							p.Anchored = true
							p.CanCollide = false
							p.CanTouch = false
							p.CanQuery = false
							p.CastShadow = false
							p.Size = Vector3.new(s, s * rnd(0.6, 1), s)
							if roll < 0.6 then
								local g = math.random(22, 55)
								p.Color = Color3.fromRGB(g, g, g + 4)
								p.Material = Enum.Material.Slate
							elseif roll < 0.85 then
								local g = math.random(215, 250)
								p.Color = Color3.fromRGB(g, g, g)
								p.Material = Enum.Material.Marble
							else
								p.Color = RED
								p.Material = Enum.Material.Neon
								p.Size = p.Size * 0.6
							end
							p.CFrame = CFrame.new(center + Vector3.new(rnd(-2, 2) * S * 0.5, 0.5, rnd(-2, 2) * S * 0.5)) * CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
							p.Parent = workspace
							bag[#bag + 1] = p
							local ang = rnd(0, math.pi * 2)
							local sp = rnd(10, 26) * SK * spd
							debris[#debris + 1] = {
								part = p,
								vel = Vector3.new(math.cos(ang) * sp, rnd(18, 38) * SK * spd, math.sin(ang) * sp),
								spin = Vector3.new(rnd(-8, 8), rnd(-8, 8), rnd(-8, 8)),
								size = p.Size.X,
								floorY = floorY,
								born = t,
								life = life or 2.2,
								baseTr = 0,
							}
						end
					end

					local function footfall(x, z, sfv)
						camShake(0.35, (0.5 + 1.1 * sfv) * SK, Vector3.new(x, floorNow, z))
						local gp = Vector3.new(x, floorNow + 0.4, z)
						if airMode then
							airSparks:Emit(math.floor(6 + 10 * sfv))
							shock(bag, gp, WHITE, 9 * FX, 0.55, 0.3 * SK, 2 * FX, 0.1)
							local tile = track(bag, fxPart("NT_BanTile", Vector3.new(3 * S, 0.3, 3 * S), RED, Enum.Material.Neon, 0.3, CFrame.new(gp) * CFrame.Angles(0, rnd(0, 3), 0)))
							TweenService:Create(tile, TweenInfo.new(0.6), { Transparency = 1, Size = Vector3.new(4.5 * S, 0.3, 4.5 * S) }):Play()
							task.delay(0.7, function()
								tile:Destroy()
							end)
						else
							dust:Emit(math.floor(6 + 10 * sfv))
							shock(bag, gp, Color3.fromRGB(225, 220, 212), 8 * FX, 0.6, 0.25 * SK, 2 * FX, 0.3)
						end
					end

					-- ===== sự kiện: chui đất =====
					local function riseBurst()
						local gp = Vector3.new(sx, startFloor + 0.4, sz)
						startSet.smoke:Emit(70)
						startSet.sparks:Emit(40)
						startSet.embers:Emit(30)
						shock(bag, gp, RED, 60 * FX, 1.0, 0.5 * SK)
						shock(bag, gp, WHITE, 95 * FX, 1.3, 0.3 * SK)
						pillar(bag, gp, RED, 9 * S, 3.2 * S, 1.0)
						spawnDebris(gp, 24, 0.85, 0.9, startFloor, 2.4)
						camShake(1.4, 2.6 * SK, gp)
					end

					local function roarBurst()
						local gp = Vector3.new(sx, startFloor + 0.4, sz)
						shock(bag, gp, WHITE, 120 * FX, 1.2, 0.35 * SK)
						shock(bag, gp, RED, 80 * FX, 1.0, 0.6 * SK, 4, 0.1)
						dome(bag, Vector3.new(sx, startFloor, sz), WHITE, 90 * FX, 0.9, 0.5)
						startSet.smoke:Emit(40)
						camShake(0.9, 2.2 * SK, gp)
						for i = 1, 8 do
							local a = i / 8 * math.pi * 2
							bolt(bag, gp + Vector3.new(0, 1, 0), Vector3.new(math.cos(a), 0.05, math.sin(a)), 40 * FX, 6, 0.3 * SK, RED, 0.35)
						end
					end

					-- ===== sự kiện: lao từ trời =====
					local function portalOpen()
						shock(bag, skyStart, RED, 70 * FX, 0.9, 0.6 * SK, 4, 0.1)
						shock(bag, skyStart, WHITE, 100 * FX, 1.1, 0.35 * SK, 4, 0.1)
						shock(bag, skyStart - Vector3.new(0, 4, 0), RED, 45 * FX, 0.7, 0.6 * SK, 4, 0.2)
						dome(bag, skyStart, WHITE, 70 * FX, 0.8, 0.4)
						for i = 1, 10 do
							local a = i / 10 * math.pi * 2
							bolt(bag, skyStart, Vector3.new(math.cos(a), rnd(-0.4, 0.4), math.sin(a)).Unit, 45 * FX, 6, 0.4 * SK, RED, 0.4)
						end
						screenFlash(0.15, 0.4)
						camShake(0.6, 1.4 * SK, skyStart)
					end

					local function diveBrake()
						local gp = startAir - Vector3.new(0, 3 * S, 0)
						shock(bag, gp, WHITE, 120 * FX, 1.0, 0.35 * SK, 4, 0.1)
						shock(bag, gp, RED, 85 * FX, 0.9, 0.6 * SK, 4, 0.1)
						dome(bag, startAir, RED, 80 * FX, 0.8, 0.35)
						airSparks:Emit(40)
						pillar(bag, gp, WHITE, 8 * S, 2.5 * S, 0.7)
						camShake(1.0, 2.6 * SK, gp)
						fovPunch(7, 0.5)
						-- bệ năng lượng dưới chân
						for i = 1, 3 do
							ring(bag, gp, (i == 2) and WHITE or RED, 10 * FX, (22 + i * 9) * FX, 0.8 + i * 0.25, 0.35 * SK, 0.1, 1, Enum.EasingStyle.Cubic)
						end
					end

					local function doImpact()
						impacted = true
						freeze = 0.07 -- hit-stop
						snd:Play()

						local gp = Vector3.new(target.X, groundY + 0.4, target.Z)
						local textPos = Vector3.new(target.X, groundY + 3.9 * S, target.Z)
						textCtl = build3DText(bag, textPos, S * 1.9, BAN.TextLife)
						bloomOn(BAN.TextLife + 0.8)
						screenFlash(0.35, 0.45)
						camShake(1.3, 2.8 * SK, target)
						fovPunch(9, 0.55)
						task.delay(0.35, function()
							if not flag11 then
								camShake(0.8, 1.3 * SK, target)
							end
						end)

						impactSet.smoke:Emit(90)
						impactSet.sparks:Emit(110)
						impactSet.embers:Emit(50)
						impactSet.linger.Rate = 28
						task.delay(0.9, function()
							impactSet.linger.Rate = 0
						end)

						flash.Brightness = 12
						TweenService:Create(flash, TweenInfo.new(0.8), { Brightness = 0 }):Play()

						shock(bag, gp, WHITE, 60 * FX, 0.55, 0.45 * SK, 4, 0)
						shock(bag, gp, RED, 85 * FX, 0.95, 0.7 * SK, 4, 0.05)
						shock(bag, gp, Color3.fromRGB(215, 205, 190), 125 * FX, 1.4, 0.3 * SK, 4, 0.3)
						shock(bag, gp, RED, 150 * FX, 1.8, 0.25 * SK, 4, 0.4)
						dome(bag, Vector3.new(target.X, groundY, target.Z), WHITE, 100 * FX, 0.9, 0.35)
						dome(bag, Vector3.new(target.X, groundY, target.Z), RED, 70 * FX, 0.7, 0.4)
						pillar(bag, gp, RED, 22 * S, 5 * S, 1.2)
						pillar(bag, gp, WHITE, 28 * S, 2.2 * S, 0.8)

						-- tia sét lan ra + vọt lên
						for i = 1, 14 do
							local a = i / 14 * math.pi * 2 + rnd(-0.15, 0.15)
							local up = (i % 3 == 0) and rnd(0.4, 0.9) or rnd(-0.05, 0.12)
							bolt(bag, gp + Vector3.new(0, 1, 0), Vector3.new(math.cos(a), up, math.sin(a)).Unit, rnd(45, 80) * FX, 7, 0.32 * SK, (i % 2 == 0) and RED or WHITE, rnd(0.35, 0.6))
						end

						if airMode then
							spawnDebris(gp, 40, 1.1, 1, nil, 2.6)
						else
							spawnCracks(bag, gp, groundY, 12, 55 * FX, 0.7 * SK, 2.4)
							spawnDebris(gp, 44, 1, 1, groundY, 2.4)
						end
					end

					conn = RunService.RenderStepped:Connect(function(dtReal)
						if flag11 or not rig.Parent then
							cleanup()
							return
						end

						local dt = dtReal
						if freeze > 0 then
							freeze -= dtReal
							dt = 0
						end
						t += dt
						if t >= TEND then
							cleanup()
							return
						end

						if textCtl and not textCtl.update() then
							pcall(textCtl.destroy)
							textCtl = nil
						end

						local p = {}
						local rate = 14
						local rootPos = lastRoot
						local sf = 0
						local running = false

						if t < T1 then
							if not airMode then
								local tR0 = BAN.RumbleTime
								local tR1 = tR0 + BAN.RiseTime
								if t < tR0 then
									-- đất rung + nứt
									rootPos = Vector3.new(sx, underY, sz)
									if not ev.rumble then
										ev.rumble = true
										local gp = Vector3.new(sx, startFloor, sz)
										spawnCracks(bag, gp, startFloor, 9, 42 * FX, 0.6 * SK, 2.2)
										ring(bag, gp + Vector3.new(0, 0.5, 0), RED, 6 * FX, 70 * FX, BAN.RumbleTime + 0.6, 0.4 * SK, 0.5, 1, Enum.EasingStyle.Quad)
										ring(bag, gp + Vector3.new(0, 0.5, 0), WHITE, 4 * FX, 40 * FX, BAN.RumbleTime, 0.3 * SK, 0.4, 1, Enum.EasingStyle.Quad)
									end
									if t - lastQuake > 0.2 then
										lastQuake = t
										camShake(0.35, (0.8 + 1.8 * t / tR0) * SK, Vector3.new(sx, startFloor, sz))
										dust:Emit(10)
									end
									dust.Rate = 16
									p.rs = math.rad(172)
									p.ls = math.rad(160)
									p.lean = -0.1
									p.neck = -0.25
									rate = 20
								elseif t < tR1 then
									-- trồi lên khỏi mặt đất
									local u = (t - tR0) / BAN.RiseTime
									if not ev.rise then
										ev.rise = true
										riseBurst()
									end
									local y = lerp(underY, startFloor + 3 * S, easeOutBack(clamp(u, 0, 1)))
									rootPos = Vector3.new(sx, y, sz)
									if t - lastQuake > 0.18 then
										lastQuake = t
										camShake(0.3, 1.8 * SK, Vector3.new(sx, startFloor, sz))
									end
									dust.Rate = 55 * (1 - u)
									p.rs = math.rad(172) + math.sin(t * 9) * 0.04
									p.ls = math.rad(150)
									p.lean = -0.08
									p.neck = -0.3
									p.bounce = math.sin(u * math.pi) * 0.2
									rate = 12
								else
									-- gầm
									local u = (t - tR1) / BAN.RoarTime
									if not ev.roar then
										ev.roar = true
										roarBurst()
									end
									rootPos = Vector3.new(sx, startFloor + 3 * S, sz)
									dust.Rate = 0
									local k = easeOutCubic(clamp(u * 2.5, 0, 1))
									p.rs = lerp(math.rad(172), math.rad(205), k)
									p.rsz = 0.4 * k
									p.ls = lerp(math.rad(160), math.rad(120), k)
									p.lsz = -0.5 * k
									p.lean = lerp(-0.08, 0.38, k)
									p.neck = -0.45 * k
									p.bounce = math.sin(t * 14) * 0.05 * (1 - u)
									rate = 14
								end
							else
								local tP = BAN.PortalTime
								local tD = tP + BAN.DiveTime
								if t < tP then
									rootPos = skyStart
									if not ev.portal then
										ev.portal = true
										portalOpen()
									end
									p.rs = math.rad(172)
									p.ls = math.rad(172)
									p.lean = -1.05
									p.rh = -0.3
									p.lh = 0.25
									rate = 14
								elseif t < tD then
									-- lao xuống từ trời
									local u = (t - tP) / BAN.DiveTime
									local s
									if u < 0.78 then
										s = 0.92 * (u / 0.78) ^ 2
									else
										s = 0.92 + 0.08 * easeOutCubic((u - 0.78) / 0.22)
									end
									rootPos = skyStart:Lerp(startAir, s)
									torsoTrail.Enabled = true
									diveFire.Rate = 60
									diveSparks.Rate = 40
									if u > 0.2 and t - lastQuake > 0.12 then
										lastQuake = t
										camShake(0.2, 0.9 * SK, rootPos)
									end
									if u >= 0.78 and not ev.brake then
										ev.brake = true
										diveBrake()
									end
									local brake = clamp((u - 0.78) / 0.22, 0, 1)
									p.rs = math.rad(172)
									p.ls = math.rad(172)
									p.lean = lerp(-1.05, -0.2, brake)
									p.rh = lerp(-0.3, 0.2, brake)
									p.lh = lerp(0.25, -0.2, brake)
									rate = 12
								else
									-- đáp xuống bệ năng lượng + gầm
									local u = (t - tD) / BAN.LandTime
									torsoTrail.Enabled = false
									diveFire.Rate = 0
									diveSparks.Rate = 0
									rootPos = startAir
									if not ev.land then
										ev.land = true
										shock(bag, startAir - Vector3.new(0, 3 * S, 0), WHITE, 90 * FX, 0.9, 0.3 * SK, 4, 0.1)
									end
									local k = easeOutCubic(clamp(u * 2.5, 0, 1))
									p.rs = lerp(math.rad(172), math.rad(205), k)
									p.rsz = 0.4 * k
									p.ls = lerp(math.rad(172), math.rad(120), k)
									p.lsz = -0.5 * k
									p.lean = lerp(-0.2, 0.35, k)
									p.neck = -0.4 * k
									p.bounce = math.sin(t * 10) * 0.06 * (1 - u)
									rate = 14
								end
							end
						elseif t < T2 then
							-- chạy
							local u = (t - T1) / runDur
							local s = smooth(u)
							local v = 6 * u * (1 - u) * runDist / runDur
							sf = clamp(v / BAN.RunSpeed, 0, 1.6)
							ph += dt * 7.5 * math.max(sf, 0.15)
							local x = lerp(sx, impactRoot.X, s)
							local z = lerp(sz, impactRoot.Z, s)
							if not airMode then
								local gt = groundAt(x, z) or floorNow
								floorNow += (gt - floorNow) * (1 - math.exp(-8 * dt))
							else
								floorNow = groundY
							end
							rootPos = Vector3.new(x, floorNow + 3 * S, z)
							runYEnd = rootPos.Y

							local sw = math.sin(ph)
							local step = math.floor(ph / math.pi)
							if step ~= lastStep then
								lastStep = step
								if sf > 0.25 then
									footfall(x, z, clamp(sf, 0, 1))
								end
							end
							p.rs = math.rad(145) + math.sin(ph * 2) * 0.1 * sf
							p.rsz = 0.1 * sf
							p.ls = -sw * 0.95 * sf
							p.lsz = -0.12
							p.rh = sw * 0.9 * sf
							p.lh = -sw * 0.9 * sf
							p.lean = -0.12 - 0.17 * clamp(sf, 0, 1)
							p.bounce = math.abs(math.sin(ph)) * 0.45 * sf
							p.twist = sw * 0.12 * sf
							p.roll = sw * 0.05 * sf
							p.neck = -p.lean * 0.9 + math.sin(ph * 2) * 0.04 * sf
							running = true
							rate = 12
						elseif t < T3 then
							-- gồng + nhảy lên
							local w = (t - T2) / BAN.WindupTime
							if not ev.wind then
								ev.wind = true
								local gp = Vector3.new(target.X, groundY + 0.5, target.Z)
								for i = 1, 3 do
									ring(bag, gp, (i == 2) and WHITE or RED, (70 + i * 28) * FX, 6 * FX, BAN.WindupTime + BAN.SmashTime, 0.4 * SK, 0.9, 0.05, Enum.EasingStyle.Quad, Enum.Material.Neon)
								end
								camShake(0.5, 1.5 * SK, target)
							end
							local u = easeOutQuad(clamp(w, 0, 1))
							local y = lerp(runYEnd, impactY, smooth(clamp(w, 0, 1)))
							rootPos = Vector3.new(impactRoot.X, y, impactRoot.Z)
							local k = (t - T2) / (T4 - T2)
							local arc = math.sin(clamp(k / kA, 0, 1) * math.pi / 2)
							local crouch = (w < 0.22) and math.sin(w / 0.22 * math.pi) or 0
							p.rs = lerp(math.rad(145), math.rad(222), u)
							p.ls = lerp(0, math.rad(165), u)
							p.rh = lerp(0, -0.45, u)
							p.lh = lerp(0, 0.45, u)
							p.lean = lerp(-0.3, 0.32, u) - crouch * 0.28
							p.bounce = arc * 1.5 - crouch * 0.4
							p.twist = math.sin(w * math.pi) * 0.12
							rate = 16
						elseif t < T4 then
							-- đập xuống (không làm mượt để đầu búa trúng đúng hố)
							local w = (t - T3) / BAN.SmashTime
							local u = easeInQuad(clamp(w, 0, 1))
							local k = (t - T2) / (T4 - T2)
							local arc = math.cos(clamp((k - kA) / (1 - kA), 0, 1) * math.pi / 2)
							rootPos = impactRoot
							p.rs = lerp(math.rad(222), thetaHit, u)
							p.ls = lerp(math.rad(165), math.rad(60), u)
							p.rh = lerp(-0.45, -0.5, u)
							p.lh = lerp(0.45, 0.5, u)
							p.lean = lerp(0.32, leanHit, u)
							p.bounce = arc * 1.5 * (1 - u)
							rate = 1e4
						else
							if not impacted then
								doImpact()
							end
							local e = t - T4
							local k = math.exp(-e * 6)
							rootPos = impactRoot
							p.rs = thetaHit + 0.1 * k * math.sin(e * 30)
							p.ls = math.rad(60)
							p.rh = -0.5
							p.lh = 0.5
							p.lean = leanHit + 0.05 * k
							p.bounce = 0
							rate = 1e4
						end

						lastRoot = rootPos
						hrp.CFrame = CFrame.lookAt(rootPos, rootPos + f)
						applyPose(J, blendPose(p, rate, dt))

						if airMode then
							dust.Rate = 0
						else
							if t >= T1 then
								dust.Rate = running and (14 * sf) or 0
							end
						end
						if t >= T1 then
							feet.CFrame = CFrame.new(rootPos.X, floorNow + 0.2, rootPos.Z)
						else
							feet.CFrame = CFrame.new(rootPos.X, ((not airMode) and startFloor or groundY) + 0.2, rootPos.Z)
							if airMode then
								feet.CFrame = CFrame.new(rootPos.X, rootPos.Y - 3 * S, rootPos.Z)
							end
						end

						-- búa: ánh sáng + gồng năng lượng + quả cầu quay
						do
							local charge = 0
							if t >= T2 and t < T4 then
								charge = clamp((t - T2) / BAN.WindupTime, 0, 1)
							elseif t >= T4 then
								charge = 1
							end
							if not hammerKilled then
								fxH.light.Brightness = 1.2 + charge * 7 + math.sin(t * 8) * 0.3
								fxH.charge.Rate = (t >= T2 and t < T3) and (90 * charge) or 0
								orbSpin += dt * (2.5 + charge * 9)
								for i, o in ipairs(H.orbs) do
									local a = orbSpin * ((i == 1) and 1 or -1) + o.phase
									o.weld.C0 = CFrame.new(math.cos(a) * o.r * S, math.sin(a) * o.r * S, o.z * S)
								end
							end
						end

						-- tan rã dần
						if t >= TD and not hammerKilled then
							hammerKilled = true
							fxH.kill()
						end
						for _, g in ipairs(groups) do
							local u = clamp((t - TD - g.delay) / BAN.DisFade, 0, 1)
							if u > 0 then
								if not g.emitted then
									g.emitted = true
									g.emitter:Emit(18)
									g.embers:Emit(18)
									g.sparks:Emit(14)
								end
								g.emitter.Rate = (u < 1) and 24 or 0
								g.embers.Rate = (u < 1) and 20 or 0
								g.sparks.Rate = (u < 1) and 14 or 0
								local o = CFrame.new(g.dir * (u * u)) * CFrame.Angles(g.spin.X * u, g.spin.Y * u, g.spin.Z * u)
								if g.base then
									g.joint.C0 = g.base * o
								else
									g.joint.C0 = g.joint.C0 * o
								end
								for _, it in ipairs(g.items) do
									it.obj.Transparency = it.orig + (1 - it.orig) * u
								end
							end
						end

						-- mảnh vụn bay
						for _, d in ipairs(debris) do
							if d.part.Parent then
								local pos = d.part.Position
								d.vel += Vector3.new(0, -110 * dt, 0)
								local np = pos + d.vel * dt
								if d.floorY then
									local floorY = d.floorY + d.size * 0.4
									if np.Y < floorY then
										np = Vector3.new(np.X, floorY, np.Z)
										d.vel = Vector3.new(d.vel.X * 0.6, 0, d.vel.Z * 0.6)
										d.spin *= 0.6
									end
								end
								d.part.CFrame = CFrame.new(np) * d.part.CFrame.Rotation * CFrame.Angles(d.spin.X * dt, d.spin.Y * dt, d.spin.Z * dt)
								local age = t - d.born
								if age > d.life then
									d.part.Transparency = clamp((age - d.life) / 0.8, 0, 1)
								end
							end
						end
					end)
				end)
			end
		end

		-- ===== Black Hole Model: 3. Neon Hand Slam + 4. Giant Sword Strike =====
		do
			local PlayersSvc = game:GetService("Players")
			local TweenService = game:GetService("TweenService")

			local SND = {
				HandFall = "rbxassetid://5732991513",
				Impact = "rbxassetid://107823188661547",
				SwordSpawn = "rbxassetid://74093722719233",
				SwordFall = "rbxassetid://140300298413190",
				SwordHit = "rbxassetid://96557957751742",
			}

			local HANDCFG = {
				Scale = 3, -- bàn tay to gấp bao nhiêu lần
				AppearHeight = 210, -- xuất hiện cao bao nhiêu studs trên đầu mục tiêu
				HoverHeight = 70,
				AppearTime = 0.75,
				SlamTime = 0.3,
				HoldTime = 1.5,
				FadeTime = 0.9,
				CraterRadius = 15,
			}

			local SWCFG = {
				BigScale = 3,
				SmallScale = 0.34,
				SmallCount = 4,
				OrbitRadius = 9,
				LiftHeight = 7,
				SpawnHeight = 150,
				CraterRadius = 13,
			}

			local WHITE = Color3.fromRGB(255, 255, 255)
			local ICE = Color3.fromRGB(150, 225, 255)
			local GOLD = Color3.fromRGB(255, 205, 90)

			local TEX_SMOKE = "rbxasset://textures/particles/smoke_main.dds"
			local TEX_SPARK = "rbxasset://textures/particles/sparkles_main.dds"

			local function rnd(a, b) return a + math.random() * (b - a) end
			local function lerp(a, b, u) return a + (b - a) * u end
			local function easeOutQuad(u) return 1 - (1 - u) * (1 - u) end
			local function easeInCubic(u) return u * u * u end
			local function easeOutBack(u)
				local c1 = 1.70158
				local c3 = c1 + 1
				return 1 + c3 * (u - 1) ^ 3 + c1 * (u - 1) ^ 2
			end

			local function seq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = NumberSequenceKeypoint.new(k[1], k[2])
				end
				return NumberSequence.new(kps)
			end

			local function cseq(...)
				local kps = {}
				for _, k in ipairs({ ... }) do
					kps[#kps + 1] = ColorSequenceKeypoint.new(k[1], k[2])
				end
				return ColorSequence.new(kps)
			end

			-- part anchored (mặc định neon)
			local function mkp(parent, props)
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanTouch = false
				p.CanQuery = false
				p.CastShadow = false
				p.Massless = true
				p.TopSurface = Enum.SurfaceType.Smooth
				p.BottomSurface = Enum.SurfaceType.Smooth
				p.Material = Enum.Material.Neon
				for k, v in pairs(props) do
					p[k] = v
				end
				p.Parent = parent
				return p
			end

			local function lineP(parent, a, b, thick, color, tr)
				local d = (b - a).Magnitude
				if d < 0.01 then
					d = 0.01
				end
				return mkp(parent, {
					Name = "NT_Line",
					Size = Vector3.new(thick, thick, d * 1.06),
					Color = color,
					Transparency = tr or 0,
					CFrame = CFrame.lookAt((a + b) / 2, b),
				})
			end

			local function sfx(id, parent, vol, looped)
				local s = Instance.new("Sound")
				s.SoundId = id
				s.Volume = vol or 3
				s.Looped = looped or false
				s.RollOffMode = Enum.RollOffMode.InverseTapered
				s.RollOffMinDistance = 80
				s.RollOffMaxDistance = 900
				s.Parent = parent
				s:Play()
				if not looped then
					task.delay(15, function()
						if s.Parent then
							s:Destroy()
						end
					end)
				end
				return s
			end

			-- part vô hình đứng yên để phát âm thanh / particle
			local function emitter(pos)
				local e = mkp(workspace, { Name = "NT_SFX", Size = Vector3.one, Transparency = 1, CFrame = CFrame.new(pos) })
				task.delay(15, function()
					if e.Parent then
						e:Destroy()
					end
				end)
				return e
			end

			-- mặt đất dưới hố đen
			local function getGround(hole)
				local ign = { hole.Parent }
				for _, pl in ipairs(PlayersSvc:GetPlayers()) do
					if pl.Character then
						ign[#ign + 1] = pl.Character
					end
				end
				local rp = RaycastParams.new()
				rp.FilterType = Enum.RaycastFilterType.Exclude
				rp.FilterDescendantsInstances = ign
				local r = workspace:Raycast(hole.Position + Vector3.new(0, 6, 0), Vector3.new(0, -600, 0), rp)
				if r then
					return r.Position.Y, r.Instance
				end
				return hole.Position.Y - 3, nil
			end

			-- người bị kick (HRP bị anchor) gần hố đen
			local function victimCtl(pos)
				local best, bd = nil, 14
				for _, pl in ipairs(PlayersSvc:GetPlayers()) do
					local ch = pl.Character
					local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
					if hrp and hrp.Anchored then
						local d = (hrp.Position - pos).Magnitude
						if d < bd then
							best, bd = ch, d
						end
					end
				end
				if not best then
					return nil
				end
				local ok, base = pcall(function()
					return best:GetPivot()
				end)
				if not ok then
					return nil
				end
				local c = { ch = best, base = base }
				function c.set(cf)
					pcall(function()
						if best.Parent then
							best:PivotTo(cf)
						end
					end)
				end
				function c.restore()
					c.set(base)
				end
				return c
			end

			-- chạy animation theo thời gian, trả false nếu bị huỷ
			local function anim(dur, fn)
				local t = 0
				while t < dur do
					local dt = RunService.RenderStepped:Wait()
					if flag11 then
						return false
					end
					t = t + dt
					fn(math.min(t / dur, 1), dt)
				end
				return true
			end

			local function shake(mag, dur)
				local t = 0
				local conn
				conn = RunService.RenderStepped:Connect(function(dt)
					t = t + dt
					if t > dur then
						conn:Disconnect()
						return
					end
					local cam = workspace.CurrentCamera
					if cam then
						local k = (1 - t / dur) * mag
						cam.CFrame = cam.CFrame * CFrame.new(rnd(-k, k), rnd(-k, k), 0) * CFrame.Angles(0, 0, rnd(-k, k) * 0.02)
					end
				end)
			end

			local function shock(position, color, maxDiameter, time)
				local p = mkp(workspace, {
					Name = "NT_Shock",
					Shape = Enum.PartType.Cylinder,
					Size = Vector3.new(0.4, 4, 4),
					Color = color,
					Transparency = 0.15,
					CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.pi / 2),
				})
				TweenService:Create(p, TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Size = Vector3.new(0.4, maxDiameter, maxDiameter),
					Transparency = 1,
				}):Play()
				task.delay(time + 0.2, function()
					p:Destroy()
				end)
			end

			local function dust(center, gy, n)
				local a = mkp(workspace, { Name = "NT_Dust", Size = Vector3.one, Transparency = 1, CFrame = CFrame.new(center.X, gy + 1, center.Z) })
				local pe = Instance.new("ParticleEmitter")
				pe.Texture = TEX_SMOKE
				pe.Rate = 0
				pe.Lifetime = NumberRange.new(1.2, 2.2)
				pe.Speed = NumberRange.new(25, 60)
				pe.SpreadAngle = Vector2.new(80, 80)
				pe.Size = seq({ 0, 6 }, { 1, 20 })
				pe.Transparency = seq({ 0, 0.3 }, { 1, 1 })
				pe.Color = cseq({ 0, Color3.fromRGB(190, 185, 180) }, { 1, Color3.fromRGB(60, 58, 56) })
				pe.Drag = 3
				pe.Rotation = NumberRange.new(0, 360)
				pe.RotSpeed = NumberRange.new(-60, 60)
				pe.Parent = a
				pe:Emit(n)

				local l = Instance.new("PointLight")
				l.Color = ICE
				l.Brightness = 10
				l.Range = 90
				l.Parent = a
				TweenService:Create(l, TweenInfo.new(0.7), { Brightness = 0 }):Play()

				task.delay(4, function()
					a:Destroy()
				end)
			end

			-- mảnh vụn bay lên rồi rơi xuống đất
			local function debrisBurst(center, gy, count, power, color, mat)
				local list = {}
				for i = 1, count do
					local sz = rnd(0.8, 3.2)
					local p = mkp(workspace, {
						Name = "NT_Debris",
						Size = Vector3.new(sz * rnd(0.6, 1.4), sz * rnd(0.6, 1.4), sz * rnd(0.6, 1.4)),
						Color = color:Lerp(Color3.new(0, 0, 0), rnd(0, 0.45)),
						Material = mat,
						CFrame = CFrame.new(center + Vector3.new(rnd(-4, 4), 1, rnd(-4, 4))) * CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6)),
					})
					local a = rnd(0, math.pi * 2)
					local sp = rnd(0.25, 1) * power
					list[i] = {
						p = p,
						v = Vector3.new(math.cos(a) * sp, rnd(0.5, 1) * power * 1.1, math.sin(a) * sp),
						w = Vector3.new(rnd(-8, 8), rnd(-8, 8), rnd(-8, 8)),
						life = rnd(2.2, 3.6),
						landed = false,
					}
				end

				local t0 = 0
				local conn
				conn = RunService.Heartbeat:Connect(function(dt)
					t0 = t0 + dt
					local alive = false
					for _, d in ipairs(list) do
						local p = d.p
						if p.Parent then
							alive = true
							if flag11 then
								p:Destroy()
							else
								if not d.landed then
									d.v = d.v + Vector3.new(0, -workspace.Gravity * 0.7 * dt, 0)
									local np = p.Position + d.v * dt
									local floorY = gy + p.Size.Y * 0.4
									if np.Y <= floorY and d.v.Y < 0 then
										np = Vector3.new(np.X, floorY, np.Z)
										d.v = Vector3.new(d.v.X * 0.4, -d.v.Y * 0.25, d.v.Z * 0.4)
										if d.v.Y < 4 then
											d.landed = true
										end
									end
									p.CFrame = CFrame.new(np) * (p.CFrame - p.Position) * CFrame.Angles(d.w.X * dt, d.w.Y * dt, d.w.Z * dt)
								end
								if t0 > d.life then
									local f = (t0 - d.life) / 0.6
									if f >= 1 then
										p:Destroy()
									else
										p.Transparency = f
									end
								end
							end
						end
					end
					if not alive then
						conn:Disconnect()
					end
				end)
			end

			-- hố lớn: đĩa tối + vành đá + vết nứt
			local function crater(center, gy, radius, color, life)
				local bag = {}
				local function add(o)
					bag[#bag + 1] = o
					return o
				end
				local function disc(d, col, y)
					return add(mkp(workspace, {
						Name = "NT_Crater",
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(0.25, d, d),
						Color = col,
						Material = Enum.Material.Slate,
						CFrame = CFrame.new(center.X, gy + y, center.Z) * CFrame.Angles(0, 0, math.pi / 2),
					}))
				end
				disc(radius * 2, Color3.fromRGB(42, 34, 29), 0.1)
				disc(radius * 1.5, Color3.fromRGB(22, 18, 16), 0.15)
				disc(radius * 0.9, Color3.fromRGB(6, 5, 5), 0.2)

				for i = 1, 18 do
					local a = i / 18 * math.pi * 2 + rnd(-0.1, 0.1)
					local r = radius * rnd(0.95, 1.15)
					local sz = rnd(1.6, 3.4)
					add(mkp(workspace, {
						Name = "NT_Rock",
						Size = Vector3.new(sz * rnd(0.8, 1.6), sz * rnd(0.5, 1), sz * rnd(0.8, 1.6)),
						Color = color:Lerp(Color3.new(0, 0, 0), rnd(0.1, 0.4)),
						Material = Enum.Material.Slate,
						CFrame = CFrame.new(center.X + math.cos(a) * r, gy + sz * 0.3, center.Z + math.sin(a) * r) * CFrame.Angles(rnd(-0.5, 0.5), rnd(0, 6), rnd(-0.5, 0.5)),
					}))
				end

				for i = 1, 10 do
					local a = rnd(0, math.pi * 2)
					local len = rnd(radius * 0.8, radius * 2.2)
					local dir = Vector3.new(math.cos(a), 0, math.sin(a))
					local mid = Vector3.new(center.X, gy + 0.2, center.Z) + dir * (radius * 0.8 + len / 2)
					add(mkp(workspace, {
						Name = "NT_Crack",
						Size = Vector3.new(0.5, 0.2, len),
						Color = Color3.fromRGB(10, 8, 8),
						Material = Enum.Material.Slate,
						CFrame = CFrame.lookAt(mid, mid + dir),
					}))
				end

				task.delay(life, function()
					for _, o in ipairs(bag) do
						if o.Parent then
							TweenService:Create(o, TweenInfo.new(1), { Transparency = 1 }):Play()
						end
					end
					task.delay(1.2, function()
						for _, o in ipairs(bag) do
							o:Destroy()
						end
					end)
				end)
			end

			local function fadeModel(m, t)
				for _, d in ipairs(m:GetDescendants()) do
					if d:IsA("BasePart") then
						TweenService:Create(d, TweenInfo.new(t), { Transparency = 1 }):Play()
					elseif d:IsA("ParticleEmitter") or d:IsA("Trail") then
						d.Enabled = false
					elseif d:IsA("PointLight") then
						TweenService:Create(d, TweenInfo.new(t), { Brightness = 0 }):Play()
					end
				end
				pcall(function()
					for _, d in ipairs(m:GetChildren()) do
						if d:IsA("Highlight") then
							TweenService:Create(d, TweenInfo.new(t), { OutlineTransparency = 1 }):Play()
						end
					end
				end)
			end

			-- vòng ma thuật nằm ngang + ngôi sao 6 cánh
			local function magicCircle(center, radius, color)
				local m = Instance.new("Model")
				m.Name = "NT_MagicCircle"
				local segs = 48
				local function circ(r, thick)
					for i = 1, segs do
						local a1 = (i - 1) / segs * math.pi * 2
						local a2 = i / segs * math.pi * 2
						lineP(m, center + Vector3.new(math.cos(a1) * r, 0, math.sin(a1) * r), center + Vector3.new(math.cos(a2) * r, 0, math.sin(a2) * r), thick, color, 0.1)
					end
				end
				circ(radius, 0.7)
				circ(radius * 0.82, 0.4)
				local pts = {}
				for i = 1, 6 do
					local a = (i - 1) / 6 * math.pi * 2
					pts[i] = center + Vector3.new(math.cos(a) * radius * 0.82, 0, math.sin(a) * radius * 0.82)
				end
				for i = 1, 6 do
					lineP(m, pts[i], pts[(i + 1) % 6 + 1], 0.45, color, 0.15)
				end
				m.WorldPivot = CFrame.new(center)
				m.Parent = workspace
				return m
			end

			-- ===== BÀN TAY neon trắng (bàn tay úp xuống, ngón chỉ về -Z) =====
			local function buildHand()
				local m = Instance.new("Model")
				m.Name = "NT_NeonHand"
				local function add(name, size, cf, col, tr, shape)
					local p = mkp(m, { Name = name, Size = size, CFrame = cf, Color = col, Transparency = tr or 0 })
					if shape then
						p.Shape = shape
					end
					return p
				end

				local palm = add("Palm", Vector3.new(8, 1.8, 8), CFrame.new(), WHITE, 0)
				m.PrimaryPart = palm
				add("PalmGlow", Vector3.new(9.4, 3, 9.4), CFrame.new(), ICE, 0.72)

				local xs = { -3, -1, 1, 3 }
				local lens = { 5.0, 6.2, 5.6, 4.4 }
				for i, x in ipairs(xs) do
					local L = lens[i]
					local cf1 = CFrame.new(x, -0.05, -(4 + L * 0.275))
					add("F" .. i .. "a", Vector3.new(1.7, 1.6, L * 0.55), cf1, WHITE, 0)
					add("F" .. i .. "aG", Vector3.new(2.3, 2.2, L * 0.55 + 0.3), cf1, ICE, 0.75)
					local cf2 = CFrame.new(x, -0.35, -(4 + L * 0.55 + L * 0.225)) * CFrame.Angles(math.rad(10), 0, 0)
					add("F" .. i .. "b", Vector3.new(1.55, 1.45, L * 0.45), cf2, WHITE, 0)
					add("F" .. i .. "bG", Vector3.new(2.1, 2, L * 0.45 + 0.3), cf2, ICE, 0.75)
					add("F" .. i .. "tip", Vector3.one * 1.55, CFrame.new(x, -0.5, -(4 + L) - 0.1), WHITE, 0, Enum.PartType.Ball)
					add("F" .. i .. "knuckle", Vector3.one * 1.9, CFrame.new(x, 0, -4), WHITE, 0, Enum.PartType.Ball)
				end

				add("Th1", Vector3.new(1.9, 1.7, 3.6), CFrame.new(4.9, -0.1, -1.4) * CFrame.Angles(0, math.rad(-38), 0), WHITE, 0)
				add("Th2", Vector3.new(1.7, 1.5, 3), CFrame.new(6.9, -0.3, -4.0) * CFrame.Angles(0, math.rad(-38), 0), WHITE, 0)
				add("ThTip", Vector3.one * 1.6, CFrame.new(7.8, -0.4, -5.4), WHITE, 0, Enum.PartType.Ball)

				-- cánh tay kéo dài lên trời
				add("Arm", Vector3.new(90, 4.6, 4.6), CFrame.new(0, 0.9 + 45, 3.4) * CFrame.Angles(0, 0, math.pi / 2), WHITE, 0.2, Enum.PartType.Cylinder)
				add("ArmGlow", Vector3.new(90, 6.6, 6.6), CFrame.new(0, 0.9 + 45, 3.4) * CFrame.Angles(0, 0, math.pi / 2), ICE, 0.82, Enum.PartType.Cylinder)
				add("Cuff", Vector3.new(1.6, 6.4, 6.4), CFrame.new(0, 3.6, 3.4) * CFrame.Angles(0, 0, math.pi / 2), ICE, 0, Enum.PartType.Cylinder)

				local light = Instance.new("PointLight")
				light.Color = ICE
				light.Brightness = 6
				light.Range = 70
				light.Parent = palm

				local a0 = Instance.new("Attachment")
				a0.Position = Vector3.new(-4, 0, 0)
				a0.Parent = palm
				local a1 = Instance.new("Attachment")
				a1.Position = Vector3.new(4, 0, 0)
				a1.Parent = palm
				local tr = Instance.new("Trail")
				tr.Attachment0 = a0
				tr.Attachment1 = a1
				tr.Lifetime = 0.35
				tr.LightEmission = 1
				tr.LightInfluence = 0
				tr.FaceCamera = true
				tr.Color = cseq({ 0, WHITE }, { 1, ICE })
				tr.Transparency = seq({ 0, 0.2 }, { 1, 1 })
				tr.Parent = palm

				local pe = Instance.new("ParticleEmitter")
				pe.Texture = TEX_SPARK
				pe.Rate = 60
				pe.Lifetime = NumberRange.new(0.6, 1.1)
				pe.Speed = NumberRange.new(4, 12)
				pe.SpreadAngle = Vector2.new(180, 180)
				pe.Size = seq({ 0, 1.6 }, { 1, 0 })
				pe.Transparency = seq({ 0, 0.1 }, { 1, 1 })
				pe.Color = ColorSequence.new(WHITE)
				pe.LightEmission = 1
				pe.Parent = palm

				pcall(function()
					local h = Instance.new("Highlight")
					h.Adornee = m
					h.FillTransparency = 1
					h.OutlineColor = ICE
					h.OutlineTransparency = 0
					h.Parent = m
				end)

				return m
			end

			-- ===== THANH KIẾM (mũi ở gốc toạ độ, thân hướng lên +Y) =====
			-- trailMode: "vert" cho kiếm quay vòng, "horiz" cho kiếm rơi
			local function buildSword(trailMode)
				local m = Instance.new("Model")
				m.Name = "NT_Sword"
				local w, BL = 2.6, 14
				local function add(name, size, cf, col, tr, shape)
					local p = mkp(m, { Name = name, Size = size, CFrame = cf, Color = col, Transparency = tr or 0 })
					if shape then
						p.Shape = shape
					end
					return p
				end

				local BLADE = Color3.fromRGB(235, 248, 255)
				local s = w * 0.7071
				add("Tip", Vector3.new(s, s, 0.5), CFrame.new(0, w * 0.5, 0) * CFrame.Angles(0, 0, math.rad(45)), BLADE, 0)
				add("TipGlow", Vector3.new(s + 0.9, s + 0.9, 0.9), CFrame.new(0, w * 0.5, 0) * CFrame.Angles(0, 0, math.rad(45)), ICE, 0.78)
				local blade = add("Blade", Vector3.new(w, BL, 0.5), CFrame.new(0, w + BL / 2, 0), BLADE, 0)
				m.PrimaryPart = blade
				add("BladeGlow", Vector3.new(w + 0.9, BL, 0.9), CFrame.new(0, w + BL / 2, 0), ICE, 0.78)
				add("Fuller", Vector3.new(0.5, BL * 0.8, 0.7), CFrame.new(0, w + BL / 2, 0), ICE, 0.1)

				local gy = w + BL + 0.4
				add("Guard", Vector3.new(w * 2.4, 0.8, 1.1), CFrame.new(0, gy, 0), GOLD, 0)
				add("WingL", Vector3.new(0.8, 1.8, 1.1), CFrame.new(-w * 1.2, gy + 0.6, 0) * CFrame.Angles(0, 0, math.rad(20)), GOLD, 0)
				add("WingR", Vector3.new(0.8, 1.8, 1.1), CFrame.new(w * 1.2, gy + 0.6, 0) * CFrame.Angles(0, 0, math.rad(-20)), GOLD, 0)
				add("Gem", Vector3.new(0.9, 0.9, 1.3), CFrame.new(0, gy, 0) * CFrame.Angles(0, 0, math.rad(45)), ICE, 0)
				add("Grip", Vector3.new(3.2, 1.2, 1.2), CFrame.new(0, gy + 0.4 + 1.6, 0) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(60, 80, 140), 0.1, Enum.PartType.Cylinder)
				add("Pommel", Vector3.one * 2, CFrame.new(0, gy + 0.4 + 3.2 + 0.8, 0), GOLD, 0, Enum.PartType.Ball)

				local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
				if trailMode == "horiz" then
					a0.Position = Vector3.new(-w / 2, -BL / 2, 0)
					a1.Position = Vector3.new(w / 2, -BL / 2, 0)
				else
					a0.Position = Vector3.new(0, -BL / 2, 0)
					a1.Position = Vector3.new(0, BL / 2, 0)
				end
				a0.Parent = blade
				a1.Parent = blade
				local tr = Instance.new("Trail")
				tr.Name = "NT_SwordTrail"
				tr.Attachment0 = a0
				tr.Attachment1 = a1
				tr.Lifetime = trailMode == "horiz" and 0.5 or 0.45
				tr.LightEmission = 1
				tr.LightInfluence = 0
				tr.FaceCamera = true
				tr.Color = cseq({ 0, WHITE }, { 0.5, ICE }, { 1, Color3.fromRGB(80, 120, 255) })
				tr.Transparency = seq({ 0, 0.1 }, { 1, 1 })
				tr.WidthScale = seq({ 0, 1 }, { 1, 0.3 })
				tr.Enabled = trailMode ~= "horiz"
				tr.Parent = blade

				local light = Instance.new("PointLight")
				light.Color = ICE
				light.Brightness = 3
				light.Range = 40
				light.Parent = blade

				local pe = Instance.new("ParticleEmitter")
				pe.Texture = TEX_SPARK
				pe.Rate = 25
				pe.Lifetime = NumberRange.new(0.5, 1)
				pe.Speed = NumberRange.new(2, 8)
				pe.SpreadAngle = Vector2.new(180, 180)
				pe.Size = seq({ 0, 1.4 }, { 1, 0 })
				pe.Transparency = seq({ 0, 0.1 }, { 1, 1 })
				pe.Color = ColorSequence.new(WHITE)
				pe.LightEmission = 1
				pe.Parent = blade

				return m
			end

			-- ===== 1. BÀN TAY NEON ĐÈ XUỐNG =====
			tbl12.PlayHandSlam = function(hole)
				if not hole or not hole:IsA("BasePart") then
					return
				end

				task.spawn(function()
					local origin = hole.Position
					local gy, gInst = getGround(hole)
					local gcol = (gInst and gInst:IsA("BasePart")) and gInst.Color or Color3.fromRGB(95, 85, 75)
					local gmat = (gInst and gInst:IsA("BasePart") and gInst.Material ~= Enum.Material.Neon) and gInst.Material or Enum.Material.Slate
					local victim = victimCtl(origin)
					local S = HANDCFG.Scale

					local hand = buildHand()
					hand.Parent = workspace
					pcall(function()
						hand:ScaleTo(S)
					end)

					local cam = workspace.CurrentCamera
					local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
					look = Vector3.new(look.X, 0, look.Z)
					if look.Magnitude < 0.1 then
						look = Vector3.new(0, 0, -1)
					end
					local yaw = CFrame.lookAt(Vector3.zero, look.Unit)
					local palmY = gy + 1.4 + 0.9 * S + 0.2
					local function place(h)
						hand:PivotTo(CFrame.new(origin.X, palmY + h, origin.Z) * yaw)
					end

					local ring = magicCircle(Vector3.new(origin.X, gy + 0.2, origin.Z), 16, ICE)
					local ringAng = 0

					local function cleanup()
						if hand.Parent then
							hand:Destroy()
						end
						if ring.Parent then
							ring:Destroy()
						end
						if victim then
							victim.restore()
						end
					end

					place(HANDCFG.AppearHeight)
					local fall = sfx(SND.HandFall, hand.PrimaryPart, 4, true)

					local alive = anim(HANDCFG.AppearTime, function(u, dt)
						place(lerp(HANDCFG.AppearHeight, HANDCFG.HoverHeight, easeOutQuad(u)))
						ringAng = ringAng + dt * 2
						ring:PivotTo(CFrame.new(origin.X, gy + 0.2, origin.Z) * CFrame.Angles(0, ringAng, 0))
					end)
					if alive then
						alive = anim(HANDCFG.SlamTime, function(u, dt)
							place(lerp(HANDCFG.HoverHeight, 0, easeInCubic(u)))
							ringAng = ringAng + dt * 4
							ring:PivotTo(CFrame.new(origin.X, gy + 0.2, origin.Z) * CFrame.Angles(0, ringAng, 0))
						end)
					end

					if fall then
						fall:Stop()
						fall:Destroy()
					end
					if not alive then
						cleanup()
						return
					end

					-- === chạm mục tiêu ===
					local at = Vector3.new(origin.X, gy, origin.Z)
					local e = emitter(at)
					sfx(SND.Impact, e, 6)
					ring:Destroy()

					if victim then
						victim.set(CFrame.new(origin.X, gy + 1.0, origin.Z) * yaw * CFrame.Angles(math.rad(-90), 0, 0))
					end

					crater(at, gy, HANDCFG.CraterRadius, gcol, 5)
					debrisBurst(at, gy, 55, 70, gcol, gmat)
					dust(at, gy, 40)
					shock(at + Vector3.new(0, 0.3, 0), WHITE, 110, 0.8)
					shock(at + Vector3.new(0, 0.3, 0), ICE, 70, 0.6)
					shake(1.2, 0.6)

					-- bàn tay ép xuống rồi giữ
					anim(0.12, function(u)
						place(-1.0 * u)
					end)
					local t = 0
					anim(HANDCFG.HoldTime, function(u, dt)
						t = t + dt
						place(-1.0 + math.sin(t * 40) * 0.12 * (1 - u))
					end)

					-- tay nhấc lên và tan biến
					fadeModel(hand, HANDCFG.FadeTime)
					anim(HANDCFG.FadeTime, function(u)
						place(-1.0 + 70 * u * u)
					end)
					cleanup()
				end)
			end

			-- ===== 2. THANH KIẾM KHỔNG LỒ ĐÂM XUỐNG =====
			tbl12.PlaySwordStrike = function(hole)
				if not hole or not hole:IsA("BasePart") then
					return
				end

				task.spawn(function()
					local origin = hole.Position
					local gy, gInst = getGround(hole)
					local gcol = (gInst and gInst:IsA("BasePart")) and gInst.Color or Color3.fromRGB(95, 85, 75)
					local gmat = (gInst and gInst:IsA("BasePart") and gInst.Material ~= Enum.Material.Neon) and gInst.Material or Enum.Material.Slate
					local victim = victimCtl(origin)
					local center = victim and victim.base.Position or origin

					local bag = {}
					local st = { vh = 0, spin = 0, orbA = 0, orbSpeed = 2.4, orbR = SWCFG.OrbitRadius, override = false }
					local clk = 0

					local smalls = {}
					for i = 1, SWCFG.SmallCount do
						local m = buildSword("vert")
						m.Parent = workspace
						bag[#bag + 1] = m
						pcall(function()
							m:ScaleTo(0.02)
						end)
						smalls[i] = { m = m, sc = 0.02, t0 = (i - 1) * 0.18, dead = false }
					end

					local conn = RunService.RenderStepped:Connect(function(dt)
						if flag11 then
							return
						end
						clk = clk + dt
						st.spin = st.spin + dt * 0.9
						st.orbA = st.orbA + dt * st.orbSpeed

						if victim and not st.override then
							local bob = math.sin(clk * 2) * 0.4 * math.min(st.vh / 3, 1)
							victim.set(CFrame.new(center + Vector3.new(0, st.vh + bob, 0)) * CFrame.Angles(0, st.spin, 0) * victim.base.Rotation)
						end

						for i, s in ipairs(smalls) do
							if not s.dead then
								local target = (clk > s.t0) and SWCFG.SmallScale or 0.02
								local newSc = s.sc + (target - s.sc) * math.min(1, dt * 7)
								if math.abs(newSc - s.sc) > 0.001 then
									s.sc = newSc
									pcall(function()
										s.m:ScaleTo(math.max(s.sc, 0.02))
									end)
								end
								local a = st.orbA + (i - 1) * (math.pi * 2 / SWCFG.SmallCount)
								local pos = Vector3.new(center.X + math.cos(a) * st.orbR, center.Y + st.vh - 1 + math.sin(clk * 2.5 + i) * 0.5, center.Z + math.sin(a) * st.orbR)
								s.m:PivotTo(CFrame.new(pos) * CFrame.Angles(0, -a + math.pi / 2, 0) * CFrame.Angles(0, 0, math.rad(10)))
							end
						end
					end)

					local big, circle
					local function cleanup()
						conn:Disconnect()
						for _, o in ipairs(bag) do
							if o.Parent then
								o:Destroy()
							end
						end
						if big and big.Parent then
							big:Destroy()
						end
						if circle and circle.Parent then
							circle:Destroy()
						end
						if victim then
							victim.restore()
						end
					end

					-- 1) người bị kick bay lơ lửng lên
					local ok = anim(1.0, function(u)
						st.vh = SWCFG.LiftHeight * easeOutQuad(u)
					end)
					if not ok then
						cleanup()
						return
					end

					-- 2) kiếm to xuất hiện trên trời (có vòng ma thuật)
					big = buildSword("horiz")
					big.Parent = workspace
					pcall(function()
						big:ScaleTo(0.2)
					end)
					local tipHold = Vector3.new(origin.X, gy + SWCFG.SpawnHeight, origin.Z)
					local bigAng = 0
					local function placeBig(tip)
						big:PivotTo(CFrame.new(tip) * CFrame.Angles(0, bigAng, 0))
					end
					placeBig(tipHold)
					circle = magicCircle(tipHold, 34, ICE)
					local circAng = 0
					sfx(SND.SwordSpawn, big.PrimaryPart, 5)

					ok = anim(0.8, function(u, dt)
						pcall(function()
							big:ScaleTo(math.max(lerp(0.2, SWCFG.BigScale, easeOutBack(u)), 0.05))
						end)
						bigAng = bigAng + dt * 1.5
						circAng = circAng + dt * 1.2
						st.orbSpeed = lerp(2.4, 5, u)
						placeBig(tipHold)
						circle:PivotTo(CFrame.new(tipHold) * CFrame.Angles(0, circAng, 0))
					end)
					if not ok then
						cleanup()
						return
					end

					-- giữ lơ lửng
					ok = anim(0.9, function(u, dt)
						bigAng = bigAng + dt * 1.5
						circAng = circAng + dt * 1.2
						placeBig(tipHold + Vector3.new(0, math.sin(u * math.pi * 2) * 1.2, 0))
						circle:PivotTo(CFrame.new(tipHold) * CFrame.Angles(0, circAng, 0))
					end)
					if not ok then
						cleanup()
						return
					end

					-- 3) rơi xuống đâm thẳng
					local tr = big.PrimaryPart:FindFirstChild("NT_SwordTrail")
					if tr then
						tr.Enabled = true
					end
					sfx(SND.SwordFall, big.PrimaryPart, 5)
					local impactTip = Vector3.new(origin.X, gy - 1.5, origin.Z)
					ok = anim(0.5, function(u, dt)
						placeBig(tipHold:Lerp(impactTip, easeInCubic(u)))
						st.orbSpeed = lerp(5, 10, u)
						st.orbR = lerp(SWCFG.OrbitRadius, 3, u)
						circAng = circAng + dt * 3
						circle:PivotTo(CFrame.new(tipHold) * CFrame.Angles(0, circAng, 0))
					end)
					if not ok then
						cleanup()
						return
					end

					-- === chạm mục tiêu ===
					fadeModel(circle, 0.6)
					local at = Vector3.new(origin.X, gy, origin.Z)
					local e = emitter(at)
					local hs = sfx(SND.SwordHit, e, 6)
					local d2 = 0.55
					if hs.TimeLength > 0.1 then
						d2 = math.min(hs.TimeLength, 1.5)
					end
					task.delay(d2, function()
						sfx(SND.Impact, e, 6)
					end)

					st.override = true
					if victim then
						victim.set(CFrame.new(origin.X, gy + 2.5, origin.Z) * victim.base.Rotation * CFrame.Angles(math.rad(-20), 0, 0))
					end

					crater(at, gy, SWCFG.CraterRadius, gcol, 5)
					debrisBurst(at, gy, 60, 75, gcol, gmat)
					dust(at, gy, 45)
					shock(at + Vector3.new(0, 0.3, 0), WHITE, 120, 0.9)
					shock(at + Vector3.new(0, 0.3, 0), ICE, 75, 0.65)
					shake(1.5, 0.7)

					-- 4 kiếm nhỏ văng ra rồi tan
					for i, s in ipairs(smalls) do
						s.dead = true
						local a = st.orbA + (i - 1) * (math.pi * 2 / SWCFG.SmallCount)
						local dir = Vector3.new(math.cos(a), 0.6, math.sin(a))
						task.spawn(function()
							local t = 0
							while t < 0.7 and s.m.Parent and not flag11 do
								local dt = RunService.Heartbeat:Wait()
								t = t + dt
								s.m:PivotTo(s.m:GetPivot() + dir * 60 * dt * (1 - t / 0.7))
							end
							if s.m.Parent then
								fadeModel(s.m, 0.4)
							end
						end)
					end

					-- giữ kiếm cắm xuống rồi tan
					local t = 0
					ok = anim(2.0, function(u, dt)
						t = t + dt
						placeBig(impactTip + Vector3.new(math.sin(t * 45) * 0.15 * (1 - u), 0, 0))
					end)
					if ok then
						fadeModel(big, 1.0)
						task.wait(1.0)
					end
					cleanup()
				end)
			end
		end

		workspace.ChildAdded:Connect(function(child)
			if flag11 then
				return
