					clone.Parent = workspace
					local hole2 = clone:FindFirstChild("Hole")

					if v22 then
						hole2 = hole2 and hole2:FindFirstChild("Blackhole")

						if hole2 then
							hole2:Destroy()
						end

						tbl12.CreateBlackHoleESP(clone, v22)
					end

					repeat
						task.wait(0.1)
					until not tbl8.BlackholeStaying

					if clone.Parent then
						clone:Destroy()
					end
				end
			end
		end)

