		tbl7.SilentAimState = { Players = setmetatable({}, { __mode = "k" }) }
		tbl7.SilentAimState.Circle = tbl6.Frame:Clone()
		tbl7.SilentAimState.Circle.Name = "SilentAimFOV"
		tbl7.SilentAimState.Circle.Position = UDim2.fromScale(0.5, 0.5)
