    -- ============================================================
-- NULLTRUST IDLE UI (tab Menu, ngay dưới Greetings)
-- Dán khối này NGAY SAU khối Greetings, tức là sau dòng `end`
-- đóng khối `do local Greetings = ... end`, và TRƯỚC khối
-- `do local Statistics = ... end`.
-- Chuỗi hiệu ứng lặp vô hạn:
--   1) Sao + sao băng -> nối dây giữa các sao -> sao tan biến
--   2) Chữ "Null Trust" hiện mờ dần thật chậm
--   3) Sóng tròn lan toả
--   4) Đom đóm bay lên
--   5) Quỹ đạo xoay
-- ============================================================
do
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")

	local G = tbl15.Home:AddLeftGroupbox("introduce", "sparkles")

	-- khung vẽ
	local canvas = Instance.new("Frame")
	canvas.Name = "IdleCanvas"
	canvas.Size = UDim2.fromScale(1, 1)
	canvas.BackgroundColor3 = Color3.new(1, 1, 1)
	canvas.BorderSizePixel = 0
	canvas.ClipsDescendants = true
	do
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(0, 4)
		c.Parent = canvas
		local g = Instance.new("UIGradient")
		g.Rotation = 90
		g.Color = ColorSequence.new(Color3.fromRGB(8, 10, 24), Color3.fromRGB(24, 14, 48))
		g.Parent = canvas
		local s = Instance.new("UIStroke")
		s.Color = Color3.fromRGB(45, 45, 70)
		s.Parent = canvas
	end
	G:AddUIPassthrough("IdleCanvas", { Instance = canvas, Height = 170 })

	local STAR = Color3.fromRGB(195, 215, 255)
	local ACCENT = Color3.fromRGB(150, 120, 255)

	local function alive() return canvas.Parent ~= nil end
	local function size() return canvas.AbsoluteSize end
	local function tw(obj, t, props, style, dir)
		local tween = TweenService:Create(obj, TweenInfo.new(t, style or Enum.EasingStyle.Sine, dir or Enum.EasingDirection.InOut), props)
		tween:Play()
		return tween
	end
	local function wait(t) task.wait(t) return alive() end
	local function layerNew()
		local l = Instance.new("Frame")
		l.BackgroundTransparency = 1
		l.Size = UDim2.fromScale(1, 1)
		l.Parent = canvas
		return l
	end
	local function dot(parent, px, py, d, color)
		local f = Instance.new("Frame")
		f.AnchorPoint = Vector2.new(0.5, 0.5)
		f.Position = UDim2.fromOffset(px, py)
		f.Size = UDim2.fromOffset(d, d)
		f.BackgroundColor3 = color or STAR
		f.BackgroundTransparency = 1
		f.BorderSizePixel = 0
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(1, 0)
		c.Parent = f
		f.Parent = parent
		return f
	end

	-- sao băng: vệt có đuôi mờ, bay chéo
	local function shootingStar(parent)
		local W, H = size().X, size().Y
		local from = Vector2.new(math.random(0, math.floor(W * 0.7)), math.random(-10, math.floor(H * 0.35)))
		local to = from + Vector2.new(math.random(110, 190), math.random(60, 110))
		local f = Instance.new("Frame")
		f.AnchorPoint = Vector2.new(1, 0.5)
		f.Position = UDim2.fromOffset(from.X, from.Y)
		f.Size = UDim2.fromOffset(math.random(50, 80), 2)
		f.BackgroundColor3 = Color3.new(1, 1, 1)
		f.BorderSizePixel = 0
		f.Rotation = math.deg(math.atan2(to.Y - from.Y, to.X - from.X))
		local g = Instance.new("UIGradient")
		g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
		g.Parent = f
		f.Parent = parent
		local t = tw(f, 0.9, { Position = UDim2.fromOffset(to.X, to.Y) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.delay(0.9, function() f:Destroy() end)
		return t
	end

	-- ---------- Cảnh 1: chòm sao ----------
	local function sceneConstellation()
		local layer = layerNew()
		local W, H = size().X, size().Y
		local pts, stars = {}, {}
		for i = 1, 12 do
			pts[i] = Vector2.new(math.random(16, math.max(40, W - 16)), math.random(16, math.max(40, H - 16)))
			stars[i] = dot(layer, pts[i].X, pts[i].Y, math.random(3, 5))
		end
		-- sao hiện dần + sao băng
		for i, s in ipairs(stars) do
			task.delay(i * 0.12, function() if alive() then tw(s, 0.8, { BackgroundTransparency = 0.05 }) end end)
		end
		for _ = 1, 3 do
			if not wait(0.6) then return layer:Destroy() end
			shootingStar(layer)
		end
		if not wait(0.6) then return layer:Destroy() end

		-- nối mỗi sao với 2 sao gần nhất (không trùng cặp)
		local lines, done = {}, {}
		for i = 1, #pts do
			local order = {}
			for j = 1, #pts do if j ~= i then order[#order + 1] = j end end
			table.sort(order, function(a, b) return (pts[a] - pts[i]).Magnitude < (pts[b] - pts[i]).Magnitude end)
			for k = 1, 2 do
				local j = order[k]
				local key = math.min(i, j) .. "_" .. math.max(i, j)
				if not done[key] then
					done[key] = true
					local d = pts[j] - pts[i]
					local l = Instance.new("Frame")
					l.AnchorPoint = Vector2.new(0, 0.5)
					l.Position = UDim2.fromOffset(pts[i].X, pts[i].Y)
					l.Size = UDim2.fromOffset(0, 1)
					l.Rotation = math.deg(math.atan2(d.Y, d.X))
					l.BackgroundColor3 = STAR
					l.BackgroundTransparency = 0.45
					l.BorderSizePixel = 0
					l.Parent = layer
					lines[#lines + 1] = l
					task.delay(#lines * 0.08, function()
						if alive() then tw(l, 0.9, { Size = UDim2.fromOffset(d.Magnitude, 1) }) end
					end)
				end
			end
		end
		if not wait(#lines * 0.08 + 1.6) then return layer:Destroy() end
		shootingStar(layer)
		if not wait(1.2) then return layer:Destroy() end

		-- sao + dây tan biến
		for _, s in ipairs(stars) do tw(s, 1.2, { BackgroundTransparency = 1, Size = UDim2.fromOffset(0, 0) }) end
		for _, l in ipairs(lines) do tw(l, 1.2, { BackgroundTransparency = 1 }) end
		wait(1.4)
		layer:Destroy()
	end

	-- ---------- Cảnh 2: chữ Null Trust ----------
	local function sceneText()
		local layer = layerNew()
		local t = Instance.new("TextLabel")
		t.AnchorPoint = Vector2.new(0.5, 0.5)
		t.Position = UDim2.fromScale(0.5, 0.5)
		t.Size = UDim2.fromScale(1, 0.5)
		t.BackgroundTransparency = 1
		t.Text = "Null Trust"
		t.Font = Enum.Font.GothamBold
		t.TextSize = 32
		t.TextColor3 = Color3.new(1, 1, 1)
		t.TextTransparency = 1
		t.Parent = layer
		local grad = Instance.new("UIGradient")
		grad.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(156, 217, 255)),
			ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 255, 255)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(186, 164, 255)),
		})
		grad.Parent = t
		local stroke = Instance.new("UIStroke")
		stroke.Color = ACCENT
		stroke.Thickness = 2
		stroke.Transparency = 1
		stroke.Parent = t

		tw(t, 3.5, { TextTransparency = 0 })
		tw(stroke, 3.5, { Transparency = 0.7 })
		if not wait(4.2) then return layer:Destroy() end
		tw(stroke, 1, { Transparency = 0.4 })
		if not wait(1.2) then return layer:Destroy() end
		tw(stroke, 1, { Transparency = 0.7 })
		if not wait(1.4) then return layer:Destroy() end
		tw(t, 1.8, { TextTransparency = 1 })
		tw(stroke, 1.8, { Transparency = 1 })
		wait(2)
		layer:Destroy()
	end

	-- ---------- Cảnh 3: sóng tròn ----------
	local function scenePulse()
		local layer = layerNew()
		local W, H = size().X, size().Y
		local core = dot(layer, W / 2, H / 2, 8, ACCENT)
		tw(core, 0.8, { BackgroundTransparency = 0.1 })
		for i = 1, 6 do
			task.delay((i - 1) * 0.8, function()
				if not alive() then return end
				local ring = Instance.new("Frame")
				ring.AnchorPoint = Vector2.new(0.5, 0.5)
				ring.Position = UDim2.fromOffset(W / 2, H / 2)
				ring.Size = UDim2.fromOffset(8, 8)
				ring.BackgroundTransparency = 1
				ring.Parent = layer
				local c = Instance.new("UICorner")
				c.CornerRadius = UDim.new(1, 0)
				c.Parent = ring
				local s = Instance.new("UIStroke")
				s.Color = ACCENT
				s.Thickness = 2
				s.Transparency = 0.2
				s.Parent = ring
				local d = math.max(W, H) * 0.9
				tw(ring, 2.6, { Size = UDim2.fromOffset(d, d) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				tw(s, 2.6, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				task.delay(2.7, function() ring:Destroy() end)
			end)
		end
		if not wait(6.8) then return layer:Destroy() end
		tw(core, 0.8, { BackgroundTransparency = 1 })
		wait(0.9)
		layer:Destroy()
	end

	-- ---------- Cảnh 4: đom đóm bay lên ----------
	local function sceneFireflies()
		local layer = layerNew()
		local W, H = size().X, size().Y
		for i = 1, 22 do
			task.delay(math.random() * 3, function()
				if not alive() then return end
				local x = math.random(8, math.max(20, W - 8))
				local f = dot(layer, x, H + 6, math.random(2, 4), (i % 2 == 0) and STAR or ACCENT)
				local dur = 2.5 + math.random() * 2
				tw(f, 0.6, { BackgroundTransparency = 0.1 })
				tw(f, dur, { Position = UDim2.fromOffset(x + math.random(-30, 30), math.random(-10, math.floor(H * 0.4))) }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
				task.delay(dur - 0.8, function() if alive() then tw(f, 0.8, { BackgroundTransparency = 1 }) end end)
				task.delay(dur + 0.1, function() f:Destroy() end)
			end)
		end
		wait(6.5)
		layer:Destroy()
	end

	-- ---------- Cảnh 5: quỹ đạo xoay ----------
	local function sceneOrbit()
		local layer = layerNew()
		local W, H = size().X, size().Y
		local cx, cy = W / 2, H / 2
		local core = dot(layer, cx, cy, 10, Color3.new(1, 1, 1))
		tw(core, 0.8, { BackgroundTransparency = 0.05 })
		local orbs = {}
		for i = 1, 3 do
			local o = dot(layer, cx, cy, 6 - i, i == 2 and ACCENT or STAR)
			tw(o, 0.8, { BackgroundTransparency = 0.05 })
			orbs[i] = { o = o, r = 18 + i * 14, speed = (1.6 - i * 0.3) * (i % 2 == 0 and -1 or 1), a = i * 2.1 }
		end
		local t0, last = os.clock(), os.clock()
		while alive() and os.clock() - t0 < 6.5 do
			local now = os.clock()
			local dt = now - last
			last = now
			for _, e in ipairs(orbs) do
				e.a += e.speed * dt
				e.o.Position = UDim2.fromOffset(cx + math.cos(e.a) * e.r * 1.5, cy + math.sin(e.a) * e.r * 0.8)
			end
			RunService.Heartbeat:Wait()
		end
		tw(core, 0.8, { BackgroundTransparency = 1 })
		for _, e in ipairs(orbs) do tw(e.o, 0.8, { BackgroundTransparency = 1 }) end
		wait(0.9)
		layer:Destroy()
	end

	-- vòng lặp chính
	task.spawn(function()
		local scenes = { sceneConstellation, sceneText, scenePulse, sceneFireflies, sceneOrbit, sceneText }
		repeat task.wait(0.3) until not alive() or size().X > 10
		while alive() do
			for _, scene in ipairs(scenes) do
				if not alive() then return end
				local ok, err = pcall(scene)
				if not ok then warn("[idle ui]", err) task.wait(1) end
			end
		end
	end)
end

