						pcall(function()
							local res = HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v2/games/" .. gameId .. "/media"))
							for _, m in ipairs(res.data or {}) do
								if m.assetType == "Image" and m.imageId and m.approved ~= false then
									covers[#covers + 1] = "rbxassetid://" .. m.imageId
								end
							end
						end)

						-- Cách 2 (dự phòng): tải thumbnail về rồi dùng getcustomasset
						if #covers == 0 and writefile and getcustomasset then
							pcall(function()
								local res = HttpService:JSONDecode(game:HttpGet(
									"https://thumbnails.roblox.com/v1/games/multiget/thumbnails?universeIds=" .. gameId
									.. "&countPerUniverse=10&size=768x432&format=Png&isCircular=false"))
								local items = res.data and res.data[1] and res.data[1].thumbnails or {}
								for i, t in ipairs(items) do
									if t.state == "Completed" and t.imageUrl then
										local name = "nt_cover_" .. gameId .. "_" .. i .. ".png"
										writefile(name, game:HttpGet(t.imageUrl))
										covers[#covers + 1] = getcustomasset(name)
									end
								end
							end)
						end

						-- Không có ảnh bìa nào thì dùng icon game
						if #covers == 0 then
							front.Image = string.format("rbxthumb://type=GameIcon&id=%d&w=256&h=256", gameId)
							return
						end

						local i = 1
						front.Image = covers[1]
						while not cover.Destroyed and front.Parent do
							task.wait(5)
							if #covers > 1 and front.Parent then
								i = i % #covers + 1
								back.Image = covers[i]
								task.wait(0.2)
								local tw = TweenService:Create(back, TweenInfo.new(1, Enum.EasingStyle.Sine), { ImageTransparency = 0 })
								tw:Play()
								tw.Completed:Wait()
								front.Image = covers[i]
								back.ImageTransparency = 1
							end
						end
					end)
				end
			end

