		-- =====================================================
		-- ANTI RAGDOLL+ / ANTI STUCK+  (shuriken, food, vat dinh tren nguoi)
		--  * Ragdolled bat -> dung day lai ngay moi frame (bat Motor6D, tat BallSocket, GettingUp)
		--  * Moi frame go moi Weld/WeldConstraint noi nhan vat voi toy la (shuriken, food...)
		--  * Tu dong chay, khong phu thuoc toggle khac. Tam nghi khi: bi grab / dang Anti Grab / Gucci
		-- =====================================================
		do
			local RS = game:GetService("RunService")
			local plusConns = {}
			local LIMBS = { "Left Leg", "Right Leg", "Left Arm", "Right Arm", "Head" }

			local function ownFolder()
				return workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
			end

			local function paused()
				local held = localPlayer:FindFirstChild("IsHeld")
				return (held and held.Value) or tbl7.States["Anti Grab"] or tbl8.GucciAntiGrab or tbl7.States.Escaping
			end

			local function isToyPart(part)
				local model = part:FindFirstAncestorOfClass("Model")
				while model do
					if model:FindFirstChild("StickyPart") or model:FindFirstChild("HoldPart") or model.Name:find("^Food") or model.Name:find("Shuriken") or model.Name:find("Creature") or model.Name:find("Blobman") then
						return true
					end
					model = model.Parent and model.Parent:FindFirstAncestorOfClass("Model")
				end
				return part.Name == "StickyPart" or part.Name == "HoldPart"
			end

			local function unragdoll(char, hum)
				local rag = hum:FindFirstChild("Ragdolled")
				if not (rag and rag.Value) then
					return
				end
				local torso = char:FindFirstChild("Torso")
				if torso then
					for _, m in ipairs(torso:GetChildren()) do
						if m:IsA("Motor6D") and not m.Enabled then
							m.Enabled = true
						end
					end
				end
				for _, name in ipairs(LIMBS) do
					local limb = char:FindFirstChild(name)
					local bsc = limb and limb:FindFirstChild("BallSocketConstraint")
					if bsc and bsc.Enabled then
						bsc.Enabled = false
					end
				end
				if hum.PlatformStand then
					hum.PlatformStand = false
				end
				local st = hum:GetState()
				if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.FallingDown or st == Enum.HumanoidStateType.Ragdoll then
					hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
			end

			local lastDrop = setmetatable({}, { __mode = "k" })

		-- Food bi gan vao nguoi qua HoldPart.RigidConstraint -> drop bang DropItemRemoteFunction (giong co che kick)
		local function dropFood(joint, other)
			local holdPart = joint.Parent
			local food = (holdPart and holdPart:FindFirstAncestorOfClass("Model")) or other:FindFirstAncestorOfClass("Model")
			pcall(function()
				joint.Enabled = false
			end)
			if food and (food.Name:find("Creature") or food.Name:find("Blobman")) then
				tbl7.OwnershipThreatAt = os.clock()
				tbl7.KickBlobAt = os.clock()
				local who = food.Parent and food.Parent.Name:match("^(.-)SpawnedInToys$")
				if tbl12.KickAlert then
					tbl12.KickAlert(who, "Blobman kick")
					tbl7.LastBlobAttacker = who
				end
			end
			if not food then
				return
			end
			local now = os.clock()
			if lastDrop[food] and now - lastDrop[food] < 0.2 then
				return
			end
			lastDrop[food] = now
			local hp = food:FindFirstChild("HoldPart") or holdPart
			local dropRF = hp and hp:FindFirstChild("DropItemRemoteFunction")
			if dropRF and dropRF:IsA("RemoteFunction") then
				task.spawn(function()
					pcall(function()
						dropRF:InvokeServer(food, CFrame.new(0, -150, 0), Vector3.new())
					end)
					pcall(function()
						dropRF:InvokeServer(food)
					end)
				end)
			end
			pcall(function()
				joint.Attachment1 = nil
			end)
		end

		local function stripStuck(char)
			local own = ownFolder()
			for _, part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") then
					for _, joint in ipairs(part:GetJoints()) do
						if joint:IsA("RigidConstraint") then
							local a0, a1 = joint.Attachment0, joint.Attachment1
							local p0, p1 = a0 and a0.Parent, a1 and a1.Parent
							local other = (p0 == part) and p1 or p0
							if other and other:IsA("BasePart") and other ~= part and not other:IsDescendantOf(char) and not (own and other:IsDescendantOf(own)) and isToyPart(other) then
								dropFood(joint, other)
							end
						elseif (joint:IsA("WeldConstraint") or joint:IsA("Weld")) and joint.Name ~= "SeatWeld" then
							local other = (joint.Part0 == part) and joint.Part1 or joint.Part0
							if other and other ~= part and not other:IsDescendantOf(char) and not (own and other:IsDescendantOf(own)) and isToyPart(other) then
								joint.Enabled = false
								joint.Parent = nil
								if other.Name == "StickyPart" then
									for _, c in ipairs(other:GetChildren()) do
										if c:IsA("TouchInterest") then
											c:Destroy()
										end
									end
								end
							end
						end
					end
				end
			end
		end

		-- Ragdolled doi gia tri -> dung day NGAY (khong cho den frame ke)
		local ragHooked = setmetatable({}, { __mode = "k" })
		local function hookChar()
			local char, _, hum = tbl12.Char()
			if not (char and hum) or ragHooked[hum] then
				return
			end
			ragHooked[hum] = true
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
				hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
			end)
			local rag = hum:FindFirstChild("Ragdolled")
			if rag then
				rag:GetPropertyChangedSignal("Value"):Connect(function()
					if tbl8.AntiRagdollPlus and rag.Value and not paused() then
						pcall(unragdoll, char, hum)
					end
				end)
			end
		end

		-- Early-detect grab: server bao CreateGrabLine ve client -> neu target la nguoi minh thi spam Struggle truoc khi isHeld kip bat
		local threatUntil = 0
		pcall(function()
			local ev = tbl11.CreateLine or tbl11.CreateGrabLine
			if ev and ev:IsA("RemoteEvent") then
				ev.OnClientEvent:Connect(function(...)
					local char = tbl12.Char()
					if not char then
						return
					end
					for _, v in ipairs({ ... }) do
						if typeof(v) == "Instance" and v:IsDescendantOf(char) then
							threatUntil = os.clock() + 0.6
							return
						end
					end
				end)
			end
		end)

		local function tick1()
				if flag11 or not tbl8.AntiRagdollPlus then
					return
				end
				local char, _, hum = tbl12.Char()
				if not (char and hum and hum.Health > 0) then
					return
				end
				if os.clock() - (tbl7.LastStrip or 0) >= 0.1 then
					tbl7.LastStrip = os.clock()
					pcall(stripStuck, char)
				end
				if not paused() then
					pcall(unragdoll, char, hum)
				end
			end

			local function setPlus(on)
				tbl8.AntiRagdollPlus = on and true or false
				for _, c in ipairs(plusConns) do
					c:Disconnect()
				end
				table.clear(plusConns)
				if on then
					table.insert(plusConns, RS.Heartbeat:Connect(tick1))
				end
			end

			Antis:AddToggle("AntiRagdollPlus", {
				Text = "Anti Ragdoll+ / Anti Stuck",
				Default = true,
				Tooltip = "Gan nhu khong bi ragdoll; shuriken/food/vat dinh tren nguoi tu rot",
				Callback = function(on)
					setPlus(on)
				end,
			})

			setPlus(true)
		end

		-- =====================================================
		-- ANTI LOG (chan doan): ghi lai HELD / RAGDOLL / OWNER / STATE / ALERT + so remote/giay + ping
		--  Bam nut "Copy Anti Log" sau khi bi grab/kick de gui log -> biet chinh xac anti dang hut o dau
		-- =====================================================
		do
			local RS = game:GetService("RunService")
			local Stats = game:GetService("Stats")
			local T0 = os.clock()
			local lines = {}
			local cnt = { own = 0, struggle = 0, line = 0 }
			local wrapped = false

			local function pingNow()
				local ok, v = pcall(function()
					return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
				end)
				return ok and math.floor(v) or -1
			end

			local function add(ev, extra)
				local now = os.clock()
				local held = localPlayer:FindFirstChild("IsHeld")
				local sh = tbl7.Shield
				lines[#lines + 1] = string.format(
					"[%7.2fs] %-9s %s | held=%s ping=%d threat=%.1f spam=%s lock=%s gucci=%s agState=%s",
					now - T0,
					ev,
					tostring(extra or ""),
					tostring(held and held.Value),
					pingNow(),
					math.max(0, ((sh and sh.threatUntil) or 0) - now),
					tostring(now < ((sh and sh.spamUntil) or 0)),
					tostring(now < (tbl7.LockdownUntil or 0)),
					tostring(tbl8.GucciAntiGrab),
					tostring(tbl7.States["Anti Grab"])
				)
				if #lines > 500 then
					table.remove(lines, 1)
				end
			end
			tbl12.AntiLog = add

			local hookedHum = setmetatable({}, { __mode = "k" })
			local hookedPart = setmetatable({}, { __mode = "k" })

			local function hookPart(part)
				if hookedPart[part] or not part:IsA("BasePart") then
					return
				end
				hookedPart[part] = true
				local function watch(po)
					if po:IsA("StringValue") then
						po:GetPropertyChangedSignal("Value"):Connect(function()
							add("OWNER", part.Name .. "=" .. tostring(po.Value))
						end)
					end
				end
				local po = part:FindFirstChild("PartOwner")
				if po then
					watch(po)
				end
				part.ChildAdded:Connect(function(c)
					if c.Name == "PartOwner" then
						add("OWNER+", part.Name .. "=" .. tostring(c.Value))
						watch(c)
					end
				end)
			end

			local function hookChar(char)
				local hum = char:WaitForChild("Humanoid", 5)
				if not hum or hookedHum[hum] then
					return
				end
				hookedHum[hum] = true
				for _, n in ipairs({ "HumanoidRootPart", "Torso", "Head" }) do
					local p = char:WaitForChild(n, 3)
					if p then
						hookPart(p)
					end
				end
				local rag = hum:WaitForChild("Ragdolled", 5)
				if rag then
					rag:GetPropertyChangedSignal("Value"):Connect(function()
						add("RAGDOLL", tostring(rag.Value))
					end)
				end
				hum.StateChanged:Connect(function(_, new)
					if new == Enum.HumanoidStateType.Physics or new == Enum.HumanoidStateType.FallingDown or new == Enum.HumanoidStateType.Ragdoll or new == Enum.HumanoidStateType.PlatformStanding then
						add("STATE", tostring(new))
					end
				end)
				hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
					add("SEAT", tostring(hum.SeatPart and hum.SeatPart:GetFullName()))
				end)
			end

			task.spawn(function()
				local held = localPlayer:WaitForChild("IsHeld", 15)
				if held then
					held:GetPropertyChangedSignal("Value"):Connect(function()
						add("HELD", tostring(held.Value))
					end)
				end
			end)
			localPlayer.CharacterAdded:Connect(function(c)
				add("RESPAWN", "")
				task.spawn(hookChar, c)
			end)
			if localPlayer.Character then
				task.spawn(hookChar, localPlayer.Character)
			end

			-- dem remote moi giay + lazy-wrap (cac ham duoc dinh nghia o cac khoi khac)
			local function wrap(name, key)
				local orig = tbl12[name]
				if orig then
					tbl12[name] = function(...)
						cnt[key] += 1
						return orig(...)
					end
				end
			end

			task.spawn(function()
				local lastV = 0
				while task.wait(1) do
					if flag11 then
						return
					end
					if not wrapped and tbl12.KickAlert and tbl12.SafeOwn then
						wrapped = true
						wrap("SafeOwn", "own")
						wrap("SafeStruggle", "struggle")
						wrap("SafeDestroyLine", "line")
						local origAlert = tbl12.KickAlert
						tbl12.KickAlert = function(name, how)
							add("ALERT", tostring(name) .. " / " .. tostring(how))
							return origAlert(name, how)
						end
					end
					if cnt.own + cnt.struggle + cnt.line > 0 then
						add("REMOTES", string.format("own=%d struggle=%d line=%d per sec", cnt.own, cnt.struggle, cnt.line))
						cnt.own, cnt.struggle, cnt.line = 0, 0, 0
					end
					local _, root = tbl12.Char()
					if root then
						local v = root.AssemblyLinearVelocity
						if (v.Y > 60 or Vector3.new(v.X, 0, v.Z).Magnitude > 90) and os.clock() - lastV > 0.5 then
							lastV = os.clock()
							add("VELOCITY", string.format("y=%.0f xz=%.0f", v.Y, Vector3.new(v.X, 0, v.Z).Magnitude))
						end
					end
				end
			end)

			Antis:AddButton({
				Text = "Copy Anti Log",
				Func = function()
					local text = "ANTI LOG (" .. #lines .. " lines)\n" .. table.concat(lines, "\n")
					local copied = false
					local fn = setclipboard or toclipboard
					if fn then
						copied = pcall(fn, text)
					end
					if not copied then
						print(text)
					end
					pcall(fn18, copied and ("Anti log copied (" .. #lines .. " lines)") or "Anti log printed to console (no clipboard access)", "Anti Log", nil, 3, true)
				end,
			})
			Antis:AddButton({
				Text = "Clear Anti Log",
				Func = function()
					table.clear(lines)
					T0 = os.clock()
				end,
			})
		end

		Antis:AddToggle("AntiSnowball", {
			Text = "Anti Snowball",
			Default = false,
			Tooltip = "Prevents you from getting snowballed",
			Callback = function(arg)
				tbl12.SetRuntimeToggle("AntiSnowball", arg)

				if not arg then
					local v20 = tbl12.Char()
					if not v20 then
						return
					end
					tbl12.ToggleCollisions(v20, true)
				end
			end,
		})

		-- ===== Anti Shuriken: an het NinjaShuriken (chong lag shuriken) =====
		do
			local AntiShurikenRun = 0
			local AntiShurikenConn = nil

			local function ownFolder()
				return workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
			end

			local function isShuriken(inst)
				return inst.Name == "NinjaShuriken" and inst:IsA("Model")
			end

			-- shuriken cua minh: chi an hinh (local), KHONG xoa de cac tinh nang khac cua script van dung duoc
			local function hideMine(model)
				for _, d in model:GetDescendants() do
					if d:IsA("BasePart") then
						d.LocalTransparencyModifier = 1
					elseif d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Light") then
						d.Enabled = false
					end
				end
			end

			local function showMine()
				local folder = ownFolder()
				if not folder then
					return
				end
				for _, model in folder:GetChildren() do
					if isShuriken(model) then
						pcall(function()
							for _, d in model:GetDescendants() do
								if d:IsA("BasePart") then
									d.LocalTransparencyModifier = 0
								end
							end
						end)
					end
				end
			end

			-- shuriken cua nguoi khac: xoa local (khong render, khong physics, khong touch -> het lag)
			local function handle(model)
				if flag11 or not model.Parent then
					return
				end
				local folder = ownFolder()
				if folder and model:IsDescendantOf(folder) then
					pcall(hideMine, model)
				else
					pcall(function()
						model:Destroy()
					end)
				end
			end

			local function scan()
				for _, child in workspace:GetChildren() do
					if isShuriken(child) then
						handle(child)
					elseif string.find(child.Name, "SpawnedInToys", 1, true) then
						for _, toy in child:GetChildren() do
							if isShuriken(toy) then
								handle(toy)
							end
						end
					end
				end
			end

			Antis:AddToggle("AntiShuriken", {
				Text = "Anti Shuriken",
				Default = false,
				Tooltip = "An/xoa (local) tat ca shuriken cua nguoi khac de chong lag shuriken. Shuriken cua ban chi bi an hinh. Shuriken da xoa chi hien lai khi rejoin",
				Callback = function(arg)
					AntiShurikenRun += 1
					local runId = AntiShurikenRun

					if AntiShurikenConn then
						AntiShurikenConn:Disconnect()
						AntiShurikenConn = nil
					end

					if arg then
						scan()
						AntiShurikenConn = workspace.DescendantAdded:Connect(function(inst)
							if isShuriken(inst) then
								task.defer(handle, inst)
							end
						end)
						task.spawn(function()
							while AntiShurikenRun == runId and not flag11 do
								scan()
								task.wait(0.5)
							end
						end)
					else
						showMine()
					end
				end,
			})
		end

		Antis:AddToggle("AntiBanana", {
			Text = "Anti Banana",
			Default = false,
			Tooltip = "Bananas won't touch you",
			Callback = function(arg)
				tbl12.SetRuntimeToggle("AntiBanana", arg)
			end,
		})

		Antis:AddToggle("AntiPaint", {
			Text = "Anti Paint",
			Default = false,
			Tooltip = "You won't get painted",
			Callback = function(antiPaint)
				tbl8.AntiPaint = antiPaint

				task.spawn(function()
					local tbl16 = {}

					local function fn21(descendant)
						if descendant:IsA("BasePart") and descendant.Name == "PaintPlayerPart" then
							descendant.CanTouch = not antiPaint

							if antiPaint then
								tbl16[descendant] = descendant:GetPropertyChangedSignal("CanTouch"):Connect(function()
									if not tbl8.AntiPaint then
										return
									end
									descendant.CanTouch = false
								end)
							end
						end
					end

					for _, v20 in pairs(workspace:QueryDescendants("BasePart#PaintPlayerPart")) do
						fn21(v20)
					end

					if antiPaint then
						local connection = workspace.DescendantAdded:Connect(fn21)

						repeat
							task.wait()
						until not tbl8.AntiPaint

						connection:Disconnect()

						for _, v20 in pairs(tbl16) do
							v20:Disconnect()
						end
					end
				end)
			end,
		})

		Antis:AddToggle("AntiPoison", {
			Text = "Anti Poison",
			Default = false,
			Tooltip = "Poison parts won't kill you",
			Callback = function(arg)
				local hole = map:FindFirstChild("Hole")
				local poisonBigHole = hole and hole:FindFirstChild("PoisonBigHole")
				hole = hole and hole:FindFirstChild("PoisonSmallHole")

				for _, v20 in pairs({ poisonBigHole, hole }) do
					if v20 then
						local poisonHurtPart = v20:FindFirstChild("PoisonHurtPart")
						local paintPlayerPart = v20:FindFirstChild("PaintPlayerPart")

						if poisonHurtPart then
							poisonHurtPart.CanTouch = not arg
						end

						if paintPlayerPart then
							paintPlayerPart.CanTouch = not arg
						end
					end
				end
			end,
		})

		Antis:AddToggle("AntiLag", {
			Text = "Anti Lag",
			Default = true,
			Tooltip = "Anti Line-Lag & Sticky-Lag",
			Callback = function(arg)
				local enabled = not arg
				if enabled and tbl7.LookFigures.Enabled then
					toggles.AntiLag:SetValue(true)
					return
				end
				localPlayer.PlayerScripts.CharacterAndBeamMove.Enabled = enabled
				localPlayer.PlayerScripts.StickyPartsTouchDetection.Enabled = enabled
				tbl12.SetAntiShurikenLag(arg)

				if arg then
					task.delay(1.5, function()
						if flag11 or not toggles.AntiLag.Value then
							return
						end

						for _, v20 in pairs(tbl7.PlayerList) do
							local v21 = tbl12.Char(v20)

							if v21 then
								for _, child in pairs(v21:GetChildren()) do
									if child.Name == "GrabParts" then
										child:Destroy()
									end
								end
							end
						end
					end)
				end
			end,
		}):AddKeyPicker("AntiLagK", { Text = "Anti Lag", Default = nil, Mode = "Toggle", NoUI = false, SyncToggleState = true })

		Antis:AddToggle("AutoAntiLag", {
			Text = "Auto Anti Lag",
			Default = true,
			Tooltip = "Enables anti-lag for you if too low fps",
			Callback = function(autoAntiLag)
				tbl8.AutoAntiLag = autoAntiLag
			end,
		})

		Antis:AddToggle("AntiToyLag", {
			Text = "Anti Toy Lag",
			Default = false,
			Tooltip = "If FPS suddenly drops to the set value, removes all toys of other players around (your own toys are kept)",
			Callback = function(antiToyLag)
				tbl8.AntiToyLag = antiToyLag
			end,
		}):AddKeyPicker("AntiToyLagK", { Text = "Anti Toy Lag", Default = nil, Mode = "Toggle", NoUI = false, SyncToggleState = true })

		Antis:AddSlider("AntiToyLagFPS", {
			Text = "Anti Toy Lag FPS",
			Default = 5,
			Min = 1,
			Max = 10,
			Rounding = 0,
			Suffix = " FPS",
			Tooltip = "Clears other players' toys when FPS falls to or below this value",
			Callback = function(antiToyLagFPS)
				tbl9.AntiToyLagFPS = antiToyLagFPS
			end,
		})

		-- Đồng bộ lại đầy đủ callback cho 3 anti auto-on khi load (phòng trường hợp bước sớm bị lỗi)
		for _, name in ipairs({ "AntiGrab", "AntiKick2", "AntiLag" }) do
			local t = toggles[name]
			if t then
				pcall(t.SetValue, t, true)
			end
		end

		-- ===== Anti Packet (no ping: reacts to real packet/line lag offenders) =====
		Antis:AddToggle("AntiPacket", {
			Text = "Anti Packet",
			Default = false,
			Tooltip = "Detects players who spam packets / line lag, then escalates: cleans effects, mutes sounds, enables Anti Lag, strips offenders' grab lines",
			Callback = function(arg)
				tbl12.SetRuntimeToggle("AntiPacket", arg)
			end,
		}):AddKeyPicker("AntiPacketK", {
			Text = "Anti Packet",
			Default = nil,
			Mode = "Toggle",
			NoUI = false,
			SyncToggleState = true,
		})

		Antis:AddSlider("AntiPacketEscalate", {
			Text = "Anti Packet Escalate After",
			Default = 4,
			Min = 1,
			Max = 15,
			Rounding = 0,
			Suffix = " s",
			Tooltip = "How long one offender must keep flooding before the next mode kicks in (lower = more aggressive)",
			Callback = function(value)
				tbl9.AntiPacketEscalate = value
			end,
		})

		Antis:AddToggle("AntiPacketBlock", {
			Text = "Anti Packet Block Remotes",
			Default = true,
			Tooltip = "From mode 2, temporarily disconnects the GAME's handlers on the flooded remotes (needs getconnections). Auto restored when safe",
			Callback = function(value)
				tbl8.AntiPacketBlock = value
			end,
		})

		Antis:AddToggle("AntiPacketRejoin", {
			Text = "Anti Packet Auto Rejoin",
			Default = false,
			Tooltip = "Rejoin if mode 3 lasts 15s",
			Callback = function(value)
				tbl8.AntiPacketRejoin = value
			end,
		})

		do
			local Lighting = game:GetService("Lighting")
			local RunService = game:GetService("RunService")

			local SWEEP_INTERVAL = { [1] = 3, [2] = 1.5, [3] = 0.6 }
			local TICK = 0.15
			local STEP_DOWN_TICKS = 12 -- 12 x 0.15s = ~1.8s on dinh moi ha 1 mode
			local HEAVY_REJOIN_AFTER = 15
			local STALL_GRACE = 5 -- chi tinh frame stall khi vua co offender

			local mode = 0
			local goodStreak = 0
			local heavySince
			local lastSweep = 0
			local lastThreat = 0
			local sweeping = false
			local addedConn
			local savedQuality, savedShadows
			local turnedOnAntiLag = false
			local worstDt = 0
			local disabledEffects = setmetatable({}, { __mode = "k" })
			local mutedSounds = setmetatable({}, { __mode = "k" })
			local offenderSince = setmetatable({}, { __mode = "k" })
			local activeOffenders = {}

			-- do frame time cua chinh minh (khong lien quan ping)
			RunService.Heartbeat:Connect(function(dt)
				if dt > worstDt then
					worstDt = dt
				end
			end)

			-- m=1: tat effect (khoi phuc duoc) | m=2: huy effect + tat tieng | m=3: huy ca sound
			local function handle(v, m)
				if m < 1 then
					return
				end
				local character = localPlayer.Character
				if character and v:IsDescendantOf(character) then
					return
				end
				if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam") then
					if m == 1 then
						if v.Enabled then
							disabledEffects[v] = true
							v.Enabled = false
						end
					else
						v:Destroy()
					end
				elseif v:IsA("Sound") then
					if m == 2 then
						if v.Volume > 0 then
							mutedSounds[v] = v.Volume
							v.Volume = 0
						end
					elseif m >= 3 then
						v:Destroy()
					end
				end
			end

			local function sweep()
				if sweeping then
					return
				end
				sweeping = true
				pcall(function()
					local list = workspace:GetDescendants()
					for i = 1, #list do
						if mode < 1 or flag11 then
							break
						end
						local v = list[i]
						if v.Parent then
							pcall(handle, v, mode)
						end
						if i % 300 == 0 then
							task.wait() -- chia nho de khong giat game
						end
					end
				end)
				sweeping = false
			end

			local function restoreEffects()
				for e in pairs(disabledEffects) do
					pcall(function()
						if e.Parent then
							e.Enabled = true
						end
					end)
					disabledEffects[e] = nil
				end
			end

			local function restoreSounds()
				for s, vol in pairs(mutedSounds) do
					pcall(function()
						if s.Parent then
							s.Volume = vol
						end
					end)
					mutedSounds[s] = nil
				end
			end

			local function setRendering(m)
				pcall(function()
					if m >= 2 then
						if not savedQuality then
							savedQuality = settings().Rendering.QualityLevel
							savedShadows = Lighting.GlobalShadows
						end
						settings().Rendering.QualityLevel = (m >= 3) and Enum.QualityLevel.Level01 or Enum.QualityLevel.Level05
						Lighting.GlobalShadows = false
					elseif savedQuality then
						settings().Rendering.QualityLevel = savedQuality
						Lighting.GlobalShadows = savedShadows
						savedQuality, savedShadows = nil, nil
					end
				end)
			end

			-- ===== Block remote: tam ngat handler cua GAME tren remote bi flood =====
			-- Handler cua script nay (executor closure) duoc giu lai de van phat hien flood.
			local blocked = {} -- [connection] = true
			local function isOwnConnection(conn)
				local fnc = conn.Function
				if not fnc then
					return false
				end
				if isexecutorclosure then
					local ok, res = pcall(isexecutorclosure, fnc)
					if ok then
						return res
					end
				end
				if is_synapse_function then
					local ok, res = pcall(is_synapse_function, fnc)
					if ok then
						return res
					end
				end
				return nil -- khong phan biet duoc
			end

			local function blockRemotes()
				if not getconnections or not (isexecutorclosure or is_synapse_function) then
					return
				end
				for _, remote in ipairs({ tbl11.Packet, tbl11.CreateGrabLine }) do
					if remote then
						pcall(function()
							for _, conn in ipairs(getconnections(remote.OnClientEvent)) do
								if not blocked[conn] and isOwnConnection(conn) == false then
									blocked[conn] = true
									conn:Disable()
								end
							end
						end)
					end
				end
			end

			local function unblockRemotes()
				for conn in pairs(blocked) do
					pcall(function()
						conn:Enable()
					end)
					blocked[conn] = nil
				end
			end

			-- Gom offender tu PacketData (packet lag) + LineData (line lag)
			local function scanOffenders()
				local now = tick()
				table.clear(activeOffenders)
				local count, longest = 0, 0

				local function mark(player)
					if player == localPlayer or activeOffenders[player] then
						return
					end
					activeOffenders[player] = true
					count = count + 1
					offenderSince[player] = offenderSince[player] or now
					local dur = now - offenderSince[player]
					if dur > longest then
						longest = dur
					end
				end

				for player, data in pairs(tbl7.PacketData) do
					if data.IsLagging then
						mark(player)
					end
				end
				for player, data in pairs(tbl7.LineData) do
					if data.IsLagging then
						mark(player)
					end
				end
				for player in pairs(offenderSince) do
					if not activeOffenders[player] then
						offenderSince[player] = nil
					end
				end
				return count, longest
			end

			local function neutralize(player, m)
				pcall(function()
					local character = player.Character
					if not character then
						return
					end
					for _, child in ipairs(character:GetChildren()) do
						if child.Name == "GrabParts" then
							child:Destroy()
						end
					end
					if m >= 2 then
						for _, d in ipairs(character:GetDescendants()) do
							if d:IsA("Beam") or d:IsA("Trail") or d:IsA("ParticleEmitter") then
								d:Destroy()
							elseif m >= 3 and d:IsA("Sound") then
								d:Destroy()
							end
						end
					end
				end)
				if m >= 2 then
					-- huy line cua offender nam trong workspace (neu co owner la ho)
					pcall(function()
						for _, v in ipairs(workspace:GetChildren()) do
							if v.Name == "GrabParts" then
								local owner = v:FindFirstChild("Owner") or v:FindFirstChild("OwnerValue")
								if owner and owner:IsA("ObjectValue") and owner.Value == player.Character then
									v:Destroy()
								end
							end
						end
					end)
				end
			end

			local function punishOffenders()
				for player in pairs(activeOffenders) do
					neutralize(player, mode)
				end
			end

			local function offenderNames()
				local names = {}
				for player in pairs(activeOffenders) do
					names[#names + 1] = tbl12.FormatPlayer(player)
					if #names >= 3 then
						break
					end
				end
				return table.concat(names, ", ")
			end

			local function applyMode(newMode)
				local old = mode
				mode = newMode

				if mode >= 1 and not addedConn then
					addedConn = workspace.DescendantAdded:Connect(function(v)
						local m = mode
						if m >= 1 then
							task.defer(function()
								pcall(handle, v, m)
							end)
						end
					end)
				elseif mode < 1 and addedConn then
					addedConn:Disconnect()
					addedConn = nil
				end

				if mode < 2 then
					restoreSounds()
				end
				if mode < 1 then
					restoreEffects()
				end
				setRendering(mode)

				if mode >= 2 and tbl8.AntiPacketBlock ~= false then
					blockRemotes()
				else
					unblockRemotes()
				end

				if mode >= 2 then
					if toggles.AntiLag and not toggles.AntiLag.Value then
						toggles.AntiLag:SetValue(true)
						turnedOnAntiLag = true
					end
				elseif turnedOnAntiLag then
					turnedOnAntiLag = false
					if toggles.AntiLag and toggles.AntiLag.Value then
						toggles.AntiLag:SetValue(false)
					end
				end

				if mode > old then
					lastSweep = 0
					local who = offenderNames()
					local suffix = who ~= "" and ("\n" .. who) or ""
					fn18("Anti packet mode " .. mode .. suffix, "Anti Packet")
				elseif mode == 0 then
					fn18("Threat cleared, anti packet off", "Anti Packet")
				end
			end

			task.spawn(function()
				while true do
					if not tbl8.AntiPacket and not tbl12.WaitForRuntimeToggle("AntiPacket") then
						return
					end
					task.wait(TICK)
					if flag11 then
						unblockRemotes()
						return
					end
					if not tbl8.AntiPacket then
						if mode ~= 0 then
							heavySince, goodStreak = nil, 0
							table.clear(activeOffenders)
							applyMode(0)
						end
						continue
					end

					local now = tick()
					local count, longest = scanOffenders()
					local stall = worstDt
					worstDt = 0

					if count > 0 then
						lastThreat = now
					end

					local escalate = tbl9.AntiPacketEscalate or 4
					local wanted = 0
					if count > 0 then
						wanted = 1
						if count >= 2 or longest >= escalate then
							wanted = 2
						end
						if count >= 3 or longest >= escalate * 2.5 then
							wanted = 3
						end
					end
					-- frame stall chi day mode len khi dang (hoac vua) co offender
					if count > 0 or now - lastThreat < STALL_GRACE then
						if stall >= 0.35 then
							wanted = math.max(wanted, 3)
						elseif stall >= 0.15 then
							wanted = math.max(wanted, 2)
						elseif stall >= 0.08 and count > 0 then
							wanted = math.max(wanted, 1)
						end
					end

					if wanted > mode then
						goodStreak = 0
						applyMode(wanted)
					elseif wanted < mode then
						goodStreak = goodStreak + 1
						if goodStreak >= STEP_DOWN_TICKS then
							goodStreak = 0
							applyMode(mode - 1)
						end
					else
						goodStreak = 0
					end

					if mode >= 1 and now - lastSweep >= SWEEP_INTERVAL[mode] then
						lastSweep = now
						task.spawn(sweep)
					end
					if mode >= 1 and count > 0 then
						punishOffenders()
					end
					if mode >= 2 and tbl8.AntiPacketBlock ~= false then
						blockRemotes()
					end

					if mode >= 3 then
						heavySince = heavySince or now
						if tbl8.AntiPacketRejoin and now - heavySince >= HEAVY_REJOIN_AFTER then
							unblockRemotes()
							fn18("Network flood keo dai, dang rejoin...", "Anti Packet")
							tbl12.Rejoin(tbl8.RejoinWithAntiLag ~= false, tbl8.RejoinWithScript)
							return
						end
					else
						heavySince = nil
					end
				end
			end)
		end


