				["V"] = { "#...#", "#...#", "#...#", "#...#", "#...#", ".#.#.", "..#.." },
				["W"] = { "#...#", "#...#", "#...#", "#.#.#", "#.#.#", "##.##", "#...#" },
				["X"] = { "#...#", "#...#", ".#.#.", "..#..", ".#.#.", "#...#", "#...#" },
				["Y"] = { "#...#", "#...#", ".#.#.", "..#..", "..#..", "..#..", "..#.." },
				["Z"] = { "#####", "....#", "...#.", "..#..", ".#...", "#....", "#####" },
				["0"] = { ".###.", "#...#", "#..##", "#.#.#", "##..#", "#...#", ".###." },
