				[":"] = { ".....", ".##..", ".##..", ".....", ".##..", ".##..", "....." },
				["+"] = { ".....", "..#..", "..#..", "#####", "..#..", "..#..", "....." },
				[" "] = { ".....", ".....", ".....", ".....", ".....", ".....", "....." },
			}
			local FOLD_FROM = "ÀÁÂÃÄÅÇÈÉÊËÌÍÎÏÑÒÓÔÕÖÙÚÛÜÝàáâãäåçèéêëìíîïñòóôõöùúûüýÿĀāĂăĄąĆćĈĉĊċČčĎďĒēĔĕĖėĘęĚěĜĝĞğĠġĢģĤĥĨĩĪīĬĭĮįİĴĵĶķĹĺĻļĽľŃńŅņŇňŌōŎŏŐőŔŕŖŗŘřŚśŜŝŞşŠšŢţŤťŨũŪūŬŭŮůŰűŲųŴŵŶŷŸŹźŻżŽžẠạẢảẤấẦầẨẩẪẫẬậẮắẰằẲẳẴẵẶặẸẹẺẻẼẽẾếỀềỂểỄễỆệỈỉỊịỌọỎỏỐốỒồỔổỖỗỘộỚớỜờỞởỠỡỢợỤụỦủỨứỪừỬửỮữỰựỲỳỴỵỶỷỸỹđĐ"
			local FOLD_TO = "AAAAAACEEEEIIIINOOOOOUUUUYAAAAAACEEEEIIIINOOOOOUUUUYYAAAAAACCCCCCCCDDEEEEEEEEEEGGGGGGGGHHIIIIIIIIIJJKKLLLLLLNNNNNNOOOOOORRRRRRSSSSSSSSTTTTUUUUUUUUUUUUWWYYYZZZZZZAAAAAAAAAAAAAAAAAAAAAAAAEEEEEEEEEEEEEEEEIIIIOOOOOOOOOOOOOOOOOOOOOOOOUUUUUUUUUUUUUUYYYYYYYYDD"
			local FoldMap = {}
			do
				local idx = 0
				for _, cp in utf8.codes(FOLD_FROM) do
					idx = idx + 1
					FoldMap[cp] = FOLD_TO:sub(idx, idx)
				end
			end

			local function normalize(text)
				local chars = {}
				for _, cp in utf8.codes(text) do
					local ch
					if cp < 128 then
						ch = string.upper(utf8.char(cp))
					else
						ch = FoldMap[cp] or " "
					end
					chars[#chars + 1] = ch
					if #chars >= 20 then
						break
					end
				end
				return chars
			end

			local Cache = { Cells = nil, Width = 1, Text = nil, Points = nil, Count = nil, Orientation = nil, Layout = nil }

			-- vertical = false: chu xep ngang (trai -> phai)
			-- vertical = true : chu xep doc (tren -> duoi), moi chu van dung thang
			local function buildCells(text, vertical)
				local chars = normalize(text)
				local cells = {}
				local cursor = 0
				for _, ch in ipairs(chars) do
					local glyph = FONT[ch] or FONT[" "]
					for r = 1, 7 do
						local rowStr = glyph[r]
						for c = 1, 5 do
							if rowStr:sub(c, c) == "#" then
								if vertical then
									cells[#cells + 1] = { c - 1, cursor + r - 1 }
								else
									cells[#cells + 1] = { cursor + c - 1, r - 1 }
								end
							end
						end
					end
					cursor = cursor + (vertical and 8 or 6)
				end
				if vertical then
					return cells, 5, math.max(cursor - 1, 7)
				end
				return cells, math.max(cursor - 1, 1), 7
			end

			tbl13.AddShape("Text", function(i, n)
				if i == 1 or not Cache.Points or Cache.Count ~= n or Cache.Text ~= TextShape.Text or Cache.Orientation ~= TextShape.Orientation or Cache.Layout ~= TextShape.Layout then
					local cells, width, height = buildCells(TextShape.Text, TextShape.Layout == "Vertical")
					local points = table.create(n)
					local total = #cells
					local half = (math.max(width, height) - 1) / 2
					if half < 1 then
						half = 1
					end
					local flat = TextShape.Orientation == "Flat (Horizontal)"

					for k = 1, n do
						local x, y, depth = 0, 0, 0
						if total > 0 then
							local cellIdx, layer
							if n >= total then
								cellIdx = ((k - 1) % total) + 1
								layer = math.floor((k - 1) / total)
							else
								cellIdx = math.floor((k - 1) * total / n) + 1
								layer = 0
							end
							local cell = cells[cellIdx]
							x = (cell[1] - (width - 1) / 2) / half
							y = ((height - 1) / 2 - cell[2]) / half
							depth = layer * 0.08
						end
						if flat then
							points[k] = Vector3.new(x, depth, -y)
						else
							points[k] = Vector3.new(x, y, depth)
						end
					end

					Cache.Points = points
					Cache.Count = n
					Cache.Text = TextShape.Text
					Cache.Orientation = TextShape.Orientation
					Cache.Layout = TextShape.Layout
				end
				return Cache.Points[i]
			end)

			-- Wall: dung pallet len (mat rong quay ra sau/truoc nhan vat), khong xoay vao tam nua
			-- Flat: giu nguyen (nil = hanh vi cu)
			local WALL_ROT = CFrame.Angles(math.pi / 2, 0, 0)
			tbl13.Shapes["Text"].GetRotation = function()
				if TextShape.Orientation == "Wall (Vertical)" then
					return WALL_ROT
				end
				return nil
			end
		end

