		v20:AddDivider("Boombox")

		local BoomboxGlobal = nil
		local BoomboxEnabled = false
		local BoomboxRun = 0
		local AutoPlayEnabled = false
		local SoundLink = nil
		local SoundVolume = 1

		local function SettingBoombox()
			if not BoomboxGlobal or not SoundLink then
				return
			end
			local speaker = BoomboxGlobal:FindFirstChild("Speaker")
			if not speaker then
				return
			end

			local sound = speaker:FindFirstChildOfClass("Sound")
			if sound then
				sound.Volume = 0
			end

			local ez = speaker:FindFirstChild("EZ")
			if ez then
				ez.TimePosition = 0
				ez.Pitch = 1
				ez.Volume = SoundVolume
				ez.SoundId = SoundLink
			else
				local sound2 = Instance.new("Sound", speaker)
				sound2.Name = "EZ"
				sound2.Pitch = 1
				sound2.Volume = SoundVolume
				sound2.SoundId = SoundLink
				sound2.Playing = true
				sound2.Looped = true
			end
		end

		v20:AddToggle("BoomboxToggle", {
			Text = "Boombox",
			Default = false,
			Callback = function(arg)
				BoomboxEnabled = arg
				BoomboxRun += 1
				if not arg then
					return
				end

				local myRun = BoomboxRun
				local function alive()
					return BoomboxEnabled and myRun == BoomboxRun
				end

				task.spawn(function()
					while alive() and task.wait() do
						local character, _, humanoid = tbl12.Char()
						local torso = character and character:FindFirstChild("Torso")

						if torso and humanoid and humanoid.Health > 0 then
							-- tham so thu 4 = true: giu cho Toys Aura khong lay mat Boombox
							local boombox = tbl12.SpawnToy("Boombox", torso.CFrame * CFrame.new(0, 5, 20), 0, true)
							BoomboxGlobal = boombox

							if boombox then
								boombox.Name = "BackPack"
								local colorPart = boombox:WaitForChild("ColorPart", 1)

								if colorPart then
									local now2 = tick()
									local owned = false

									while alive() and task.wait() do
										owned = tbl12.SNO(colorPart)
										if owned
											or not colorPart.Parent
											or humanoid.Health <= 0
											or (colorPart.Position - torso.Position).Magnitude > 20
											or tick() - now2 > 3
										then
											break
										end
									end

									if owned and alive() then
										for _, part in ipairs(boombox:GetChildren()) do
											if part:IsA("BasePart") then
												part.CanCollide = false
												part.CanQuery = false
											end
										end

										if AutoPlayEnabled then
											SettingBoombox()
										end

										while alive() and task.wait() and colorPart.Parent and tbl12.IsPartOwner(colorPart) and torso.Parent and humanoid.Health > 0 do
											tbl12.Teleport(
												colorPart,
												torso.CFrame,
												CFrame.new(0, 0, 1) * CFrame.Angles(0, math.pi, 0.3490658503988659)
											)
										end
									end
								end

								tbl12.DestroyToy(boombox)
							end

							BoomboxGlobal = nil
						end
					end
				end)
			end,
		})

