			Text = "Break All",
			Func = function()
				if breakingAll then
					return
				end
				breakingAll = true

				task.spawn(function()
					local ok, err = pcall(function()
						for _, part in map.BaseGround:GetChildren() do
							if part:IsA("BasePart") and part.Parent then
								fn21(part)
								task.wait(0.1)
							end
						end
					end)

					if not ok then
						warn("Break All failed:", err)
					end

					breakingAll = false
				end)
			end,
		})

		Experimental:AddDropdown("BreakMethod", {
			Values = { "Non-collidable part", "Kickable part" },
			Default = 1,
			Multi = false,
			Searchable = true,
			Text = "Break Method",
			Callback = function(arg)
				local n38

				if arg == "Non-collidable part" then
					n38 = 1
				else
					n38 = 2
				end

				n36 = n38
			end,
		})

		Experimental:AddLabel("Fix part: delete the shuriken that was spawned from your inventory!", true)
		Experimental:AddDivider("Flying Parts")

		Experimental:AddDropdown("WhichToBreak", {
			Values = {
				"InnerUFO",
				"OuterUFO",
				"CaveCart",
				"Train",
				"Flying Rock 1",
				"Flying Rock 2",
