		})

		Experimental:AddButton({
			Text = "Break",
			Func = function()
				local value = options.WhichToBreak.Value
				local v21 = tbl7.BreakParts[value]

				if v21 then
					local v22 = v21()

					if v22 then
						for _, child in pairs(v22:GetChildren()) do
							if child:IsA("BasePart") then
								tbl12.BlackHole(child.AssemblyRootPart)
								break
							end
						end

						if v22.Parent:FindFirstChild("FollowThisPart") then
							v22.Parent:FindFirstChild("FollowThisPart").AlignPosition.Enabled = false
							v22.Parent:FindFirstChild("FollowThisPart").AlignOrientation.Enabled = false
						end
					else
						warn("Part not found for:", value)
					end
				else
					warn("Invalid selection:", value)
				end
			end,
		})

		-- UFO Star: lay network owner cua 2 UFO (SNO giong BringPlayer / toy code khac) roi giu bang AlignPosition/AlignOrientation
		-- (owner = vat ly chay o may minh nen server + nguoi khac thay muot). UFO nao khong lay duoc owner thi fallback ve loop Break.
		do
			local star = {
				Active = false,
				Distance = 30,
				Tilt = 35,
				Speed = 1,
				Interval = 0.25,
				Angle = 0,
				LastTick = 0,
				UFOs = {},
				Toys = {},
				Pins = {},
				Follow = {},
				Collide = {},
			}
			local SHURIKENS_PER_UFO = 2

			local function getUfoRoot(name)
				local getter = tbl7.BreakParts[name]
				local model = getter and getter()
				if not model then
					return nil
				end
				for _, child in pairs(model:GetChildren()) do
					if child:IsA("BasePart") then
						local ok, nice = pcall(tbl12.FindNicePart, model) -- part grab duoc (CanQuery, khong anchor) giong code toys khac
						return child.AssemblyRootPart or child, model, (ok and nice) or child.AssemblyRootPart or child
					end
				end
				return nil
			end

			local function ownedNow(part)
				return part and part.Parent and (tbl12.IsNetworkOwner(part) or tbl12.IsPartOwner(part)) and true or false
			end

			-- lay owner: thu lai nhieu lan (SNO tu bay nguoi qua gan neu xa, y nhu BringPlayer)
			local function acquire(u)
				for _ = 1, 30 do
					if not star.Active then
						return false
					end
					if ownedNow(u.Part) then
						return true
					end
					pcall(tbl12.SNO, u.Part)
					task.wait(0.05)
				end
				return ownedNow(u.Part)
			end

			-- giu UFO bang AlignPosition/AlignOrientation (cung kieu ToyKit.Hold / Wings cua script)
			local function attachAlign(u)
				if u.AP and u.AP.Parent and u.AO and u.AO.Parent then
					return
				end
				local at = Instance.new("Attachment")
				at.Name = "UFOStarAt"
				at.Parent = u.Part

				local ap = Instance.new("AlignPosition")
				ap.Name = "UFOStarAP"
				ap.Mode = Enum.PositionAlignmentMode.OneAttachment
				ap.Attachment0 = at
				ap.ApplyAtCenterOfMass = true
				ap.MaxForce = math.huge
				ap.MaxVelocity = math.huge
				ap.Responsiveness = 200
				ap.Position = u.Part.Position
				ap.Parent = u.Part

				local ao = Instance.new("AlignOrientation")
				ao.Name = "UFOStarAO"
				ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
				ao.Attachment0 = at
				ao.MaxTorque = math.huge
				ao.MaxAngularVelocity = math.huge
				ao.Responsiveness = 200
				ao.CFrame = u.Part.CFrame
				ao.Parent = u.Part

				u.AT, u.AP, u.AO = at, ap, ao
			end

			-- tat va cham de UFO khong hat nguoi choi ra xa
			local function noCollide(inst)
				for _, d in ipairs(inst:GetDescendants()) do
					if d:IsA("BasePart") then
						if star.Collide[d] == nil then
							star.Collide[d] = d.CanCollide
						end
						d.CanCollide = false
					end
				end
				if inst:IsA("BasePart") then
					if star.Collide[inst] == nil then
						star.Collide[inst] = inst.CanCollide
					end
					inst.CanCollide = false
				end
			end

			-- vi tri + huong cua UFO: nam tren truc nghieng, truc nay xoay quanh nguoi
			local function poseFor(u, center)
				local R = CFrame.Angles(0, star.Angle, 0) * CFrame.Angles(0, 0, math.rad(star.Tilt))
				local rot = R * (u.Flip and CFrame.Angles(math.pi, 0, 0) or CFrame.new()) * u.Base
				return CFrame.new(center + R.UpVector * (u.Sign * star.Distance)) * rot
			end

			-- moi frame: (1) cap nhat goc quay, (2) UFO da co owner -> dat muc tieu cho Align, (3) giu shuriken cua UFO fallback dung yen
			local function holdPins()
				local now = os.clock()
				local dt = star.LastTick > 0 and math.min(now - star.LastTick, 0.1) or 0
				star.LastTick = now
				star.Angle = (star.Angle + dt * star.Speed) % (math.pi * 2)

				local _, hrp = tbl12.Char()
				if hrp then
					local center = hrp.Position
					for _, u in ipairs(star.UFOs) do
						if u.Owned and u.AP and u.AP.Parent and u.AO and u.AO.Parent then
							local pose = poseFor(u, center)
							u.AP.Position = pose.Position
							u.AO.CFrame = pose
						end
					end
				end

				for _, item in ipairs(star.Pins) do
					if item.Sound.Parent then
						item.Sound.CFrame = item.CF * item.Rel
						item.Sound.AssemblyLinearVelocity = Vector3.zero
						item.Sound.AssemblyAngularVelocity = Vector3.zero
					end
				end
			end

			-- 1 vong "break": tao shuriken moi, dat SoundPart tai vi tri ngoi sao, cho server nhan, han vao UFO, roi bo shuriken cu
			local function placeAll()
				local _, hrp, hum = tbl12.Char()
				if not (hrp and hum and hum.Health > 0) then
					return
				end
				local center = hrp.Position
				local fresh = {}
				local freshCount = {}

				for _, u in ipairs(star.UFOs) do
					if u.Root.Parent and star.Active and not u.Owned then
						local pose = poseFor(u, center)
						for _ = 1, SHURIKENS_PER_UFO do
							local toy = tbl12.SpawnToy("NinjaShuriken")
							local stickyPart = toy and toy:WaitForChild("StickyPart", 0.25)
							local soundPart = toy and toy:WaitForChild("SoundPart", 0.25)
							if stickyPart and soundPart and tbl12.SNO(soundPart) then
								noCollide(toy)
								local item = {
									Toy = toy,
									Sticky = stickyPart,
									Sound = soundPart,
									Rel = stickyPart.CFrame:ToObjectSpace(soundPart.CFrame),
									CF = pose,
									Root = u.Root,
									U = u,
								}
								table.insert(star.Toys, toy)
								table.insert(star.Pins, item)
								table.insert(fresh, item)
								freshCount[u] = (freshCount[u] or 0) + 1
							elseif toy then
								pcall(tbl12.DestroyToy, toy)
							end
						end
					end
				end

				task.wait(0.2) -- cho vi tri shuriken replicate len server (giong Break)
				if star.Active then
					for _, item in ipairs(fresh) do
						if item.Toy.Parent and item.Sticky.Parent then
							tbl11.StickyPartEvent:FireServer(item.Sticky, item.Root, CFrame.new())
						end
					end
					task.wait(0.15) -- cho server han xong
				end

				-- bo shuriken cu (chi khi UFO do da co shuriken moi)
				local keep, keepToys = {}, {}
				for _, item in ipairs(star.Pins) do
					local isFresh = table.find(fresh, item) ~= nil
					if star.Active and (isFresh or (freshCount[item.U] or 0) == 0) then
						table.insert(keep, item)
					else
						pcall(tbl12.DestroyToy, item.Toy)
					end
				end
				for _, item in ipairs(keep) do
					table.insert(keepToys, item.Toy)
				end
				star.Pins, star.Toys = keep, keepToys
			end

			local function stopStar()
				star.Active = false
				tbl12.SetRuntimeConnection("UFOStar", RunService.Heartbeat, false)
				for _, u in ipairs(star.UFOs) do
					for _, inst in ipairs({ u.AP, u.AO, u.AT }) do
						pcall(function()
							inst:Destroy()
						end)
					end
					if u.Owned then
						pcall(tbl12.RNO, u.Part)
					end
				end
				for _, toy in ipairs(star.Toys) do
					pcall(tbl12.DestroyToy, toy)
				end
				for _, f in ipairs(star.Follow) do
					pcall(function()
						f.AlignPosition.Enabled = true
						f.AlignOrientation.Enabled = true
					end)
				end
				for part, v in pairs(star.Collide) do
					if part.Parent then
						part.CanCollide = v
					end
				end
				star.UFOs, star.Toys, star.Pins, star.Follow, star.Collide = {}, {}, {}, {}, {}
			end

			local function startStar()
				local _, hrp, hum = tbl12.Char()
				if not (hrp and hum and hum.Health > 0) then
					warn("[UFO Star] character not ready")
					return false
				end

				star.Angle = 0
				local defs = { { Name = "InnerUFO", Sign = -1, Flip = false }, { Name = "OuterUFO", Sign = 1, Flip = true } }
				local ufos = {}

				for _, d in ipairs(defs) do
					local root, model, part = getUfoRoot(d.Name)
					if not root then
						warn("[UFO Star] part not found:", d.Name)
						return false
					end
					noCollide(model) -- tat va cham truoc khi UFO bay toi cho nguoi choi
					local follow = model.Parent and model.Parent:FindFirstChild("FollowThisPart")
					if follow and follow:FindFirstChild("AlignPosition") and follow:FindFirstChild("AlignOrientation") then
						follow.AlignPosition.Enabled = false
						follow.AlignOrientation.Enabled = false
						table.insert(star.Follow, follow)
					end
					table.insert(ufos, {
						Root = root,
						Part = part,
						Model = model,
						Sign = d.Sign,
						Flip = d.Flip,
						Base = part.CFrame - part.CFrame.Position, -- tu the thang dung tu nhien cua UFO (theo Part se dieu khien)
						Owned = false,
					})
				end

				star.UFOs = ufos
				star.Active = true
				star.LastTick = 0
				tbl12.SetRuntimeConnection("UFOStar", RunService.Heartbeat, true, holdPins)

				-- lay owner tung UFO; thanh cong thi gan Align, that bai thi fallback loop Break
				for _, u in ipairs(ufos) do
					if acquire(u) then
						u.Owned = true
						attachAlign(u)
					else
						warn("[UFO Star] khong lay duoc owner, dung loop Break cho UFO nay")
					end
				end

				-- vong lap nen: giu owner (grab lai khi mat) + loop Break cho UFO chua co owner
				task.spawn(function()
					while star.Active do
						local anyFallback = false
						for _, u in ipairs(star.UFOs) do
							if u.Owned then
								if not ownedNow(u.Part) then
									pcall(tbl12.SNO, u.Part)
								end
								attachAlign(u)
							else
								anyFallback = true
							end
						end
						if anyFallback then
							local ok, err = pcall(placeAll)
							if not ok then
								warn("[UFO Star] " .. tostring(err))
							end
							task.wait(star.Interval)
						else
							task.wait(0.3)
						end
					end
				end)
				return true
			end

			Experimental:AddToggle("UFOStarT", {
				Text = "UFO Star",
				Tooltip = "Takes network ownership of the 2 UFOs and orbits them around you like the jets of a star (Inner = lower jet, Outer = upper jet)",
				Default = false,
				Callback = function(on)
					if on then
						task.spawn(function()
							local ok, started = pcall(startStar)
							if not ok or not started then
								if not ok then
									warn("[UFO Star] " .. tostring(started))
								end
								pcall(stopStar)
								if toggles and toggles.UFOStarT then
									toggles.UFOStarT:SetValue(false)
								end
							end
						end)
					else
						pcall(stopStar)
					end
				end,
			})

			Experimental:AddSlider("UFOStarDistance", {
				Text = "Star Distance",
				Default = 30,
				Min = 10,
				Max = 150,
				Rounding = 0,
				Callback = function(v)
					star.Distance = v
				end,
			})

			Experimental:AddSlider("UFOStarTilt", {
				Text = "Star Tilt (degrees)",
				Default = 35,
				Min = 0,
				Max = 90,
				Rounding = 0,
				Callback = function(v)
					star.Tilt = v
				end,
			})

			Experimental:AddSlider("UFOStarSpeed", {
				Text = "Star Spin Speed",
				Default = 1,
				Min = 0,
				Max = 8,
				Rounding = 1,
				Callback = function(v)
					star.Speed = v
				end,
			})

			Experimental:AddSlider("UFOStarInterval", {
				Text = "Loop Delay (seconds)",
				Default = 0.25,
				Min = 0,
				Max = 2,
				Rounding = 2,
				Callback = function(v)
					star.Interval = v
				end,
			})
		end

		Experimental:AddDivider("Misc")
		Experimental:AddButton({ Text = "Destroy Train", Func = tbl12.DestroyTrain })

		Experimental:AddButton({
			Text = "Make Tsunami",
			Func = function()
				local cframe = CFrame.new
				tbl12.BlackHole(workspace.Map.AlwaysHereTweenedObjects.Ocean.Object.ObjectModel:GetChildren()[22], cframe(4294967296, 2147483648, 2147483648))
			end,
		})
	end

	do
		local Misc = tbl15.Toys:AddLeftGroupbox("Misc", "funnel")

		Misc:AddDropdown("CoconutFormsDropdown", {
			Values = tbl7.CoconutForms.Names,
			Multi = true,
			AllowNull = true,
			Text = "Forms",
			Callback = function(selected)
				local coconutForms = tbl7.CoconutForms

				for i = #coconutForms.Order, 1, -1 do
					if not selected[coconutForms.Order[i]] then
						table.remove(coconutForms.Order, i)
					end
				end

				for _, v20 in coconutForms.Names, nil, nil do
					if selected[v20] and not table.find(coconutForms.Order, v20) then
						coconutForms.Order[#coconutForms.Order + 1] = v20
					end
				end

				coconutForms.Selected = selected
				tbl12.RefreshCoconutForms()
