				if arg then
					localPlayer.CameraMode = "Classic"
					localPlayer.CameraMaxZoomDistance = "inf"
					localPlayer.CameraMinZoomDistance = 20
					localPlayer.CameraMinZoomDistance = 0.5
				else
					localPlayer.CameraMode = "LockFirstPerson"
				end
			end,
		}):AddKeyPicker("ThirdPersonK", {
			Text = "Third Person",
			Default = "Three",
			Mode = "Toggle",
			NoUI = false,
			SyncToggleState = true,
		})

		Camera:AddToggle("CameraNoclip", { Text = "Camera Noclip", Default = false, Callback = tbl12.SetCameraNoclip })

		Camera:AddSlider("FOVsl", {
			Text = "FOV",
			Default = 70,
			Min = 30,
			Max = 120,
			Callback = function(arg)
				tbl12.SetFOV(arg, false)
			end,
		})

		Camera:AddDivider()

		local function fn21(localTransparencyModifier)
			if not localTransparencyModifier then
				return
			end
			local v20 = tbl12.Char()
			if not (v20 and v20:FindFirstChild("Head")) then
				return
			end

			if (currentCamera.CFrame.Position - currentCamera.Focus.Position).Magnitude > 1.5 then
				localTransparencyModifier = 0
			end

			for _, child in ipairs(v20:GetChildren()) do
				if child:IsA("BasePart") and child.Name ~= "Head" and child.Name ~= "HumanoidRootPart" and child.Name ~= "Torso" then
					child.LocalTransparencyModifier = localTransparencyModifier
				end
			end
		end

		local function fn22()
			fn21(options.RFPTransparency.Value)
		end

		Camera:AddToggle("RealisticFirstPersonT", {
			Text = "Realistic First Person",
			Default = false,
			Callback = function(arg)
				tbl12.SetRuntimeConnection("RealisticFirstPerson", RunService.RenderStepped, arg, fn22)

				if arg then
					fn22()
				else
					fn21(1)
				end
			end,
		})

		Camera:AddSlider("RFPTransparency", {
			Text = "Limb Transparency",
			Default = 0.3,
			Min = 0,
			Max = 1,
			Rounding = 2,
			Callback = function()
				if toggles.RealisticFirstPersonT.Value then
					fn22()
				end
			end,
		})
	end
    -- ============================================================
-- PSHADE -> NULLTRUST : Visual > Shader
-- Dán nguyên khối này vào file nulltrust, ngay TRƯỚC dòng:
--     do
--         local Graphics = tbl15.Visual:AddRightGroupbox("Graphics", "file-image")
-- (khoảng dòng 39947). Khối này tự đóng trong do ... end nên
-- không làm tăng số local của hàm bao ngoài.
-- Dùng các upvalue có sẵn: tbl15, lib, options, toggles.
-- ============================================================
do
	local Lighting = game:GetService("Lighting")
	local RunService = game:GetService("RunService")
	local Players = game:GetService("Players")
	local ws = workspace
	local terrain = ws.Terrain
	local LP = Players.LocalPlayer
	local BASE = "https://raw.githubusercontent.com/randomstring0/pshade-ultimate/refs/heads/main/"

	local function rnd(n)
		local s = ""
		for _ = 1, n or 8 do s ..= string.char(math.random(97, 122)) end
		return s
	end
	local function notify(msg)
		pcall(function() lib:Notify({ Title = "Shader", Description = tostring(msg), Time = 3 }) end)
	end

	-- key trong file preset của pshade (giữ nguyên để tải được preset)
	local K = {
		amb = "yfbghj", clock = "tgvbyd", lat = "ghuybhuyhj", bright = "khnbfth",
		csb = "hgyghkg", cst = "yfbhjku", envd = "ygyyfgvhbjytrt", envs = "sdfcddc",
		gs = "hgnujuu7thgr", oamb = "hyhnngtf", exp = "hdfr7thgr",
		ccb = "fhnchvhfjsd", ccc = "ugtbbjhygt", ccs = "tfbghuugbnjhg", cct = "fvrtccvghghj",
		bli = "jnfdhbnfcvh", bls = "fvtyghj", blt = "ygbhnj", blur = "njnfg",
		dfar = "jdfkd", dfd = "fvgsdfg", dr = "sdkvkflv", dnear = "hbjhd",
		clc = "gyhgtg", cld = "ygbhggv", clcol = "jghbjhgyfd",
		atd = "shdbsnjfc", ato = "skdjfkdm", atcol = "sjdjncdjf", atdec = "efjdjfk",
		atg = "sejfd", ath = "jddfjsd",
	}

	-- giá trị mặc định = lấy từ game, thiếu thì dùng mặc định của Roblox
	local function gv(class, parent, prop, fb)
		local i = parent and parent:FindFirstChildOfClass(class)
		if i then
			local ok, v = pcall(function() return i[prop] end)
			if ok then return v end
		end
		return fb
	end
	local def = {
		[K.amb] = Lighting.Ambient, [K.clock] = Lighting.ClockTime, [K.lat] = Lighting.GeographicLatitude,
		[K.bright] = Lighting.Brightness, [K.csb] = Lighting.ColorShift_Bottom, [K.cst] = Lighting.ColorShift_Top,
		[K.envd] = Lighting.EnvironmentDiffuseScale, [K.envs] = Lighting.EnvironmentSpecularScale,
		[K.gs] = Lighting.GlobalShadows, [K.oamb] = Lighting.OutdoorAmbient, [K.exp] = Lighting.ExposureCompensation,
		[K.ccb] = 0, [K.ccc] = 0, [K.ccs] = 0, [K.cct] = Color3.new(1, 1, 1),
		[K.bli] = 0.4, [K.bls] = 24, [K.blt] = 0.95, [K.blur] = 0,
		[K.dfar] = 0.1, [K.dfd] = 50, [K.dr] = 30, [K.dnear] = 0.1,
		[K.clc] = gv("Clouds", terrain, "Cover", 0), [K.cld] = gv("Clouds", terrain, "Density", 0),
		[K.clcol] = gv("Clouds", terrain, "Color", Color3.new(1, 1, 1)),
		[K.atd] = gv("Atmosphere", Lighting, "Density", 0), [K.ato] = gv("Atmosphere", Lighting, "Offset", 0),
		[K.atcol] = gv("Atmosphere", Lighting, "Color", Color3.fromRGB(199, 170, 107)),
		[K.atdec] = gv("Atmosphere", Lighting, "Decay", Color3.fromRGB(92, 60, 13)),
		[K.atg] = gv("Atmosphere", Lighting, "Glare", 0), [K.ath] = gv("Atmosphere", Lighting, "Haze", 0),
	}
	local cur = setmetatable({}, { __index = def })
	for k, v in pairs(def) do cur[k] = v end

	local flags = { dof = true, cor = true, bl = true, blr = false, rays = false, sflare = false, mblur = false, global = false }
	local extra = { sunI = 0.25, sunS = 0.2, bmsize = 26, reflect = nil, tech = nil, giRadius = 100 }

	-- skybox
	local SKY_DEFAULT = {
		bk = "rbxassetid://9544505500", dn = "rbxassetid://9544547905", ft = "rbxassetid://9544504852",
		lt = "rbxassetid://9544547694", rt = "rbxassetid://9544547542", up = "rbxassetid://9544547398",
	}
	local skyChoice = SKY_DEFAULT
	local skyCache = {}

	local S = { on = false, fx = {}, made = {}, disabled = {}, lightBackup = {}, reflOrig = {}, conns = {}, gi = { parts = {}, on = false } }

	-- ---------- tải preset từ GitHub (cache) ----------
	local function fetch(path)
		if skyCache[path] then return skyCache[path] end
		local ok, res = pcall(function() return loadstring(game:HttpGet(BASE .. path))() end)
		if ok and type(res) == "table" then
			skyCache[path] = res
			return res
		end
		notify("Không tải được: " .. path .. " (kiểm tra mạng / repo)")
	end

	-- ---------- hiệu ứng ----------
	local LIGHT_PROPS = { "Ambient", "Brightness", "ColorShift_Bottom", "ColorShift_Top", "EnvironmentDiffuseScale", "EnvironmentSpecularScale",
		"GlobalShadows", "OutdoorAmbient", "ExposureCompensation", "ClockTime", "GeographicLatitude", "FogEnd", "FogStart", "FogColor" }
	local AT_PROPS = { "Density", "Offset", "Color", "Decay", "Glare", "Haze" }
	local CL_PROPS = { "Cover", "Density", "Color" }
	local SKY_PROPS = { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }

	local function mk(class, parent)
		local i = Instance.new(class)
		i.Name = rnd()
		i:SetAttribute("PSH", true)
		i.Parent = parent
		return i
	end
	local function snapshot(inst, props)
		local t = {}
		for _, p in ipairs(props) do t[p] = inst[p] end
		return t
	end
	local function restoreProps(inst, t)
		for p, v in pairs(t) do pcall(function() inst[p] = v end) end
	end

	local function setTech(name)
		pcall(function()
			(sethiddenproperty or set_hidden_property or set_hidden_prop)(Lighting, "Technology", Enum.Technology[name])
		end)
	end

	local function start()
		if S.on then return end
		S.on = true
		S.lightBackup = snapshot(Lighting, LIGHT_PROPS)
		if gethiddenproperty then
			pcall(function() S.techBackup = gethiddenproperty(Lighting, "Technology") end)
		end
		-- tắt hiệu ứng gốc của game
		for _, c in ipairs(Lighting:GetChildren()) do
			if not c:GetAttribute("PSH") and (c:IsA("BloomEffect") or c:IsA("BlurEffect") or c:IsA("DepthOfFieldEffect")
				or c:IsA("ColorCorrectionEffect") or c:IsA("SunRaysEffect")) then
				S.disabled[c] = c.Enabled
				c.Enabled = false
			end
		end
		local fx = S.fx
		fx.cc = mk("ColorCorrectionEffect", Lighting)
		fx.bloom = mk("BloomEffect", Lighting)
		fx.blur = mk("BlurEffect", Lighting)
		fx.dof = mk("DepthOfFieldEffect", Lighting)
		fx.sray = mk("SunRaysEffect", Lighting)
		fx.mblur = mk("BlurEffect", Lighting)
		fx.mblur.Size = 0

		fx.sky = Lighting:FindFirstChildOfClass("Sky")
		if fx.sky then S.skyBackup = snapshot(fx.sky, SKY_PROPS) else fx.sky = mk("Sky", Lighting); S.made.sky = true end
		fx.at = Lighting:FindFirstChildOfClass("Atmosphere")
		if fx.at then S.atBackup = snapshot(fx.at, AT_PROPS) else fx.at = mk("Atmosphere", Lighting); S.made.at = true end
		fx.cl = terrain:FindFirstChildOfClass("Clouds")
		if fx.cl then S.clBackup = snapshot(fx.cl, CL_PROPS) else fx.cl = mk("Clouds", terrain); S.made.cl = true end
		if S.techBackup == nil then S.techBackup = nil end
		setTech(extra.tech or "ShadowMap")
	end

	local function stop()
		if not S.on then return end
		S.on = false
		for _, c in pairs(S.conns) do pcall(function() c:Disconnect() end) end
		table.clear(S.conns)
		for _, k in ipairs({ "cc", "bloom", "blur", "dof", "sray", "mblur" }) do
			if S.fx[k] then pcall(function() S.fx[k]:Destroy() end) end
		end
		restoreProps(Lighting, S.lightBackup)
		if S.made.sky then S.fx.sky:Destroy() elseif S.skyBackup then restoreProps(S.fx.sky, S.skyBackup) end
		if S.made.at then S.fx.at:Destroy() elseif S.atBackup then restoreProps(S.fx.at, S.atBackup) end
		if S.made.cl then S.fx.cl:Destroy() elseif S.clBackup then restoreProps(S.fx.cl, S.clBackup) end
		table.clear(S.made)
		for c, en in pairs(S.disabled) do
			if c.Parent then c.Enabled = en end
		end
		table.clear(S.disabled)
		if S.techBackup then
			pcall(function() (sethiddenproperty or set_hidden_property or set_hidden_prop)(Lighting, "Technology", S.techBackup) end)
		end
		for p, r in pairs(S.reflOrig) do
			if p.Parent then p.Reflectance = r end
		end
		table.clear(S.reflOrig)
		if S.flareGui then S.flareGui.Enabled = false end
		S.gi.on = false
		for _, e in pairs(S.gi.parts) do pcall(function() e.part:Destroy() end) end
		table.clear(S.gi.parts)
		S.fx = {}
	end

	-- ---------- sun flare ----------
	local FDIST, FSIZE, FTRANS = { 1.7, 0.3, -0.3, -0.9 }, { 0.7, 0.2, 1.2, 0.45 }, { 0.8, 0.7, 0.9, 0.6 }
	local flares, sunLabel = {}, nil
	local function ensureFlare()
		if S.flareGui then return end
		local g = Instance.new("ScreenGui")
		g.Name = rnd()
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 5
		local ok = pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not ok then g.Parent = LP:WaitForChild("PlayerGui") end
		sunLabel = Instance.new("ImageLabel")
		sunLabel.BackgroundTransparency = 1
		sunLabel.SizeConstraint = Enum.SizeConstraint.RelativeYY
		sunLabel.Image = "rbxassetid://277033149"
		sunLabel.ImageColor3 = Color3.new(1, 1, 0.95)
		sunLabel.Size = UDim2.fromScale(3, 3)
		sunLabel.Parent = g
		for i = 1, #FDIST do
			local f = Instance.new("ImageLabel")
			f.BackgroundTransparency = 1
			f.SizeConstraint = Enum.SizeConstraint.RelativeYY
			f.Size = UDim2.fromScale(FSIZE[i] * 0.2, FSIZE[i] * 0.2)
			f.Image = "rbxassetid://15164863822"
			f.ImageColor3 = Color3.new(1, 1, 0.8)
			f.Rotation = -25
			f.Parent = g
			flares[i] = f
		end
		S.flareGui = g
	end

	local rmod, lastLook = 1, nil
	local function stepFlare(cam)
		ensureFlare()
		S.flareGui.Enabled = true
		local p = cam.CFrame.Position
		local sp = cam:WorldToViewportPoint(p + Lighting:GetSunDirection())
		local sunPos, front = Vector2.new(sp.X, sp.Y), sp.Z > 0
		local params = RaycastParams.new()
		params.FilterDescendantsInstances = { LP.Character }
		local hit = ws:Raycast(p, Lighting:GetSunDirection() * 900, params)
		rmod = rmod * 0.5 + (hit and 0 or 1) * 0.5
		local center = cam.ViewportSize / 2
		local vec = sunPos - center
		for i, f in ipairs(flares) do
			f.ImageTransparency = 1 - rmod + FTRANS[i] * rmod
			local pos = center + vec * FDIST[i]
			local s = f.AbsoluteSize
			f.Position = UDim2.fromOffset(pos.X - s.X / 2, pos.Y - s.Y / 2)
			f.Visible = front
		end
		sunLabel.ImageTransparency = 1 - rmod
		local s = sunLabel.AbsoluteSize
		sunLabel.Position = UDim2.fromOffset(sunPos.X - s.X / 2, sunPos.Y - s.Y / 2)
		sunLabel.Visible = front
	end

	-- ---------- áp dụng mỗi frame ----------
	local function apply()
		local c, fx = cur, S.fx
		local cam = ws.CurrentCamera
		fx.cc.Brightness, fx.cc.Contrast, fx.cc.Saturation, fx.cc.TintColor = c[K.ccb], c[K.ccc], c[K.ccs], c[K.cct]
		fx.cc.Enabled = flags.cor
		fx.blur.Enabled, fx.blur.Size = flags.blr, c[K.blur]
		fx.bloom.Enabled, fx.bloom.Intensity, fx.bloom.Size, fx.bloom.Threshold = flags.bl, c[K.bli], c[K.bls], c[K.blt]
		fx.dof.Enabled, fx.dof.FarIntensity, fx.dof.FocusDistance = flags.dof, c[K.dfar], c[K.dfd]
		fx.dof.InFocusRadius, fx.dof.NearIntensity = c[K.dr], c[K.dnear]
		fx.sray.Enabled, fx.sray.Intensity, fx.sray.Spread = flags.rays, extra.sunI, extra.sunS

		Lighting.Ambient, Lighting.ClockTime, Lighting.GeographicLatitude = c[K.amb], c[K.clock], c[K.lat]
		Lighting.Brightness, Lighting.ColorShift_Bottom, Lighting.ColorShift_Top = c[K.bright], c[K.csb], c[K.cst]
		Lighting.EnvironmentDiffuseScale, Lighting.EnvironmentSpecularScale = c[K.envd], c[K.envs]
		Lighting.GlobalShadows, Lighting.OutdoorAmbient, Lighting.ExposureCompensation = c[K.gs], c[K.oamb], c[K.exp]
		Lighting.FogEnd, Lighting.FogStart, Lighting.FogColor = math.huge, math.huge, Color3.new(1, 1, 1)

		fx.cl.Cover, fx.cl.Density, fx.cl.Color = c[K.clc], c[K.cld], c[K.clcol]
		local a = fx.at
		a.Density, a.Offset, a.Color, a.Decay, a.Glare, a.Haze = c[K.atd], c[K.ato], c[K.atcol], c[K.atdec], c[K.atg], c[K.ath]

		local sk = skyChoice
		fx.sky.SkyboxBk, fx.sky.SkyboxDn, fx.sky.SkyboxFt = sk.bk, sk.dn, sk.ft
		fx.sky.SkyboxLf, fx.sky.SkyboxRt, fx.sky.SkyboxUp = sk.lt, sk.rt, sk.up

		if cam then
			if flags.mblur then
				local look = cam.CFrame.LookVector
				lastLook = lastLook or look
				fx.mblur.Size = math.clamp((look - lastLook).Magnitude * 55 / 2, 0, extra.bmsize)
				lastLook = look
			else
				fx.mblur.Size = 0
			end
			if flags.sflare then
				pcall(stepFlare, cam)
			elseif S.flareGui then
				S.flareGui.Enabled = false
			end
		end
	end

	-- ---------- global illumination (nhẹ, giới hạn tốc độ) ----------
	local GRID = 25
	local DIRS = { Vector3.xAxis, -Vector3.xAxis, Vector3.yAxis, -Vector3.yAxis, Vector3.zAxis, -Vector3.zAxis }
	local function giPoint(pos)
		local part = Instance.new("Part")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true, false, false, false
		part.Transparency, part.Size, part.Position, part.Name = 1, Vector3.one, pos, rnd()
		part.Parent = S.gi.folder
		local l = Instance.new("PointLight")
		l.Range, l.Brightness, l.Shadows, l.Parent = 24, 0, false, part
		return { part = part, light = l, pos = pos }
	end
	local function giUpdate(e, params)
		local indoor = ws:Raycast(e.pos, Vector3.new(0, 500, 0), params) ~= nil
		local base = indoor and Color3.fromRGB(255, 240, 220) or cur[K.oamb]
		local br = indoor and 0.35 or 0.75
		local r, g, b, n = 0, 0, 0, 0
		for _, d in ipairs(DIRS) do
			local hit = ws:Raycast(e.pos, d * 10, params)
			if hit and hit.Instance:IsA("BasePart") then
				local col = hit.Instance.Color
				r, g, b, n = r + col.R, g + col.G, b + col.B, n + 1
			end
		end
		if n > 0 then
			local avg = Color3.new(r / n, g / n, b / n)
			base = base:Lerp(avg, 0.7)
		end
		e.light.Color, e.light.Brightness = base, br
	end
	local function giLoop()
		if S.gi.looping then return end
		S.gi.looping = true
		S.gi.folder = S.gi.folder or Instance.new("Folder")
		S.gi.folder.Name = rnd()
		S.gi.folder.Parent = ws
		task.spawn(function()
			while S.gi.on and S.on do
				local cam = ws.CurrentCamera
				if cam then
					local cp, R = cam.CFrame.Position, extra.giRadius
					local params = RaycastParams.new()
					params.FilterDescendantsInstances = { LP.Character, S.gi.folder }
					local seen = {}
					for x = cp.X - R, cp.X + R, GRID do
						for y = cp.Y - R, cp.Y + R, GRID do
							for z = cp.Z - R, cp.Z + R, GRID do
								local pos = Vector3.new(math.floor(x / GRID + 0.5) * GRID, math.floor(y / GRID + 0.5) * GRID, math.floor(z / GRID + 0.5) * GRID)
								if (pos - cp).Magnitude <= R then
									local h = pos.X .. "_" .. pos.Y .. "_" .. pos.Z
									seen[h] = true
									if not S.gi.parts[h] then S.gi.parts[h] = giPoint(pos) end
								end
							end
						end
					end
					local i = 0
					for h, e in pairs(S.gi.parts) do
						if not seen[h] and (e.pos - cp).Magnitude > R + GRID then
							e.part:Destroy()
							S.gi.parts[h] = nil
						else
							giUpdate(e, params)
							i += 1
							if i % 25 == 0 then task.wait() end
						end
					end
				end
				task.wait(2)
			end
			S.gi.looping = false
			for h, e in pairs(S.gi.parts) do pcall(function() e.part:Destroy() end) S.gi.parts[h] = nil end
		end)
	end

	-- ---------- UI ----------
	local G = tbl15.Visual:AddLeftGroupbox("Shader", "sun")
	local sliders = {}

	local function refreshUI()
		S.refreshing = true
		for _, s in ipairs(sliders) do
			local o = options[s[1]]
			if o then pcall(function() o:SetValue(cur[s[2]]) end) end
		end
		S.refreshing = false
	end
	local function usePreset(file)
		if file == "default" then
			cur = setmetatable({}, { __index = def })
			for k, v in pairs(def) do cur[k] = v end
		else
			local p = fetch("shr/" .. file .. ".json")
			if not p then return end
			cur = setmetatable({}, { __index = def })
			for k, v in pairs(p) do cur[k] = v end
		end
		refreshUI()
	end
	local function slider(idx, text, key, min, max, round)
		sliders[#sliders + 1] = { idx, key }
		G:AddSlider(idx, {
			Text = text, Default = math.clamp(tonumber(cur[key]) or 0, min, max), Min = min, Max = max,
			Rounding = round or 2, Compact = true,
			Callback = function(v) if not S.refreshing then cur[key] = v end end,
		})
	end
	local function flagToggle(idx, text, flag)
		G:AddToggle(idx, { Text = text, Default = flags[flag], Callback = function(v) flags[flag] = v end })
	end

	G:AddToggle("PshadeOn", {
		Text = "Shaders (pshade)", Default = false,
		Callback = function(v)
			if v then start(); S.conns.render = RunService.PreRender:Connect(function() if S.on then pcall(apply) end end)
				if flags.global then S.gi.on = true; giLoop() end
			else stop() end
		end,
	})

	G:AddDivider("Presets")
	local function presetDrop(idx, text, list)
		local names = {}
		for _, p in ipairs(list) do names[#names + 1] = p[1] end
		local map = {}
		for _, p in ipairs(list) do map[p[1]] = p[2] end
		G:AddDropdown(idx, { Text = text, Values = names, Default = 1, Searchable = true,
			Callback = function(v) task.spawn(usePreset, map[v]) end })
	end
	presetDrop("PshTime", "Time of day", { { "Default", "default" }, { "Morning", "morning" }, { "Midday", "midday" }, { "Afternoon", "afternoon" },
