	do
		-- ======================= AURA v2 (Visual > Aura): 32 client-side aura effects =======================
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local LP = Players.LocalPlayer

		local TEX_SPARK = "rbxasset://textures/particles/sparkles_main.dds"
		local TEX_FIRE = "rbxasset://textures/particles/fire_main.dds"

		local CSK = ColorSequenceKeypoint.new
		local NSK = NumberSequenceKeypoint.new
		local rad, sin, cos, pi = math.rad, math.sin, math.cos, math.pi
		local WHITE = Color3.new(1, 1, 1)

		local folderRoot = nil
		local function getRoot()
			if not folderRoot or not folderRoot.Parent then
				folderRoot = Instance.new("Folder")
				folderRoot.Name = "Aura_" .. tostring(math.random(100000, 999999))
				folderRoot.Parent = workspace
			end
			return folderRoot
		end

		-- ---------- shared per-frame context ----------
		local C = {}
		local rayParams = RaycastParams.new()
		rayParams.FilterType = Enum.RaycastFilterType.Exclude

		local function updateContext()
			local char = LP.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			local cam = workspace.CurrentCamera
			if not (hum and hrp and cam) then
				return false
			end
			C.char, C.hum, C.hrp = char, hum, hrp
			C.head = char:FindFirstChild("Head")
			C.cf = hrp.CFrame
			C.pos = hrp.Position
			C.camPos = cam.CFrame.Position
			local feet = 3
			if hum.RigType ~= Enum.HumanoidRigType.R6 then
				feet = hum.HipHeight + hrp.Size.Y / 2
			end
			C.feet = feet
			rayParams.FilterDescendantsInstances = { char, folderRoot }
			local res = workspace:Raycast(C.pos, Vector3.new(0, -(feet + 40), 0), rayParams)
			C.gy = (res and res.Position.Y or (C.pos.Y - feet)) + 0.06
			C.camDist = (C.pos - C.camPos).Magnitude
			return true
		end

		-- player's facing direction on the ground plane (everything is attached to the PLAYER, never to the camera)
		local function flatLook()
			local lv = C.cf.LookVector
			local f = Vector3.new(lv.X, 0, lv.Z)
			if f.Magnitude < 0.01 then
				return Vector3.new(0, 0, -1)
			end
			return f.Unit
		end

		local function groundPos(x, z)
			return Vector3.new(x, C.gy, z)
		end

		-- ---------- helpers ----------
		local function newPart(parent, props)
			local p = Instance.new("Part")
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.CastShadow = false
			p.Massless = true
			p.Material = Enum.Material.SmoothPlastic
			p.Size = Vector3.new(0.2, 0.2, 0.2)
			p.TopSurface = Enum.SurfaceType.Smooth
			p.BottomSurface = Enum.SurfaceType.Smooth
			if props then
				for k, v in pairs(props) do
					p[k] = v
				end
			end
			p.Parent = parent
			return p
		end

		local function newSphere(parent, size, color, material, transparency)
			local p = newPart(parent, {
				Size = size,
				Color = color,
				Material = material or Enum.Material.SmoothPlastic,
				Transparency = transparency or 0,
			})
			local m = Instance.new("SpecialMesh")
			m.MeshType = Enum.MeshType.Sphere
			m.Parent = p
			return p
		end

		local function newBall(parent, diameter, color, material, transparency)
			return newPart(parent, {
				Shape = Enum.PartType.Ball,
				Size = Vector3.new(diameter, diameter, diameter),
				Color = color,
				Material = material or Enum.Material.Neon,
				Transparency = transparency or 0,
			})
		end

		local function newEmitter(parent, props)
			local e = Instance.new("ParticleEmitter")
			e.Texture = TEX_SPARK
			e.LightEmission = 1
			e.Rate = 20
			e.Lifetime = NumberRange.new(1, 1.5)
			e.Speed = NumberRange.new(1, 2)
			e.Size = NumberSequence.new(0.5)
			e.Transparency = NumberSequence.new({ NSK(0, 1), NSK(0.15, 0.2), NSK(1, 1) })
			e.Color = ColorSequence.new(WHITE)
			e.Rotation = NumberRange.new(0, 360)
			e.RotSpeed = NumberRange.new(-60, 60)
			if props then
				for k, v in pairs(props) do
					e[k] = v
				end
			end
			e.Parent = parent
			return e
		end

		local function newLight(parent, color, range, brightness)
			local l = Instance.new("PointLight")
			l.Color = color
			l.Range = range
			l.Brightness = brightness
			l.Shadows = false
			l.Parent = parent
			return l
		end

		-- glowing orb with a trail (used for swirling / orbiting streaks)
		local function makeOrb(parent, color, size, life, color2)
			local p = newBall(parent, size, color, Enum.Material.Neon, 0.05)
			local a0 = Instance.new("Attachment")
			a0.Position = Vector3.new(0, size * 0.8, 0)
			a0.Parent = p
			local a1 = Instance.new("Attachment")
			a1.Position = Vector3.new(0, -size * 0.8, 0)
			a1.Parent = p
			local tr = Instance.new("Trail")
			tr.Attachment0 = a0
			tr.Attachment1 = a1
			tr.Lifetime = life
			tr.Color = ColorSequence.new(color, color2 or WHITE)
			tr.Transparency = NumberSequence.new({ NSK(0, 0.1), NSK(1, 1) })
			tr.LightEmission = 1
			tr.FaceCamera = true
			tr.Parent = p
			return p, tr
		end

		local function addHighlight(folder, char, fillColor, fillT, outColor, outT)
			local h = Instance.new("Highlight")
			h.Adornee = char
			h.FillColor = fillColor
			h.FillTransparency = fillT
			h.OutlineColor = outColor or fillColor
			h.OutlineTransparency = outT or 1
			h.DepthMode = Enum.HighlightDepthMode.Occluded
			h.Parent = folder
			return h
		end

		local function hueColor(h, s, v)
			return Color3.fromHSV(h % 1, s or 0.65, v or 1)
		end

		-- ring groups (CanvasGroup) so rings can be faded / pulsed
		local ringGroups = setmetatable({}, { __mode = "k" })
		local function setRingAlpha(part, a)
			local g = ringGroups[part]
			if g then
				for _, cg in ipairs(g) do
					cg.GroupTransparency = a
				end
			end
		end

		local function newGui(p, face, canvas)
			local sg = Instance.new("SurfaceGui")
			sg.Face = face
			sg.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
			sg.CanvasSize = Vector2.new(canvas or 512, canvas or 512)
			sg.LightInfluence = 0
			sg.Brightness = 2
			sg.Adornee = p
			sg.Parent = p
			return sg
		end

		local function newGroup(sg)
			local cg = Instance.new("CanvasGroup")
			cg.Size = UDim2.fromScale(1, 1)
			cg.BackgroundTransparency = 1
			cg.BorderSizePixel = 0
			cg.Parent = sg
			return cg
		end

		local function flatPart(parent, diameter, vertical)
			if vertical then
				return newPart(parent, { Size = Vector3.new(diameter, diameter, 0.05), Transparency = 1 }),
					{ Enum.NormalId.Front, Enum.NormalId.Back }
			end
			return newPart(parent, { Size = Vector3.new(diameter, 0.05, diameter), Transparency = 1 }),
				{ Enum.NormalId.Top, Enum.NormalId.Bottom }
		end

		-- flat glowing ring: UIStroke + gradient + soft glow
		local function makeRing(parent, diameter, c1, c2, thick, vertical)
			local p, faces = flatPart(parent, diameter, vertical)
			local inset = thick * 6 + 12
			local groups = {}
			for _, face in ipairs(faces) do
				local sg = newGui(p, face)
				local cg = newGroup(sg)
				groups[#groups + 1] = cg
				for layer = 1, 2 do
					local fr = Instance.new("Frame")
					fr.AnchorPoint = Vector2.new(0.5, 0.5)
					fr.Position = UDim2.fromScale(0.5, 0.5)
					fr.Size = UDim2.new(1, -inset, 1, -inset)
					fr.BackgroundTransparency = 1
					fr.Parent = cg
					local cor = Instance.new("UICorner")
					cor.CornerRadius = UDim.new(1, 0)
					cor.Parent = fr
					local st = Instance.new("UIStroke")
					st.Thickness = (layer == 1) and (thick * 3) or thick
					st.Transparency = (layer == 1) and 0.8 or 0
					st.Color = WHITE
					st.Parent = fr
					local g = Instance.new("UIGradient")
					g.Color = ColorSequence.new({ CSK(0, c1), CSK(0.5, c2), CSK(1, c1) })
					g.Rotation = 45
					g.Parent = st
				end
			end
			ringGroups[p] = groups
			return p
		end

		local function line(parent, x1, y1, x2, y2, th, col)
			local dx, dy = x2 - x1, y2 - y1
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2)
			f.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), th)
			f.Rotation = math.deg(math.atan2(dy, dx))
			f.BackgroundColor3 = col
			f.BorderSizePixel = 0
			f.Parent = parent
			return f
		end

		-- magic circle: rings + hexagram + diamonds (no fonts / assets needed)
		local function makeMagic(parent, diameter, c1, c2, vertical, points)
			local p, faces = flatPart(parent, diameter, vertical)
			local groups = {}
			for _, face in ipairs(faces) do
				local sg = newGui(p, face)
				local cg = newGroup(sg)
				groups[#groups + 1] = cg
				local function ring(inset, thick, col)
					local fr = Instance.new("Frame")
					fr.AnchorPoint = Vector2.new(0.5, 0.5)
					fr.Position = UDim2.fromScale(0.5, 0.5)
					fr.Size = UDim2.new(1, -inset, 1, -inset)
					fr.BackgroundTransparency = 1
					fr.Parent = cg
					local cor = Instance.new("UICorner")
					cor.CornerRadius = UDim.new(1, 0)
					cor.Parent = fr
					local st = Instance.new("UIStroke")
					st.Thickness = thick
					st.Color = col
					st.Parent = fr
				end
				ring(30, 14, c2) -- soft glow
				ring(24, 5, c1)
				ring(84, 3, c1)
				ring(150, 2, c2)
				local n = points or 6
				local R = 214
				for tri = 0, 1 do
					local pts = {}
					for k = 0, 2 do
						local a = rad((tri * 180) + k * 120 - 90)
						pts[#pts + 1] = { 256 + cos(a) * R, 256 + sin(a) * R }
					end
					for k = 1, 3 do
						local a, b = pts[k], pts[k % 3 + 1]
						line(cg, a[1], a[2], b[1], b[2], 3, tri == 0 and c1 or c2)
					end
				end
				for k = 0, n * 2 - 1 do
					local a = rad(k * (360 / (n * 2)))
					local d = Instance.new("Frame")
					d.AnchorPoint = Vector2.new(0.5, 0.5)
					d.Position = UDim2.fromOffset(256 + cos(a) * 237, 256 + sin(a) * 237)
					d.Size = UDim2.fromOffset(13, 13)
					d.Rotation = 45
					d.BackgroundColor3 = (k % 2 == 0) and c1 or c2
					d.BorderSizePixel = 0
					d.Parent = cg
				end
				local core = Instance.new("Frame")
				core.AnchorPoint = Vector2.new(0.5, 0.5)
				core.Position = UDim2.fromScale(0.5, 0.5)
				core.Size = UDim2.fromOffset(30, 30)
				core.Rotation = 45
				core.BackgroundColor3 = WHITE
				core.BorderSizePixel = 0
				core.Parent = cg
			end
			ringGroups[p] = groups
			return p
		end

		-- heart drawn from frames (square + 2 circles), with glow layers
		local function makeHeart(parent, diameter, color, vertical)
			local p, faces = flatPart(parent, diameter, vertical)
			for _, face in ipairs(faces) do
				local sg = newGui(p, face)
				local function layer(s, col, groupT)
					local cg = newGroup(sg)
					cg.GroupTransparency = groupT
					local cy = 256 + 0.0735 * s
					local function blob(cx, cyy, rot, round)
						local f = Instance.new("Frame")
						f.AnchorPoint = Vector2.new(0.5, 0.5)
						f.Position = UDim2.fromOffset(cx, cyy)
						f.Size = UDim2.fromOffset(s, s)
						f.Rotation = rot
						f.BackgroundColor3 = col
						f.BorderSizePixel = 0
						f.Parent = cg
						if round then
							local c = Instance.new("UICorner")
							c.CornerRadius = UDim.new(1, 0)
							c.Parent = f
						end
					end
					blob(256, cy, 45, false)
					blob(256 - 0.354 * s, cy - 0.354 * s, 0, true)
					blob(256 + 0.354 * s, cy - 0.354 * s, 0, true)
				end
				layer(330, color, 0.82)
				layer(270, color, 0.05)
				layer(140, WHITE, 0.45)
			end
			return p
		end

		-- ---------- character helpers ----------
		local function groupOf(name)
			if name == "Head" then
				return "Head"
			end
			if name:find("Arm") or name:find("Hand") then
				return "Arm"
			end
			if name:find("Leg") or name:find("Foot") then
				return "Leg"
			end
			return "Torso"
		end

		local function snapshotChar(char, hrp)
			local snap = { parts = {}, decals = {} }
			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("BasePart") and d ~= hrp then
					snap.parts[d] = { d.Color, d.Material, d.Transparency }
				elseif d:IsA("Decal") then
					snap.decals[d] = d.Transparency
				end
			end
			function snap.restore()
				for d, v in pairs(snap.parts) do
					if d.Parent then
						d.Color, d.Material, d.Transparency = v[1], v[2], v[3]
					end
				end
				for d, v in pairs(snap.decals) do
					if d.Parent then
						d.Transparency = v
					end
				end
			end
			return snap
		end

		local function bodyParts(char, hrp)
			local list = {}
			for _, d in ipairs(char:GetChildren()) do
				if d:IsA("BasePart") and d ~= hrp then
					list[#list + 1] = d
				end
			end
			return list
		end

		local function torsoOf(char)
			return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
		end

		local function chestCF()
			local tor = torsoOf(C.char)
			if not tor then
				return C.cf
			end
			return tor.CFrame * CFrame.new(0, 0.1, -(tor.Size.Z / 2 + 0.04))
		end

		local function limbTip(char, side)
			local hand = char:FindFirstChild(side .. "Hand")
			if hand then
				return hand.CFrame
			end
			local arm = char:FindFirstChild(side .. " Arm")
			if arm then
				return arm.CFrame * CFrame.new(0, -0.9, 0)
			end
			return C.cf
		end

		local function headCF(lift)
			local h = C.head
			if h then
				return h.CFrame * CFrame.new(0, lift or 0, 0)
			end
			return C.cf * CFrame.new(0, 1.5 + (lift or 0), 0)
		end

		-- shared wing builder (white angel wings / dark angel wings)
		local function buildWings(folder, o)
			local feathers = {}
			for side = -1, 1, 2 do
				for layer = 1, 3 do
					local n = (layer == 1) and 9 or ((layer == 2) and 8 or 7)
					for i = 1, n do
						local f = i / n
						local base
						if layer == 1 then
							base = 3.2 + 2.6 * sin(f * pi * 0.85)
						elseif layer == 2 then
							base = 1.9 + 1.6 * sin(f * pi * 0.85)
						else
							base = 1.0 + 0.9 * sin(f * pi * 0.85)
						end
						local len = base * o.scale
						local bt = o.trans + 0.1 * (layer - 1)
						local part = newSphere(
							folder,
							Vector3.new(0.5 - 0.11 * (layer - 1), 0.07, len),
							o.c1:Lerp(o.c2, f),
							o.material,
							bt
						)
						feathers[#feathers + 1] = {
							part = part,
							side = side,
							th0 = rad(6 + f * 92) - (layer - 1) * rad(4),
							f = f,
							len = len,
							bt = bt,
							ph = i * 0.4 + layer,
						}
					end
				end
			end
			return function(t)
				local flap = sin(t * o.speed) * o.amp
				for _, ft in ipairs(feathers) do
					local rootCF = C.cf * CFrame.new(ft.side * 0.35, 0.55, 0.55)
					local th = ft.th0 + flap * (0.4 + ft.f) + sin(t * o.speed - ft.f * 1.4) * 0.04
					local dir = Vector3.new(ft.side * sin(th), cos(th), o.sweep).Unit
					ft.part.CFrame = rootCF * (CFrame.lookAt(Vector3.zero, dir, Vector3.new(0, 0, 1)) * CFrame.new(0, 0, -ft.len / 2))
					ft.part.Transparency = ft.bt + 0.08 * sin(t * 3 - ft.f * 3 + ft.ph)
				end
			end
		end

		local Builders = {}

		-- ============================== ORIGINAL 10 (improved) ==============================

		-- 1) Ghost outline: see-through body (incl. accessories + face) with glowing wireframe
		Builders.Ghost = function(folder, char, hum, hrp)
			local snap = snapshotChar(char, hrp)
			for d in pairs(snap.parts) do
				if d.Transparency < 1 then
					d.Transparency = 0.86
				end
			end
			local decals = {}
			for d in pairs(snap.decals) do
				decals[#decals + 1] = d
			end
			local boxes = {}
			local function addBox(part)
				local sb = Instance.new("SelectionBox")
				sb.Adornee = part
				sb.LineThickness = 0.025
				sb.Color3 = Color3.fromRGB(255, 240, 225)
				sb.SurfaceTransparency = 1
				sb.Transparency = 0.2
				sb.Parent = folder
				boxes[#boxes + 1] = sb
			end
			for _, d in ipairs(char:GetChildren()) do
				if d:IsA("BasePart") and d ~= hrp then
					addBox(d)
				elseif d:IsA("Accessory") then
					local h = d:FindFirstChild("Handle")
					if h then
						addBox(h)
					end
				end
			end
			local hl = addHighlight(folder, char, Color3.fromRGB(255, 235, 215), 0.92, Color3.fromRGB(255, 240, 225), 0.55)
			local anchor = newPart(folder, { Transparency = 1, Size = Vector3.new(3, 5, 1.5) })
			newEmitter(anchor, {
				Rate = 12,
				Lifetime = NumberRange.new(1.2, 2),
				Speed = NumberRange.new(0.3, 1),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(0.5, 0.45), NSK(1, 0) }),
				Color = ColorSequence.new(Color3.fromRGB(255, 240, 225)),
			})
			local wisps = {}
			for i = 1, 6 do
				local p = makeOrb(folder, Color3.fromRGB(255, 240, 225), 0.14, 0.8, Color3.fromRGB(255, 210, 190))
				wisps[i] = { part = p, ph = i / 6, ang = i * 1.1, r = 1.4 + (i % 3) * 0.35 }
			end
			local function update(dt, t)
				anchor.CFrame = C.cf
				local tr = 0.12 + 0.14 * (sin(t * 2.2) * 0.5 + 0.5)
				for _, sb in ipairs(boxes) do
					sb.Transparency = tr
				end
				hl.OutlineTransparency = 0.45 + 0.3 * sin(t * 2.2)
				local ft = 0.55 + 0.35 * sin(t * 1.6)
				for _, d in ipairs(decals) do
					if d.Parent then
						d.Transparency = ft
					end
				end
				for _, w in ipairs(wisps) do
					local u = (t * 0.35 + w.ph) % 1
					local a = w.ang + t * 1.6
					w.part.CFrame = CFrame.new(C.pos.X + cos(a) * w.r, C.gy + u * 5.2, C.pos.Z + sin(a) * w.r)
					w.part.Transparency = math.max(0.05, math.abs(u - 0.5) * 1.6 - 0.2)
				end
			end
			return update, snap.restore
		end

		-- 2) Angel wings + halo + soft glow on head / accessories
		Builders.Wings = function(folder, char, hum, hrp)
			local gold, white = Color3.fromRGB(255, 232, 150), Color3.fromRGB(255, 255, 255)
			local wingUpdate = buildWings(folder, {
				c1 = white, c2 = Color3.fromRGB(235, 245, 255), material = Enum.Material.Neon,
				trans = 0.1, scale = 1, speed = 2.2, amp = 0.12, sweep = 0.45,
			})
			local halo = makeRing(folder, 2.6, gold, white, 6)
			local hl = addHighlight(folder, char, white, 0.88)
			local anchor = newPart(folder, { Transparency = 1, Size = Vector3.new(2, 2, 1) })
			newEmitter(anchor, {
				Rate = 8,
				Lifetime = NumberRange.new(2, 3),
				Speed = NumberRange.new(0.3, 1.2),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(1, 0.15) }),
				SpreadAngle = Vector2.new(180, 180),
				Acceleration = Vector3.new(0, -1.5, 0),
			})
			local haloLight = newPart(folder, { Transparency = 1 })
			newLight(haloLight, gold, 9, 1.1)
			local function update(dt, t)
				wingUpdate(t)
				anchor.CFrame = C.cf * CFrame.new(0, 1, 1)
				local hc = headCF(1.3 + sin(t * 2) * 0.08)
				halo.CFrame = CFrame.new(hc.Position) * CFrame.Angles(rad(sin(t * 1.3) * 6), t * 1.5, rad(cos(t * 1.1) * 6))
				haloLight.CFrame = CFrame.new(hc.Position)
				setRingAlpha(halo, 0.08 + 0.12 * sin(t * 3))
				hl.FillTransparency = 0.86 + 0.06 * sin(t * 2.4)
			end
			return update, nil
		end

		-- 3) Golden roman clock (locked to the character's back)
		Builders.Clock = function(folder, char, hum, hrp)
			local gold1, gold2 = Color3.fromRGB(255, 226, 120), Color3.fromRGB(196, 140, 24)
			local p = newPart(folder, { Size = Vector3.new(8, 8, 0.1), Transparency = 1 })
			local numerals = { "XII", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI" }
			local hands, spinners = {}, {}

			local function ringFrame(parent, inset, thick, trans)
				local fr = Instance.new("Frame")
				fr.AnchorPoint = Vector2.new(0.5, 0.5)
				fr.Position = UDim2.fromScale(0.5, 0.5)
				fr.Size = UDim2.new(1, -inset, 1, -inset)
				fr.BackgroundTransparency = 1
				fr.Parent = parent
				local cor = Instance.new("UICorner")
				cor.CornerRadius = UDim.new(1, 0)
				cor.Parent = fr
				local st = Instance.new("UIStroke")
				st.Thickness = thick
				st.Transparency = trans
				st.Color = WHITE
				st.Parent = fr
				local g = Instance.new("UIGradient")
				g.Color = ColorSequence.new({ CSK(0, gold1), CSK(0.5, gold2), CSK(1, gold1) })
				g.Rotation = 45
				g.Parent = st
			end

			local function makeHand(parent, width, length, color, speed)
				local holder = Instance.new("Frame")
				holder.AnchorPoint = Vector2.new(0.5, 0.5)
				holder.Position = UDim2.fromScale(0.5, 0.5)
				holder.Size = UDim2.fromScale(width, length * 2)
				holder.BackgroundTransparency = 1
				holder.Parent = parent
				local vis = Instance.new("Frame")
				vis.Size = UDim2.fromScale(1, 0.5)
				vis.BackgroundColor3 = color
				vis.BorderSizePixel = 0
				vis.Parent = holder
				local cor = Instance.new("UICorner")
				cor.CornerRadius = UDim.new(1, 0)
				cor.Parent = vis
				hands[#hands + 1] = { frame = holder, speed = speed }
			end

			local function diamondRing(parent, count, radius, size, speed)
				local holder = Instance.new("Frame")
				holder.AnchorPoint = Vector2.new(0.5, 0.5)
				holder.Position = UDim2.fromScale(0.5, 0.5)
				holder.Size = UDim2.fromScale(1, 1)
				holder.BackgroundTransparency = 1
				holder.Parent = parent
				for k = 0, count - 1 do
					local a = rad(k * (360 / count))
					local d = Instance.new("Frame")
					d.AnchorPoint = Vector2.new(0.5, 0.5)
					d.Position = UDim2.fromScale(0.5 + radius * sin(a), 0.5 - radius * cos(a))
					d.Size = UDim2.fromOffset(size, size)
					d.Rotation = 45 + k * (360 / count)
					d.BackgroundColor3 = (k % 2 == 0) and gold1 or gold2
					d.BorderSizePixel = 0
					d.Parent = holder
				end
				spinners[#spinners + 1] = { frame = holder, speed = speed }
			end

			for _, face in ipairs({ Enum.NormalId.Front, Enum.NormalId.Back }) do
				local sg = newGui(p, face, 600)
				local cg = newGroup(sg)
				cg.GroupTransparency = 0.25
				ringFrame(cg, 30, 10, 0)
				ringFrame(cg, 90, 3, 0.1)
				ringFrame(cg, 420, 2, 0.5)
				diamondRing(cg, 24, 0.44, 12, 8)
				diamondRing(cg, 12, 0.275, 16, -14)
				for k = 0, 11 do
					local a = rad(k * 30)
					local lbl = Instance.new("TextLabel")
					lbl.AnchorPoint = Vector2.new(0.5, 0.5)
					lbl.Position = UDim2.fromScale(0.5 + 0.36 * sin(a), 0.5 - 0.36 * cos(a))
					lbl.Size = UDim2.fromScale(0.14, 0.09)
					lbl.BackgroundTransparency = 1
					lbl.Text = numerals[k + 1]
					lbl.TextScaled = true
					lbl.Font = Enum.Font.Antique
					lbl.TextColor3 = gold1
					lbl.TextStrokeColor3 = gold2
					lbl.TextStrokeTransparency = 0.5
					lbl.Parent = cg
				end
				makeHand(cg, 0.022, 0.22, gold1, 2.5)
				makeHand(cg, 0.014, 0.33, gold1, 30)
				makeHand(cg, 0.006, 0.36, WHITE, 90)
				local dot = Instance.new("Frame")
				dot.AnchorPoint = Vector2.new(0.5, 0.5)
				dot.Position = UDim2.fromScale(0.5, 0.5)
				dot.Size = UDim2.fromScale(0.05, 0.05)
				dot.BackgroundColor3 = gold1
				dot.BorderSizePixel = 0
				dot.Parent = cg
				local dc = Instance.new("UICorner")
				dc.CornerRadius = UDim.new(1, 0)
				dc.Parent = dot
			end
			newLight(p, gold1, 10, 1.2)
			local hl = addHighlight(folder, char, gold1, 0.9)
			local sparkle = newPart(folder, { Transparency = 1, Size = Vector3.new(3, 5, 2) })
			newEmitter(sparkle, {
				Rate = 14,
				Lifetime = NumberRange.new(1.2, 2.2),
				Speed = NumberRange.new(0.3, 1.2),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(0.5, 0.45), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, gold1), CSK(1, gold2) }),
				Acceleration = Vector3.new(0, 1.5, 0),
			})
			local function update(dt, t)
				p.CFrame = C.cf * CFrame.new(0, 0.9 + sin(t * 1.5) * 0.15, 1.9) * CFrame.Angles(0, 0, sin(t * 0.5) * 0.06)
				for _, h in ipairs(hands) do
					h.frame.Rotation = (t * h.speed) % 360
				end
				for _, s in ipairs(spinners) do
					s.frame.Rotation = (t * s.speed) % 360
				end
				sparkle.CFrame = C.cf
				hl.FillTransparency = 0.88 + 0.05 * sin(t * 2)
			end
			return update, nil
		end

		-- 4) Spirit swords (fan locked to the character's back) + ground rings
		Builders.Swords = function(folder, char, hum, hrp)
			local N = 9
			local silver = Color3.fromRGB(235, 245, 255)
			local swords = {}
			for i = 1, N do
				local sw = {
					blade = newPart(folder, { Size = Vector3.new(0.26, 3.2, 0.07), Color = WHITE, Material = Enum.Material.Neon }),
					tip = newPart(folder, { Size = Vector3.new(0.19, 0.19, 0.07), Color = WHITE, Material = Enum.Material.Neon }),
					guard = newPart(folder, { Size = Vector3.new(1.0, 0.14, 0.14), Color = Color3.fromRGB(255, 240, 200), Material = Enum.Material.Neon }),
					grip = newPart(folder, { Size = Vector3.new(0.12, 0.6, 0.12), Color = silver, Material = Enum.Material.Neon }),
					phi = rad(-70 + (i - 1) * 140 / (N - 1)),
					seed = i * 1.7,
					len = (i % 2 == 0) and 0 or 0.5,
				}
				newEmitter(sw.blade, {
					Rate = 5,
					Lifetime = NumberRange.new(0.8, 1.4),
					Speed = NumberRange.new(0.2, 0.8),
					Size = NumberSequence.new({ NSK(0, 0.3), NSK(1, 0) }),
					SpreadAngle = Vector2.new(180, 180),
				})
				swords[i] = sw
			end
			local r1 = makeRing(folder, 6.5, WHITE, Color3.fromRGB(190, 220, 255), 9)
			local r2 = makeRing(folder, 4.4, Color3.fromRGB(190, 220, 255), WHITE, 6)
			local orbs = {}
			for i = 1, 5 do
				local p = makeOrb(folder, WHITE, 0.16, 0.7, Color3.fromRGB(190, 220, 255))
				orbs[i] = { part = p, ph = i / 5 * 6.283 }
			end
			local hl = addHighlight(folder, char, WHITE, 0.9)
			local function update(dt, t)
				local fan = 1 + sin(t * 1.2) * 0.06
				for _, sw in ipairs(swords) do
					local base = C.cf * CFrame.new(0, 0.4, 1.5) * CFrame.Angles(0, 0, sw.phi * fan + sin(t * 1.5 + sw.seed) * 0.05)
					local rise = sin(t * 2 + sw.seed) * 0.12 + sw.len
					sw.grip.CFrame = base * CFrame.new(0, 0.9 + rise, 0)
					sw.guard.CFrame = base * CFrame.new(0, 1.25 + rise, 0)
					sw.blade.CFrame = base * CFrame.new(0, 2.9 + rise, 0)
					sw.tip.CFrame = base * CFrame.new(0, 4.5 + rise, 0) * CFrame.Angles(0, 0, rad(45))
					sw.blade.Transparency = 0.05 + 0.1 * sin(t * 3 + sw.seed)
				end
				local gp = groundPos(C.pos.X, C.pos.Z)
				r1.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 1.2, 0)
				r2.CFrame = CFrame.new(gp) * CFrame.Angles(0, -t * 1.8, 0)
				for _, o in ipairs(orbs) do
					local a = t * 2.4 + o.ph
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * 2.8, C.gy + 0.4 + (sin(t * 3 + o.ph) * 0.5 + 0.5) * 3, C.pos.Z + sin(a) * 2.8)
				end
				hl.FillTransparency = 0.88 + 0.05 * sin(t * 2.6)
			end
			return update, nil
		end

		-- 5) Galaxy vortex (pink / white)
		Builders.Vortex = function(folder, char, hum, hrp)
			local pink, white = Color3.fromRGB(255, 120, 200), Color3.fromRGB(255, 235, 250)
			local rings = {
				{ part = makeRing(folder, 11, pink, white, 8), spin = 1.2, tilt = rad(8), y = 0 },
				{ part = makeRing(folder, 8.5, white, pink, 6), spin = -1.8, tilt = rad(-12), y = 0.3 },
				{ part = makeRing(folder, 6, pink, white, 5), spin = 2.5, tilt = rad(5), y = -0.3 },
			}
			local orbs = {}
			for i = 1, 24 do
				local col = (i % 2 == 0) and pink or white
				local p = makeOrb(folder, col, 0.14, 0.6 + math.random() * 0.4, WHITE)
				orbs[i] = {
					part = p,
					r = 2.6 + math.random() * 3.2,
					h = -1.2 + math.random() * 3,
					speed = 1.5 + math.random() * 2.5,
					phase = math.random() * 6.283,
				}
			end
			local lightPart = newPart(folder, { Transparency = 1 })
			newLight(lightPart, pink, 12, 1.5)
			local hl = addHighlight(folder, char, pink, 0.88, white, 0.7)
			local function update(dt, t)
				for i, r in ipairs(rings) do
					r.part.CFrame = CFrame.new(C.pos + Vector3.new(0, r.y + sin(t * 1.5 + i) * 0.15, 0))
						* CFrame.Angles(r.tilt + sin(t * 0.8 + i) * 0.08, 0, 0) * CFrame.Angles(0, t * r.spin, 0)
					setRingAlpha(r.part, 0.05 + 0.15 * (sin(t * 2 + i * 2) * 0.5 + 0.5))
				end
				for _, o in ipairs(orbs) do
					local a = o.phase + t * o.speed
					o.part.CFrame = CFrame.new(C.pos + Vector3.new(cos(a) * o.r, o.h + sin(t * 2 + o.phase) * 0.25, sin(a) * o.r))
				end
				lightPart.CFrame = CFrame.new(C.pos)
				hl.FillTransparency = 0.85 + 0.07 * sin(t * 3)
			end
			return update, nil
		end

		-- 6) Glitch blocks (body, accessories, face flicker)
		Builders.Glitch = function(folder, char, hum, hrp)
			local cols = {
				Color3.fromRGB(70, 190, 255),
				WHITE,
				Color3.fromRGB(150, 220, 255),
				Color3.fromRGB(110, 140, 255),
			}
			local items = {}
			local function addItem(part)
				items[#items + 1] = {
					src = part,
					box = newPart(folder, { Material = Enum.Material.Neon, Transparency = 0.5, Color = cols[1] }),
					bar = newPart(folder, { Material = Enum.Material.Neon, Transparency = 0.3, Color = cols[2] }),
					nextT = 0,
					off = Vector3.zero,
					boff = Vector3.zero,
				}
			end
			for _, d in ipairs(char:GetChildren()) do
				if d:IsA("BasePart") and d ~= hrp then
					addItem(d)
				elseif d:IsA("Accessory") then
					local h = d:FindFirstChild("Handle")
					if h and h:IsA("BasePart") then
						addItem(h)
					end
				end
			end
			local decals = {}
			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("Decal") then
					decals[d] = d.Transparency
				end
			end
			local hl = addHighlight(folder, char, cols[1], 0.85, WHITE, 0.6)
			local faceNext = 0
			local function update(dt, t)
				for _, it in ipairs(items) do
					if it.src.Parent then
						if t >= it.nextT then
							it.nextT = t + 0.04 + math.random() * 0.12
							local s = it.src.Size
							it.off = Vector3.new((math.random() - 0.5) * 0.5, (math.random() - 0.5) * 0.3, (math.random() - 0.5) * 0.3)
							it.box.Size = s * (1.08 + math.random() * 0.25)
							it.box.Color = cols[math.random(#cols)]
							it.box.Transparency = (math.random() < 0.25) and 1 or (0.35 + math.random() * 0.4)
							it.bar.Size = Vector3.new(s.X * (1.1 + math.random() * 0.5), 0.08 + math.random() * 0.22, s.Z * 1.15)
							it.boff = Vector3.new(0, (math.random() - 0.5) * s.Y * 1.2, 0)
							it.bar.Color = cols[math.random(#cols)]
							it.bar.Transparency = (math.random() < 0.3) and 1 or (math.random() * 0.4)
						end
						it.box.CFrame = it.src.CFrame * CFrame.new(it.off)
						it.bar.CFrame = it.src.CFrame * CFrame.new(it.boff)
					end
				end
				if t >= faceNext then
					faceNext = t + 0.06 + math.random() * 0.2
					for d, orig in pairs(decals) do
						if d.Parent then
							d.Transparency = (math.random() < 0.3) and 0.85 or orig
						end
					end
					hl.FillColor = cols[math.random(#cols)]
					hl.FillTransparency = 0.75 + math.random() * 0.2
				end
			end
			local function cleanup()
				for d, orig in pairs(decals) do
					if d.Parent then
						d.Transparency = orig
					end
				end
			end
			return update, cleanup
		end

		-- 7) Divine blue-violet energy ring
		Builders.Divine = function(folder, char, hum, hrp)
			local violet, blue = Color3.fromRGB(150, 90, 255), Color3.fromRGB(80, 160, 255)
			local g1 = makeRing(folder, 8, violet, WHITE, 9)
			local g2 = makeRing(folder, 5.6, blue, WHITE, 7)
			local o1 = makeRing(folder, 6.4, WHITE, violet, 5)
			local o2 = makeRing(folder, 5.2, WHITE, blue, 4)
			local halo = makeRing(folder, 2.4, blue, WHITE, 5)
			local anchor = newPart(folder, { Transparency = 1, Size = Vector3.new(3.5, 5.5, 3.5) })
			newEmitter(anchor, {
				Shape = Enum.ParticleEmitterShape.Cylinder,
				ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward,
				ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
				Rate = 45,
				Lifetime = NumberRange.new(1.2, 2.2),
				Speed = NumberRange.new(0.5, 2),
				Size = NumberSequence.new({ NSK(0, 0.5), NSK(0.5, 0.8), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(0.5, blue), CSK(1, violet) }),
				Acceleration = Vector3.new(0, 2, 0),
			})
			newLight(anchor, violet, 14, 1.6)
			local hl = addHighlight(folder, char, violet, 0.86, blue, 0.6)
			local orbs = {}
			for i = 1, 8 do
				local p = makeOrb(folder, (i % 2 == 0) and blue or violet, 0.13, 0.6, WHITE)
				orbs[i] = { part = p, ph = i / 8 * 6.283 }
			end
			local function update(dt, t)
				local gp = groundPos(C.pos.X, C.pos.Z)
				g1.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 1.0, 0)
				g2.CFrame = CFrame.new(gp) * CFrame.Angles(0, -t * 1.6, 0)
				o1.CFrame = CFrame.new(C.pos) * CFrame.Angles(rad(70), 0, 0) * CFrame.Angles(0, t * 1.5, 0)
				o2.CFrame = CFrame.new(C.pos) * CFrame.Angles(0, 0, rad(70)) * CFrame.Angles(0, -t * 1.2, 0)
				local hc = headCF(1.4 + sin(t * 2) * 0.08)
				halo.CFrame = CFrame.new(hc.Position) * CFrame.Angles(0, t * 2, 0)
				anchor.CFrame = CFrame.new(C.pos)
				setRingAlpha(g1, 0.05 + 0.15 * sin(t * 2) ^ 2)
				for _, o in ipairs(orbs) do
					local a = t * 2.2 + o.ph
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * 3.2, C.pos.Y + sin(t * 2.5 + o.ph) * 1.8, C.pos.Z + sin(a) * 3.2)
				end
				hl.FillTransparency = 0.84 + 0.07 * sin(t * 3)
			end
			return update, nil
		end

		-- 8) Flame wings + burning head
		Builders.FlameWings = function(folder, char, hum, hrp)
			local orange = Color3.fromRGB(255, 140, 40)
			local fireColor = ColorSequence.new({
				CSK(0, Color3.fromRGB(255, 230, 120)),
				CSK(0.4, Color3.fromRGB(255, 130, 20)),
				CSK(1, Color3.fromRGB(150, 20, 0)),
			})
			local pts = {}
			for side = -1, 1, 2 do
				for k = 0, 4 do
					local a = newPart(folder, { Transparency = 1 })
					newEmitter(a, {
						Texture = TEX_FIRE,
						Rate = 30,
						Lifetime = NumberRange.new(0.5, 0.9),
						Speed = NumberRange.new(1.5, 3),
						Size = NumberSequence.new({ NSK(0, 2.2), NSK(0.5, 1.7), NSK(1, 0) }),
						Color = fireColor,
						Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(0.7, 0.5), NSK(1, 1) }),
						EmissionDirection = Enum.NormalId.Top,
						SpreadAngle = Vector2.new(18, 18),
						Acceleration = Vector3.new(0, 3, 0),
					})
					pts[#pts + 1] = { part = a, side = side, k = k }
				end
			end
			local headFire = newPart(folder, { Transparency = 1 })
			newEmitter(headFire, {
				Texture = TEX_FIRE,
				Rate = 25,
				Lifetime = NumberRange.new(0.4, 0.8),
				Speed = NumberRange.new(1, 2.5),
				Size = NumberSequence.new({ NSK(0, 1.5), NSK(0.5, 1.1), NSK(1, 0) }),
				Color = fireColor,
				Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(0.7, 0.5), NSK(1, 1) }),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(25, 25),
				Acceleration = Vector3.new(0, 3, 0),
			})
			local ember = newPart(folder, { Transparency = 1, Size = Vector3.new(3, 4, 1.5) })
			newEmitter(ember, {
				Rate = 15,
				Lifetime = NumberRange.new(1, 2),
				Speed = NumberRange.new(1, 3),
				Size = NumberSequence.new({ NSK(0, 0.25), NSK(1, 0) }),
				Color = ColorSequence.new(orange),
				Acceleration = Vector3.new(0, 3, 0),
				SpreadAngle = Vector2.new(60, 60),
			})
			local light = newLight(ember, orange, 14, 1.6)
			local hl = addHighlight(folder, char, orange, 0.86, Color3.fromRGB(255, 200, 80), 0.5)
			local function update(dt, t)
				for _, pt in ipairs(pts) do
					local k = pt.k
					local x = pt.side * (0.9 + 0.55 * k + 0.15 * sin(t * 3 + k * 0.5))
					local y = 0.1 + 0.65 * k + sin(t * 4 + k) * 0.08
					pt.part.CFrame = C.cf * CFrame.new(x, y, 0.55) * CFrame.Angles(0, 0, -pt.side * rad(25 + sin(t * 3 + k) * 4))
				end
				headFire.CFrame = CFrame.new(headCF(0.5).Position)
				ember.CFrame = C.cf
				light.Brightness = 1.4 + 0.4 * sin(t * 12)
				hl.FillTransparency = 0.82 + 0.08 * sin(t * 9)
			end
			return update, nil
		end

		-- 9) Bunny spirits (+ bunny ears on your own head)
		Builders.Bunny = function(folder, char, hum, hrp)
			local white = Color3.fromRGB(255, 250, 252)
			local pinkIn = Color3.fromRGB(255, 170, 190)
			local nosePink = Color3.fromRGB(255, 130, 160)
			local black = Color3.fromRGB(20, 20, 24)

			local function makeBunny()
				local pieces = {}
				local function add(part, offCF)
					pieces[#pieces + 1] = { part = part, off = offCF }
				end
				add(newSphere(folder, Vector3.new(1.7, 1.5, 1.5), white), CFrame.new())
				add(newSphere(folder, Vector3.new(0.5, 1.7, 0.3), white), CFrame.new(-0.42, 1.35, 0.05) * CFrame.Angles(0, 0, rad(10)))
				add(newSphere(folder, Vector3.new(0.5, 1.7, 0.3), white), CFrame.new(0.42, 1.35, 0.05) * CFrame.Angles(0, 0, rad(-10)))
				add(newSphere(folder, Vector3.new(0.26, 1.2, 0.15), pinkIn), CFrame.new(-0.42, 1.35, -0.08) * CFrame.Angles(0, 0, rad(10)))
				add(newSphere(folder, Vector3.new(0.26, 1.2, 0.15), pinkIn), CFrame.new(0.42, 1.35, -0.08) * CFrame.Angles(0, 0, rad(-10)))
				add(newSphere(folder, Vector3.new(0.2, 0.26, 0.1), black), CFrame.new(-0.38, 0.12, -0.72))
				add(newSphere(folder, Vector3.new(0.2, 0.26, 0.1), black), CFrame.new(0.38, 0.12, -0.72))
				add(newSphere(folder, Vector3.new(0.18, 0.12, 0.1), nosePink), CFrame.new(0, -0.1, -0.76))
				add(newSphere(folder, Vector3.new(0.3, 0.2, 0.1), nosePink, nil, 0.5), CFrame.new(-0.62, -0.15, -0.52))
				add(newSphere(folder, Vector3.new(0.3, 0.2, 0.1), nosePink, nil, 0.5), CFrame.new(0.62, -0.15, -0.52))
				return pieces
			end

			local bunnies = {}
			for side = -1, 1, 2 do
				bunnies[#bunnies + 1] = {
					side = side,
					pieces = makeBunny(),
					ringA = makeRing(folder, 3.6, white, pinkIn, 7),
					ringB = makeRing(folder, 2.4, pinkIn, white, 5),
				}
			end
			local wings = {}
			for side = -1, 1, 2 do
				wings[#wings + 1] = {
					side = side, len = 3.2, ang = 55,
					part = newSphere(folder, Vector3.new(0.55, 3.2, 0.25), Color3.fromRGB(255, 240, 245), Enum.Material.Neon, 0.1),
				}
				wings[#wings + 1] = {
					side = side, len = 2.4, ang = 85,
					part = newSphere(folder, Vector3.new(0.45, 2.4, 0.22), Color3.fromRGB(255, 240, 245), Enum.Material.Neon, 0.2),
				}
			end
			local ears = {}
			for side = -1, 1, 2 do
				ears[#ears + 1] = {
					side = side,
					outer = newSphere(folder, Vector3.new(0.45, 1.5, 0.22), white),
					inner = newSphere(folder, Vector3.new(0.22, 1.0, 0.12), pinkIn),
				}
			end
			local hl = addHighlight(folder, char, pinkIn, 0.9)
			local hearts = newPart(folder, { Transparency = 1, Size = Vector3.new(5, 1, 5) })
			newEmitter(hearts, {
				Rate = 10,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.5, 1.5),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(0.5, 0.5), NSK(1, 0) }),
				Color = ColorSequence.new(pinkIn),
				Acceleration = Vector3.new(0, 1.5, 0),
			})
			local function update(dt, t)
				local fl = flatLook()
				for _, b in ipairs(bunnies) do
					local pos = (C.cf * CFrame.new(b.side * 3.2, -0.4 + sin(t * 2 + b.side) * 0.25, -0.2)).Position
					local rootCF = CFrame.lookAt(pos, pos + fl) * CFrame.Angles(0, 0, sin(t * 2.4 + b.side) * 0.08)
					for _, pc in ipairs(b.pieces) do
						pc.part.CFrame = rootCF * pc.off
					end
					local gp = groundPos(pos.X, pos.Z)
					b.ringA.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 1.4, 0)
					b.ringB.CFrame = CFrame.new(gp) * CFrame.Angles(0, -t * 2.0, 0)
				end
				local flap = sin(t * 2.4) * 6
				for _, w in ipairs(wings) do
					local root = C.cf * CFrame.new(w.side * 1.1, 0.8, 0.5)
					w.part.CFrame = root * CFrame.Angles(0, 0, -w.side * rad(w.ang + flap)) * CFrame.new(0, w.len / 2, 0)
				end
				local flick = (sin(t * 1.3) > 0.9) and 16 or 0
				for _, e in ipairs(ears) do
					local sway = 12 + sin(t * 2 + e.side) * 5 + flick
					local root = headCF(0.5) * CFrame.new(e.side * 0.35, 0, 0) * CFrame.Angles(0, 0, -e.side * rad(sway))
					e.outer.CFrame = root * CFrame.new(0, 0.75, 0)
					e.inner.CFrame = root * CFrame.new(0, 0.75, -0.06)
				end
				hearts.CFrame = C.cf
				hl.FillTransparency = 0.88 + 0.05 * sin(t * 2.5)
			end
			return update, nil
		end

		-- 10) Crimson flame ring
		Builders.Crimson = function(folder, char, hum, hrp)
			local red, pink, white = Color3.fromRGB(255, 40, 60), Color3.fromRGB(255, 120, 150), Color3.fromRGB(255, 235, 240)
			local r1 = makeRing(folder, 6.5, red, pink, 10)
			local r2 = makeRing(folder, 4.2, pink, white, 6)
			local disc = newPart(folder, { Transparency = 1, Size = Vector3.new(5, 0.2, 5) })
			newEmitter(disc, {
				Texture = TEX_FIRE,
				Rate = 80,
				Lifetime = NumberRange.new(0.8, 1.3),
				Speed = NumberRange.new(3, 6),
				Size = NumberSequence.new({ NSK(0, 1.8), NSK(0.5, 1.4), NSK(1, 0) }),
				Color = ColorSequence.new({
					CSK(0, Color3.fromRGB(255, 160, 170)),
					CSK(0.4, Color3.fromRGB(255, 50, 70)),
					CSK(1, Color3.fromRGB(140, 10, 40)),
				}),
				Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(0.7, 0.5), NSK(1, 1) }),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(8, 8),
			})
			local light = newLight(disc, red, 12, 1.5)
			local sparks = {}
			for i = 1, 10 do
				local p, tr = makeOrb(folder, (i % 2 == 0) and red or pink, 0.12, 0.5, pink)
				sparks[i] = { part = p, trail = tr, ph = i / 10 }
			end
			local hl = addHighlight(folder, char, red, 0.86, pink, 0.6)
			local function update(dt, t)
				local gp = groundPos(C.pos.X, C.pos.Z)
				r1.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 1.3, 0)
				r2.CFrame = CFrame.new(gp) * CFrame.Angles(0, -t * 2.2, 0)
				setRingAlpha(r1, 0.05 + 0.15 * sin(t * 4) ^ 2)
				disc.CFrame = CFrame.new(gp + Vector3.new(0, 0.1, 0))
				for _, s in ipairs(sparks) do
					local u = (t * 0.45 + s.ph) % 1
					local ang = t * 3.5 + s.ph * 6.283
					local r = 2.6 * (1 - u * 0.6)
					s.part.CFrame = CFrame.new(C.pos.X + cos(ang) * r, C.gy + u * 5, C.pos.Z + sin(ang) * r)
					s.trail.Enabled = u > 0.05
				end
				light.Brightness = 1.4 + 0.5 * sin(t * 8)
				hl.FillTransparency = 0.82 + 0.08 * sin(t * 6)
			end
			return update, nil
		end

		-- ============================== NEW 8 (from your reference image) ==============================

		-- 11) Pink bubble: translucent pink sphere with glowing orbs inside
		Builders.PinkBubble = function(folder, char, hum, hrp)
			local pink, soft = Color3.fromRGB(255, 140, 170), Color3.fromRGB(255, 205, 220)
			local outer = newBall(folder, 9, pink, Enum.Material.Neon, 0.82)
			local inner = newBall(folder, 8.2, soft, Enum.Material.Neon, 0.93)
			local shadow = makeRing(folder, 9, pink, WHITE, 7)
			local center = newPart(folder, { Transparency = 1, Size = Vector3.new(6, 6, 6) })
			newEmitter(center, {
				Shape = Enum.ParticleEmitterShape.Sphere,
				ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
				Rate = 25,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.2, 0.8),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(0.5, 0.5), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(1, pink) }),
			})
			newLight(center, pink, 14, 1.4)
			local glow = newBall(folder, 1.0, WHITE, Enum.Material.Neon, 0.1)
			newLight(glow, soft, 10, 2)
			local orbs = {}
			for i = 1, 5 do
				local p = makeOrb(folder, (i % 2 == 0) and soft or WHITE, 0.2, 0.7, pink)
				orbs[i] = { part = p, ph = i / 5 * 6.283, r = 2.3 + (i % 3) * 0.5 }
			end
			local hl = addHighlight(folder, char, pink, 0.88)
			local function update(dt, t)
				local D = 9 + sin(t * 2) * 0.35
				outer.Size = Vector3.new(D, D, D)
				inner.Size = Vector3.new(D - 0.8, D - 0.8, D - 0.8)
				outer.CFrame = CFrame.new(C.pos)
				inner.CFrame = CFrame.new(C.pos)
				outer.Transparency = 0.8 + 0.05 * sin(t * 2.5)
				center.CFrame = CFrame.new(C.pos)
				local gp = groundPos(C.pos.X, C.pos.Z)
				shadow.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 0.8, 0)
				glow.CFrame = CFrame.new(C.pos + Vector3.new(cos(t * 1.2) * 2.6, sin(t * 1.7) * 0.9 + 0.3, sin(t * 1.2) * 2.6))
				local g = 1 + 0.3 * sin(t * 4)
				glow.Size = Vector3.new(g, g, g)
				for _, o in ipairs(orbs) do
					local a = t * 2 + o.ph
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * o.r, C.pos.Y + sin(t * 2.2 + o.ph) * 1.6, C.pos.Z + sin(a) * o.r)
				end
				hl.FillTransparency = 0.86 + 0.05 * sin(t * 3)
			end
			return update, nil, 8.5
		end

		-- 12) Heart bloom: pulsing heart on the ground + pink flames in the hands
		Builders.HeartBloom = function(folder, char, hum, hrp)
			local pink, hot = Color3.fromRGB(255, 120, 170), Color3.fromRGB(255, 70, 130)
			local heart = makeHeart(folder, 7, pink, false)
			local ring = makeRing(folder, 9.5, pink, WHITE, 6)
			local dust = newPart(folder, { Transparency = 1, Size = Vector3.new(7, 0.3, 7) })
			newEmitter(dust, {
				Rate = 45,
				Lifetime = NumberRange.new(1, 2),
				Speed = NumberRange.new(0.5, 2),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(0.5, 0.5), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(1, hot) }),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(25, 25),
			})
			local flame = ColorSequence.new({ CSK(0, Color3.fromRGB(255, 220, 235)), CSK(0.4, pink), CSK(1, Color3.fromRGB(180, 30, 110)) })
			local hands = {}
			for _, side in ipairs({ "Left", "Right" }) do
				local a = newPart(folder, { Transparency = 1 })
				newEmitter(a, {
					Texture = TEX_FIRE,
					Rate = 35,
					Lifetime = NumberRange.new(0.4, 0.8),
					Speed = NumberRange.new(1, 2.5),
					Size = NumberSequence.new({ NSK(0, 1.3), NSK(0.5, 1.0), NSK(1, 0) }),
					Color = flame,
					Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(0.7, 0.5), NSK(1, 1) }),
					EmissionDirection = Enum.NormalId.Top,
					SpreadAngle = Vector2.new(20, 20),
					Acceleration = Vector3.new(0, 2, 0),
				})
				hands[#hands + 1] = { part = a, side = side }
			end
			local orbs = {}
			for i = 1, 8 do
				local p = makeOrb(folder, (i % 2 == 0) and pink or WHITE, 0.13, 0.6, hot)
				orbs[i] = { part = p, ph = i / 8 }
			end
			local chestHeart = makeHeart(folder, 1.0, hot, true)
			local hl = addHighlight(folder, char, pink, 0.88)
			local function update(dt, t)
				local gp = groundPos(C.pos.X, C.pos.Z)
				local beat = 1 + 0.08 * sin(t * 5) + 0.05 * sin(t * 10)
				heart.Size = Vector3.new(7 * beat, 0.05, 7 * beat)
				heart.CFrame = CFrame.lookAt(gp, gp + flatLook()) * CFrame.Angles(0, sin(t * 0.8) * 0.2, 0)
				dust.CFrame = CFrame.new(gp + Vector3.new(0, 0.1, 0))
				ring.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 0.9, 0)
				setRingAlpha(ring, 0.1 + 0.2 * sin(t * 3) ^ 2)
				for _, h in ipairs(hands) do
					h.part.CFrame = CFrame.new(limbTip(C.char, h.side).Position)
				end
				for _, o in ipairs(orbs) do
					local u = (t * 0.3 + o.ph) % 1
					local a = t * 2 + o.ph * 6.283
					local r = 3.4 * (1 - u * 0.5)
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * r, C.gy + u * 4.5, C.pos.Z + sin(a) * r)
				end
				local cb = 0.9 * (1 + 0.12 * sin(t * 5))
				chestHeart.Size = Vector3.new(cb, cb, 0.05)
				chestHeart.CFrame = chestCF()
				hl.FillTransparency = 0.84 + 0.07 * sin(t * 5)
			end
			return update, nil
		end

		-- 13) Arcane purple: glowing white body, magic circles, ripples, chest sigil
		Builders.Arcane = function(folder, char, hum, hrp)
			local violet, pink = Color3.fromRGB(190, 90, 255), Color3.fromRGB(255, 130, 230)
			local snap = snapshotChar(char, hrp)
			local body = bodyParts(char, hrp)
			for _, b in ipairs(body) do
				b.Color = WHITE
				b.Material = Enum.Material.Neon
			end
			local c1 = makeMagic(folder, 12, pink, violet, false)
			local c2 = makeMagic(folder, 7, violet, WHITE, false)
			local back = makeMagic(folder, 9, pink, violet, true)
			local sigil = makeMagic(folder, 1.1, WHITE, pink, true, 4)
			local ripples = {}
			for i = 1, 3 do
				ripples[i] = { part = makeRing(folder, 4, pink, WHITE, 6), ph = i / 3 }
			end
			local orbs = {}
			for i = 1, 12 do
				local p = makeOrb(folder, (i % 2 == 0) and pink or violet, 0.14, 0.6, WHITE)
				orbs[i] = { part = p, ph = math.random() * 6.283, r = 2 + math.random() * 2.2, sp = 1.5 + math.random() * 2, h = math.random() * 4 }
			end
			local sparkle = newPart(folder, { Transparency = 1, Size = Vector3.new(3.5, 5.5, 3.5) })
			newEmitter(sparkle, {
				Shape = Enum.ParticleEmitterShape.Cylinder,
				ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
				Rate = 40,
				Lifetime = NumberRange.new(1.2, 2.2),
				Speed = NumberRange.new(0.5, 2),
				Size = NumberSequence.new({ NSK(0, 0.5), NSK(0.5, 0.8), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(0.5, pink), CSK(1, violet) }),
				Acceleration = Vector3.new(0, 2.5, 0),
			})
			newLight(sparkle, violet, 14, 1.6)
			local hl = addHighlight(folder, char, violet, 0.8, pink, 0.5)
			local function update(dt, t)
				local gp = groundPos(C.pos.X, C.pos.Z)
				c1.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 0.5, 0)
				c2.CFrame = CFrame.new(gp + Vector3.new(0, 0.02, 0)) * CFrame.Angles(0, -t * 0.9, 0)
				back.CFrame = C.cf * CFrame.new(0, 1.0, 2.2) * CFrame.Angles(0, 0, t * 0.4)
				sigil.CFrame = chestCF() * CFrame.Angles(0, 0, t * 1.5)
				setRingAlpha(back, 0.3 + 0.15 * sin(t * 2) ^ 2)
				for _, r in ipairs(ripples) do
					local u = (t * 0.45 + r.ph) % 1
					local D = 3 + 9 * u
					r.part.Size = Vector3.new(D, 0.05, D)
					r.part.CFrame = CFrame.new(gp + Vector3.new(0, 0.04, 0))
					setRingAlpha(r.part, 0.15 + 0.85 * u)
				end
				for _, o in ipairs(orbs) do
					local a = o.ph + t * o.sp
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * o.r, C.gy + 0.5 + (o.h + t * 0.8) % 4.5, C.pos.Z + sin(a) * o.r)
				end
				sparkle.CFrame = CFrame.new(C.pos)
				local m = 0.5 + 0.5 * sin(t * 3)
				local glowCol = WHITE:Lerp(Color3.fromRGB(245, 205, 255), m)
				for _, b in ipairs(body) do
					b.Color = glowCol
				end
				hl.FillTransparency = 0.78 + 0.08 * sin(t * 3)
			end
			return update, snap.restore
		end

		-- 14) Color shift: body parts cycle through colors (head / torso / arms / legs each offset)
		Builders.ColorShift = function(folder, char, hum, hrp)
			local snap = snapshotChar(char, hrp)
			local body = bodyParts(char, hrp)
			local offs = { Head = 0.0, Torso = 0.22, Arm = 0.5, Leg = 0.78 }
			local items = {}
			for _, b in ipairs(body) do
				items[#items + 1] = { part = b, off = offs[groupOf(b.Name)] }
			end
			local hl = addHighlight(folder, char, WHITE, 0.8)
			local ring = makeRing(folder, 7, Color3.fromRGB(255, 120, 200), Color3.fromRGB(110, 220, 255), 8)
			local rainbow = ColorSequence.new({
				CSK(0, hueColor(0)), CSK(0.2, hueColor(0.2)), CSK(0.4, hueColor(0.4)),
				CSK(0.6, hueColor(0.6)), CSK(0.8, hueColor(0.8)), CSK(1, hueColor(1)),
			})
			local sparkle = newPart(folder, { Transparency = 1, Size = Vector3.new(3.5, 5.5, 3.5) })
			newEmitter(sparkle, {
				Shape = Enum.ParticleEmitterShape.Cylinder,
				ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
				Rate = 35,
				Lifetime = NumberRange.new(1, 2),
				Speed = NumberRange.new(0.5, 2),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(0.5, 0.6), NSK(1, 0) }),
				Color = rainbow,
				Acceleration = Vector3.new(0, 2, 0),
			})
			local orbs = {}
			for i = 1, 8 do
				local p = makeOrb(folder, hueColor(i / 8), 0.14, 0.6, WHITE)
				orbs[i] = { part = p, ph = i / 8 }
			end
			local function update(dt, t)
				for _, it in ipairs(items) do
					if it.part.Parent then
						it.part.Color = hueColor(t * 0.2 + it.off)
					end
				end
				hl.FillColor = hueColor(t * 0.2 + 0.35, 0.5, 1)
				hl.FillTransparency = 0.78 + 0.08 * sin(t * 3)
				ring.CFrame = CFrame.new(groundPos(C.pos.X, C.pos.Z)) * CFrame.Angles(0, t * 1.4, 0)
				sparkle.CFrame = CFrame.new(C.pos)
				for _, o in ipairs(orbs) do
					local a = t * 2.4 + o.ph * 6.283
					o.part.Color = hueColor(t * 0.3 + o.ph)
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * 3, C.pos.Y + sin(t * 2 + o.ph * 6) * 1.4, C.pos.Z + sin(a) * 3)
				end
			end
			return update, snap.restore
		end

		-- 15) Pink core: heartbeat energy orb in the chest + expanding ripples
		Builders.PinkCore = function(folder, char, hum, hrp)
			local pink, hot = Color3.fromRGB(255, 110, 160), Color3.fromRGB(255, 50, 90)
			local core = newBall(folder, 0.8, WHITE, Enum.Material.Neon, 0)
			local coreLight = newLight(core, pink, 12, 2)
			local flare = newPart(folder, { Transparency = 1 })
			newEmitter(flare, {
				Rate = 30,
				Lifetime = NumberRange.new(0.6, 1.2),
				Speed = NumberRange.new(2, 5),
				Size = NumberSequence.new({ NSK(0, 0.6), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(1, hot) }),
				SpreadAngle = Vector2.new(180, 180),
			})
			local ripples = {}
			for i = 1, 4 do
				ripples[i] = { part = makeRing(folder, 4, hot, pink, 7), ph = i / 4 }
			end
			local ground = makeRing(folder, 10, hot, pink, 6)
			local orbs = {}
			for i = 1, 8 do
				local p = makeOrb(folder, (i % 2 == 0) and pink or WHITE, 0.12, 0.5, hot)
				orbs[i] = { part = p, ph = i / 8 }
			end
			local hl = addHighlight(folder, char, hot, 0.86, pink, 0.6)
			local function update(dt, t)
				local beat = math.max(0, sin(t * 6)) ^ 3 + 0.5 * math.max(0, sin(t * 6 - 1.2)) ^ 3
				local s = 0.7 + 0.5 * beat
				core.Size = Vector3.new(s, s, s)
				core.CFrame = CFrame.new(chestCF().Position)
				coreLight.Brightness = 1.5 + 2 * beat
				flare.CFrame = core.CFrame
				local gp = groundPos(C.pos.X, C.pos.Z)
				ground.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 1.1, 0)
				setRingAlpha(ground, 0.1 + 0.3 * (1 - beat))
				for _, r in ipairs(ripples) do
					local u = (t * 0.5 + r.ph) % 1
					local D = 2.5 + 10 * u
					r.part.Size = Vector3.new(D, 0.05, D)
					r.part.CFrame = CFrame.new(gp + Vector3.new(0, 0.04, 0))
					setRingAlpha(r.part, 0.1 + 0.9 * u)
				end
				for _, o in ipairs(orbs) do
					local a = t * 2.6 + o.ph * 6.283
					local r = 1.8 + 1.2 * ((t * 0.5 + o.ph) % 1)
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * r, C.pos.Y + sin(t * 2 + o.ph * 6) * 1.5, C.pos.Z + sin(a) * r)
				end
				hl.FillTransparency = 0.88 - 0.2 * beat
			end
			return update, nil
		end

		-- 16) Jade dome: green translucent dome + rune circles
		Builders.JadeDome = function(folder, char, hum, hrp)
			local green, mint = Color3.fromRGB(90, 255, 170), Color3.fromRGB(190, 255, 225)
			local dome = newBall(folder, 10, green, Enum.Material.Neon, 0.88)
			local shell = newBall(folder, 9.3, mint, Enum.Material.Neon, 0.94)
			local c1 = makeMagic(folder, 11, green, mint, false)
			local c2 = makeMagic(folder, 6.5, mint, green, false)
			local ripples = {}
			for i = 1, 3 do
				ripples[i] = { part = makeRing(folder, 4, green, mint, 6), ph = i / 3 }
			end
			local sparkle = newPart(folder, { Transparency = 1, Size = Vector3.new(7, 5, 7) })
			newEmitter(sparkle, {
				Shape = Enum.ParticleEmitterShape.Cylinder,
				ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
				Rate = 35,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.3, 1),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(0.5, 0.5), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, WHITE), CSK(1, green) }),
				Acceleration = Vector3.new(0, 1.5, 0),
			})
			newLight(sparkle, green, 14, 1.2)
			local orbs = {}
			for i = 1, 8 do
				local p = makeOrb(folder, (i % 2 == 0) and green or mint, 0.13, 0.6, WHITE)
				orbs[i] = { part = p, ph = i / 8 }
			end
			local hl = addHighlight(folder, char, green, 0.9, mint, 0.7)
			local function update(dt, t)
				local D = 10 + sin(t * 1.6) * 0.3
				dome.Size = Vector3.new(D, D, D)
				shell.Size = Vector3.new(D - 0.7, D - 0.7, D - 0.7)
				dome.CFrame = CFrame.new(C.pos)
				shell.CFrame = CFrame.new(C.pos)
				dome.Transparency = 0.86 + 0.04 * sin(t * 2)
				local gp = groundPos(C.pos.X, C.pos.Z)
				c1.CFrame = CFrame.new(gp) * CFrame.Angles(0, t * 0.4, 0)
				c2.CFrame = CFrame.new(gp + Vector3.new(0, 0.02, 0)) * CFrame.Angles(0, -t * 0.8, 0)
				for _, r in ipairs(ripples) do
					local u = (t * 0.4 + r.ph) % 1
					local D2 = 3 + 8 * u
					r.part.Size = Vector3.new(D2, 0.05, D2)
					r.part.CFrame = CFrame.new(gp + Vector3.new(0, 0.04, 0))
					setRingAlpha(r.part, 0.15 + 0.85 * u)
				end
				sparkle.CFrame = CFrame.new(C.pos)
				for _, o in ipairs(orbs) do
					local a = t * 1.8 + o.ph * 6.283
					o.part.CFrame = CFrame.new(C.pos.X + cos(a) * 3.6, C.gy + 0.6 + (sin(t * 1.4 + o.ph * 7) * 0.5 + 0.5) * 3.5, C.pos.Z + sin(a) * 3.6)
				end
				hl.FillTransparency = 0.88 + 0.05 * sin(t * 2.4)
			end
			return update, nil, 8.5
		end

		-- 17) Dark angel: purple-black wings, glowing heart on the chest, pink-white rings
		Builders.DarkAngel = function(folder, char, hum, hrp)
			local pink = Color3.fromRGB(255, 120, 200)
			local wingUpdate = buildWings(folder, {
				c1 = Color3.fromRGB(35, 10, 65), c2 = Color3.fromRGB(150, 70, 220), material = Enum.Material.Neon,
				trans = 0.05, scale = 1.05, speed = 1.8, amp = 0.14, sweep = 0.4,
			})
			local heart = makeHeart(folder, 1.0, pink, true)
			local r1 = makeRing(folder, 13, pink, WHITE, 6)
			local r2 = makeRing(folder, 10, WHITE, pink, 5)
			local orbs = {}
			for i = 1, 14 do
				local col = (i % 2 == 0) and pink or WHITE
				local p = makeOrb(folder, col, 0.14, 0.7, WHITE)
				orbs[i] = { part = p, ph = math.random() * 6.283, r = 3.5 + math.random() * 3, sp = 2 + math.random() * 2.5, h = -0.5 + math.random() * 1.5 }
			end
			local sparkle = newPart(folder, { Transparency = 1, Size = Vector3.new(3, 5, 2) })
			newEmitter(sparkle, {
				Rate = 18,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.3, 1.2),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(0.5, 0.45), NSK(1, 0) }),
				Color = ColorSequence.new({ CSK(0, pink), CSK(1, Color3.fromRGB(150, 70, 220)) }),
				Acceleration = Vector3.new(0, 1, 0),
			})
			local lightPart = newPart(folder, { Transparency = 1 })
			newLight(lightPart, pink, 12, 1.4)
			local hl = addHighlight(folder, char, Color3.fromRGB(120, 50, 200), 0.86, pink, 0.5)
			local function update(dt, t)
				wingUpdate(t)
				local beat = 1 + 0.12 * sin(t * 5)
				heart.Size = Vector3.new(beat, beat, 0.05)
				heart.CFrame = chestCF()
				r1.CFrame = CFrame.new(C.pos + Vector3.new(0, 0.3, 0)) * CFrame.Angles(rad(18), 0, rad(sin(t * 0.7) * 8)) * CFrame.Angles(0, t * 1.6, 0)
				r2.CFrame = CFrame.new(C.pos + Vector3.new(0, 0.1, 0)) * CFrame.Angles(rad(-14), 0, rad(cos(t * 0.9) * 8)) * CFrame.Angles(0, -t * 2.2, 0)
				setRingAlpha(r1, 0.05 + 0.15 * sin(t * 2.5) ^ 2)
				for _, o in ipairs(orbs) do
					local a = o.ph + t * o.sp
					o.part.CFrame = CFrame.new(C.pos + Vector3.new(cos(a) * o.r, o.h + sin(t * 2 + o.ph) * 0.4, sin(a) * o.r))
				end
				sparkle.CFrame = C.cf
				lightPart.CFrame = chestCF()
				hl.FillTransparency = 0.84 + 0.06 * sin(t * 2.4)
			end
			return update, nil
		end

		-- 18) Hat squish: hats / hair get squashed and bounce
		Builders.HatSquish = function(folder, char, hum, hrp)
			local items = {}
			for _, acc in ipairs(char:GetChildren()) do
				if acc:IsA("Accessory") then
					local at = acc.AccessoryType
					if at == Enum.AccessoryType.Hat or at == Enum.AccessoryType.Hair or at == Enum.AccessoryType.Unknown then
						local handle = acc:FindFirstChild("Handle")
						if handle and handle:IsA("BasePart") then
							local it = { handle = handle }
							local weld = handle:FindFirstChild("AccessoryWeld")
							if weld and weld:IsA("Weld") then
								it.weld = weld
								it.c1 = weld.C1
							end
							local mesh = handle:FindFirstChildOfClass("SpecialMesh")
							if mesh then
								it.mesh = mesh
								it.scale = mesh.Scale
								it.sizeY = handle.Size.Y
							elseif handle:IsA("MeshPart") then
								it.size = handle.Size
							end
							items[#items + 1] = it
						end
					end
				end
			end
			local stars = {}
			for i = 1, 4 do
				local p = makeOrb(folder, (i % 2 == 0) and Color3.fromRGB(255, 230, 140) or WHITE, 0.14, 0.5, WHITE)
				stars[i] = { part = p, ph = i / 4 * 6.283 }
			end
			local puff = newPart(folder, { Transparency = 1 })
			newEmitter(puff, {
				Rate = 8,
				Lifetime = NumberRange.new(0.8, 1.4),
				Speed = NumberRange.new(0.5, 1.5),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(0.5, 0.7), NSK(1, 0) }),
				Color = ColorSequence.new(Color3.fromRGB(255, 245, 250)),
				SpreadAngle = Vector2.new(60, 60),
			})
			local hl = addHighlight(folder, char, Color3.fromRGB(255, 220, 240), 0.9)
			local function update(dt, t)
				local k = 0.38 + 0.12 * sin(t * 3.2)
				local sy, sxz = 1 - k, 1 + k * 0.35
				for _, it in ipairs(items) do
					if it.handle.Parent then
						local oy
						if it.mesh then
							it.mesh.Scale = Vector3.new(it.scale.X * sxz, it.scale.Y * sy, it.scale.Z * sxz)
							oy = it.sizeY
						elseif it.size then
							it.handle.Size = Vector3.new(it.size.X * sxz, it.size.Y * sy, it.size.Z * sxz)
							oy = it.size.Y
						end
						if it.weld and oy then
							it.weld.C1 = it.c1 * CFrame.new(0, (oy - oy * sy) / 2, 0)
						end
					end
				end
				local hc = headCF(0.9)
				puff.CFrame = hc
				for _, s in ipairs(stars) do
					local a = t * 3 + s.ph
					s.part.CFrame = CFrame.new(hc.Position + Vector3.new(cos(a) * 1.3, 0.5 + sin(t * 4 + s.ph) * 0.2, sin(a) * 1.3))
				end
				hl.FillTransparency = 0.88 + 0.05 * sin(t * 3.2)
			end
			local function cleanup()
				for _, it in ipairs(items) do
					if it.handle.Parent then
						if it.mesh then
							it.mesh.Scale = it.scale
						elseif it.size then
							it.handle.Size = it.size
						end
						if it.weld then
							it.weld.C1 = it.c1
						end
					end
				end
			end
			return update, cleanup
		end

		-- ============================== NEW 14 (tab "Aura 2") ==============================
		local AX = {}

		-- thin glowing segment between two points
		function AX.seg(p, a, b, th)
			local d = b - a
			if d.Magnitude < 0.05 then
				b = a + Vector3.new(0, 0.05, 0)
				d = b - a
			end
			p.Size = Vector3.new(th, th, d.Magnitude)
			p.CFrame = CFrame.lookAt(a + d / 2, b)
		end

		function AX.fireCol(f)
			f = math.clamp(f, 0, 1)
			return Color3.fromRGB(255, math.floor(235 - 185 * f), math.floor(90 - 90 * f))
		end

		-- petals / leaves swirling around you (flat glowing ellipsoids, tumbling, fading in & out)
		function AX.petals(folder, char, o)
			local random = math.random
			local petals = {}
			for i = 1, o.n do
				petals[i] = {
					part = newSphere(folder, o.size * (0.8 + random() * 0.5), o.colors[i % #o.colors + 1], Enum.Material.Neon, 0.2),
					ph = i / o.n,
					spd = 0.7 + random() * 0.6,
					rot = Vector3.new(random() * 6.28, random() * 6.28, random() * 6.28),
					spin = 1.5 + random() * 3,
					r0 = 1.1 + random() * 0.9,
					wob = random() * 6.28,
				}
			end
			local core = newPart(folder, { Transparency = 1 })
			newEmitter(core, {
				Color = ColorSequence.new(o.colors[1], WHITE),
				Rate = 16,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.5, 1.5),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(1, 0) }),
				Acceleration = Vector3.new(0, o.down and -1 or 1.5, 0),
			})
			newLight(core, o.colors[1], 10, 1)
			local ring = makeRing(folder, 8.5, o.colors[1], WHITE, 4)
			local ring2 = makeRing(folder, 5.5, WHITE, o.colors[2] or o.colors[1], 3)
			local hl = addHighlight(folder, char, o.colors[1], 0.93, WHITE, 0.85)
			local function update(dt, t)
				for _, q in ipairs(petals) do
					local f = (q.ph + t * 0.1 * q.spd) % 1
					local ang = q.ph * 37 + t * q.spd * 1.2
					local r = q.r0 + sin(f * pi) * 2.4 + sin(t + q.wob) * 0.3
					local y = o.down and (6.8 - f * 9.6) or (-2.8 + f * 9.6)
					q.part.CFrame = CFrame.new(C.pos + Vector3.new(cos(ang) * r, y, sin(ang) * r))
						* CFrame.Angles(q.rot.X + t * q.spin, q.rot.Y + t * q.spin * 0.7, q.rot.Z + sin(t + q.wob))
					q.part.Transparency = 0.92 - 0.8 * sin(f * pi)
				end
				core.CFrame = CFrame.new(C.pos)
				local g = groundPos(C.pos.X, C.pos.Z)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 0.6, 0)
				ring2.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 0.9, 0)
				setRingAlpha(ring, 0.15 + 0.15 * sin(t * 2))
				setRingAlpha(ring2, 0.2 + 0.15 * sin(t * 2 + 2))
				hl.FillTransparency = 0.9 + 0.04 * sin(t * 2)
			end
			return update, nil
		end

		-- 19) Lightning storm: jagged bolts that re-roll and flicker + electric sparks
		Builders.Lightning = function(folder, char, hum, hrp)
			local random = math.random
			local blue, white = Color3.fromRGB(90, 170, 255), Color3.fromRGB(235, 245, 255)
			local bolts = {}
			for b = 1, 8 do
				local segs = {}
				for s = 1, 8 do
					segs[s] = newPart(folder, { Color = (s % 2 == 0) and white or blue, Material = Enum.Material.Neon, Transparency = 1 })
				end
				bolts[b] = { segs = segs, nextT = 0 }
			end
			local ring = makeRing(folder, 9, blue, white, 5)
			local ring2 = makeRing(folder, 6, white, blue, 4)
			local core = newPart(folder, { Transparency = 1 })
			newEmitter(core, {
				Color = ColorSequence.new(blue, white),
				Rate = 40,
				Lifetime = NumberRange.new(0.3, 0.7),
				Speed = NumberRange.new(4, 9),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.5), NSK(1, 0) }),
			})
			newLight(core, blue, 16, 2)
			local hl = addHighlight(folder, char, blue, 0.9, white, 0.5)
			local function regen(b)
				local ang = random() * 6.283
				local up = -1.5 + random() * 4.5
				local s = C.pos + Vector3.new(cos(ang) * 1.2, up * 0.5, sin(ang) * 1.2)
				local da = ang + (random() - 0.5)
				local rr = 4 + random() * 3
				local e = C.pos + Vector3.new(cos(da) * rr, up + (random() - 0.4) * 3.5, sin(da) * rr)
				local prev = s
				local n = #b.segs
				for i, seg in ipairs(b.segs) do
					local f = i / n
					local pnt = s:Lerp(e, f)
					if i < n then
						pnt = pnt + Vector3.new(random() - 0.5, random() - 0.5, random() - 0.5) * 1.6
					end
					AX.seg(seg, prev, pnt, 0.16 * (1 - f * 0.55))
					prev = pnt
				end
			end
			local function update(dt, t)
				for _, b in ipairs(bolts) do
					if t >= b.nextT then
						local on = random() < 0.8
						b.nextT = t + 0.04 + random() * 0.11
						if on then
							regen(b)
						end
						for _, seg in ipairs(b.segs) do
							seg.Transparency = on and 0.05 or 1
						end
					end
				end
				core.CFrame = CFrame.new(C.pos)
				local g = groundPos(C.pos.X, C.pos.Z)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 1.5, 0)
				ring2.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 2.2, 0)
				setRingAlpha(ring, 0.1 + 0.25 * math.abs(sin(t * 23)))
				setRingAlpha(ring2, 0.1 + 0.25 * math.abs(sin(t * 17 + 1)))
				hl.FillTransparency = 0.82 + 0.15 * math.abs(sin(t * 31))
			end
			return update, nil
		end

		-- 20) Sakura petals (rising pink swirl)
		Builders.SakuraPetals = function(folder, char, hum, hrp)
			return AX.petals(folder, char, {
				n = 46,
				size = Vector3.new(0.34, 0.05, 0.22),
				down = false,
				colors = {
					Color3.fromRGB(255, 170, 210), Color3.fromRGB(255, 205, 225),
					Color3.fromRGB(255, 130, 185), Color3.fromRGB(255, 235, 242),
				},
			})
		end

		-- 21) Maple leaves (falling autumn swirl)
		Builders.MapleLeaves = function(folder, char, hum, hrp)
			return AX.petals(folder, char, {
				n = 40,
				size = Vector3.new(0.42, 0.05, 0.32),
				down = true,
				colors = {
					Color3.fromRGB(255, 120, 30), Color3.fromRGB(225, 55, 30),
					Color3.fromRGB(255, 190, 50), Color3.fromRGB(170, 75, 20),
				},
			})
		end

		-- 22) Atom gyroscope: 3 tumbling rings with orbs + pulsing core
		Builders.AtomGyro = function(folder, char, hum, hrp)
			local cyan, gold, white = Color3.fromRGB(80, 230, 255), Color3.fromRGB(255, 215, 100), Color3.fromRGB(240, 255, 255)
			local rings = {
				{ d = 8.6, c1 = cyan, c2 = white, w = Vector3.new(1.1, 0.6, 0.0), ph = 0, orbs = 2 },
				{ d = 7.0, c1 = gold, c2 = white, w = Vector3.new(-0.5, 0.9, 0.7), ph = 2, orbs = 2 },
				{ d = 5.4, c1 = white, c2 = cyan, w = Vector3.new(0.3, -0.8, 1.2), ph = 4, orbs = 1 },
			}
			for _, r in ipairs(rings) do
				r.part = makeRing(folder, r.d, r.c1, r.c2, 4)
				r.R = r.d / 2 * 0.92
				r.o = {}
				for k = 1, r.orbs do
					r.o[k] = { part = makeOrb(folder, r.c1, 0.32, 0.9, r.c2), off = (k - 1) * pi }
				end
			end
			local core = newBall(folder, 0.7, white, Enum.Material.Neon, 0.05)
			local halo = newBall(folder, 1.3, cyan, Enum.Material.Neon, 0.7)
			newEmitter(core, {
				Color = ColorSequence.new(cyan, white),
				Rate = 22,
				Lifetime = NumberRange.new(0.6, 1.1),
				Speed = NumberRange.new(1, 3),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(1, 0) }),
			})
			newLight(core, cyan, 14, 1.6)
			local function update(dt, t)
				local center = C.pos + Vector3.new(0, 0.4, 0)
				for i, r in ipairs(rings) do
					local cf = CFrame.new(center) * CFrame.Angles(t * r.w.X + r.ph, t * r.w.Y, t * r.w.Z)
					r.part.CFrame = cf
					setRingAlpha(r.part, 0.04 + 0.12 * (sin(t * 2 + i * 2) * 0.5 + 0.5))
					for _, o in ipairs(r.o) do
						local a = t * 2.4 * ((i % 2 == 0) and -1 or 1) + o.off
						o.part.CFrame = CFrame.new(cf * Vector3.new(cos(a) * r.R, 0, sin(a) * r.R))
					end
				end
				local s = 1 + 0.18 * sin(t * 4)
				core.Size = Vector3.new(0.7 * s, 0.7 * s, 0.7 * s)
				halo.Size = Vector3.new(1.3 * s, 1.3 * s, 1.3 * s)
				core.CFrame = CFrame.new(center)
				halo.CFrame = CFrame.new(center)
			end
			return update, nil
		end

		-- 23) Inferno tornado: rising fire spiral, hot core -> red tips
		Builders.InfernoTornado = function(folder, char, hum, hrp)
			local random = math.random
			local orbs, streaks = {}, {}
			for i = 1, 60 do
				orbs[i] = {
					part = newBall(folder, 0.3, AX.fireCol(0), Enum.Material.Neon, 0.1),
					ph = i / 60,
					spd = 0.8 + random() * 0.5,
					off = random() * 6.283,
				}
			end
			for i = 1, 6 do
				streaks[i] = {
					part = makeOrb(folder, Color3.fromRGB(255, 150, 30), 0.26, 0.8, Color3.fromRGB(255, 50, 0)),
					ph = i / 6,
				}
			end
			local base = newPart(folder, { Transparency = 1 })
			newEmitter(base, {
				Texture = TEX_FIRE,
				Color = ColorSequence.new(Color3.fromRGB(255, 200, 60), Color3.fromRGB(255, 40, 0)),
				Rate = 70,
				Lifetime = NumberRange.new(0.6, 1.1),
				Speed = NumberRange.new(2, 5),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(25, 25),
				Size = NumberSequence.new({ NSK(0, 2), NSK(1, 0.3) }),
				Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(1, 1) }),
				Acceleration = Vector3.new(0, 4, 0),
			})
			newLight(base, Color3.fromRGB(255, 120, 30), 18, 2)
			local ring = makeRing(folder, 9, Color3.fromRGB(255, 90, 20), Color3.fromRGB(255, 220, 90), 6)
			local ring2 = makeRing(folder, 6, Color3.fromRGB(255, 220, 90), Color3.fromRGB(255, 60, 20), 4)
			local hl = addHighlight(folder, char, Color3.fromRGB(255, 110, 30), 0.88, Color3.fromRGB(255, 200, 80), 0.6)
			local function update(dt, t)
				for _, o in ipairs(orbs) do
					local f = (o.ph + t * 0.16 * o.spd) % 1
					local r = 0.9 + f * f * 3.6
					local ang = o.off + t * (4 - f * 2) + f * 9
					local s = 0.5 * (1 - f * 0.75) + 0.08
					o.part.Size = Vector3.new(s, s, s)
					o.part.Color = AX.fireCol(f)
					o.part.Transparency = 0.05 + f * 0.75
					o.part.CFrame = CFrame.new(C.pos.X + cos(ang) * r, C.gy + f * 6.5, C.pos.Z + sin(ang) * r)
				end
				for _, s in ipairs(streaks) do
					local f = (s.ph + t * 0.22) % 1
					local r = 1.4 + f * f * 3.8
					local ang = t * 5 + s.ph * 6.283 + f * 9
					s.part.CFrame = CFrame.new(C.pos.X + cos(ang) * r, C.gy + f * 6.5, C.pos.Z + sin(ang) * r)
				end
				base.CFrame = CFrame.new(C.pos.X, C.gy + 0.2, C.pos.Z)
				local g = groundPos(C.pos.X, C.pos.Z)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 1.2, 0)
				ring2.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 1.8, 0)
				setRingAlpha(ring, 0.1 + 0.2 * (sin(t * 6) * 0.5 + 0.5))
				setRingAlpha(ring2, 0.1 + 0.2 * (sin(t * 6 + 2) * 0.5 + 0.5))
				hl.FillTransparency = 0.86 + 0.06 * sin(t * 9)
			end
			return update, nil
		end

		-- 24) Frost crystals: glass shards orbiting in 2 tiers + snowfall + frost sigil
		Builders.FrostCrystals = function(folder, char, hum, hrp)
			local random = math.random
			local ice, white = Color3.fromRGB(170, 230, 255), Color3.fromRGB(240, 252, 255)
			local crystals = {}
			for i = 1, 10 do
				local tier = (i % 2 == 0) and 1 or 2
				crystals[i] = {
					a = newPart(folder, { Size = Vector3.new(0.45, 1.7, 0.45), Color = ice, Material = Enum.Material.Glass, Transparency = 0.2 }),
					b = newPart(folder, { Size = Vector3.new(0.45, 1.7, 0.45), Color = ice, Material = Enum.Material.Glass, Transparency = 0.2 }),
					core = newBall(folder, 0.28, white, Enum.Material.Neon, 0.1),
					ang = i / 10 * 6.283,
					r = 3.2 + tier * 0.4,
					y = (tier == 1) and 0.2 or 2.4,
					spd = (tier == 1) and 0.7 or -0.5,
					ph = random() * 6.28,
				}
			end
			local orbs = {}
			for i = 1, 4 do
				orbs[i] = { part = makeOrb(folder, ice, 0.2, 0.9, white), ph = i / 4 * 6.283 }
			end
			local snow = newPart(folder, { Size = Vector3.new(12, 0.2, 12), Transparency = 1 })
			newEmitter(snow, {
				Color = ColorSequence.new(white),
				Rate = 30,
				Lifetime = NumberRange.new(2, 2.6),
				Speed = NumberRange.new(3, 5),
				EmissionDirection = Enum.NormalId.Bottom,
				SpreadAngle = Vector2.new(15, 15),
				Size = NumberSequence.new({ NSK(0, 0.3), NSK(1, 0.1) }),
			})
			newLight(snow, ice, 14, 1.2)
			local magic = makeMagic(folder, 10, ice, white, false, 6)
			local ring = makeRing(folder, 7, white, ice, 4)
			local hl = addHighlight(folder, char, ice, 0.9, white, 0.5)
			local function update(dt, t)
				for _, c in ipairs(crystals) do
					local ang = c.ang + t * c.spd
					local y = c.y + sin(t * 1.6 + c.ph) * 0.35
					local pos = C.pos + Vector3.new(cos(ang) * c.r, y, sin(ang) * c.r)
					local cf = CFrame.new(pos) * CFrame.Angles(0, -ang + t * 0.8, rad(sin(t + c.ph) * 15))
					c.a.CFrame = cf
					c.b.CFrame = cf * CFrame.Angles(0, rad(45), 0)
					c.core.CFrame = cf
				end
				for _, o in ipairs(orbs) do
					local a = t * 1.8 + o.ph
					o.part.CFrame = CFrame.new(C.pos + Vector3.new(cos(a) * 2.2, 1 + sin(a * 2) * 1.6, sin(a) * 2.2))
				end
				snow.CFrame = CFrame.new(C.pos + Vector3.new(0, 8, 0))
				local g = groundPos(C.pos.X, C.pos.Z)
				magic.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 0.25, 0)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 0.7, 0)
				setRingAlpha(magic, 0.1 + 0.1 * sin(t * 2))
				setRingAlpha(ring, 0.15 + 0.15 * sin(t * 2 + 1))
				hl.FillTransparency = 0.9 + 0.04 * sin(t * 2)
			end
			return update, nil
		end

		-- 25) Void singularity: miniature black hole above you, accretion disk + infalling matter
		Builders.VoidSingularity = function(folder, char, hum, hrp)
			local random = math.random
			local purple, orange, white = Color3.fromRGB(150, 60, 255), Color3.fromRGB(255, 140, 40), Color3.fromRGB(255, 240, 255)
			local core = newBall(folder, 1.7, Color3.new(0, 0, 0), Enum.Material.SmoothPlastic, 0)
			local halo = newBall(folder, 2.2, purple, Enum.Material.Neon, 0.78)
			local disks = {
				{ part = makeRing(folder, 6.2, orange, purple, 6), spd = 1.6 },
				{ part = makeRing(folder, 4.8, purple, white, 5), spd = -2.2 },
				{ part = makeRing(folder, 3.6, white, orange, 4), spd = 3.0 },
			}
			local orbs = {}
			for i = 1, 36 do
				orbs[i] = {
					part = newBall(folder, 0.3, purple, Enum.Material.Neon, 0.05),
					ph = i / 36,
					spd = 0.8 + random() * 0.5,
					off = random() * 6.283,
					y = random() - 0.5,
				}
			end
			local beam = newPart(folder, { Material = Enum.Material.Neon, Color = purple, Transparency = 0.5 })
			local lightPart = newPart(folder, { Transparency = 1 })
			newLight(lightPart, purple, 16, 2)
			newEmitter(lightPart, {
				Color = ColorSequence.new(purple, orange),
				Rate = 20,
				Lifetime = NumberRange.new(0.8, 1.4),
				Speed = NumberRange.new(0.5, 2),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.45), NSK(1, 0) }),
			})
			local ground = makeRing(folder, 8, purple, orange, 5)
			local function update(dt, t)
				local center = C.pos + Vector3.new(0, 4.6 + sin(t) * 0.25, 0)
				local diskCF = CFrame.new(center) * CFrame.Angles(rad(20), t * 0.3, rad(10))
				core.CFrame = CFrame.new(center)
				local s = 2.2 + 0.15 * sin(t * 3)
				halo.Size = Vector3.new(s, s, s)
				halo.CFrame = CFrame.new(center)
				lightPart.CFrame = CFrame.new(center)
				for i, d in ipairs(disks) do
					d.part.CFrame = diskCF * CFrame.Angles(0, t * d.spd, 0)
					setRingAlpha(d.part, 0.05 + 0.15 * (sin(t * 3 + i * 2) * 0.5 + 0.5))
				end
				for _, o in ipairs(orbs) do
					local f = (o.ph + t * 0.3 * o.spd) % 1
					local r = 4.8 * (1 - f) + 1.1
					local ang = o.off + t * (1.5 + f * f * 7)
					o.part.CFrame = CFrame.new(diskCF * Vector3.new(cos(ang) * r, o.y * r * 0.15, sin(ang) * r))
					local sz = 0.34 * (1 - f * 0.6)
					o.part.Size = Vector3.new(sz, sz, sz)
					o.part.Color = (f < 0.5) and purple:Lerp(orange, f * 2) or orange:Lerp(white, (f - 0.5) * 2)
				end
				AX.seg(beam, center - Vector3.new(0, 1, 0), C.pos + Vector3.new(0, 2.6, 0), 0.08 + 0.05 * sin(t * 8))
				ground.CFrame = CFrame.new(groundPos(C.pos.X, C.pos.Z)) * CFrame.Angles(0, -t * 1.2, 0)
				setRingAlpha(ground, 0.15 + 0.15 * sin(t * 2))
			end
			return update, nil
		end

		-- 26) Rainbow ribbons: 8 hue-shifting comets weaving a helix around you
		Builders.RainbowRibbons = function(folder, char, hum, hrp)
			local ribbons = {}
			for i = 1, 8 do
				local p, tr = makeOrb(folder, hueColor(i / 8), 0.28, 1.1, WHITE)
				ribbons[i] = { part = p, tr = tr, ph = i / 8 * 6.283 }
			end
			local rb = ColorSequence.new({
				CSK(0, Color3.fromRGB(255, 80, 80)), CSK(0.2, Color3.fromRGB(255, 180, 60)),
				CSK(0.4, Color3.fromRGB(255, 240, 90)), CSK(0.6, Color3.fromRGB(90, 255, 140)),
				CSK(0.8, Color3.fromRGB(90, 170, 255)), CSK(1, Color3.fromRGB(190, 110, 255)),
			})
			local core = newPart(folder, { Transparency = 1 })
			newEmitter(core, {
				Color = rb,
				Rate = 28,
				Lifetime = NumberRange.new(1, 1.8),
				Speed = NumberRange.new(1, 3),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(1, 0) }),
			})
			newLight(core, WHITE, 12, 1)
			local ring = makeRing(folder, 9, Color3.fromRGB(255, 150, 220), Color3.fromRGB(120, 220, 255), 5)
			local ring2 = makeRing(folder, 6, Color3.fromRGB(120, 220, 255), Color3.fromRGB(255, 240, 150), 4)
			local hl = addHighlight(folder, char, WHITE, 0.92, WHITE, 0.8)
			local function update(dt, t)
				for _, r in ipairs(ribbons) do
					local hue = (t * 0.15 + r.ph / 6.283) % 1
					local col = hueColor(hue, 0.7, 1)
					r.part.Color = col
					r.tr.Color = ColorSequence.new(col, hueColor(hue + 0.12, 0.5, 1))
					local a = r.ph + t * 1.8
					local rad_ = 2.4 + sin(t * 0.7 + r.ph * 2) * 0.6
					local y = 0.7 + sin(t * 0.9 + r.ph) * 2.6
					r.part.CFrame = CFrame.new(C.pos + Vector3.new(cos(a) * rad_, y, sin(a) * rad_))
				end
				core.CFrame = CFrame.new(C.pos)
				local g = groundPos(C.pos.X, C.pos.Z)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 0.8, 0)
				ring2.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 1.3, 0)
				setRingAlpha(ring, 0.1 + 0.15 * sin(t * 2))
				setRingAlpha(ring2, 0.15 + 0.15 * sin(t * 2 + 1.5))
				hl.FillColor = hueColor(t * 0.2, 0.5, 1)
				hl.FillTransparency = 0.9 + 0.04 * sin(t * 3)
			end
			return update, nil
		end

		-- 27) Celestial sun: golden sun disc with rays behind your back (locked to the character) + halo over your head
		Builders.CelestialSun = function(folder, char, hum, hrp)
			local gold, white = Color3.fromRGB(255, 205, 90), Color3.fromRGB(255, 250, 225)
			local disk = makeMagic(folder, 9, gold, white, true, 8)
			local disk2 = makeRing(folder, 11, gold, white, 6, true)
			local halo = makeRing(folder, 2.6, gold, white, 4)
			local rays = {}
			for i = 1, 20 do
				rays[i] = {
					part = newPart(folder, { Size = Vector3.new(0.14, 2.6, 0.06), Color = (i % 2 == 0) and gold or white, Material = Enum.Material.Neon, Transparency = 0.15 }),
					ph = i * 0.7,
					ang = i / 20 * 6.283,
				}
			end
			local lightPart = newPart(folder, { Transparency = 1 })
			newLight(lightPart, gold, 18, 2)
			newEmitter(lightPart, {
				Color = ColorSequence.new(gold, white),
				Rate = 20,
				Lifetime = NumberRange.new(1.2, 2),
				Speed = NumberRange.new(1, 3),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(1, 0) }),
				Acceleration = Vector3.new(0, -1.5, 0),
			})
			local hl = addHighlight(folder, char, gold, 0.9, white, 0.7)
			local function update(dt, t)
				-- locked to the character (behind its back), never follows the camera
				local fwd = flatLook()
				local pos = C.pos - fwd * 2.8 + Vector3.new(0, 1.2, 0)
				local base = CFrame.lookAt(pos, pos + fwd)
				disk.CFrame = base * CFrame.Angles(0, 0, t * 0.35)
				disk2.CFrame = base * CFrame.Angles(0, 0, -t * 0.2)
				setRingAlpha(disk, 0.05 + 0.1 * (sin(t * 2) * 0.5 + 0.5))
				setRingAlpha(disk2, 0.1 + 0.15 * (sin(t * 1.5 + 1) * 0.5 + 0.5))
				for _, r in ipairs(rays) do
					local len = 2.4 + sin(t * 3 + r.ph) * 0.8
					r.part.Size = Vector3.new(0.14, len, 0.06)
					r.part.CFrame = base * CFrame.Angles(0, 0, r.ang + t * 0.15) * CFrame.new(0, 4.9 + len / 2, 0)
				end
				lightPart.CFrame = CFrame.new(pos)
				local hp = (C.head and C.head.Position or (C.pos + Vector3.new(0, 1.5, 0))) + Vector3.new(0, 1.7, 0)
				halo.CFrame = CFrame.new(hp) * CFrame.Angles(rad(8) * sin(t), t * 1.2, rad(8) * cos(t))
				setRingAlpha(halo, 0.05 + 0.1 * sin(t * 3))
				hl.FillTransparency = 0.9 + 0.04 * sin(t * 2)
			end
			return update, nil
		end

		-- 28) Neon equalizer: ring of dancing bars + expanding sound ripples
		Builders.Equalizer = function(folder, char, hum, hrp)
			local N = 28
			local bars = {}
			for i = 1, N do
				bars[i] = newPart(folder, { Size = Vector3.new(0.38, 1, 0.38), Material = Enum.Material.Neon, Color = hueColor(i / N), Transparency = 0.1 })
			end
			local ripples = {}
			for k = 1, 3 do
				ripples[k] = makeRing(folder, 6, Color3.fromRGB(255, 120, 220), Color3.fromRGB(120, 230, 255), 5)
			end
			local core = newPart(folder, { Transparency = 1 })
			newEmitter(core, {
				Color = ColorSequence.new(Color3.fromRGB(255, 120, 220), Color3.fromRGB(120, 230, 255)),
				Rate = 24,
				Lifetime = NumberRange.new(1, 1.6),
				Speed = NumberRange.new(2, 5),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(40, 40),
				Size = NumberSequence.new({ NSK(0, 0.4), NSK(1, 0) }),
			})
			newLight(core, Color3.fromRGB(255, 120, 220), 14, 1.4)
			local function update(dt, t)
				for i, b in ipairs(bars) do
					local a = i / N * 6.283 + t * 0.4
					local h = 0.5 + (sin(t * 6 + i * 0.9) * 0.5 + 0.5) * (1.2 + (sin(t * 2.3 + i * 0.35) * 0.5 + 0.5) * 2.2)
					b.Size = Vector3.new(0.38, h, 0.38)
					b.Color = hueColor(i / N + t * 0.1)
					b.CFrame = CFrame.new(C.pos.X + cos(a) * 3.4, C.gy + h / 2, C.pos.Z + sin(a) * 3.4)
				end
				for k, r in ipairs(ripples) do
					local f = (t * 0.45 + k / 3) % 1
					local d = 3 + f * 10
					r.Size = Vector3.new(d, 0.05, d)
					r.CFrame = CFrame.new(groundPos(C.pos.X, C.pos.Z))
					setRingAlpha(r, 0.1 + 0.9 * f)
				end
				core.CFrame = CFrame.new(C.pos.X, C.gy + 0.3, C.pos.Z)
			end
			return update, nil
		end

		-- 29) Spirit wisps: 7 glowing spirits on lissajous paths + cold ghost fire around your feet
		Builders.SpiritWisps = function(folder, char, hum, hrp)
			local cols = { Color3.fromRGB(90, 255, 220), Color3.fromRGB(120, 200, 255), Color3.fromRGB(190, 150, 255) }
			local wisps = {}
			for i = 1, 7 do
				local col = cols[i % 3 + 1]
				local p = makeOrb(folder, col, 0.42, 1.8, WHITE)
				newEmitter(p, {
					Color = ColorSequence.new(col, WHITE),
					Rate = 25,
					Lifetime = NumberRange.new(0.6, 1.1),
					Speed = NumberRange.new(0.4, 1.2),
					SpreadAngle = Vector2.new(180, 180),
					Size = NumberSequence.new({ NSK(0, 0.55), NSK(1, 0) }),
				})
				wisps[i] = {
					part = p,
					halo = newBall(folder, 1.1, col, Enum.Material.Neon, 0.82),
					ph = i / 7 * 6.283,
					R = 3 + (i % 3) * 0.8,
					spd = 0.5 + (i % 4) * 0.12,
				}
			end
			local flames = {}
			for i = 1, 8 do
				local p = newPart(folder, { Transparency = 1 })
				newEmitter(p, {
					Texture = TEX_FIRE,
					Color = ColorSequence.new(Color3.fromRGB(120, 255, 235), Color3.fromRGB(70, 90, 255)),
					Rate = 10,
					Lifetime = NumberRange.new(0.7, 1.1),
					Speed = NumberRange.new(1.5, 3),
					EmissionDirection = Enum.NormalId.Top,
					SpreadAngle = Vector2.new(10, 10),
					Size = NumberSequence.new({ NSK(0, 1.2), NSK(1, 0) }),
					Transparency = NumberSequence.new({ NSK(0, 0.4), NSK(1, 1) }),
				})
				flames[i] = p
			end
			local lightPart = newPart(folder, { Transparency = 1 })
			newLight(lightPart, cols[1], 16, 1.6)
			local ring = makeRing(folder, 8, cols[1], cols[3], 4)
			local hl = addHighlight(folder, char, cols[1], 0.93, WHITE, 0.8)
			local function update(dt, t)
				for _, w in ipairs(wisps) do
					local a = t * w.spd + w.ph
					local pos = C.pos + Vector3.new(cos(a) * w.R, 0.8 + sin(a * 1.7 + w.ph) * 1.6, sin(a * 1.3) * w.R * 0.85)
					w.part.CFrame = CFrame.new(pos)
					w.halo.CFrame = CFrame.new(pos)
					local s = 1.1 + 0.25 * sin(t * 4 + w.ph)
					w.halo.Size = Vector3.new(s, s, s)
				end
				for i, p in ipairs(flames) do
					local a = i / 8 * 6.283 + t * 0.2
					p.CFrame = CFrame.new(C.pos.X + cos(a) * 2.6, C.gy + 0.1, C.pos.Z + sin(a) * 2.6)
				end
				lightPart.CFrame = CFrame.new(C.pos)
				ring.CFrame = CFrame.new(groundPos(C.pos.X, C.pos.Z)) * CFrame.Angles(0, t * 0.5, 0)
				setRingAlpha(ring, 0.15 + 0.15 * sin(t * 2))
				hl.FillTransparency = 0.92 + 0.04 * sin(t * 2)
			end
			return update, nil
		end

		-- 30) Cyber scan: hologram cylinder, scanning rings sweeping your body, data cubes, hex floor
		Builders.CyberScan = function(folder, char, hum, hrp)
			local cy, mag = Color3.fromRGB(0, 255, 230), Color3.fromRGB(255, 60, 200)
			local grid = makeMagic(folder, 10, cy, mag, false, 6)
			local scan1 = makeRing(folder, 4.4, cy, WHITE, 5)
			local scan2 = makeRing(folder, 4.4, mag, WHITE, 4)
			local holo = newPart(folder, {
				Shape = Enum.PartType.Cylinder,
				Size = Vector3.new(6.5, 4.4, 4.4),
				Color = cy,
				Material = Enum.Material.Neon,
				Transparency = 0.92,
			})
			local cubes = {}
			for i = 1, 10 do
				cubes[i] = {
					part = newPart(folder, { Size = Vector3.new(0.3, 0.3, 0.3), Color = (i % 2 == 0) and cy or mag, Material = Enum.Material.Neon, Transparency = 0.05 }),
					ph = i / 10 * 6.283,
					h = 0.4 + (i % 5) * 0.9,
				}
			end
			local bits = newPart(folder, { Size = Vector3.new(4, 0.2, 4), Transparency = 1 })
			newEmitter(bits, {
				Color = ColorSequence.new(cy, mag),
				Rate = 30,
				Lifetime = NumberRange.new(1.2, 1.8),
				Speed = NumberRange.new(3, 6),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(5, 5),
				Size = NumberSequence.new({ NSK(0, 0.22), NSK(1, 0.05) }),
			})
			newLight(bits, cy, 14, 1.4)
			local hl = addHighlight(folder, char, cy, 0.88, WHITE, 0.4)
			local function update(dt, t)
				local g = groundPos(C.pos.X, C.pos.Z)
				grid.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 0.3, 0)
				setRingAlpha(grid, 0.1 + 0.1 * sin(t * 3))
				local f = (t * 0.5) % 1
				scan1.CFrame = CFrame.new(C.pos.X, C.gy + f * 6.2, C.pos.Z) * CFrame.Angles(0, t * 2, 0)
				scan2.CFrame = CFrame.new(C.pos.X, C.gy + (1 - f) * 6.2, C.pos.Z) * CFrame.Angles(0, -t * 2, 0)
				setRingAlpha(scan1, 0.05)
				setRingAlpha(scan2, 0.1)
				holo.CFrame = CFrame.new(C.pos.X, C.gy + 3.25, C.pos.Z) * CFrame.Angles(0, 0, rad(90))
				holo.Transparency = 0.9 + 0.04 * sin(t * 4)
				for _, c in ipairs(cubes) do
					local a = t * 1.3 + c.ph
					c.part.CFrame = CFrame.new(C.pos.X + cos(a) * 3, C.gy + c.h + sin(t * 2 + c.ph) * 0.3, C.pos.Z + sin(a) * 3)
						* CFrame.Angles(t * 2 + c.ph, t * 1.5, t)
				end
				bits.CFrame = CFrame.new(C.pos.X, C.gy + 0.2, C.pos.Z)
				hl.FillTransparency = 0.86 + 0.06 * sin(t * 5)
			end
			return update, nil
		end

		-- 31) Starry night: twinkling star shell, shooting stars, moon and a galaxy ring
		Builders.StarryNight = function(folder, char, hum, hrp)
			local random = math.random
			local purple, blue, white = Color3.fromRGB(160, 90, 255), Color3.fromRGB(100, 150, 255), Color3.fromRGB(255, 250, 235)
			local scol = { white, Color3.fromRGB(255, 235, 160), Color3.fromRGB(170, 210, 255) }
			local stars = {}
			for i = 1, 40 do
				local dir = Vector3.new(random() - 0.5, random() * 0.9 - 0.15, random() - 0.5)
				if dir.Magnitude < 0.05 then
					dir = Vector3.new(0, 1, 0)
				end
				stars[i] = {
					part = newBall(folder, 0.2, scol[i % 3 + 1], Enum.Material.Neon, 0.1),
					v = dir.Unit * (5 + random() * 3.5),
					ph = random() * 6.28,
					sz = 0.12 + random() * 0.16,
				}
			end
			local shooters = {}
			for i = 1, 3 do
				shooters[i] = { part = makeOrb(folder, white, 0.34, 1.5, Color3.fromRGB(150, 170, 255)), tilt = rad(25 + i * 25), ph = i / 3 * 6.283 }
			end
			local moon = newBall(folder, 1.8, Color3.fromRGB(255, 245, 200), Enum.Material.Neon, 0.05)
			local moonHalo = newBall(folder, 2.9, Color3.fromRGB(255, 240, 180), Enum.Material.Neon, 0.86)
			local dust = newPart(folder, { Transparency = 1 })
			newEmitter(dust, {
				Color = ColorSequence.new(purple, blue),
				Rate = 26,
				Lifetime = NumberRange.new(1.5, 2.5),
				Speed = NumberRange.new(0.5, 1.5),
				SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(1, 0) }),
			})
			newLight(dust, purple, 14, 1.2)
			local ring = makeRing(folder, 11, purple, blue, 7)
			local ring2 = makeRing(folder, 7.5, blue, white, 5)
			local function update(dt, t)
				local spin = CFrame.Angles(0, t * 0.08, 0)
				for _, s in ipairs(stars) do
					s.part.CFrame = CFrame.new(C.pos + spin * s.v)
					local tw = sin(t * 3 + s.ph) * 0.5 + 0.5
					local z = s.sz * (0.5 + tw)
					s.part.Size = Vector3.new(z, z, z)
					s.part.Transparency = 0.7 - 0.65 * tw
				end
				for _, s in ipairs(shooters) do
					local a = t * 1.4 + s.ph
					s.part.CFrame = CFrame.new(C.pos + CFrame.Angles(s.tilt, t * 0.3 + s.ph, 0) * Vector3.new(cos(a) * 7.5, 0, sin(a) * 7.5))
				end
				local mp = C.pos + CFrame.Angles(0, t * 0.15, 0) * Vector3.new(5.5, 5.8, 0)
				moon.CFrame = CFrame.new(mp)
				moonHalo.CFrame = CFrame.new(mp)
				local hs = 2.9 + 0.2 * sin(t * 2)
				moonHalo.Size = Vector3.new(hs, hs, hs)
				dust.CFrame = CFrame.new(C.pos)
				local g = groundPos(C.pos.X, C.pos.Z)
				ring.CFrame = CFrame.new(g) * CFrame.Angles(0, t * 0.5, 0)
				ring2.CFrame = CFrame.new(g) * CFrame.Angles(0, -t * 0.8, 0)
				setRingAlpha(ring, 0.1 + 0.15 * sin(t * 1.5))
				setRingAlpha(ring2, 0.15 + 0.15 * sin(t * 1.5 + 2))
			end
			return update, nil
		end

		-- 32) Golden ki: spiky flame blades, expanding shockwaves, rising debris, golden fire at your feet
		Builders.GoldenKi = function(folder, char, hum, hrp)
			local random = math.random
			local gold, yellow = Color3.fromRGB(255, 200, 40), Color3.fromRGB(255, 245, 150)
			local hl = addHighlight(folder, char, gold, 0.8, yellow, 0.3)
			local flame = newPart(folder, { Transparency = 1 })
			newEmitter(flame, {
				Texture = TEX_FIRE,
				Color = ColorSequence.new(yellow, Color3.fromRGB(255, 140, 20)),
				Rate = 80,
				Lifetime = NumberRange.new(0.5, 0.9),
				Speed = NumberRange.new(6, 10),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(12, 12),
				Size = NumberSequence.new({ NSK(0, 2.2), NSK(1, 0.2) }),
				Transparency = NumberSequence.new({ NSK(0, 0.3), NSK(1, 1) }),
			})
			newEmitter(flame, {
				Color = ColorSequence.new(yellow, WHITE),
				Rate = 30,
				Lifetime = NumberRange.new(0.6, 1.1),
				Speed = NumberRange.new(8, 14),
				EmissionDirection = Enum.NormalId.Top,
				SpreadAngle = Vector2.new(25, 25),
				Size = NumberSequence.new({ NSK(0, 0.35), NSK(1, 0) }),
			})
			newLight(flame, gold, 20, 2.5)
			local blades = {}
			for i = 1, 12 do
				blades[i] = {
					part = newPart(folder, { Size = Vector3.new(0.35, 0.1, 2.5), Color = (i % 2 == 0) and gold or yellow, Material = Enum.Material.Neon, Transparency = 0.1 }),
					ang = i / 12 * 6.283,
					ph = random() * 6.28,
				}
			end
			local waves = {}
			for k = 1, 2 do
				waves[k] = makeRing(folder, 6, gold, yellow, 6)
			end
			local rocks = {}
			for i = 1, 12 do
				rocks[i] = {
					part = newPart(folder, {
						Size = Vector3.new(0.3 + random() * 0.3, 0.3 + random() * 0.3, 0.3 + random() * 0.3),
						Color = Color3.fromRGB(115, 105, 95),
						Material = Enum.Material.Slate,
					}),
					ph = i / 12,
					off = random() * 6.283,
					r = 1.8 + random() * 1.8,
					rot = Vector3.new(random() * 3, random() * 3, random() * 3),
				}
			end
			local function update(dt, t)
				flame.CFrame = CFrame.new(C.pos.X, C.gy + 0.2, C.pos.Z)
				for _, b in ipairs(blades) do
					local h = 2.5 + sin(t * 9 + b.ph) * 0.9 + random() * 0.2
					local lean = rad(22 + sin(t * 5 + b.ph) * 10)
					local outward = Vector3.new(cos(b.ang), 0, sin(b.ang))
					local basePos = Vector3.new(C.pos.X, C.gy, C.pos.Z) + outward * 1.2
					local dir = (outward * math.sin(lean) + Vector3.new(0, math.cos(lean), 0)).Unit
					local center = basePos + dir * h / 2
					b.part.Size = Vector3.new(0.35, 0.1, h)
					b.part.CFrame = CFrame.lookAt(center, center + dir)
				end
				for k, w in ipairs(waves) do
					local f = (t * 0.7 + k / 2) % 1
					local d = 3 + f * 9
					w.Size = Vector3.new(d, 0.05, d)
					w.CFrame = CFrame.new(groundPos(C.pos.X, C.pos.Z))
					setRingAlpha(w, 0.05 + 0.95 * f * f)
				end
				for _, r in ipairs(rocks) do
					local f = (r.ph + t * 0.25) % 1
					local a = r.off + t * 1.2
					r.part.CFrame = CFrame.new(C.pos.X + cos(a) * r.r, C.gy + 0.3 + f * 5, C.pos.Z + sin(a) * r.r)
						* CFrame.Angles(t * r.rot.X, t * r.rot.Y, t * r.rot.Z)
					r.part.Transparency = f * f
				end
				hl.FillTransparency = 0.78 + 0.07 * sin(t * 12)
			end
			return update, nil
		end

		-- ============================== IDLE ANIMATION (player pose while standing still) ==============================
		-- Moves the character's Motor6D C0 offsets (additive on top of the default animations) only while you stand
		-- still, blends smoothly in/out, never lifts more than ~0.35 studs and restores everything when disabled.
		AX.IdleOn = true
		AX.IdleIntensity = 1
		AX.IdleOrder = {} -- aura ids in the order they were enabled (the last one decides the pose)

		AX.Idle = (function()
			local sin, rad, abs, floor, max = math.sin, math.rad, math.abs, math.floor, math.max
			local V3 = Vector3.new

			-- Q(rotX, rotY, rotZ, posX, posY, posZ): rotation in degrees (torso space), offset in studs
			-- arms/legs hang down: +X rot = forward/up, +Z rot = outward on the RIGHT side (negate for the left side)
			local function Q(rx, ry, rz, px, py, pz)
				return { r = V3(rad(rx or 0), rad(ry or 0), rad(rz or 0)), p = V3(px or 0, py or 0, pz or 0) }
			end

			local St = {}

			-- angelic float: tiny hover, arms slightly out, legs trailing
			St.Levitate = function(t)
				local b = sin(t * 1.5)
				return {
					Root = Q(0, 3 * sin(t * 0.6), 0, 0, 0.30 + 0.08 * b, 0),
					Waist = Q(-2, 0, 0),
					Neck = Q(6 + 2 * b, 4 * sin(t * 0.7), 0),
					RS = Q(-4, 0, 18 + 3 * b), LS = Q(-4, 0, -(18 + 3 * b)),
					RE = Q(10), LE = Q(10),
					RH = Q(-9, 0, 2), LH = Q(-9, 0, -2),
					RK = Q(-10), LK = Q(-10),
				}
			end

			-- power-up stance: wide legs, bent arms, small tremble, periodic surge
			St.Power = function(t, glitch)
				local pulse = max(0, sin(t * 1.2)) ^ 3
				local j = glitch and (floor(sin(t * 9) * 2) / 2) or 0
				return {
					Root = Q(0, sin(t * 31) * 0.8 + j * 3, 0, sin(t * 38) * 0.012 + j * 0.05, -0.08 + sin(t * 2.4) * 0.02, 0),
					Waist = Q(-5 + 2 * sin(t * 2.4), sin(t * 27) * 0.8, 0),
					Neck = Q(7, 0, 0),
					RS = Q(8, 0, 28 + 8 * pulse), LS = Q(8, 0, -(28 + 8 * pulse)),
					RE = Q(32), LE = Q(32),
					RH = Q(0, 0, 11), LH = Q(0, 0, -11),
					RK = Q(-14), LK = Q(-14),
				}
			end
			St.Glitch = function(t)
				return St.Power(t, true)
			end

			-- casting: right arm raised forward, left hand open, head scanning
			St.Cast = function(t)
				local b = sin(t * 1.6)
				return {
					Root = Q(0, 0, 0, 0, 0.16 + 0.05 * b, 0),
					Waist = Q(-2, -8, 0),
					Neck = Q(8, 6 * sin(t * 0.8), 0),
					RS = Q(75 + 4 * b, 0, 8), LS = Q(14, 0, -22 - 2 * b),
					RE = Q(12), LE = Q(18),
					RH = Q(0, 0, 6), LH = Q(0, 0, -6),
					RK = Q(-6), LK = Q(-6),
				}
			end

			-- calm breathing, relaxed arms
			St.Calm = function(t)
				local b = sin(t * 1.2)
				return {
					Root = Q(0, 2 * sin(t * 0.5), 0, 0, 0.12 + 0.05 * b, 0),
					Waist = Q(1.5 * b),
					Neck = Q(-4, 6 * sin(t * 0.5), 2 * sin(t * 0.5)),
					RS = Q(4, 0, 10 + 2 * b), LS = Q(4, 0, -(10 + 2 * b)),
					RE = Q(8), LE = Q(8),
					RH = Q(-3, 0, 2), LH = Q(-3, 0, -2),
				}
			end

			-- heart hands at the chest, cute head tilt
			St.Heart = function(t)
				return {
					Root = Q(0, 0, 3 * sin(t * 1.1), 0, abs(sin(t * 2)) * 0.05, 0),
					Waist = Q(-2, 0, 0),
					Neck = Q(2, 0, 7 * sin(t * 1.1)),
					RS = Q(50, 0, -14), LS = Q(50, 0, 14),
					RE = Q(88), LE = Q(88),
					RH = Q(0, 0, 3), LH = Q(0, 0, -3),
				}
			end

			-- little bunny hops (max 0.26 studs), paws up
			St.Bounce = function(t)
				local hop = max(0, sin(t * 3.2))
				return {
					Root = Q(0, 0, 0, 0, hop * 0.26, 0),
					Waist = Q(2 - 3 * hop),
					Neck = Q(-4, 0, 8 * sin(t * 1.6)),
					RS = Q(38, 0, -6 + 8 * hop), LS = Q(38, 0, 6 - 8 * hop),
					RE = Q(70), LE = Q(70),
					RH = Q(-20 * hop, 0, 3), LH = Q(-20 * hop, 0, -3),
					RK = Q(-30 * hop), LK = Q(-30 * hop),
				}
			end

			-- bobbing to the beat, arms pumping
			St.Beat = function(t)
				local s = sin(t * 4)
				return {
					Root = Q(0, 5 * sin(t * 2), 0, 0, 0.07 - abs(s) * 0.07, 0),
					Waist = Q(4 * abs(s) - 3, 4 * sin(t * 2), 0),
					Neck = Q(3 * s, 0, 5 * sin(t * 2)),
					RS = Q(20 + 22 * s, 0, 18), LS = Q(20 - 22 * s, 0, -18),
					RE = Q(50 + 15 * s), LE = Q(50 - 15 * s),
					RH = Q(0, 0, 7), LH = Q(0, 0, -7),
					RK = Q(-10 * abs(s)), LK = Q(-10 * abs(s)),
				}
			end

			-- gentle breeze sway
			St.Sway = function(t)
				local s = sin(t * 1.5)
				return {
					Root = Q(0, 4 * s, 0, 0.1 * s, 0.10 + 0.04 * sin(t * 3), 0),
					Waist = Q(0, -4 * s, 5 * s),
					Neck = Q(-2, 0, -6 * s),
					RS = Q(0, 0, 24 + 14 * s), LS = Q(0, 0, -(24 - 14 * s)),
					RE = Q(14), LE = Q(14),
					RH = Q(0, 0, 4), LH = Q(0, 0, -4),
				}
			end

			-- ready stance (swords)
			St.Stance = function(t)
				local b = sin(t * 1.4)
				return {
					Root = Q(0, 8, 0, 0, -0.06 + 0.02 * b, 0),
					Waist = Q(-3, 8, 0),
					Neck = Q(2, -8, 0),
					RS = Q(35 + 2 * b, 0, 6), LS = Q(-10, 0, -26),
					RE = Q(55), LE = Q(20),
					RH = Q(4, 0, 10), LH = Q(-6, 0, -9),
					RK = Q(-12), LK = Q(-8),
				}
			end

			local StyleOf = {
				Ghost = "Levitate", Wings = "Levitate", DarkAngel = "Levitate", Divine = "Levitate", CelestialSun = "Levitate",
				Glitch = "Glitch", Crimson = "Power", FlameWings = "Power", InfernoTornado = "Power", GoldenKi = "Power", Lightning = "Power",
				Arcane = "Cast", Clock = "Cast", VoidSingularity = "Cast", FrostCrystals = "Cast", AtomGyro = "Cast", CyberScan = "Cast",
				Vortex = "Calm", PinkBubble = "Calm", JadeDome = "Calm", SpiritWisps = "Calm", StarryNight = "Calm", ColorShift = "Calm", HatSquish = "Calm",
				HeartBloom = "Heart", PinkCore = "Heart",
				Bunny = "Bounce",
				Equalizer = "Beat",
				RainbowRibbons = "Sway", SakuraPetals = "Sway", MapleLeaves = "Sway",
				Swords = "Stance",
			}

			local JN = {
				Root = { "Root", "RootJoint" },
				Waist = { "Waist" },
				Neck = { "Neck" },
				RS = { "RightShoulder", "Right Shoulder" }, LS = { "LeftShoulder", "Left Shoulder" },
				RE = { "RightElbow" }, LE = { "LeftElbow" },
				RH = { "RightHip", "Right Hip" }, LH = { "LeftHip", "Left Hip" },
				RK = { "RightKnee" }, LK = { "LeftKnee" },
			}
			local ARM = { RS = true, LS = true, RE = true, LE = true }

			local joints, jchar, cur = nil, nil, {}

			local function restore()
				if joints then
					for _, j in pairs(joints) do
						if j.m.Parent then
							pcall(function()
								j.m.C0 = j.c0
							end)
						end
					end
				end
				joints, jchar, cur = nil, nil, {}
			end

			local function bind(char)
				joints, jchar, cur = {}, char, {}
				local byName = {}
				for _, d in ipairs(char:GetDescendants()) do
					if d:IsA("Motor6D") and not byName[d.Name] then
						byName[d.Name] = d
					end
				end
				for key, names in pairs(JN) do
					for _, n in ipairs(names) do
						local m = byName[n]
						if m then
							joints[key] = { m = m, c0 = m.C0 }
							break
						end
					end
				end
			end

			local api = {}

			function api.release()
				restore()
			end

			function api.update(dt, t, c, order, intensity, enabled)
				local char, hum, hrp = c.char, c.hum, c.hrp
				if not (char and hum and hrp) then
					return
				end
				if jchar ~= char then
					restore()
					bind(char)
				end
				local style = StyleOf[order[#order] or ""]
				local still = false
				if enabled and style and hum.Health > 0 and not hum.Sit then
					local st = hum:GetState()
					local v = hrp.AssemblyLinearVelocity
					still = hum.MoveDirection.Magnitude < 0.1
						and Vector3.new(v.X, 0, v.Z).Magnitude < 2
						and (st == Enum.HumanoidStateType.Running or st == Enum.HumanoidStateType.RunningNoPhysics or st == Enum.HumanoidStateType.Landed)
				end
				local pose = still and St[style](t) or nil
				local hasTool = char:FindFirstChildOfClass("Tool") ~= nil
				local a = math.min(1, dt * 5)
				for key, j in pairs(joints) do
					if j.m.Parent then
						local tgt = pose and pose[key]
						if tgt and hasTool and ARM[key] then
							tgt = nil
						end
						local cs = cur[key]
						if not cs then
							cs = { r = V3(), p = V3() }
							cur[key] = cs
						end
						cs.r = cs.r:Lerp(tgt and tgt.r * intensity or V3(), a)
						cs.p = cs.p:Lerp(tgt and tgt.p * intensity or V3(), a)
						if cs.r.Magnitude > 0.0005 or cs.p.Magnitude > 0.0005 then
							local c0 = j.c0
							j.m.C0 = CFrame.new(c0.Position + cs.p) * CFrame.Angles(cs.r.X, cs.r.Y, cs.r.Z) * (c0 - c0.Position)
						elseif j.m.C0 ~= j.c0 then
							j.m.C0 = j.c0
						end
					end
				end
			end

			return api
		end)()

		-- ============================== manager ==============================
		local Defs = {
			{ id = "Ghost", text = "Ghost Outline" },
			{ id = "Wings", text = "Angel Wings" },
			{ id = "Clock", text = "Golden Clock" },
			{ id = "Swords", text = "Spirit Swords" },
			{ id = "Vortex", text = "Galaxy Vortex" },
			{ id = "Glitch", text = "Glitch Blocks" },
			{ id = "Divine", text = "Divine Ring" },
			{ id = "FlameWings", text = "Flame Wings" },
			{ id = "Bunny", text = "Bunny Spirits" },
			{ id = "Crimson", text = "Crimson Flame" },
			{ id = "PinkBubble", text = "Pink Bubble" },
			{ id = "HeartBloom", text = "Heart Bloom" },
			{ id = "Arcane", text = "Arcane Purple" },
			{ id = "ColorShift", text = "Color Shift" },
			{ id = "PinkCore", text = "Pink Core" },
			{ id = "JadeDome", text = "Jade Dome" },
			{ id = "DarkAngel", text = "Dark Angel" },
			{ id = "HatSquish", text = "Hat Squish" },
			{ id = "Lightning", text = "Lightning Storm" },
			{ id = "SakuraPetals", text = "Sakura Petals" },
			{ id = "MapleLeaves", text = "Maple Leaves" },
			{ id = "AtomGyro", text = "Atom Gyroscope" },
			{ id = "InfernoTornado", text = "Inferno Tornado" },
			{ id = "FrostCrystals", text = "Frost Crystals" },
			{ id = "VoidSingularity", text = "Void Singularity" },
			{ id = "RainbowRibbons", text = "Rainbow Ribbons" },
			{ id = "CelestialSun", text = "Celestial Sun" },
			{ id = "Equalizer", text = "Neon Equalizer" },
			{ id = "SpiritWisps", text = "Spirit Wisps" },
			{ id = "CyberScan", text = "Cyber Scan" },
			{ id = "StarryNight", text = "Starry Night" },
			{ id = "GoldenKi", text = "Golden Ki" },
		}

		local Active = {}
		local Enabled = {}
		local loopConn = nil

		-- the aura is NEVER hidden in first person / zoomed in; only a piece that sits right on the lens (< 0.8 studs) is skipped
		local function collect(a)
			a.parts, a.emit, a.trails, a.guis, a.hls, a.sbs = {}, {}, {}, {}, {}, {}
			for _, d in ipairs(a.folder:GetDescendants()) do
				if d:IsA("BasePart") then
					a.parts[#a.parts + 1] = d
				elseif d:IsA("ParticleEmitter") then
					a.emit[#a.emit + 1] = d
				elseif d:IsA("Trail") then
					a.trails[#a.trails + 1] = d
				elseif d:IsA("SurfaceGui") then
					a.guis[#a.guis + 1] = d
				elseif d:IsA("Highlight") then
					a.hls[#a.hls + 1] = d
				elseif d:IsA("SelectionBox") then
					a.sbs[#a.sbs + 1] = d
				end
			end
		end

		local function fadePass(a, camPos, hideAll)
			for _, p in ipairs(a.parts) do
				local want = (hideAll or (p.Position - camPos).Magnitude < 0.8) and 1 or 0
				if p.LocalTransparencyModifier ~= want then
					p.LocalTransparencyModifier = want
				end
			end
			for _, e in ipairs(a.emit) do
				local par = e.Parent
				local want = not (hideAll or (par and (par.Position - camPos).Magnitude < 0.8))
				if e.Enabled ~= want then
					e.Enabled = want
					if not want then
						e:Clear()
					end
				end
			end
			for _, tr in ipairs(a.trails) do
				local par = tr.Parent
				local want = not (hideAll or (par and (par.Position - camPos).Magnitude < 0.8))
				if a.trailForce and a.trailForce[tr] ~= nil then
					want = want and a.trailForce[tr]
				end
				if tr.Enabled ~= want then
					tr.Enabled = want
				end
			end
			for _, h in ipairs(a.hls) do
				if h.Enabled == hideAll then
					h.Enabled = not hideAll
				end
			end
			for _, sb in ipairs(a.sbs) do
				if sb.Visible == hideAll then
					sb.Visible = not hideAll
				end
			end
			for _, sg in ipairs(a.guis) do
				local ad = sg.Adornee
				local want = not (hideAll or (ad and (ad.Position - camPos).Magnitude < 0.8))
				if sg.Enabled ~= want then
					sg.Enabled = want
				end
			end
		end

		local function refreshLoop()
			local any = next(Active) ~= nil
			if any and not loopConn then
				loopConn = RunService.RenderStepped:Connect(function(dt)
					if not updateContext() then
						return
					end
					local t = os.clock()
					for name, a in pairs(Active) do
						if a.update then
							local ok, err = pcall(a.update, dt, t)
							if not ok and not a.warned then
								a.warned = true
								warn("[Aura] " .. name .. ": " .. tostring(err))
							end
						end
						pcall(fadePass, a, C.camPos, false)
					end
					pcall(AX.Idle.update, dt, t, C, AX.IdleOrder, AX.IdleIntensity, AX.IdleOn)
				end)
			elseif not any and loopConn then
				loopConn:Disconnect()
				loopConn = nil
				AX.Idle.release()
			end
		end

		local function destroyAura(name)
			local a = Active[name]
			if not a then
				return
			end
			Active[name] = nil
			if a.cleanup then
				pcall(a.cleanup)
			end
			pcall(function()
				a.folder:Destroy()
			end)
		end

		local function buildAura(name)
			destroyAura(name)
			if not updateContext() then
				return
			end
			local folder = Instance.new("Folder")
			folder.Name = name
			folder.Parent = getRoot()
			local a = { folder = folder }
			Active[name] = a
			local ok, upd, clean, hideDist = pcall(Builders[name], folder, C.char, C.hum, C.hrp)
			if ok then
				a.update = upd
				a.cleanup = clean
				a.hideDist = hideDist
				collect(a)
			else
				warn("[Aura] build failed (" .. name .. "): " .. tostring(upd))
				destroyAura(name)
			end
		end

		local function clearAll()
			for _, d in ipairs(Defs) do
				destroyAura(d.id)
			end
			refreshLoop()
		end

		local connRemoving = LP.CharacterRemoving:Connect(function()
			clearAll()
		end)
		local connAdded = LP.CharacterAdded:Connect(function(char)
			char:WaitForChild("HumanoidRootPart", 15)
			char:WaitForChild("Humanoid", 15)
			task.wait(0.6)
			if LP.Character ~= char then
				return
			end
			for _, d in ipairs(Defs) do
				if Enabled[d.id] then
					buildAura(d.id)
				end
			end
			refreshLoop()
		end)

		pcall(function()
			lib:OnUnload(function()
				connRemoving:Disconnect()
				connAdded:Disconnect()
				clearAll()
				if folderRoot then
					pcall(function()
						folderRoot:Destroy()
					end)
				end
			end)
		end)

		-- ---------- UI: Visual > Aura ----------
		local AuraBox = tbl15.Visual:AddRightTabbox("Aura")
		local AuraTab = AuraBox:AddTab("Aura", "sparkles")
		local AuraTab2 = AuraBox:AddTab("Aura 2", "flame")

		AuraTab:AddToggle("AuraIdleAnim", {
			Text = "Idle Animation",
			Default = true,
			Tooltip = "Khi đứng yên, nhân vật làm động tác nhẹ hợp với aura đang bật (chỉ bạn thấy). Tắt đi sẽ trả về như cũ",
			Callback = function(v)
				AX.IdleOn = v and true or false
			end,
		})
		AuraTab:AddSlider("AuraIdleIntensity", {
			Text = "Idle Intensity",
			Default = 1,
			Min = 0.3,
			Max = 1.5,
			Rounding = 2,
			Compact = true,
			Callback = function(v)
				AX.IdleIntensity = v
			end,
		})

		for idx, d in ipairs(Defs) do
			(idx <= 18 and AuraTab or AuraTab2):AddToggle("Aura_" .. d.id, {
				Text = d.text,
				Default = false,
				Callback = function(state)
					Enabled[d.id] = state and true or nil
					for i = #AX.IdleOrder, 1, -1 do
						if AX.IdleOrder[i] == d.id then
							table.remove(AX.IdleOrder, i)
						end
					end
					if state then
						table.insert(AX.IdleOrder, d.id)
						buildAura(d.id)
					else
						destroyAura(d.id)
					end
					refreshLoop()
				end,
			})
		end
	end

	do
		local R63Group = tbl15.Visual:AddRightGroupbox("Funny", "sparkles")
		local r63Applied = false
		local r63Loading = false

		R63Group:AddButton({
			Text = "Apply R63",
			Tooltip = "Runs the R63 script (only once)",
			Func = function()
				if r63Applied or r63Loading then
					lib:Notify({
						Title = "R63",
						Description = r63Loading
							and "R63 is still loading. Please wait and do not click multiple times."
							or "R63 has already been applied. You cannot activate it again.",
						Time = 4,
					})
					return
				end

				r63Loading = true

				local ok, err = pcall(function()
					local source = game:HttpGet("https://raw.githubusercontent.com/nkhang00012-svg/script/refs/heads/main/r63.lua")
					-- Remove UTF-8 BOM (U+FEFF) and stray leading whitespace that break loadstring
					source = source:gsub("^\239\187\191", ""):gsub("^%s+", "")
					-- Remove stray trailing lines starting with a non-ASCII char (e.g. "✕Merlin") that cause syntax errors
					repeat
						local trimmed, count = source:gsub("%s*\n[\128-\255][^\n]*%s*$", "")
						source = trimmed
					until count == 0
					local chunk, message = loadstring(source, "@R63")
					assert(chunk, message)
					chunk()
				end)

				r63Loading = false

				if ok then
					r63Applied = true
					lib:Notify({
						Title = "R63",
						Description = "R63 applied successfully.",
						Time = 4,
					})
				else
					lib:Notify({
						Title = "R63",
						Description = "Failed to apply R63: " .. tostring(err),
						Time = 6,
					})
				end
			end,
		})

		local stopTimeDuration = 20
		local stopTimeLoading = false

		R63Group:AddButton({
			Text = "Stop Time",
			Tooltip = "Runs the Stop Time script using the duration set below",
			Func = function()
				if stopTimeLoading then
					lib:Notify({
						Title = "Stop Time",
						Description = "Stop Time is still loading. Please wait.",
						Time = 4,
					})
					return
				end

				stopTimeLoading = true

				local ok, err = pcall(function()
					local source = game:HttpGet("https://raw.githubusercontent.com/nkhang00012-svg/script/refs/heads/main/deepseek_lua_20261113_7faad9.lua")
					source = source:gsub("^\239\187\191", "")
					-- Override: local DURATION = 20
					local replaced = 0
					source, replaced = source:gsub("local%s+DURATION%s*=%s*[%d%.]+", function()
						return "local DURATION = " .. tostring(stopTimeDuration)
					end, 1)
					local chunk, message = loadstring(source, "@StopTime")
					assert(chunk, message)
					chunk()
				end)

				stopTimeLoading = false

				if ok then
					lib:Notify({
						Title = "Stop Time",
						Description = "Stop Time started (" .. tostring(stopTimeDuration) .. "s).",
						Time = 4,
					})
				else
					lib:Notify({
						Title = "Stop Time",
						Description = "Failed to run Stop Time: " .. tostring(err),
						Time = 6,
					})
				end
			end,
		})

		R63Group:AddSlider("StopTimeDuration", {
			Text = "Stop Time Duration",
			Default = 20,
			Min = 5,
			Max = 120,
			Rounding = 0,
			Suffix = "s",
			Compact = true,
			Callback = function(value)
				stopTimeDuration = value
			end,
		})

		-- ======================= SAND PARADISE (palm trees + sandcastle + rocks + grass + yacht, client-side only) =======================
		xpcall(function()
			local Players = game:GetService("Players")
			local RunService = game:GetService("RunService")
			local Workspace = game:GetService("Workspace")

			local SP = {
				Enabled = false,
				Generation = 0,
				Folder = nil,
				Conns = {},
				Trees = {},
				Boats = {},
				Growing = {},
				Seen = setmetatable({}, { __mode = "k" }),
				Sites = {},
				PropSites = {},
				Reserved = {},
				GrowIdx = 0,
				CastleBuilt = false,
				CastleModel = nil,
				CastlePos = nil,
				YachtBuilt = false,
				RockN = 0,
				GrassN = 0,
				BusyGen = nil,
				Dirty = false,
				SwayAcc = 0,
				Seed = os.time() % 100000,
				AreaDone = 0,
				CastleSea = nil,
				Counter = 0,
				Sway = true,
				Detail = true,
				Castle = true,
				FaceSea = true,
				ExtraBeach = true,
				Solid = false,
				Rocks = true,
				Grass = true,
				Inland = true,
				Yacht = true,
				MaxTrees = 30,
				Density = 6,
				MinH = 14,
				MaxH = 30,
				CastleMult = 100,
				RockCount = 30,
				GrassCount = 50,
				InlandRange = 90,
				YachtMult = 100,
			}

			local UP = Vector3.new(0, 1, 0)
			local SAND = Enum.Material.Sand

			local function notify(title, desc)
				pcall(function()
					lib:Notify({ Title = title, Description = desc, Time = 5 })
				end)
			end

			-- ---------- generic helpers ----------
			local function mk(parent, props)
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.TopSurface = Enum.SurfaceType.Smooth
				p.BottomSurface = Enum.SurfaceType.Smooth
				p.Material = Enum.Material.SmoothPlastic
				for k, v in pairs(props) do
					p[k] = v
				end
				p.Parent = parent
				return p
			end

			-- cylinder whose axis runs from world point a to world point b
			local function cyl(parent, a, b, diameter, color, material, name)
				local d = b - a
				local len = d.Magnitude
				if len < 0.01 then
					return nil
				end
				local up = UP
				if math.abs(d.Unit.Y) > 0.995 then
					up = Vector3.new(1, 0, 0)
				end
				return mk(parent, {
					Shape = Enum.PartType.Cylinder,
					Size = Vector3.new(len + 0.06, diameter, diameter),
					CFrame = CFrame.lookAt((a + b) / 2, b, up) * CFrame.Angles(0, math.pi / 2, 0),
					Color = color,
					Material = material or Enum.Material.Wood,
					Name = name or "Part",
				})
			end

			-- flat vertical-axis disc (dune / patch)
			local function disc(parent, center, diameter, thick, color, material, name)
				return mk(parent, {
					Shape = Enum.PartType.Cylinder,
					Size = Vector3.new(thick, diameter, diameter),
					CFrame = CFrame.new(center) * CFrame.Angles(0, 0, math.pi / 2),
					Color = color,
					Material = material or SAND,
					Name = name or "Part",
				})
			end

			local function rootPos()
				local ch = Players.LocalPlayer and Players.LocalPlayer.Character
				local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
				return hrp and hrp.Position or nil
			end

			local function insidePart(part, world, margin)
				local l = part.CFrame:PointToObjectSpace(world)
				return math.abs(l.X) <= part.Size.X / 2 - margin and math.abs(l.Z) <= part.Size.Z / 2 - margin
			end

			local function shuffle(t, rng)
				for i = #t, 2, -1 do
					local j = rng:NextInteger(1, i)
					t[i], t[j] = t[j], t[i]
				end
			end

			local function isCharacterPart(inst)
				local mdl = inst:FindFirstAncestorOfClass("Model")
				return mdl ~= nil and mdl:FindFirstChildOfClass("Humanoid") ~= nil
			end

			local function makeRayParams()
				local p = RaycastParams.new()
				p.FilterType = Enum.RaycastFilterType.Exclude
				local ex = {}
				if SP.Folder then
					ex[#ex + 1] = SP.Folder
				end
				local ch = Players.LocalPlayer and Players.LocalPlayer.Character
				if ch then
					ex[#ex + 1] = ch
				end
				p.FilterDescendantsInstances = ex
				p.IgnoreWater = false
				return p
			end

			local function isWaterHit(hit)
				if not hit then
					return false
				end
				if hit.Material == Enum.Material.Water then
					return true
				end
				local inst = hit.Instance
				if inst and inst:IsA("BasePart") and not inst:IsA("Terrain") then
					if inst.Material == Enum.Material.Water then
						return true
					end
					local n = string.lower(inst.Name)
					if n == "water" or n == "sea" or n == "ocean" then
						return true
					end
				end
				return false
			end

			-- ---------- detection: Name = "Sand", Material = Sand, Color ~ Wheat (240,230,198) ----------
			local function isSandPart(inst)
				if not inst:IsA("BasePart") or inst.Name ~= "Sand" then
					return false
				end
				if inst.Material ~= SAND then
					return false
				end
				local c = inst.Color
				if math.abs(c.R * 255 - 240) > 14 or math.abs(c.G * 255 - 230) > 14 or math.abs(c.B * 255 - 198) > 14 then
					return false
				end
				if SP.Folder and inst:IsDescendantOf(SP.Folder) then
					return false
				end
				return true
			end

			local function scan(gen)
				local found = {}
				local all = Workspace:GetDescendants()
				for i = 1, #all do
					if gen ~= SP.Generation then
						return nil
					end
					local d = all[i]
					if d.Name == "Sand" and isSandPart(d) then
						found[#found + 1] = d
					end
					if i % 4000 == 0 then
						task.wait()
					end
				end
				return found
			end

			-- ---------- sea finder: returns horizontal unit direction towards the sea ----------
			local function findSea(origin, params)
				local sum = Vector3.zero
				local N = 24
				local count = 0
				for i = 0, N - 1 do
					local a = i / N * math.pi * 2
					local dir = Vector3.new(math.cos(a), 0, math.sin(a))
					for d = 14, 170, 8 do
						local pt = origin + dir * d
						local hit = Workspace:Raycast(Vector3.new(pt.X, origin.Y + 60, pt.Z), Vector3.new(0, -220, 0), params)
						if isWaterHit(hit) then
							sum = sum + dir * (1 / d)
							count = count + 1
							break
						end
					end
					if i % 6 == 5 then
						task.wait()
					end
				end
				if count == 0 or sum.Magnitude < 1e-5 then
					return nil
				end
				return sum.Unit
			end

			-- ---------- is the volume around a spot empty (no foreign parts)? ----------
			local function areaFree(pos, radius, height, ignorePart)
				local op = OverlapParams.new()
				op.FilterType = Enum.RaycastFilterType.Exclude
				local ex = {}
				if SP.Folder then
					ex[#ex + 1] = SP.Folder
				end
				local ch = Players.LocalPlayer and Players.LocalPlayer.Character
				if ch then
					ex[#ex + 1] = ch
				end
				op.FilterDescendantsInstances = ex
				local center = CFrame.new(pos + Vector3.new(0, 1.2 + height / 2, 0))
				local parts = Workspace:GetPartBoundsInBox(center, Vector3.new(radius * 2, height, radius * 2), op)
				for _, p in ipairs(parts) do
					if p ~= ignorePart and not SP.Seen[p] and not isSandPart(p) then
						if (p.CanCollide or p.Transparency < 0.9) and not isCharacterPart(p) then
							return false
						end
					end
				end
				return true
			end

			-- ---------- growth animation driver ----------
			local function queueGrow(model, target, delay, dur)
				pcall(function()
					model:ScaleTo(0.12 * target)
				end)
				SP.Growing[#SP.Growing + 1] = {
					M = model,
					T = target,
					Start = os.clock() + delay,
					Dur = dur or 1.5,
					Started = false,
				}
			end

			local function nextDelay()
				SP.GrowIdx = SP.GrowIdx + 1
				return math.min(SP.GrowIdx * 0.07, 7)
			end

			-- ---------- PALM TREE ----------
			local function buildPalm(base, rng, height)
				local s = math.clamp(height / 20, 0.6, 1.8)
				local tree = Instance.new("Model")
				tree.Name = "PalmTree"

				-- curved trunk path
				local leanAng = rng:NextNumber(0, math.pi * 2)
				local lean = Vector3.new(math.cos(leanAng), 0, math.sin(leanAng)) * height * rng:NextNumber(0.04, 0.2)
				local segs = 9
				local pts = {}
				for i = 0, segs do
					local t = i / segs
					pts[i] = base + Vector3.new(0, height * t, 0) + lean * (t ^ 1.8)
				end

				local baseD, topD = 1.9 * s, 1.05 * s
				local colA, colB = Color3.fromRGB(139, 101, 62), Color3.fromRGB(113, 80, 49)
				for i = 1, segs do
					local d = baseD + (topD - baseD) * ((i - 0.5) / segs)
					local a = pts[i - 1]
					if i == 1 then
						a = a - Vector3.new(0, 0.6, 0)
					end
					local col = (i % 2 == 0) and colA or colB
					cyl(tree, a, pts[i], d, col, Enum.Material.Wood, "Trunk")
					if i < segs then
						mk(tree, {
							Shape = Enum.PartType.Ball,
							Size = Vector3.new(d, d, d),
							CFrame = CFrame.new(pts[i]),
							Color = col,
							Material = Enum.Material.Wood,
						})
					end
				end
				-- root flare
				disc(tree, base + Vector3.new(0, 0.5, 0), baseD * 1.55, 1.1, colB, Enum.Material.Wood, "RootFlare")

				-- sand mound (dune) under the tree
				local mound = rng:NextNumber(9, 13) * s
				disc(tree, base + Vector3.new(0, 0.2, 0), mound, 0.45, Color3.fromRGB(233, 215, 168), SAND, "Dune")
				disc(tree, base + Vector3.new(0, 0.42, 0), mound * 0.6, 0.4, Color3.fromRGB(238, 221, 176), SAND, "Dune")

				-- fallen coconuts on the ground
				for _ = 1, rng:NextInteger(0, 2) do
					local a = rng:NextNumber(0, math.pi * 2)
					local r = rng:NextNumber(2.5, 4.5) * s
					local d = 1.0 * s
					mk(tree, {
						Shape = Enum.PartType.Ball,
						Size = Vector3.new(d, d, d),
						CFrame = CFrame.new(base + Vector3.new(math.cos(a) * r, d * 0.3 + 0.35, math.sin(a) * r)),
						Color = Color3.fromRGB(94, 64, 38),
						Material = Enum.Material.Wood,
					})
				end

				-- crown
				local top = pts[segs]
				local crown = Instance.new("Model")
				crown.Name = "Crown"
				mk(crown, {
					Shape = Enum.PartType.Ball,
					Size = Vector3.new(1.9 * s, 1.9 * s, 1.9 * s),
					CFrame = CFrame.new(top),
					Color = Color3.fromRGB(92, 88, 52),
					Material = Enum.Material.Wood,
				})

				local nF = rng:NextInteger(9, 12)
				for f = 1, nF do
					local a = (f / nF) * math.pi * 2 + rng:NextNumber(-0.22, 0.22)
					local h = Vector3.new(math.cos(a), 0, math.sin(a))
					local pitch0
					if f % 3 == 0 then
						pitch0 = math.rad(rng:NextNumber(-6, 14)) -- low drooping fronds
					else
						pitch0 = math.rad(rng:NextNumber(24, 56)) -- high fronds
					end
					local len = rng:NextNumber(8.5, 12) * s
					local N = 5
					local segLen = len / N
					local droop = math.rad(rng:NextNumber(20, 27))
					local col = Color3.fromRGB(rng:NextInteger(38, 66), rng:NextInteger(122, 160), rng:NextInteger(36, 58))
					local col2 = Color3.fromRGB(
						math.min(col.R * 255 + 14, 255),
						math.min(col.G * 255 + 18, 255),
						math.min(col.B * 255 + 6, 255)
					)
					local pos = top
					for i = 1, N do
						local pitch = pitch0 - droop * (i - 1)
						local dir = h * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)
						local nxt = pos + dir * segLen
						local w = 1.5 * s * (1 - (i - 1) / N * 0.75)
						local cf = CFrame.lookAt((pos + nxt) / 2, nxt)
						mk(crown, {
							Size = Vector3.new(w, 0.12, segLen + 0.1),
							CFrame = cf,
							Color = col,
							Material = Enum.Material.Grass,
							Name = "Frond",
						})
						if SP.Detail and i >= 2 then
							local L = 2.9 * s * (1 - (i - 1) / N * 0.55)
							for side = -1, 1, 2 do
								local lcf = cf
									* CFrame.Angles(0, side * math.rad(54), 0)
									* CFrame.Angles(math.rad(-18), 0, 0)
									* CFrame.new(0, 0, -L / 2)
								mk(crown, {
									Size = Vector3.new(0.7, 0.1, L),
									CFrame = lcf,
									Color = col2,
									Material = Enum.Material.Grass,
									Name = "Leaflet",
								})
							end
						end
						pos = nxt
					end
				end

				-- coconut cluster
				for k = 1, rng:NextInteger(3, 5) do
					local a = (k / 5) * math.pi * 2 + rng:NextNumber(-0.4, 0.4)
					local d = rng:NextNumber(1.0, 1.3) * s
					mk(crown, {
						Shape = Enum.PartType.Ball,
						Size = Vector3.new(d, d, d),
						CFrame = CFrame.new(top + Vector3.new(math.cos(a) * 0.95 * s, -0.95 * s, math.sin(a) * 0.95 * s)),
						Color = Color3.fromRGB(88, 60, 36),
						Material = Enum.Material.Wood,
						Name = "Coconut",
					})
				end

				crown.WorldPivot = CFrame.new(top)
				crown.Parent = tree
				tree.WorldPivot = CFrame.new(base)
				return tree, crown, top
			end

			-- ---------- SAND CASTLE (medium, 1 resident) ----------
			local function buildCastle(baseCF, part, sc, rng)
				local m = Instance.new("Model")
				m.Name = "SandCastle"
				local sand1 = Color3.fromRGB(231, 208, 150)
				local sand2 = Color3.fromRGB(214, 188, 130)
				local sand3 = Color3.fromRGB(242, 224, 172)
				local wet = Color3.fromRGB(178, 152, 106)
				local dark = Color3.fromRGB(78, 56, 36)
				local PLASTIC = Enum.Material.SmoothPlastic

				local function wp(v)
					return baseCF:PointToWorldSpace(v)
				end
				local function blk(lcf, size, col, mat, name)
					return mk(m, {
						Size = size,
						CFrame = baseCF * lcf,
						Color = col or sand1,
						Material = mat or SAND,
						Name = name or "Part",
					})
				end
				local function vcyl(pos, h, d, col, mat, name)
					return mk(m, {
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(h, d, d),
						CFrame = baseCF * CFrame.new(pos + Vector3.new(0, h / 2, 0)) * CFrame.Angles(0, 0, math.pi / 2),
						Color = col or sand1,
						Material = mat or SAND,
						Name = name or "Part",
					})
				end
				local function zdisc(pos, d, th, col, mat)
					return mk(m, {
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(th, d, d),
						CFrame = baseCF * CFrame.new(pos) * CFrame.Angles(0, math.pi / 2, 0),
						Color = col,
						Material = mat or Enum.Material.Wood,
					})
				end
				local function ball(pos, d, col, mat, name)
					return mk(m, {
						Shape = Enum.PartType.Ball,
						Size = Vector3.new(d, d, d),
						CFrame = baseCF * CFrame.new(pos),
						Color = col,
						Material = mat or SAND,
						Name = name or "Part",
					})
				end
				local function okAt(lx, lz)
					return insidePart(part, wp(Vector3.new(lx * sc, 0, lz * sc)), 1.0)
				end

				local H, T, WH, GH = 13, 2.2, 7, 6
				local zf, zb = -(H - T / 2), (H - T / 2)

				-- ground: wet sand ring + courtyard floor
				vcyl(Vector3.new(0, 0, 0), 0.12, 36, wet, SAND, "Decor")
				vcyl(Vector3.new(0, 0, 0), 0.22, 2 * H - 2 * T + 0.6, sand3, SAND, "Decor")

				-- curtain walls (front wall has a gate 5.2 wide x 6 tall)
				blk(CFrame.new(0, WH / 2, zb), Vector3.new(2 * H, WH, T))
				blk(CFrame.new(-(H - T / 2), WH / 2, 0), Vector3.new(T, WH, 2 * H))
				blk(CFrame.new(H - T / 2, WH / 2, 0), Vector3.new(T, WH, 2 * H))
				blk(CFrame.new(-7.8, WH / 2, zf), Vector3.new(10.4, WH, T))
				blk(CFrame.new(7.8, WH / 2, zf), Vector3.new(10.4, WH, T))
				blk(CFrame.new(0, GH + (WH - GH) / 2, zf), Vector3.new(5.2, WH - GH, T))
				for _, sx in ipairs({ -1, 1 }) do
					blk(CFrame.new(sx * 3.2, 4, zf - 0.1), Vector3.new(1.2, 8, T + 0.3), sand2)
					blk(CFrame.new(sx * 3.2, 8.2, zf - 0.1), Vector3.new(1.7, 0.4, T + 0.7), sand1)
				end

				-- wall battlements
				local my = WH + 0.7
				for x = -8.6, -3.4, 3.1 do
					blk(CFrame.new(x, my, zf), Vector3.new(1.7, 1.4, T - 0.5))
					blk(CFrame.new(-x, my, zf), Vector3.new(1.7, 1.4, T - 0.5))
				end
				for x = -9.1, 9.2, 3.05 do
					blk(CFrame.new(x, my, zb), Vector3.new(1.7, 1.4, T - 0.5))
				end
				for z = -8.1, 8.2, 3.2 do
					blk(CFrame.new(-(H - T / 2), my, z), Vector3.new(T - 0.5, 1.4, 1.7))
					blk(CFrame.new(H - T / 2, my, z), Vector3.new(T - 0.5, 1.4, 1.7))
				end

				-- four corner towers
				local tc = H - 1.4
				for _, sx in ipairs({ -1, 1 }) do
					for _, sz in ipairs({ -1, 1 }) do
						local c = Vector3.new(sx * tc, 0, sz * tc)
						vcyl(c, 8, 7.2, sand1)
						vcyl(c + Vector3.new(0, 7.8, 0), 0.5, 7.9, sand2)
						vcyl(c + Vector3.new(0, 8, 0), 3.6, 6.2, sand3)
						for k = 0, 7 do
							local a = k / 8 * math.pi * 2
							local p = c + Vector3.new(math.cos(a) * 2.6, 12.3, math.sin(a) * 2.6)
							blk(CFrame.new(p) * CFrame.Angles(0, -a, 0), Vector3.new(1.0, 1.4, 1.5), sand1)
						end
						local out = Vector3.new(sx, 0, sz).Unit
						local w1 = c + out * 3.6 + Vector3.new(0, 5.5, 0)
						blk(CFrame.lookAt(w1, w1 + out), Vector3.new(0.7, 2.0, 0.3), dark, PLASTIC)
						local w2 = c + out * 3.1 + Vector3.new(0, 9.8, 0)
						blk(CFrame.lookAt(w2, w2 + out), Vector3.new(0.6, 1.6, 0.3), dark, PLASTIC)
					end
				end

				-- central keep
				local kz = 4.5
				blk(CFrame.new(0, 6.5, kz), Vector3.new(10, 13, 10))
				blk(CFrame.new(0, 13.2, kz), Vector3.new(11, 0.4, 11), sand2)
				for _, x in ipairs({ -4.4, -1.5, 1.5, 4.4 }) do
					blk(CFrame.new(x, 14.1, kz - 4.4), Vector3.new(1.5, 1.4, 1.5))
					blk(CFrame.new(x, 14.1, kz + 4.4), Vector3.new(1.5, 1.4, 1.5))
				end
				for _, sx in ipairs({ -1, 1 }) do
					for _, dz in ipairs({ -1.5, 1.5 }) do
						blk(CFrame.new(sx * 4.4, 14.1, kz + dz), Vector3.new(1.5, 1.4, 1.5))
					end
				end
				-- turret + stepped roof + flag
				vcyl(Vector3.new(0, 13.4, kz), 3.2, 5.2, sand1)
				vcyl(Vector3.new(0, 16.6, kz), 0.8, 6.2, sand2)
				vcyl(Vector3.new(0, 17.4, kz), 1.1, 4.8, sand1)
				vcyl(Vector3.new(0, 18.5, kz), 1.1, 3.4, sand3)
				vcyl(Vector3.new(0, 19.6, kz), 1.0, 1.8, sand1)
				blk(CFrame.new(0, 14.9, kz - 2.6), Vector3.new(1.0, 1.6, 0.3), dark, PLASTIC)
				vcyl(Vector3.new(0, 20.6, kz), 3.4, 0.28, Color3.fromRGB(120, 88, 56), Enum.Material.Wood, "Decor")
				blk(CFrame.new(1.25, 23.1, kz), Vector3.new(2.5, 1.5, 0.1), Color3.fromRGB(204, 58, 58), PLASTIC, "Decor")
				blk(CFrame.new(1.25, 23.1, kz), Vector3.new(2.5, 0.4, 0.14), Color3.fromRGB(245, 205, 60), PLASTIC, "Decor")

				-- keep door, frame, windows, steps
				blk(CFrame.new(0, 2.2, -0.58), Vector3.new(3.8, 4.4, 0.16), sand2)
				zdisc(Vector3.new(0, 4.4, -0.58), 3.8, 0.16, sand2, SAND)
				blk(CFrame.new(0, 2.2, -0.66), Vector3.new(3.0, 4.4, 0.16), dark, Enum.Material.Wood, "Decor")
				zdisc(Vector3.new(0, 4.4, -0.66), 3.0, 0.16, dark)
				ball(Vector3.new(1.0, 2.2, -0.8), 0.35, Color3.fromRGB(230, 190, 70), Enum.Material.Metal, "Decor")
				for _, sx in ipairs({ -1, 1 }) do
					blk(CFrame.new(sx * 2.8, 9.5, -0.55), Vector3.new(1.3, 2.2, 0.3), dark, PLASTIC)
					zdisc(Vector3.new(sx * 2.8, 10.6, -0.55), 1.3, 0.3, dark, PLASTIC)
					blk(CFrame.new(sx * 2.8, 8.3, -0.7), Vector3.new(1.9, 0.3, 0.6), sand2)
				end
				blk(CFrame.new(0, 0.25, -1.3), Vector3.new(4.6, 0.5, 1.4), sand2)
				blk(CFrame.new(0, 0.12, -2.3), Vector3.new(5.4, 0.25, 1.2), sand2)

				-- stepping-stone path from the gate
				for i = 1, 5 do
					local x = rng:NextNumber(-0.7, 0.7)
					vcyl(Vector3.new(x, 0, zf - T / 2 - 1.2 - i * 2.3), 0.16, rng:NextNumber(1.8, 2.4), wet, SAND, "Decor")
				end

				-- THE RESIDENT: a little sandman standing in the courtyard
				do
					local sm = Vector3.new(6.2, 0, -5.5)
					ball(sm + Vector3.new(0, 1.6, 0), 3.2, sand1, SAND, "Decor")
					ball(sm + Vector3.new(0, 3.95, 0), 2.4, sand1, SAND, "Decor")
					local head = ball(sm + Vector3.new(0, 5.5, 0), 1.8, sand3, SAND, "Decor")
					for _, ex in ipairs({ -0.32, 0.32 }) do
						ball(sm + Vector3.new(ex, 5.72, -0.8), 0.26, dark, PLASTIC, "Decor")
					end
					mk(m, {
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(0.9, 0.3, 0.3),
						CFrame = baseCF * CFrame.new(sm + Vector3.new(0, 5.45, -1.2)) * CFrame.Angles(0, math.pi / 2, 0),
						Color = Color3.fromRGB(235, 125, 40),
						Material = PLASTIC,
						Name = "Decor",
					})
					for k = -2, 2 do
						local z = -math.sqrt(math.max(0.81 - 0.16 - (k * 0.2) ^ 2, 0.05))
						ball(sm + Vector3.new(k * 0.2, 5.1 + 0.03 * k * k, z), 0.14, dark, PLASTIC, "Decor")
					end
					for _, by in ipairs({ 3.5, 3.95, 4.4 }) do
						ball(sm + Vector3.new(0, by, -1.17), 0.3, dark, PLASTIC, "Decor")
					end
					cyl(m, wp(sm + Vector3.new(-1.1, 4.1, 0)), wp(sm + Vector3.new(-2.8, 5.2, -0.3)), 0.2, Color3.fromRGB(110, 80, 50), Enum.Material.Wood, "Decor")
					cyl(m, wp(sm + Vector3.new(1.1, 4.1, 0)), wp(sm + Vector3.new(2.7, 5.7, -0.3)), 0.2, Color3.fromRGB(110, 80, 50), Enum.Material.Wood, "Decor")
					vcyl(sm + Vector3.new(0, 6.3, 0), 0.15, 2.5, dark, Enum.Material.Wood, "Decor")
					vcyl(sm + Vector3.new(0, 6.45, 0), 1.1, 1.5, dark, Enum.Material.Wood, "Decor")

					local bb = Instance.new("BillboardGui")
					bb.Size = UDim2.new(0, 170, 0, 34)
					bb.StudsOffset = Vector3.new(0, 4.2, 0)
					bb.AlwaysOnTop = false
					bb.MaxDistance = 90
					bb.Adornee = head
					local tl = Instance.new("TextLabel")
					tl.Size = UDim2.new(1, 0, 1, 0)
					tl.BackgroundColor3 = Color3.fromRGB(40, 30, 20)
					tl.BackgroundTransparency = 0.35
					tl.TextColor3 = Color3.fromRGB(255, 240, 200)
					tl.Font = Enum.Font.GothamBold
					tl.TextScaled = true
					tl.Text = "Sand Castle - 1 resident"
					local corner = Instance.new("UICorner")
					corner.CornerRadius = UDim.new(0, 8)
					corner.Parent = tl
					tl.Parent = bb
					bb.Parent = head
				end

				-- beach props in front of the gate (only if they fit on the sand part)
				if okAt(-7, -19) then
					local bp = Vector3.new(-7, 0, -19)
					local blue = Color3.fromRGB(60, 120, 220)
					vcyl(bp, 1.8, 1.9, blue, PLASTIC, "Decor")
					vcyl(bp + Vector3.new(0, 1.8, 0), 0.15, 2.1, Color3.fromRGB(40, 90, 180), PLASTIC, "Decor")
					vcyl(bp + Vector3.new(0, 1.65, 0), 0.12, 1.6, sand1, SAND, "Decor")
					cyl(m, wp(bp + Vector3.new(1.8, 0.25, 0.2)), wp(bp + Vector3.new(3.9, 0.55, 1.0)), 0.18, Color3.fromRGB(120, 88, 56), Enum.Material.Wood, "Decor")
					blk(CFrame.new(bp + Vector3.new(1.4, 0.16, 0.12)) * CFrame.Angles(0, math.rad(20), 0), Vector3.new(0.9, 0.12, 1.1), Color3.fromRGB(210, 60, 60), PLASTIC, "Decor")
				end
				if okAt(9, -20) then
					local tp = Vector3.new(9, 0.09, -20)
					for k = 1, 5 do
						blk(
							CFrame.new(tp) * CFrame.Angles(0, math.rad(25), 0) * CFrame.new((k - 3) * 0.8, 0, 0),
							Vector3.new(0.8, 0.12, 6),
							(k % 2 == 1) and Color3.fromRGB(215, 70, 70) or Color3.fromRGB(245, 245, 240),
							Enum.Material.Fabric,
							"Decor"
						)
					end
				end
				if okAt(14, -22) then
					local up2 = Vector3.new(14, 0, -22)
					vcyl(up2, 7.2, 0.3, Color3.fromRGB(235, 235, 230), PLASTIC, "Decor")
					vcyl(up2 + Vector3.new(0, 6.9, 0), 0.3, 8.6, Color3.fromRGB(215, 62, 62), Enum.Material.Fabric, "Decor")
					vcyl(up2 + Vector3.new(0, 7.2, 0), 0.3, 6.2, Color3.fromRGB(245, 245, 240), Enum.Material.Fabric, "Decor")
					vcyl(up2 + Vector3.new(0, 7.5, 0), 0.3, 3.6, Color3.fromRGB(215, 62, 62), Enum.Material.Fabric, "Decor")
					vcyl(up2 + Vector3.new(0, 7.8, 0), 0.3, 1.2, Color3.fromRGB(245, 245, 240), Enum.Material.Fabric, "Decor")
				end

				-- shells and starfish scattered around
				local shellCols = {
					Color3.fromRGB(250, 220, 215),
					Color3.fromRGB(245, 245, 235),
					Color3.fromRGB(240, 190, 175),
				}
				for _ = 1, 8 do
					local a = rng:NextNumber(0, math.pi * 2)
					local r = rng:NextNumber(15, 21)
					local lx, lz = math.cos(a) * r, math.sin(a) * r
					if okAt(lx, lz) then
						ball(Vector3.new(lx, 0, lz), rng:NextNumber(0.7, 1.2), shellCols[rng:NextInteger(1, 3)], PLASTIC, "Decor")
					end
				end
				for _ = 1, 3 do
					local a = rng:NextNumber(0, math.pi * 2)
					local r = rng:NextNumber(14, 20)
					local lx, lz = math.cos(a) * r, math.sin(a) * r
					if okAt(lx, lz) then
						local sc0 = Vector3.new(lx, 0.1, lz)
						local rot = rng:NextNumber(0, math.pi)
						for k = 0, 4 do
							blk(
								CFrame.new(sc0) * CFrame.Angles(0, rot + k * math.pi * 2 / 5, 0) * CFrame.new(0.65, 0, 0),
								Vector3.new(1.3, 0.2, 0.42),
								Color3.fromRGB(235, 120, 60),
								PLASTIC,
								"Decor"
							)
						end
						vcyl(sc0 - Vector3.new(0, 0.1, 0), 0.2, 0.7, Color3.fromRGB(235, 120, 60), PLASTIC, "Decor")
					end
				end

				m.WorldPivot = baseCF
				return m
			end

			local function applySolid()
				if SP.CastleModel then
					for _, d in ipairs(SP.CastleModel:GetDescendants()) do
						if d:IsA("BasePart") and d.Name ~= "Decor" then
							d.CanCollide = SP.Solid
						end
					end
				end
			end

			-- ---------- extra beach: sandy patches that extend the shoreline ----------
			local function addBeachPatches(part, rng, count)
				if not SP.Folder then
					return
				end
				local params = RaycastParams.new()
				params.FilterType = Enum.RaycastFilterType.Exclude
				params.FilterDescendantsInstances = { SP.Folder, Players.LocalPlayer and Players.LocalPlayer.Character }
				params.IgnoreWater = true
				local cf = part.CFrame
				local sx, sz, sy = part.Size.X, part.Size.Z, part.Size.Y
				for _ = 1, count do
					local side = rng:NextInteger(1, 4)
					local lx, lz, outL
					if side == 1 then
						lx, lz, outL = sx / 2, rng:NextNumber(-sz / 2, sz / 2), Vector3.new(1, 0, 0)
					elseif side == 2 then
						lx, lz, outL = -sx / 2, rng:NextNumber(-sz / 2, sz / 2), Vector3.new(-1, 0, 0)
					elseif side == 3 then
						lx, lz, outL = rng:NextNumber(-sx / 2, sx / 2), sz / 2, Vector3.new(0, 0, 1)
					else
						lx, lz, outL = rng:NextNumber(-sx / 2, sx / 2), -sz / 2, Vector3.new(0, 0, -1)
					end
					local edge = cf * Vector3.new(lx, sy / 2, lz)
					local dia = rng:NextNumber(9, 20)
					local center = edge + cf:VectorToWorldSpace(outL) * (dia * 0.3)
					local hit = Workspace:Raycast(center + Vector3.new(0, 12, 0), Vector3.new(0, -40, 0), params)
					if hit and math.abs(hit.Position.Y - edge.Y) < 5 then
						local g = hit.Position
						local pm = Instance.new("Model")
						pm.Name = "BeachPatch"
						local tone = rng:NextInteger(-8, 6)
						disc(pm, g + Vector3.new(0, 0.07, 0), dia, 0.25, Color3.fromRGB(236 + tone, 219 + tone, 172 + tone), SAND, "SandPatch")
						local off = Vector3.new(rng:NextNumber(-0.2, 0.2) * dia, 0, rng:NextNumber(-0.2, 0.2) * dia)
						disc(pm, g + off + Vector3.new(0, 0.1, 0), dia * 0.62, 0.25, Color3.fromRGB(241 + tone, 225 + tone, 180 + tone), SAND, "SandPatch")
						pm.WorldPivot = CFrame.new(g)
						queueGrow(pm, 1, nextDelay(), 1.2)
					end
				end
			end

			-- ---------- ROCK ----------
			local ROCK_MATS = { Enum.Material.Slate, Enum.Material.Rock, Enum.Material.Granite }

			local function clampC(v)
				return math.clamp(math.floor(v + 0.5), 0, 255)
			end

			local function buildRock(base, rng)
				local m = Instance.new("Model")
				m.Name = "Rock"
				local g = rng:NextInteger(92, 150)
				local tint = rng:NextInteger(-10, 10)
				local mat = ROCK_MATS[rng:NextInteger(1, #ROCK_MATS)]
				-- mostly small / medium, occasionally a big boulder
				local roll = rng:NextNumber()
				local s
				if roll < 0.5 then
					s = rng:NextNumber(0.9, 1.8)
				elseif roll < 0.88 then
					s = rng:NextNumber(1.8, 3.0)
				else
					s = rng:NextNumber(3.2, 4.8)
				end
				local n = rng:NextInteger(2, 4)
				for i = 1, n do
					local k = (i == 1) and 1 or rng:NextNumber(0.4, 0.7)
					local sx = s * rng:NextNumber(1.0, 1.6) * k
					local sy = s * rng:NextNumber(0.65, 1.05) * k
					local sz = s * rng:NextNumber(1.0, 1.6) * k
					local off = Vector3.zero
					if i > 1 then
						off = Vector3.new(rng:NextNumber(-1, 1) * s * 0.85, 0, rng:NextNumber(-1, 1) * s * 0.85)
					end
					local cf = CFrame.new(base + off + Vector3.new(0, sy * 0.3, 0))
						* CFrame.Angles(rng:NextNumber(-0.3, 0.3), rng:NextNumber(0, math.pi * 2), rng:NextNumber(-0.3, 0.3))
					local v = rng:NextInteger(-8, 8)
					mk(m, {
						Size = Vector3.new(sx, sy, sz),
						CFrame = cf,
						Color = Color3.fromRGB(clampC(g + tint + v), clampC(g + v), clampC(g - tint + v)),
						Material = mat,
						Name = "Rock",
					})
				end
				-- rounded top so the outline is less boxy
				local bd = s * rng:NextNumber(0.9, 1.25)
				mk(m, {
					Shape = Enum.PartType.Ball,
					Size = Vector3.new(bd, bd, bd),
					CFrame = CFrame.new(base + Vector3.new(rng:NextNumber(-0.2, 0.2) * s, bd * 0.18, rng:NextNumber(-0.2, 0.2) * s)),
					Color = Color3.fromRGB(clampC(g + tint + 6), clampC(g + 6), clampC(g - tint + 6)),
					Material = mat,
					Name = "Rock",
				})
				-- little pebbles around big ones
				if s > 2.2 then
					for _ = 1, rng:NextInteger(1, 3) do
						local a = rng:NextNumber(0, math.pi * 2)
						local r = s * rng:NextNumber(0.9, 1.5)
						local pd = rng:NextNumber(0.35, 0.7)
						mk(m, {
							Shape = Enum.PartType.Ball,
							Size = Vector3.new(pd, pd, pd),
							CFrame = CFrame.new(base + Vector3.new(math.cos(a) * r, pd * 0.25, math.sin(a) * r)),
							Color = Color3.fromRGB(clampC(g + tint), clampC(g), clampC(g - tint)),
							Material = mat,
							Name = "Rock",
						})
					end
				end
				m.WorldPivot = CFrame.new(base)
				return m
			end

			-- ---------- GRASS TUFT ----------
			local function buildGrass(base, rng)
				local m = Instance.new("Model")
				m.Name = "GrassTuft"
				local s = rng:NextNumber(0.8, 1.5)
				local r0, g0, b0 = rng:NextInteger(66, 110), rng:NextInteger(138, 182), rng:NextInteger(44, 76)
				local blades = rng:NextInteger(10, 16)
				for i = 1, blades do
					local a = rng:NextNumber(0, math.pi * 2)
					local h = rng:NextNumber(1.6, 3.4) * s
					local lean = rng:NextNumber(0.08, 0.6)
					local w = rng:NextNumber(0.16, 0.32) * s
					local rr = rng:NextNumber(0, 0.55) * s
					local root = base + Vector3.new(math.cos(a) * rr, -0.1, math.sin(a) * rr)
					local out = Vector3.new(math.cos(a), 0, math.sin(a))
					local tip = root + (out * math.sin(lean) + UP * math.cos(lean)) * h
					local cf = CFrame.lookAt((root + tip) / 2, tip)
						* CFrame.Angles(-math.pi / 2, 0, 0)
						* CFrame.Angles(0, rng:NextNumber(-1.2, 1.2), 0)
					local v = rng:NextInteger(-14, 18)
					mk(m, {
						Size = Vector3.new(w, h, 0.07),
						CFrame = cf,
						Color = Color3.fromRGB(clampC(r0 + v * 0.4), clampC(g0 + v), clampC(b0 + v * 0.3)),
						Material = Enum.Material.Grass,
						Name = "Blade",
					})
					if i == 1 and rng:NextNumber() < 0.18 then
						local fc = ({
							Color3.fromRGB(240, 220, 90),
							Color3.fromRGB(235, 120, 150),
							Color3.fromRGB(250, 250, 245),
						})[rng:NextInteger(1, 3)]
						mk(m, {
							Shape = Enum.PartType.Ball,
							Size = Vector3.new(0.5 * s, 0.5 * s, 0.5 * s),
							CFrame = CFrame.new(tip),
							Color = fc,
							Material = Enum.Material.SmoothPlastic,
							Name = "Flower",
						})
					end
				end
				m.WorldPivot = CFrame.new(base)
				return m
			end

			-- ---------- YACHT (bow = -Z, waterline at y = 0) ----------
			local function buildYacht(baseCF)
				local m = Instance.new("Model")
				m.Name = "Yacht"
				local PL = Enum.Material.SmoothPlastic
				local white = Color3.fromRGB(246, 247, 250)
				local navy = Color3.fromRGB(26, 50, 94)
				local teak = Color3.fromRGB(178, 130, 84)
				local glass = Color3.fromRGB(110, 185, 230)
				local steel = Color3.fromRGB(190, 196, 204)
				local red = Color3.fromRGB(210, 56, 56)

				local function blk(lcf, size, col, mat, name, transp)
					return mk(m, {
						Size = size,
						CFrame = baseCF * lcf,
						Color = col or white,
						Material = mat or PL,
						Name = name or "Part",
						Transparency = transp or 0,
					})
				end
				local function vcyl(pos, h, d, col, mat, name)
					return mk(m, {
						Shape = Enum.PartType.Cylinder,
						Size = Vector3.new(h, d, d),
						CFrame = baseCF * CFrame.new(pos + Vector3.new(0, h / 2, 0)) * CFrame.Angles(0, 0, math.pi / 2),
						Color = col or white,
						Material = mat or PL,
						Name = name or "Part",
					})
				end

				-- hull: white upper, navy waterline band
				blk(CFrame.new(0, 0.2, 3), Vector3.new(8, 3, 22), white)
				blk(CFrame.new(0, -0.75, 3), Vector3.new(8.06, 1.1, 22.06), navy)
				blk(CFrame.new(0, 0.55, 3), Vector3.new(8.04, 0.28, 22.04), navy)
				-- pointed bow (two angled plates) + fill underneath
				local tip = Vector3.new(0, 0.2, -17)
				for _, sx in ipairs({ -1, 1 }) do
					local from = Vector3.new(sx * 4, 0.2, -8)
					local mid = (from + tip) / 2
					local len = (from - tip).Magnitude
					blk(CFrame.lookAt(mid, tip), Vector3.new(0.5, 3, len), white)
					blk(CFrame.lookAt(mid - Vector3.new(0, 0.95, 0), tip - Vector3.new(0, 0.95, 0)), Vector3.new(0.55, 1.1, len), navy)
				end
				blk(CFrame.new(0, -0.75, -12.5), Vector3.new(3.4, 1.1, 8.5), navy)
				-- decks
				blk(CFrame.new(0, 1.8, 3), Vector3.new(7.4, 0.25, 22), teak, Enum.Material.WoodPlanks, "Deck")
				local steps = { { -9, 6.2 }, { -11, 4.4 }, { -13, 2.6 }, { -15, 0.9 } }
				for _, st in ipairs(steps) do
					blk(CFrame.new(0, 1.8, st[1]), Vector3.new(st[2], 0.25, 2), teak, Enum.Material.WoodPlanks, "Deck")
				end
				-- swim platform
				blk(CFrame.new(0, -0.85, 15.6), Vector3.new(6, 0.3, 3), white)
				blk(CFrame.new(0, -0.55, 14.6), Vector3.new(5.2, 0.15, 0.6), steel, Enum.Material.Metal)

				-- rails
				for _, sx in ipairs({ -1, 1 }) do
					blk(CFrame.new(sx * 3.7, 2.95, 3), Vector3.new(0.14, 0.14, 21), steel, Enum.Material.Metal, "Rail")
					for z = -5, 13, 3.6 do
						blk(CFrame.new(sx * 3.7, 2.4, z), Vector3.new(0.14, 1.1, 0.14), steel, Enum.Material.Metal, "Rail")
					end
				end
				blk(CFrame.new(0, 2.95, 14), Vector3.new(7.4, 0.14, 0.14), steel, Enum.Material.Metal, "Rail")

				-- main cabin + windows
				blk(CFrame.new(0, 3.2, 5), Vector3.new(6, 2.8, 9.2), white)
				blk(CFrame.new(0, 4.7, 5), Vector3.new(6.3, 0.25, 9.6), navy)
				for _, sx in ipairs({ -1, 1 }) do
					for _, z in ipairs({ 2, 5, 8 }) do
						blk(CFrame.new(sx * 3.04, 3.4, z), Vector3.new(0.12, 1.1, 2), glass, Enum.Material.Glass, "Window", 0.25)
					end
				end
				blk(CFrame.new(0, 3.6, 0.38), Vector3.new(5, 1.3, 0.14), glass, Enum.Material.Glass, "Window", 0.25)
				-- flybridge
				blk(CFrame.new(0, 5.9, 4), Vector3.new(5, 2.1, 5.6), white)
				blk(CFrame.new(0, 7.1, 4), Vector3.new(5.6, 0.25, 6.4), navy)
				blk(CFrame.new(0, 6.1, 1.1), Vector3.new(4.4, 1.0, 0.12), glass, Enum.Material.Glass, "Window", 0.25)
				for _, sx in ipairs({ -1, 1 }) do
					blk(CFrame.new(sx * 2.54, 6.1, 4), Vector3.new(0.12, 1.0, 3.6), glass, Enum.Material.Glass, "Window", 0.25)
				end
				-- mast, radar, flag
				vcyl(Vector3.new(0, 7.2, 4.6), 3.2, 0.26, steel, Enum.Material.Metal, "Mast")
				blk(CFrame.new(0, 10.1, 4.6), Vector3.new(2.4, 0.18, 0.4), steel, Enum.Material.Metal, "Radar")
				vcyl(Vector3.new(0, 1.9, 13.6), 3.4, 0.18, steel, Enum.Material.Metal, "Pole")
				blk(CFrame.new(0, 4.6, 14.4), Vector3.new(0.08, 0.9, 1.5), red, Enum.Material.Fabric, "Flag")

				-- sun loungers on the bow deck
				for _, sx in ipairs({ -1, 1 }) do
					blk(CFrame.new(sx * 1.6, 2.1, -3.3), Vector3.new(1.7, 0.35, 3.6), white)
					blk(CFrame.new(sx * 1.6, 2.33, -3.3), Vector3.new(1.5, 0.12, 3.3), Color3.fromRGB(110, 175, 225), Enum.Material.Fabric)
					blk(CFrame.new(sx * 1.6, 2.7, -1.6) * CFrame.Angles(math.rad(-38), 0, 0), Vector3.new(1.5, 0.12, 1.3), Color3.fromRGB(110, 175, 225), Enum.Material.Fabric)
				end

				-- foam halo on the water
				disc(m, baseCF.Position + Vector3.new(0, 0.06, 0), 26, 0.08, Color3.fromRGB(235, 245, 250), PL, "Decor").Transparency = 0.78

				m.WorldPivot = baseCF
				return m
			end

			-- find open water in front of a shore point; returns CFrame at waterline (bow facing the sea) or nil
			local function findYachtSpot(origin, seaDir, params, sc)
				local L, W = 34 * sc, 8.4 * sc
				local right = seaDir:Cross(UP).Unit
				local function waterAt(pt)
					local hit = Workspace:Raycast(Vector3.new(pt.X, origin.Y + 60, pt.Z), Vector3.new(0, -240, 0), params)
					if isWaterHit(hit) then
						return hit.Position.Y
					end
					return nil
				end
				for d = 10, 230, 6 do
					local first = waterAt(origin + seaDir * d)
					if first then
						for extra = 10, 70, 6 do
							local c = origin + seaDir * (d + extra)
							local y = waterAt(c)
							if y then
								local ok = true
								local pts = {
									c + seaDir * (L / 2 + 3),
									c - seaDir * (L / 2 + 3),
									c + right * (W / 2 + 4),
									c - right * (W / 2 + 4),
								}
								for _, pt in ipairs(pts) do
									if not waterAt(pt) then
										ok = false
										break
									end
								end
								if ok then
									local pos = Vector3.new(c.X, y, c.Z)
									return CFrame.lookAt(pos, pos + seaDir)
								end
							end
						end
						return nil
					end
					if d % 36 == 0 then
						task.wait()
					end
				end
				return nil
			end

			-- ---------- choose a free, open spot for the castle ----------
			local function pickCastleSpot(found, pp)
				local look = Vector3.new(0, 0, -1)
				local cam = Workspace.CurrentCamera
				if cam then
					local l = cam.CFrame.LookVector
					l = Vector3.new(l.X, 0, l.Z)
					if l.Magnitude > 0.01 then
						look = l.Unit
					end
				end
				local desired = pp and (pp + look * 30) or nil

				local flat = {}
				for _, p in ipairs(found) do
					if math.min(p.Size.X, p.Size.Z) >= 15 and p.CFrame.UpVector.Y > 0.97 then
						flat[#flat + 1] = p
					end
				end
				if #flat == 0 then
					return nil
				end
				table.sort(flat, function(a, b)
					if desired then
						return (a.Position - desired).Magnitude < (b.Position - desired).Magnitude
					end
					return a.Size.X * a.Size.Z > b.Size.X * b.Size.Z
				end)
				while #flat > 14 do
					table.remove(flat)
				end

				local factors = { 1, 0.82, 0.66, 0.52 }
				for _, k in ipairs(factors) do
					local cands = {}
					for _, p in ipairs(flat) do
						local md = math.min(p.Size.X, p.Size.Z)
						local sc = math.clamp(md / 36, 0.42, 1) * (SP.CastleMult / 100) * k
						if sc >= 0.3 then
							local reach = 18 * sc
							local maxX = math.max(0, p.Size.X / 2 - reach)
							local maxZ = math.max(0, p.Size.Z / 2 - reach)
							local nx = (maxX > 0) and math.clamp(math.ceil(maxX * 2 / (reach * 0.8)), 2, 6) or 1
							local nz = (maxZ > 0) and math.clamp(math.ceil(maxZ * 2 / (reach * 0.8)), 2, 6) or 1
							for i = 1, nx do
								for j = 1, nz do
									local lx = (nx == 1) and 0 or (-maxX + (i - 1) / (nx - 1) * 2 * maxX)
									local lz = (nz == 1) and 0 or (-maxZ + (j - 1) / (nz - 1) * 2 * maxZ)
									local w = p.CFrame * Vector3.new(lx, p.Size.Y / 2, lz)
									cands[#cands + 1] = {
										Part = p,
										Pos = w,
										Sc = sc,
										D = desired and (w - desired).Magnitude or 0,
									}
								end
							end
						end
					end
					table.sort(cands, function(a, b)
						return a.D < b.D
					end)
					for idx = 1, math.min(#cands, 160) do
						local c = cands[idx]
						if areaFree(c.Pos, 21 * c.Sc, 26 * c.Sc, c.Part) then
							return c
						end
						if idx % 10 == 0 then
							task.wait()
						end
					end
				end
				return nil
			end

			-- ---------- placement helpers ----------
			local function farFromSites(w, treeDist, propDist, resMargin)
				for _, s in ipairs(SP.Sites) do
					if (s - w).Magnitude < treeDist then
						return false
					end
				end
				for _, s in ipairs(SP.PropSites) do
					if (s - w).Magnitude < propDist then
						return false
					end
				end
				local flat = Vector3.new(w.X, 0, w.Z)
				for _, r in ipairs(SP.Reserved) do
					if (Vector3.new(r.Pos.X, 0, r.Pos.Z) - flat).Magnitude < r.R + resMargin then
						return false
					end
				end
				return true
			end

			local function validGround(hit)
				if not hit then
					return false
				end
				if hit.Material == Enum.Material.Water or hit.Normal.Y < 0.85 then
					return false
				end
				local inst = hit.Instance
				if inst and inst:IsA("BasePart") and not inst:IsA("Terrain") then
					if not inst.Anchored then
						return false
					end
					if not inst.CanCollide and inst.Name ~= "Sand" then
						return false
					end
					if isCharacterPart(inst) then
						return false
					end
				end
				return true
			end

			local function pickPart(list, total, rng)
				local r = rng:NextNumber() * total
				for _, c in ipairs(list) do
					r = r - c.A
					if r <= 0 then
						return c.P
					end
				end
				return list[#list].P
			end

			-- random ground point for rocks / grass: on the sand or (optionally) on the land around it
			local function pickPropPoint(list, total, rng, params, minDist)
				for _ = 1, 14 do
					local p = pickPart(list, total, rng)
					local sx, sz = p.Size.X, p.Size.Z
					local lx, lz
					local inland = SP.Inland and rng:NextNumber() < 0.5
					if inland then
						local R = SP.InlandRange
						local okp = false
						for _ = 1, 10 do
							lx = rng:NextNumber(-1, 1) * (sx / 2 + R)
							lz = rng:NextNumber(-1, 1) * (sz / 2 + R)
							if math.abs(lx) > sx / 2 + 1.5 or math.abs(lz) > sz / 2 + 1.5 then
								okp = true
								break
							end
						end
						if not okp then
							inland = false
						end
					end
					if not inland then
						lx = rng:NextNumber(-1, 1) * (sx / 2 - math.min(1.5, sx * 0.2))
						lz = rng:NextNumber(-1, 1) * (sz / 2 - math.min(1.5, sz * 0.2))
					end
					local w = p.CFrame * Vector3.new(lx, p.Size.Y / 2, lz)
					local hit = Workspace:Raycast(Vector3.new(w.X, w.Y + 40, w.Z), Vector3.new(0, -120, 0), params)
					if validGround(hit) and math.abs(hit.Position.Y - w.Y) <= 30 and farFromSites(hit.Position, 3, minDist, 1) then
						return hit.Position
					end
				end
				return nil
			end

			-- ---------- main generation ----------
			local function generate(gen)
				if SP.BusyGen == gen then
					SP.Dirty = true
					return
				end
				SP.BusyGen = gen
				local ok, err = pcall(function()
					local found = scan(gen)
					if not found or gen ~= SP.Generation then
						return
					end
					SP.Counter = SP.Counter + 1
					local rng = Random.new(SP.Seed + SP.Counter * 7919)

					local fresh = {}
					for _, p in ipairs(found) do
						if not SP.Seen[p] then
							SP.Seen[p] = true
							fresh[#fresh + 1] = p
						end
					end
					if SP.Counter == 1 and #found == 0 then
						notify("Sand Paradise", "No 'Sand' parts found yet. Waiting for the map...")
						return
					end
					if #fresh == 0 then
						return
					end

					local pp = rootPos()
					local params = makeRayParams()

					-- 1) castle: only on a spot with nothing around it (shrinks / moves if the area is crowded)
					local castlePart = nil
					local castleMsg = ""
					if SP.Castle and not SP.CastleBuilt then
						local spot = pickCastleSpot(found, pp)
						if gen ~= SP.Generation then
							return
						end
						if spot then
							local pos, sc = spot.Pos, spot.Sc
							castlePart = spot.Part
							local seaDir = findSea(pos, params)
							if gen ~= SP.Generation then
								return
							end
							SP.CastleSea = seaDir
							local face
							if SP.FaceSea and seaDir then
								face = pos + seaDir * 10
							elseif pp then
								face = Vector3.new(pp.X, pos.Y, pp.Z)
							else
								face = pos + Vector3.new(0, 0, -1)
							end
							if (face - pos).Magnitude < 1 then
								face = pos + Vector3.new(0, 0, -1)
							end
							local baseCF = CFrame.lookAt(pos, Vector3.new(face.X, pos.Y, face.Z))
							local model = buildCastle(baseCF, castlePart, sc, rng)
							SP.CastleModel = model
							SP.CastleBuilt = true
							SP.CastlePos = pos
							SP.Reserved[#SP.Reserved + 1] = { Pos = pos, R = 21 * sc }
							applySolid()
							queueGrow(model, sc, 0.2, 2.4)
							castleMsg = " + sand castle"
						else
							castleMsg = " (no free open spot for the castle)"
						end
					end

					-- share of this scan relative to everything scanned so far (keeps late-streamed parts from over-filling)
					local freshList, freshArea = {}, 0
					for _, p in ipairs(fresh) do
						local a = p.Size.X * p.Size.Z
						if a >= 25 and p.CFrame.UpVector.Y > 0.85 then
							freshList[#freshList + 1] = { P = p, A = a }
							freshArea = freshArea + a
						end
					end
					local frac = (freshArea > 0) and (freshArea / (SP.AreaDone + freshArea)) or 0
					local function budgetOf(total, already)
						local f = total * frac
						local b = math.floor(f) + ((rng:NextNumber() < f % 1) and 1 or 0)
						return math.max(0, math.min(b, total - already))
					end

					-- 2) palm trees: spread evenly over ALL sand parts (area-weighted, stratified inside each part)
					local treesMade = 0
					do
						local cand, totalArea = {}, 0
						for _, c in ipairs(freshList) do
							if c.A >= 40 then
								cand[#cand + 1] = { P = c.P, A = c.A, N = 0, Cap = math.max(1, math.ceil(c.A / 1000 * SP.Density)) }
								totalArea = totalArea + c.A
							end
						end
						local budget = budgetOf(SP.MaxTrees, #SP.Trees)
						if budget > 0 and totalArea > 0 then
							local assigned = 0
							for _, c in ipairs(cand) do
								local share = budget * c.A / totalArea
								local n = math.floor(share)
								if rng:NextNumber() < share - n then
									n = n + 1
								end
								c.N = math.min(n, c.Cap)
								assigned = assigned + c.N
							end
							-- hand leftovers to parts that still have room (weighted by area)
							local guard = 0
							while assigned < budget and guard < budget * 6 do
								guard = guard + 1
								local pool, poolArea = {}, 0
								for _, c in ipairs(cand) do
									if c.N < c.Cap then
										pool[#pool + 1] = c
										poolArea = poolArea + c.A
									end
								end
								if #pool == 0 then
									break
								end
								local r = rng:NextNumber() * poolArea
								for _, c in ipairs(pool) do
									r = r - c.A
									if r <= 0 then
										c.N = c.N + 1
										assigned = assigned + 1
										break
									end
								end
							end

							shuffle(cand, rng)
							for _, c in ipairs(cand) do
								if gen ~= SP.Generation then
									return
								end
								if #SP.Trees >= SP.MaxTrees then
									break
								end
								if c.N > 0 then
									local p = c.P
									local sx, sz = p.Size.X, p.Size.Z
									local mx, mz = math.min(3.5, sx * 0.25), math.min(3.5, sz * 0.25)
									local ux, uz = sx / 2 - mx, sz / 2 - mz
									local gx = math.max(1, math.ceil(math.sqrt(c.N * sx / sz)))
									local gz = math.max(1, math.ceil(c.N / gx))
									local cells = {}
									for i = 0, gx - 1 do
										for j = 0, gz - 1 do
											cells[#cells + 1] = { i, j }
										end
									end
									shuffle(cells, rng)
									local placed = 0
									for _, cell in ipairs(cells) do
										if placed >= c.N or #SP.Trees >= SP.MaxTrees then
											break
										end
										for _ = 1, 5 do
											local lx = -ux + (cell[1] + rng:NextNumber()) / gx * 2 * ux
											local lz = -uz + (cell[2] + rng:NextNumber()) / gz * 2 * uz
											local w = p.CFrame * Vector3.new(lx, p.Size.Y / 2, lz)
											if farFromSites(w, 9, 2.5, 4) then
												local lo, hi = math.min(SP.MinH, SP.MaxH), math.max(SP.MinH, SP.MaxH)
												local height = rng:NextNumber(lo, hi)
												if rng:NextNumber() < 0.28 then
													height = height * rng:NextNumber(0.5, 0.7)
												end
												local tree, crown, top = buildPalm(w, rng, height)
												SP.Sites[#SP.Sites + 1] = w
												local entry = {
													Model = tree,
													Crown = crown,
													Top = top,
													Phase = rng:NextNumber(0, 6.28),
													Amp = math.rad(rng:NextNumber(1.2, 2.6)),
													Done = false,
												}
												SP.Trees[#SP.Trees + 1] = entry
												queueGrow(tree, 1, nextDelay(), 1.5)
												SP.Growing[#SP.Growing].Entry = entry
												treesMade = treesMade + 1
												placed = placed + 1
												task.wait()
												break
											end
										end
									end
								end
							end
						end
					end

					-- 3) rocks + grass tufts (on the sand and, optionally, inland)
					local rocksMade, grassMade = 0, 0
					if #freshList > 0 then
						local total = freshArea
						if SP.Rocks then
							local budget = budgetOf(SP.RockCount, SP.RockN)
							for i = 1, budget do
								if gen ~= SP.Generation then
									return
								end
								local pt = pickPropPoint(freshList, total, rng, params, 3.5)
								if pt then
									local model = buildRock(pt, rng)
									SP.PropSites[#SP.PropSites + 1] = pt
									queueGrow(model, 1, nextDelay(), 1.1)
									SP.RockN = SP.RockN + 1
									rocksMade = rocksMade + 1
								end
								if i % 4 == 0 then
									task.wait()
								end
							end
						end
						if SP.Grass then
							local budget = budgetOf(SP.GrassCount, SP.GrassN)
							for i = 1, budget do
								if gen ~= SP.Generation then
									return
								end
								local pt = pickPropPoint(freshList, total, rng, params, 2.5)
								if pt then
									local model = buildGrass(pt, rng)
									SP.PropSites[#SP.PropSites + 1] = pt
									queueGrow(model, 1, nextDelay(), 1.0)
									SP.GrassN = SP.GrassN + 1
									grassMade = grassMade + 1
								end
								if i % 4 == 0 then
									task.wait()
								end
							end
						end
					end
					SP.AreaDone = SP.AreaDone + freshArea

					-- 4) extra beach patches (castle part first, then nearest parts)
					if SP.ExtraBeach then
						local list = {}
						if castlePart then
							list[#list + 1] = castlePart
						end
						for _, p in ipairs(fresh) do
							if #list >= 6 then
								break
							end
							if p ~= castlePart and p.Size.X * p.Size.Z >= 60 then
								list[#list + 1] = p
							end
						end
						for _, p in ipairs(list) do
							if gen ~= SP.Generation then
								return
							end
							addBeachPatches(p, rng, 2)
							task.wait()
						end
					end

					-- 5) yacht on the water, bow pointing out to sea
					local yachtMsg = ""
					if SP.Yacht and not SP.YachtBuilt then
						local origin = SP.CastlePos
						if not origin then
							local best, bd
							for _, p in ipairs(found) do
								local d = pp and (p.Position - pp).Magnitude or -(p.Size.X * p.Size.Z)
								if not bd or d < bd then
									best, bd = p, d
								end
							end
							origin = best and best.Position
						end
						if origin then
							local seaDir = SP.CastleSea or findSea(origin, params)
							if gen ~= SP.Generation then
								return
							end
							if seaDir then
								local sc = SP.YachtMult / 100
								local cf = findYachtSpot(origin, seaDir, params, sc)
								if gen ~= SP.Generation then
									return
								end
								if cf then
									local model = buildYacht(cf)
									local entry = { Model = model, Base = cf, Phase = rng:NextNumber(0, 6.28), Done = false }
									SP.Boats[#SP.Boats + 1] = entry
									SP.YachtBuilt = true
									queueGrow(model, sc, 0.6, 2.2)
									SP.Growing[#SP.Growing].Entry = entry
									yachtMsg = " + yacht"
								else
									yachtMsg = " (no open water for the yacht)"
								end
							else
								yachtMsg = " (no sea found for the yacht)"
							end
						end
					end

					notify(
						"Sand Paradise",
						string.format(
							"Found %d sand parts - %d palms, %d rocks, %d grass%s%s",
							#found,
							treesMade,
							rocksMade,
							grassMade,
							castleMsg,
							yachtMsg
						)
					)
				end)
				if SP.BusyGen == gen then
					SP.BusyGen = nil
				end
				if not ok then
					warn("[Sand Paradise] " .. tostring(err))
				end
			end

			-- ---------- start / stop ----------
			local function stop()
				SP.Enabled = false
				SP.Generation = SP.Generation + 1
				for _, c in ipairs(SP.Conns) do
					pcall(function()
						c:Disconnect()
					end)
				end
				SP.Conns = {}
				if SP.Folder then
					pcall(function()
						SP.Folder:Destroy()
					end)
				end
				SP.Folder = nil
				SP.Trees = {}
				SP.Boats = {}
				SP.Growing = {}
				SP.Seen = setmetatable({}, { __mode = "k" })
				SP.Sites = {}
				SP.PropSites = {}
				SP.Reserved = {}
				SP.GrowIdx = 0
				SP.AreaDone = 0
				SP.CastleBuilt = false
				SP.CastleModel = nil
				SP.CastlePos = nil
				SP.CastleSea = nil
				SP.YachtBuilt = false
				SP.RockN = 0
				SP.GrassN = 0
				SP.BusyGen = nil
				SP.Dirty = false
				SP.Counter = 0
			end

			local function start()
				stop()
				SP.Enabled = true
				local gen = SP.Generation
				local folder = Instance.new("Folder")
				folder.Name = "SandParadise"
				folder.Parent = Workspace
				SP.Folder = folder

				SP.Conns[#SP.Conns + 1] = RunService.Heartbeat:Connect(function(dt)
					local now = os.clock()
					-- growth animation
					local g = SP.Growing
					local i = 1
					while i <= #g do
						local it = g[i]
						local x = (now - it.Start) / it.Dur
						if x < 0 then
							i = i + 1
						else
							if not it.Started then
								it.Started = true
								it.M.Parent = SP.Folder
							end
							if x >= 1 then
								pcall(function()
									it.M:ScaleTo(it.T)
								end)
								if it.Entry then
									it.Entry.Done = true
								end
								table.remove(g, i)
							else
								local c1 = 1.70158
								local c3 = c1 + 1
								local e = 1 + c3 * (x - 1) ^ 3 + c1 * (x - 1) ^ 2
								local sc = math.max(it.T * (0.12 + 0.88 * e), 0.05)
								pcall(function()
									it.M:ScaleTo(sc)
								end)
								i = i + 1
							end
						end
					end

					-- wind sway (crowns only, nearby trees only) + yacht bobbing
					if SP.Sway then
						SP.SwayAcc = SP.SwayAcc + dt
						if SP.SwayAcc >= 1 / 30 then
							SP.SwayAcc = 0
							local cam = Workspace.CurrentCamera
							local cpos = cam and cam.CFrame.Position
							for _, tr in ipairs(SP.Trees) do
								if tr.Done and tr.Crown.Parent and (not cpos or (tr.Top - cpos).Magnitude < 180) then
									local t = now * 0.9 + tr.Phase
									local ax = math.sin(t) * tr.Amp
									local az = math.sin(t * 0.73 + 1.3) * tr.Amp
									tr.Crown:PivotTo(CFrame.new(tr.Top) * CFrame.Angles(ax, 0, az))
								end
							end
							for _, b in ipairs(SP.Boats) do
								if b.Done and b.Model.Parent then
									local t = now * 0.8 + b.Phase
									b.Model:PivotTo(
										b.Base
											* CFrame.new(0, math.sin(t) * 0.22, 0)
											* CFrame.Angles(math.sin(t * 0.9) * 0.012, 0, math.sin(t * 0.7 + 1.2) * 0.022)
									)
								end
							end
						end
					end
				end)

				-- new Sand parts appearing later (map streaming) trigger an incremental rescan
				SP.Conns[#SP.Conns + 1] = Workspace.DescendantAdded:Connect(function(d)
					if d.Name == "Sand" then
						SP.Dirty = true
					end
				end)
				task.spawn(function()
					while gen == SP.Generation do
						task.wait(3)
						if gen ~= SP.Generation then
							break
						end
						if SP.Dirty and SP.BusyGen == nil then
							SP.Dirty = false
							generate(gen)
						end
					end
				end)

				task.spawn(generate, gen)
			end

			pcall(function()
				lib:OnUnload(stop)
			end)

