			Callback = function(density)
				clouds.Density = density
			end,
		})

		Sky:AddSlider("CloudsCover", {
			Text = "Clouds Cover",
			Default = math.round(tbl16.CloudCover * 1000) / 1000,
			Min = 0,
			Max = 1,
			Rounding = 3,
			Callback = function(cover)
				clouds.Cover = cover
			end,
		})

		Sky:AddToggle("CloudsEnabled", {
			Text = "Enable Clouds",
			Default = clouds.Enabled,
			Callback = function(enabled)
				clouds.Enabled = enabled
			end,
		})

		tbl12.AddRainbowToggle(Sky, "RGBClouds", "RGB Clouds", "CloudColor")

		tbl12.RestoreSkySettings = function()
			Lighting.ClockTime = tbl16.ClockTime

			if tbl16.Created then
				if tbl16.Instance.Parent then
					tbl16.Instance:Destroy()
				end
			elseif tbl16.Instance.Parent then
				sky = tbl16.Instance
				sky.SunAngularSize = tbl16.SunAngularSize
				fn22()
			end

			if tbl16.CloudsCreated then
				if clouds.Parent then
					clouds:Destroy()
				end
			elseif clouds.Parent then
				clouds.Color = tbl16.CloudColor
				clouds.Density = tbl16.CloudDensity
				clouds.Cover = tbl16.CloudCover
				clouds.Enabled = tbl16.CloudsEnabled
			end
		end
	end

	do
		-- ==========================================
		-- VISUAL > TOYS: Custom Pallet
		--   * Decal: 1 tấm dán lên MẶT TO của cả pallet (trên + dưới), không dán từng part
		--   * Trail: 1 trail ở giữa + 4 trail ở 4 góc pallet (đổi được màu + độ trong suốt)
		--   * Có thêm: màu pallet, độ trong suốt pallet / decal / trail
		-- Chỉ áp dụng cho pallet của chính mình (folder <TênMình>SpawnedInToys).
		-- Mọi thay đổi chỉ ở phía client (chỉ bạn thấy), tắt toggle / unload sẽ trả về như cũ.
		-- ==========================================
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local ContentProvider = game:GetService("ContentProvider")
		local lp = Players.LocalPlayer

		local Cfg = {
			Enabled = false,
			Material = "Neon",
			Color = Color3.new(1, 1, 1),
			DecalId = "92129311226501",
			TrailId = "",
			TrailColor = Color3.new(1, 1, 1),
			TrailColor2 = Color3.fromRGB(0, 170, 255),
			TrailStyle = "1 Color",   -- "1 Color" | "2 Colors" | "End Color"
			TrailMode = "Static",     -- hiệu ứng màu trail
			PalletMode = "Static",    -- hiệu ứng màu pallet
			EffectSpeed = 1,
			TrailPerArm = 4,          -- số trail trên mỗi nhánh của chữ X
			TrailWidth = 0.35,        -- trail nhỏ
			AnimT = 0,
			CurPalletColor = Color3.new(1, 1, 1),
			PalletTransparency = 0,
			DecalTransparency = 0,
			TrailTransparency = 0.05,
		}

		local MATERIALS = {
			"Neon", "SmoothPlastic", "Plastic", "Glass", "ForceField", "Metal",
			"Foil", "Marble", "Granite", "DiamondPlate", "Ice", "Wood",
		}

		local TRAIL_LIFETIME = 1.6
		local MODES = {
			"Static", "RGB", "Rainbow Wave", "Fire", "Ocean", "Aurora",
			"Sunset", "Neon Pulse", "Strobe", "Police", "Galaxy", "Matrix",
		}
		local STYLES = { "1 Color", "2 Colors", "End Color" }

		-- trail xếp hình chữ X: 1 trail ở tâm + N trail trên mỗi nhánh (4 nhánh chéo ra 4 góc)
		-- SA / SB = hệ số theo 2 trục nằm trên mặt to của pallet (1 = sát góc)
		local function buildTrailDefs()
			local defs = { { SA = 0, SB = 0 } }
			local n = math.clamp(math.floor(Cfg.TrailPerArm), 1, 8)
			for k = 1, n do
				local f = k / n
				for _, sa in ipairs({ 1, -1 }) do
					for _, sb in ipairs({ 1, -1 }) do
						defs[#defs + 1] = { SA = sa * f, SB = sb * f }
					end
				end
			end
			return defs
		end

		local DECAL_PAD = 0.06 -- tấm decal dày hơn pallet 1 chút để không bị z-fighting

		-- ---------- hiệu ứng màu animation ----------
		local function samplePalette(stops, x)
			local n = #stops
			x = (x % 1) * n
			local i = math.floor(x)
			local f = x - i
			return stops[i % n + 1]:Lerp(stops[(i + 1) % n + 1], f)
		end

		local P_FIRE = { Color3.fromRGB(255, 245, 130), Color3.fromRGB(255, 160, 30), Color3.fromRGB(255, 60, 0), Color3.fromRGB(120, 10, 0) }
		local P_OCEAN = { Color3.fromRGB(0, 60, 200), Color3.fromRGB(0, 180, 255), Color3.fromRGB(0, 255, 220), Color3.fromRGB(0, 100, 255) }
		local P_AURORA = { Color3.fromRGB(0, 255, 120), Color3.fromRGB(0, 200, 255), Color3.fromRGB(150, 70, 255), Color3.fromRGB(0, 255, 160) }
		local P_SUNSET = { Color3.fromRGB(255, 120, 0), Color3.fromRGB(255, 50, 100), Color3.fromRGB(180, 40, 200), Color3.fromRGB(255, 180, 60) }
		local P_GALAXY = { Color3.fromRGB(35, 0, 90), Color3.fromRGB(110, 40, 255), Color3.fromRGB(255, 70, 210), Color3.fromRGB(30, 110, 255) }
		local P_MATRIX = { Color3.fromRGB(0, 70, 0), Color3.fromRGB(0, 255, 70), Color3.fromRGB(190, 255, 200), Color3.fromRGB(0, 120, 20) }
		local RED, BLUE = Color3.fromRGB(255, 20, 20), Color3.fromRGB(20, 60, 255)

		-- mode: tên hiệu ứng | t: thời gian (đã nhân tốc độ) | u: vị trí dọc trail (0 đầu -> 1 đuôi)
		-- idx: số thứ tự trail (lệch pha giữa các trail) | c1, c2: màu custom (Neon Pulse / Strobe)
		local function effectColor(mode, t, u, idx, c1, c2)
			if mode == "RGB" then
				return Color3.fromHSV((t * 0.2 + idx * 0.03) % 1, 1, 1)
			elseif mode == "Rainbow Wave" then
				return Color3.fromHSV((t * 0.25 - u * 0.35 + idx * 0.06) % 1, 1, 1)
			elseif mode == "Fire" then
				local fl = math.sin(t * 9 + idx * 1.7) * 0.5 + 0.5
				return samplePalette(P_FIRE, math.clamp(u * 0.7 + fl * 0.05, 0, 0.74))
			elseif mode == "Ocean" then
				return samplePalette(P_OCEAN, u * 0.6 - t * 0.3 + idx * 0.07)
			elseif mode == "Aurora" then
				return samplePalette(P_AURORA, u * 0.5 + t * 0.25 + idx * 0.1)
			elseif mode == "Sunset" then
				return samplePalette(P_SUNSET, u * 0.5 + t * 0.15 + idx * 0.08)
			elseif mode == "Neon Pulse" then
				return c1:Lerp(c2, 0.5 + 0.5 * math.sin(t * 3 - u * 2 + idx * 0.4))
			elseif mode == "Strobe" then
				return ((t * 3 + idx * 0.1) % 1 < 0.5) and c1 or c2
			elseif mode == "Police" then
				local flip = (math.floor(t * 3) + idx + (u > 0.5 and 1 or 0)) % 2
				return flip == 0 and RED or BLUE
			elseif mode == "Galaxy" then
				return samplePalette(P_GALAXY, t * 0.15 + u * 0.4 + idx * 0.09)
			elseif mode == "Matrix" then
				return samplePalette(P_MATRIX, u * 0.8 - t * 0.5 + idx * 0.11)
			end
			return c1
		end

		local U_STOPS = { 0, 0.2, 0.4, 0.6, 0.8, 1 }

		local function animTrailSeq(idx)
			local kps = {}
			for i, u in ipairs(U_STOPS) do
				kps[i] = ColorSequenceKeypoint.new(u, effectColor(Cfg.TrailMode, Cfg.AnimT, u, idx, Cfg.TrailColor, Cfg.TrailColor2))
			end
			return ColorSequence.new(kps)
		end

		-- Static: 1 màu / 2 màu (đầu -> đuôi) / gần cuối đổi sang màu thứ 2
		local function staticTrailSeq()
			local c1, c2 = Cfg.TrailColor, Cfg.TrailColor2
			if Cfg.TrailStyle == "2 Colors" then
				return ColorSequence.new(c1, c2)
			elseif Cfg.TrailStyle == "End Color" then
				return ColorSequence.new({
					ColorSequenceKeypoint.new(0, c1),
					ColorSequenceKeypoint.new(0.7, c1),
					ColorSequenceKeypoint.new(1, c2),
				})
			end
			return ColorSequence.new(c1)
		end

		local function palletEffectColor()
			local h, sat, v = Cfg.Color:ToHSV()
			local comp = Color3.fromHSV((h + 0.5) % 1, sat, v)
			return effectColor(Cfg.PalletMode, Cfg.AnimT, 0.5, 0, Cfg.Color, comp)
		end

		local Records = {} -- [pallet] = rec
		local FxFolder = nil
		local Active = true
		local HeartbeatConn = nil

		local function getFxFolder()
			if FxFolder and FxFolder.Parent then
				return FxFolder
			end
			FxFolder = Instance.new("Folder")
			FxFolder.Name = "RSCPalletFx"
			FxFolder.Parent = workspace
			return FxFolder
		end

		local function normId(v)
			local s = tostring(v or ""):gsub("%s", "")
			if s == "" then
				return ""
			end
			if s:match("^%d+$") then
				return "rbxassetid://" .. s
			end
			return s
		end

		local function getMaterial()
			local ok, m = pcall(function()
				return Enum.Material[Cfg.Material]
			end)
			return ok and m or Enum.Material.Neon
		end

		local function preload(id)
			id = normId(id)
			if id ~= "" then
				task.spawn(function()
					pcall(function()
						ContentProvider:PreloadAsync({ id })
					end)
				end)
			end
		end
		preload(Cfg.DecalId)

		local function newAnchoredPart(name, size)
			local p = Instance.new("Part")
			p.Name = name
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.CastShadow = false
			p.Transparency = 1
			p.Size = size
			return p
		end

		local function pivotCFOf(model)
			local ok, cf = pcall(function()
				return model:GetPivot()
			end)
			return ok and cf or nil
		end

		-- ---------- hộp bao của CẢ pallet (tính trong toạ độ local của pivot) ----------
		local function collectParts(model)
			local list = {}
			if model:IsA("BasePart") then
				list[#list + 1] = model
			end
			for _, d in ipairs(model:GetDescendants()) do
				if d:IsA("BasePart") then
					list[#list + 1] = d
				end
			end
			return list
		end

		local function computeBox(rec, parts)
			local pcf = pivotCFOf(rec.Model)
			if not pcf then
				return false
			end
			local inv = pcf:Inverse()

			-- ưu tiên part nhìn thấy; nếu không có thì dùng hết
			local use = {}
			for _, p in ipairs(parts) do
				if p.Transparency < 0.99 then
					use[#use + 1] = p
				end
			end
			if #use == 0 then
				use = parts
			end
			if #use == 0 then
				return false
			end

			local mn = Vector3.new(math.huge, math.huge, math.huge)
			local mx = Vector3.new(-math.huge, -math.huge, -math.huge)
			for _, p in ipairs(use) do
				local cf = inv * p.CFrame
				local h = p.Size / 2
				for _, sx in ipairs({ -1, 1 }) do
					for _, sy in ipairs({ -1, 1 }) do
						for _, sz in ipairs({ -1, 1 }) do
							local v = cf * Vector3.new(sx * h.X, sy * h.Y, sz * h.Z)
							mn = mn:Min(v)
							mx = mx:Max(v)
						end
					end
				end
			end

			local size = mx - mn
			local center = (mn + mx) / 2

			-- trục mỏng nhất = pháp tuyến của mặt to; 2 trục còn lại nằm trên mặt to
			local thin = 2
			if size.X <= size.Y and size.X <= size.Z then
				thin = 1
			elseif size.Z <= size.X and size.Z <= size.Y then
				thin = 3
			end

			local halfA, halfB, faces, pad
			if thin == 2 then
				halfA = Vector3.new(size.X / 2, 0, 0)
				halfB = Vector3.new(0, 0, size.Z / 2)
				faces = { Enum.NormalId.Top, Enum.NormalId.Bottom }
				pad = Vector3.new(0, DECAL_PAD, 0)
			elseif thin == 1 then
				halfA = Vector3.new(0, size.Y / 2, 0)
				halfB = Vector3.new(0, 0, size.Z / 2)
				faces = { Enum.NormalId.Right, Enum.NormalId.Left }
				pad = Vector3.new(DECAL_PAD, 0, 0)
			else
				halfA = Vector3.new(size.X / 2, 0, 0)
				halfB = Vector3.new(0, size.Y / 2, 0)
				faces = { Enum.NormalId.Back, Enum.NormalId.Front }
				pad = Vector3.new(0, 0, DECAL_PAD)
			end

			rec.Center = center
			rec.HalfA = halfA
			rec.HalfB = halfB
			rec.BoxSize = size + pad
			rec.Faces = faces
			rec.PartCount = #parts
			return true
		end

		-- ---------- hiệu ứng (decal mặt to + trail + decal bắn xuống) ----------
		local function trailTransparency()
			local t = math.clamp(Cfg.TrailTransparency, 0, 1)
			local kp = NumberSequenceKeypoint.new
			return NumberSequence.new({ kp(0, t), kp(0.6, t + (1 - t) * 0.45), kp(1, 1) })
		end

		local function updateFx(rec)
			local tex = normId(Cfg.DecalId)
			if rec.Decals then
				rec.Decals.Texture = tex
				rec.Decals.Enabled = tex ~= ""
			end
			for _, img in ipairs(rec.BigImgs or {}) do
				img.Image = tex
				img.Visible = tex ~= ""
				img.ImageTransparency = math.clamp(Cfg.DecalTransparency, 0, 1)
			end
			local trailTex = normId(Cfg.TrailId)
			local seq = trailTransparency()
			local staticSeq = staticTrailSeq()
			local w = math.max(Cfg.TrailWidth, 0.05)
			for i, e in ipairs(rec.TrailFx or {}) do
				e.Trail.Texture = trailTex
				e.Trail.Transparency = seq
				e.Trail.Color = (Cfg.TrailMode == "Static") and staticSeq or animTrailSeq(i)
				e.A0.Position = Vector3.new(0, w / 2, 0)
				e.A1.Position = Vector3.new(0, -w / 2, 0)
			end
		end

		local function fxAlive(rec)
			return rec.Decals and rec.Decals.Parent and rec.BigPart and rec.BigPart.Parent and rec.TrailFx ~= nil
		end

		local function destroyFx(rec)
			if rec.DecalPart then
				pcall(function()
					rec.DecalPart:Destroy()
				end)
			end
			rec.DecalPart, rec.Decals = nil, nil
			if rec.BigPart then
				pcall(function()
					rec.BigPart:Destroy()
				end)
			end
			rec.BigPart, rec.BigImgs = nil, nil
			for _, e in ipairs(rec.TrailFx or {}) do
				pcall(function()
					e.Part:Destroy()
				end)
			end
			rec.TrailFx = nil
		end

		local function ensureFx(rec)
			if fxAlive(rec) then
				return
			end
			if not rec.Center then
				return
			end
			destroyFx(rec)

			local folder = getFxFolder()
			local kp = NumberSequenceKeypoint.new
			local pcf = pivotCFOf(rec.Model) or CFrame.new(rec.Last)

			-- 1 tấm decal phủ nguyên mặt to của pallet (trên + dưới)
			local big = newAnchoredPart("PalletBigDecal", rec.BoxSize)
			big.CFrame = pcf * CFrame.new(rec.Center)
			big.Parent = folder
			rec.BigImgs = {}
			for _, face in ipairs(rec.Faces) do
				local sg = Instance.new("SurfaceGui")
				sg.Face = face
				sg.Adornee = big
				sg.LightInfluence = 0
				sg.Brightness = 1
				sg.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
				sg.CanvasSize = Vector2.new(512, 512)
				sg.Parent = big

				local img = Instance.new("ImageLabel")
				img.BackgroundTransparency = 1
				img.BorderSizePixel = 0
				img.Size = UDim2.fromScale(1, 1)
				img.ScaleType = Enum.ScaleType.Stretch
				img.Parent = sg
				rec.BigImgs[#rec.BigImgs + 1] = img
			end
			rec.BigPart = big

			-- vùng phát decal bắn xuống: mỏng, nằm trên pallet
			local dpart = newAnchoredPart("PalletDecalEmitter", Vector3.new(6, 0.2, 6))
			dpart.CFrame = CFrame.new(pcf:PointToWorldSpace(rec.Center) + Vector3.new(0, 1.5, 0))
			dpart.Parent = folder

			local pe = Instance.new("ParticleEmitter")
			pe.Rate = 90
			pe.Lifetime = NumberRange.new(1.2, 2.2)
			pe.Speed = NumberRange.new(6, 14)
			pe.EmissionDirection = Enum.NormalId.Bottom
			pe.SpreadAngle = Vector2.new(30, 30)
			pe.Acceleration = Vector3.new(0, -30, 0)
			pe.Rotation = NumberRange.new(0, 360)
			pe.RotSpeed = NumberRange.new(-150, 150)
			pe.Size = NumberSequence.new({ kp(0, 0.3), kp(0.15, 1.3), kp(1, 1) })
			pe.Transparency = NumberSequence.new({ kp(0, 1), kp(0.08, 0), kp(0.5, 0), kp(1, 1) })
			pe.LightEmission = 0.6
			pe.LightInfluence = 0
			pe.LockedToPart = false
			pe.Parent = dpart
			rec.DecalPart, rec.Decals = dpart, pe

			-- trail: hình chữ X (tâm + 4 nhánh chéo), đứng yên theo pallet
			rec.TrailFx = {}
			local w = math.max(Cfg.TrailWidth, 0.05)
			for i, cfg in ipairs(buildTrailDefs()) do
				local lpos = rec.Center + rec.HalfA * cfg.SA + rec.HalfB * cfg.SB

				local part = newAnchoredPart("PalletTrailEmitter" .. i, Vector3.new(0.2, 0.2, 0.2))
				part.CFrame = CFrame.new(pcf * lpos)
				part.Parent = folder

				local a0 = Instance.new("Attachment")
				a0.Position = Vector3.new(0, w / 2, 0)
				a0.Parent = part
				local a1 = Instance.new("Attachment")
				a1.Position = Vector3.new(0, -w / 2, 0)
				a1.Parent = part

				local tr = Instance.new("Trail")
				tr.Attachment0 = a0
				tr.Attachment1 = a1
				tr.Lifetime = TRAIL_LIFETIME
				tr.LightEmission = 1
				tr.FaceCamera = true
				tr.MinLength = 0.02
				tr.TextureMode = Enum.TextureMode.Stretch
				tr.Color = staticTrailSeq()
				tr.Transparency = trailTransparency()
				tr.WidthScale = NumberSequence.new({ kp(0, 1), kp(1, 0.15) })
				tr.Parent = part

				rec.TrailFx[i] = { Part = part, Trail = tr, A0 = a0, A1 = a1, Local = lpos }
			end
			updateFx(rec)
		end

		-- ---------- pallet ----------
		local function restorePallet(rec)
			for part, o in pairs(rec.Parts) do
				if part.Parent then
					pcall(function()
						part.Color = o.Color
						part.Material = o.Material
						part.Transparency = o.Transparency
						if o.Tex ~= nil then
							part.TextureID = o.Tex
						end
						for _, sa in ipairs(o.SA) do
							sa.Parent = part
						end
					end)
				end
			end
			rec.Parts = {}
			destroyFx(rec)
		end

		local function applyPart(rec, part, mat)
			local o = rec.Parts[part]
			if not o then
				if part.Transparency >= 0.99 then
					return
				end
				o = {
					Color = part.Color,
					Material = part.Material,
					Transparency = part.Transparency,
					Tex = part:IsA("MeshPart") and part.TextureID or nil,
					SA = {},
				}
				rec.Parts[part] = o
				for _, c in ipairs(part:GetChildren()) do
					if c:IsA("SurfaceAppearance") then
						table.insert(o.SA, c)
					end
				end
				for _, sa in ipairs(o.SA) do
					sa.Parent = nil
				end
			end

			local wantC = (Cfg.PalletMode == "Static") and Cfg.Color or Cfg.CurPalletColor
			if part.Color ~= wantC then
				part.Color = wantC
			end
			if part.Material ~= mat then
				part.Material = mat
			end
			if part:IsA("MeshPart") and part.TextureID ~= "" then
				part.TextureID = ""
			end

			local T = math.clamp(Cfg.PalletTransparency, 0, 0.95)
			local wantT = o.Transparency + (1 - o.Transparency) * T
			if part.Transparency ~= wantT then
				part.Transparency = wantT
			end
		end

		local function applyPallet(rec)
			local model = rec.Model
			if not model.Parent then
				return
			end
			local mat = getMaterial()
			local parts = collectParts(model)

			-- số part đổi (pallet spawn chưa xong) -> tính lại hộp bao + dựng lại fx
			if rec.PartCount ~= #parts then
				if computeBox(rec, parts) then
					destroyFx(rec)
				end
			end

			for _, p in ipairs(parts) do
				pcall(applyPart, rec, p, mat)
			end
			ensureFx(rec)
			updateFx(rec)
		end

		local function isPalletName(name)
			return string.find(name, "Pallet", 1, true) ~= nil or string.find(name, "Palete", 1, true) ~= nil
		end

		local function scanPallets()
			local folder = workspace:FindFirstChild(lp.Name .. "SpawnedInToys")
			if not folder then
				return
			end
			for _, child in ipairs(folder:GetChildren()) do
				if (child:IsA("Model") or child:IsA("BasePart")) and isPalletName(child.Name) then
					local rec = Records[child]
					if not rec then
						local cf = pivotCFOf(child)
						rec = {
							Model = child,
							Parts = {},
							Last = cf and cf.Position or Vector3.zero,
						}
						Records[child] = rec
					end
					applyPallet(rec)
				end
			end
		end

		local animAcc = 0
		local function step(dt)
			if not Active or not Cfg.Enabled then
				return
			end

			-- animation màu (cập nhật ~30 lần/giây cho nhẹ)
			Cfg.AnimT = Cfg.AnimT + dt * Cfg.EffectSpeed
			animAcc = animAcc + dt
			local doAnim = animAcc >= 1 / 30
			if doAnim then
				animAcc = 0
				if Cfg.PalletMode ~= "Static" then
					Cfg.CurPalletColor = palletEffectColor()
				end
			end

			for model, rec in pairs(Records) do
				if not model.Parent then
					restorePallet(rec)
					Records[model] = nil
				else
					local pcf = pivotCFOf(model)
					if pcf and rec.Center then
						rec.Last = pcf.Position

						if doAnim then
							if Cfg.PalletMode ~= "Static" then
								for part in pairs(rec.Parts) do
									if part.Parent then
										part.Color = Cfg.CurPalletColor
									end
								end
							end
							if Cfg.TrailMode ~= "Static" then
								for i, e in ipairs(rec.TrailFx or {}) do
									e.Trail.Color = animTrailSeq(i)
								end
							end
						end

						-- trail: giữa + 4 góc bám theo pallet
						for _, e in ipairs(rec.TrailFx or {}) do
							if e.Part.Parent then
								e.Part.CFrame = CFrame.new(pcf * e.Local)
							end
						end

						-- decal phủ mặt to
						if rec.BigPart and rec.BigPart.Parent then
							rec.BigPart.CFrame = pcf * CFrame.new(rec.Center)
						end

						if rec.DecalPart and rec.DecalPart.Parent then
							rec.DecalPart.CFrame = CFrame.new(pcf:PointToWorldSpace(rec.Center) + Vector3.new(0, 1.5, 0))
						end
					end
				end
			end
		end

		local function refreshAll()
			for _, rec in pairs(Records) do
				applyPallet(rec)
			end
		end

		-- đổi số lượng trail -> dựng lại hiệu ứng
		local function rebuildFx()
			for _, rec in pairs(Records) do
				destroyFx(rec)
			end
			refreshAll()
		end

		local function setEnabled(v)
			Cfg.Enabled = v and true or false
			if Cfg.Enabled then
				scanPallets()
			else
				for model, rec in pairs(Records) do
					restorePallet(rec)
					Records[model] = nil
				end
			end
		end

		HeartbeatConn = RunService.Heartbeat:Connect(step)

		task.spawn(function()
			while Active do
				if Cfg.Enabled then
					pcall(scanPallets)
				end
				task.wait(0.5)
			end
		end)

		pcall(function()
			lib:OnUnload(function()
				Active = false
				Cfg.Enabled = false
				if HeartbeatConn then
					HeartbeatConn:Disconnect()
					HeartbeatConn = nil
				end
				for model, rec in pairs(Records) do
					pcall(restorePallet, rec)
					Records[model] = nil
				end
				if FxFolder then
					pcall(function()
						FxFolder:Destroy()
					end)
				end
			end)
		end)

