	end

	do
		local Gamepasses = tbl15.Misc:AddLeftTabbox("Gamepasses")
		local Gamepasses2 = Gamepasses:AddTab("Gamepasses", "dollar-sign")
		local tbl16 = { Enabled = false }

		Gamepasses2:AddToggle("FartherReach", {
			Text = "Further Reach Line",
			Default = false,
			Tooltip = "Increases your reach",
			Callback = function(arg)
				local flag12 = arg and not flag11
				if tbl16.Enabled == flag12 then
					return
				end

				if flag12 then
					local gamepassEvents = ReplicatedStorage:FindFirstChild("GamepassEvents")
					local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
					local furtherReachBoughtNotifier = gamepassEvents and gamepassEvents:FindFirstChild("FurtherReachBoughtNotifier")
					local limitedTimeToyEvent = menuToys and menuToys:FindFirstChild("LimitedTimeToyEvent")
					local fartherReach = localPlayer:FindFirstChild("FartherReach")
					if not (furtherReachBoughtNotifier and furtherReachBoughtNotifier:IsA("RemoteEvent") and limitedTimeToyEvent and limitedTimeToyEvent:IsA("RemoteEvent")) or fartherReach and not fartherReach:IsA("BoolValue") then
						toggles.FartherReach:SetValue(false)
						return fn18("Further Reach is unavailable: required game objects are missing or invalid.")
					end
					local v20 = tbl16
					local v21 = tbl16
					local v22 = tbl16
					local v23 = tbl16
					tbl16.Enabled = true
					v20.Notifier = furtherReachBoughtNotifier
					v21.Event = limitedTimeToyEvent
					v22.Events = gamepassEvents
					v23.Toys = menuToys
					local v24 = tbl16
					local v25 = tbl16
					local boolValue = fartherReach or Instance.new("BoolValue")
					fartherReach = fartherReach and fartherReach.Value
					v24.Line = boolValue
					v25.LineValue = fartherReach
					local line = tbl16.Line
					local line2 = tbl16.Line
					local v26 = localPlayer
					tbl16.Line.Name = "FartherReach"
					line.Value = true
					line2.Parent = v26
					furtherReachBoughtNotifier.Parent = workspace
					limitedTimeToyEvent.Name = "FurtherReachBoughtNotifier"
					limitedTimeToyEvent.Parent = gamepassEvents
					local connection = nil

					local function fn21(character)
						if not connection.Connected or flag11 then
							return
						end
						local grabbingScript = character and character:WaitForChild("GrabbingScript", 5)
						if not (connection.Connected and not flag11 and character == localPlayer.Character and grabbingScript and grabbingScript.Parent == character and grabbingScript:IsA("LocalScript")) then
							return
						end

						if tbl16.Script then
							tbl16.Script:Disconnect()
						end

						local function fn22()
							if connection.Connected and not flag11 and character == localPlayer.Character and grabbingScript.Parent == character and grabbingScript.Enabled and limitedTimeToyEvent.Parent then
								limitedTimeToyEvent:FireServer()
							end
						end

						grabbingScript.Enabled = false
						grabbingScript.Enabled = true

						tbl16.Script = grabbingScript:GetPropertyChangedSignal("Enabled"):Connect(function()
							if grabbingScript.Enabled then
								task.delay(1, fn22)
							end
						end)

						task.delay(1, fn22)
					end

					connection = localPlayer.CharacterAdded:Connect(fn21)
					tbl16.Connection = connection
					task.spawn(fn21, localPlayer.Character)
				else
					tbl16.Enabled = false

					if tbl16.Connection then
						tbl16.Connection:Disconnect()
					end

					if tbl16.Script then
						tbl16.Script:Disconnect()
					end

					if tbl16.Line and tbl16.Line.Parent then
						if tbl16.LineValue == nil then
							tbl16.Line:Destroy()
						else
							tbl16.Line.Value = tbl16.LineValue
						end
					end

					if tbl16.Event and tbl16.Event.Parent and tbl16.Toys.Parent then
						local event = tbl16.Event
						local toys = tbl16.Toys
						tbl16.Event.Name = "LimitedTimeToyEvent"
						event.Parent = toys
					end

					if tbl16.Notifier and tbl16.Notifier.Parent and tbl16.Events.Parent then
						tbl16.Notifier.Parent = tbl16.Events
					end

					local v20 = tbl16
					local v21 = tbl16
					local v22 = tbl16
					local v23 = tbl16
					tbl16.Connection = nil
					v20.Script = nil
					v21.Line = nil
					v22.Event = nil
					v23.Notifier = nil
					local grabbingScript = localPlayer.Character and localPlayer.Character:FindFirstChild("GrabbingScript")

					if grabbingScript and grabbingScript:IsA("LocalScript") then
						grabbingScript.Enabled = false
						grabbingScript.Enabled = true
					end
				end

				local grabParts = workspace:FindFirstChild("GrabParts")

				if grabParts then
					grabParts:Destroy()
				end
			end,
		})

		Gamepasses2:AddToggle("GradientLineT", {
			Text = "Gradient Line",
			Default = false,
			Tooltip = "Changes the color of your line to the selected gradient in Config",
			Callback = function(gradientLine)
				tbl8.GradientLine = gradientLine

				task.spawn(function()
					local gradients = tbl7.Gradients

					while task.wait(0.5) and tbl8.GradientLine and not flag11 do
						local updateLineColorsEvent = ReplicatedStorage.DataEvents.UpdateLineColorsEvent
						local fireServer = updateLineColorsEvent.FireServer
						local colorSequence = ColorSequence.new
						local tbl17 = {}
						local v20 = ColorSequenceKeypoint.new(0, gradients.Color1)
						local v21 = ColorSequenceKeypoint.new(0.125, gradients.Color2)
						local v22 = ColorSequenceKeypoint.new(0.25, gradients.Color3)
						local v23 = ColorSequenceKeypoint.new(0.375, gradients.Color4)
						local v24 = ColorSequenceKeypoint.new(0.5, gradients.Color5)
						local v25 = ColorSequenceKeypoint.new(0.625, gradients.Color6)
						local v26 = ColorSequenceKeypoint.new(0.75, gradients.Color7)
						local v27 = ColorSequenceKeypoint.new(0.875, gradients.Color8)
						local new = ColorSequenceKeypoint.new
						local dotColor = gradients.DotColor
						tbl17[1] = v20
						tbl17[2] = v21
						tbl17[3] = v22
						tbl17[4] = v23
						tbl17[5] = v24
						tbl17[6] = v25
						tbl17[7] = v26
						tbl17[8] = v27

						do
							local values = table.pack(new(1, dotColor))
							table.move(values, 1, values.n, 9, tbl17)
						end

						local color1 = gradients.Color1
						local color2 = gradients.Color2
						local color3 = gradients.Color3
						local color4 = gradients.Color4
						local color5 = gradients.Color5
						local color6 = gradients.Color6
						local color7 = gradients.Color7
						local color8 = gradients.Color8
						local dotColor2 = gradients.DotColor
						fireServer(updateLineColorsEvent, colorSequence(tbl17), color1, color2, color3, color4, color5, color6, color7, color8, dotColor2)
					end
				end)
			end,
		})

		Gamepasses2:AddToggle("FasterEscapeT", {
			Text = "Faster Escape",
			Default = false,
			Tooltip = "Allows you to escape in 3 seconds instead of 12",
			Callback = function(fasterEscape)
				tbl8.FasterEscape = fasterEscape
			end,
		})

		do
			-- Mini Map (từ Endoris)
			local Players = game:GetService("Players")
			local RunService = game:GetService("RunService")
			local UserInputService = game:GetService("UserInputService")
			local Workspace = game:GetService("Workspace")
			local LocalPlayer = Players.LocalPlayer

			local MM = {
				Enabled = false,
				Gui = nil,
				Frame = nil,
				ViewArrow = nil,
				Pixels = {},
				PlayerDots = {},
				RenderConn = nil,
				InputConns = {},
				Zoom = 500,
				GridRes = 28,
				Rebuild = nil,
				Offset = Vector3.zero,
				LastScanPos = Vector3.zero,
				LastScanTime = 0,
			}

			local function stopMiniMap()
				MM.Enabled = false
				if MM.RenderConn then
					MM.RenderConn:Disconnect()
					MM.RenderConn = nil
				end
				for _, conn in ipairs(MM.InputConns) do
					if conn.Connected then
						conn:Disconnect()
					end
				end
				MM.InputConns = {}
				for _, dot in pairs(MM.PlayerDots) do
					if dot and dot.Parent then
						dot:Destroy()
					end
				end
				MM.PlayerDots = {}
				if MM.Gui then
					MM.Gui:Destroy()
					MM.Gui = nil
					MM.Frame = nil
					MM.ViewArrow = nil
				end
				MM.Pixels = {}
				MM.Rebuild = nil
			end

			local function startMiniMap()
				if MM.Gui then
					return
				end

				local mapRp = RaycastParams.new()
				mapRp.FilterType = Enum.RaycastFilterType.Exclude

				local MapGui = Instance.new("ScreenGui")
				MapGui.Name = "CustomMinimapGui"
				MapGui.ResetOnSpawn = false
				pcall(function()
					MapGui.Parent = game:GetService("CoreGui")
				end)
				if not MapGui.Parent then
					MapGui.Parent = LocalPlayer:WaitForChild("PlayerGui")
				end
				MM.Gui = MapGui

				local MapFrame = Instance.new("Frame", MapGui)
				MapFrame.Size = UDim2.new(0, 220, 0, 220)
				MapFrame.Position = UDim2.new(0.01, 0, 0.02, 0)
				MapFrame.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
				MapFrame.BorderColor3 = Color3.fromRGB(255, 105, 180)
				MapFrame.BorderSizePixel = 2
				MapFrame.ClipsDescendants = true
				MapFrame.Visible = true
				MapFrame.Active = true
				MM.Frame = MapFrame

				local function buildGrid()
					for _, col in ipairs(MM.Pixels) do
						for _, px in ipairs(col) do
							px:Destroy()
						end
					end
					local gridRes = MM.GridRes
					MM.Pixels = {}
					for x = 1, gridRes do
						MM.Pixels[x] = {}
						for y = 1, gridRes do
							local p = Instance.new("Frame", MapFrame)
							p.Size = UDim2.new(1 / gridRes, 0, 1 / gridRes, 0)
							p.Position = UDim2.new((x - 1) / gridRes, 0, (y - 1) / gridRes, 0)
							p.BorderSizePixel = 0
							p.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
							MM.Pixels[x][y] = p
						end
					end
				end
				MM.Rebuild = function()
					buildGrid()
					MM.LastScanTime = 0 -- ép quét lại ngay
				end
				buildGrid()

				local viewArrow = Instance.new("ImageLabel", MapFrame)
				viewArrow.Name = "ViewArrow"
				viewArrow.AnchorPoint = Vector2.new(0.5, 0.5)
				viewArrow.Size = UDim2.new(0, 20, 0, 14)
				viewArrow.BackgroundTransparency = 1
				viewArrow.ZIndex = 15
				viewArrow.Image = "rbxassetid://7072706796"
				viewArrow.ImageColor3 = Color3.fromRGB(0, 255, 255)
				viewArrow.Rotation = 0
				MM.ViewArrow = viewArrow

				local dragStartPos = nil
				local dragging = false
				local uiMoving = false
				local mapScrolling = false
				local pressTime = 0
				local uiStartPos = nil
				local mapOffsetStart = nil
				local moveCon, endCon

				local function onInputBegin(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = true
						uiMoving = false
						mapScrolling = false
						pressTime = tick()
						dragStartPos = input.Position
						uiStartPos = MapFrame.Position
						mapOffsetStart = MM.Offset

						moveCon = UserInputService.InputChanged:Connect(function(inp)
							if
								(inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch)
								and dragging
							then
								local delta = inp.Position - dragStartPos
								local elapsed = tick() - pressTime
								if not uiMoving and not mapScrolling then
									if delta.Magnitude > 5 then
										if elapsed > 0.25 then
											mapScrolling = true
										else
											uiMoving = true
										end
									end
								end
								if uiMoving then
									MapFrame.Position = UDim2.new(
										uiStartPos.X.Scale,
										uiStartPos.X.Offset + delta.X,
										uiStartPos.Y.Scale,
										uiStartPos.Y.Offset + delta.Y
									)
								elseif mapScrolling then
									local relX = delta.X / MapFrame.AbsoluteSize.X
									local relY = delta.Y / MapFrame.AbsoluteSize.Y
									MM.Offset = mapOffsetStart - Vector3.new(relX * MM.Zoom, 0, relY * MM.Zoom)
								end
							end
						end)

						endCon = UserInputService.InputEnded:Connect(function(inp)
							if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
								if dragging then
									dragging = false
									-- chạm nhẹ (không kéo) = teleport tới vị trí trên map
									if
										not uiMoving
										and not mapScrolling
										and (inp.Position - dragStartPos).Magnitude < 15
										and LocalPlayer.Character
									then
										local root = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
										if root then
											local relX = (inp.Position.X - MapFrame.AbsolutePosition.X) / MapFrame.AbsoluteSize.X - 0.5
											local relY = (inp.Position.Y - MapFrame.AbsolutePosition.Y) / MapFrame.AbsoluteSize.Y - 0.5
											local centerPos = root.Position + MM.Offset
											local targetX = centerPos.X + (relX * MM.Zoom)
											local targetZ = centerPos.Z + (relY * MM.Zoom)
											mapRp.FilterDescendantsInstances = { LocalPlayer.Character }
											local rayRes = Workspace:Raycast(Vector3.new(targetX, 1000, targetZ), Vector3.new(0, -2000, 0), mapRp)
											local finalY = rayRes and rayRes.Position.Y or root.Position.Y
											root.CFrame = CFrame.new(targetX, finalY + 4, targetZ)
										end
									end
								end
								if moveCon then
									moveCon:Disconnect()
									moveCon = nil
								end
								if endCon then
									endCon:Disconnect()
									endCon = nil
								end
							end
						end)
					end
				end

				table.insert(MM.InputConns, MapFrame.InputBegan:Connect(onInputBegin))
				table.insert(
					MM.InputConns,
					MapFrame.InputChanged:Connect(function(input)
						if input.UserInputType == Enum.UserInputType.MouseWheel then
							MM.Zoom = math.clamp(MM.Zoom + (input.Position.Z * -100), 50, 1500)
						end
					end)
				)

				local initialZoom = MM.Zoom
				table.insert(
					MM.InputConns,
					UserInputService.TouchPinch:Connect(function(_, scale, _, state)
						if not MapFrame.Visible then
							return
						end
						if state == Enum.UserInputState.Begin then
							initialZoom = MM.Zoom
						elseif state == Enum.UserInputState.Change then
							MM.Zoom = math.clamp(initialZoom / scale, 50, 1500)
						end
					end)
				)

				table.insert(
					MM.InputConns,
					Players.PlayerRemoving:Connect(function(p)
						if MM.PlayerDots[p.Name] then
							MM.PlayerDots[p.Name]:Destroy()
							MM.PlayerDots[p.Name] = nil
						end
					end)
				)

				MM.RenderConn = RunService.RenderStepped:Connect(function()
					if not MM.Enabled then
						return
					end
					local char = LocalPlayer.Character
					local hrp = char and char:FindFirstChild("HumanoidRootPart")
					if not hrp then
						return
					end

					local centerPos = hrp.Position + MM.Offset
					local now = tick()
					local moved = (centerPos - MM.LastScanPos).Magnitude > 6
					local timed = now - MM.LastScanTime > 1.5

					if MapFrame.Visible and (moved or timed) then
						MM.LastScanPos = centerPos
						MM.LastScanTime = now
						local gridRes = MM.GridRes
						mapRp.FilterDescendantsInstances = { char }
						for x = 1, gridRes do
							for y = 1, gridRes do
								local offX = ((x - 1) / (gridRes - 1) - 0.5) * MM.Zoom
								local offZ = ((y - 1) / (gridRes - 1) - 0.5) * MM.Zoom
								local ray = Workspace:Raycast(centerPos + Vector3.new(offX, 100, offZ), Vector3.new(0, -200, 0), mapRp)
								if ray and ray.Instance then
									local partColor = ray.Instance.Color
									local h = math.clamp((ray.Position.Y - centerPos.Y + 30) / 60, 0.3, 1.2)
									MM.Pixels[x][y].BackgroundColor3 = Color3.fromRGB(
										math.clamp(partColor.R * 255 * h, 0, 255),
										math.clamp(partColor.G * 255 * h, 0, 255),
										math.clamp(partColor.B * 255 * h, 0, 255)
									)
								else
									MM.Pixels[x][y].BackgroundColor3 = Color3.fromRGB(15, 15, 20)
								end
							end
						end
					end

					if MapFrame.Visible then
						local cam = Workspace.CurrentCamera
						if cam and MM.ViewArrow then
							local lookVec = cam.CFrame.LookVector
							local angle = math.atan2(lookVec.Z, lookVec.X)
							local radius = 18
							MM.ViewArrow.Position = UDim2.new(
								0.5 + math.cos(angle) * radius / MapFrame.AbsoluteSize.X,
								0,
								0.5 + math.sin(angle) * radius / MapFrame.AbsoluteSize.Y,
								0
							)
							MM.ViewArrow.Rotation = math.deg(angle) + 90
						end

						for _, p in pairs(Players:GetPlayers()) do
							local pr = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
							if pr then
								local d = MM.PlayerDots[p.Name]
								if not d then
									d = Instance.new("Frame", MapFrame)
									d.Size = UDim2.new(0, 26, 0, 26)
									d.AnchorPoint = Vector2.new(0.5, 0.5)
									d.BackgroundTransparency = 1
									d.ZIndex = 10

									local iconBg = Instance.new("Frame", d)
									iconBg.Size = UDim2.new(1, 0, 1, 0)
									iconBg.BackgroundColor3 = (p == LocalPlayer) and Color3.fromRGB(0, 255, 255) or Color3.fromRGB(255, 50, 50)
									Instance.new("UICorner", iconBg).CornerRadius = UDim.new(1, 0)

									local icon = Instance.new("ImageLabel", iconBg)
									icon.Size = UDim2.new(1, -4, 1, -4)
									icon.Position = UDim2.new(0, 2, 0, 2)
									icon.BackgroundTransparency = 1
									icon.ClipsDescendants = true
									Instance.new("UICorner", icon).CornerRadius = UDim.new(1, 0)
									task.spawn(function()
										local ok, url = pcall(function()
											return Players:GetUserThumbnailAsync(p.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
										end)
										if ok and url then
											icon.Image = url
										end
									end)

									local nameLbl = Instance.new("TextLabel", d)
									nameLbl.Size = UDim2.new(0, 100, 0, 12)
									nameLbl.Position = UDim2.new(0.5, -50, 1, 2)
									nameLbl.BackgroundTransparency = 1
									nameLbl.Text = p.DisplayName
									nameLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
									nameLbl.TextStrokeTransparency = 0.3
									nameLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
									nameLbl.TextSize = 10
									nameLbl.Font = Enum.Font.GothamBold
									nameLbl.ZIndex = 11

									MM.PlayerDots[p.Name] = d
								end
								local rx = (pr.Position.X - centerPos.X) / MM.Zoom
								local rz = (pr.Position.Z - centerPos.Z) / MM.Zoom
								d.Position = UDim2.new(0.5 + rx, 0, 0.5 + rz, 0)
								d.Visible = math.abs(rx) < 0.5 and math.abs(rz) < 0.5
							end
						end
					end
				end)
			end

			Gamepasses2:AddToggle("MiniMapT", {
				Text = "Mini Map",
				Default = false,
				Tooltip = "Bản đồ nhỏ: kéo nhanh để di chuyển UI, giữ rồi kéo để cuộn map, chạm để teleport, lăn chuột/chụm tay để zoom",
				Callback = function(value)
					if value then
						MM.Enabled = true
						startMiniMap()
					else
						stopMiniMap()
					end
				end,
			})

			-- Chỉnh độ nét pixel của Mini Map
			local QualityLevels = {
				["Blurrier (20x20)"] = 20,
				["Default (28x28)"] = 28,
				["Clearer (48x48)"] = 48,
				["Ultra Sharp (100x100) - 180+ FPS"] = 100,
			}
			local ULTRA_NAME = "Ultra Sharp (100x100) - 180+ FPS"
			local MIN_FPS_ULTRA = 180
			local CurrentQuality = "Default (28x28)"
			local Reverting = false
			local QualityDropdown

			local function notify(text)
				pcall(function()
					lib:Notify({ Title = "Mini Map", Description = text, Time = 5 })
				end)
			end

			local function measureFPS(duration)
				local frames = 0
				local t0 = tick()
				while tick() - t0 < duration do
					RunService.RenderStepped:Wait()
					frames += 1
				end
				return frames / math.max(tick() - t0, 0.001)
			end

			local function applyQuality(name)
				CurrentQuality = name
				MM.GridRes = QualityLevels[name]
				if MM.Rebuild then
					MM.Rebuild()
				end
			end

			QualityDropdown = Gamepasses2:AddDropdown("MiniMapQuality", {
				Values = {
					"Blurrier (20x20)",
					"Default (28x28)",
					"Clearer (48x48)",
					ULTRA_NAME,
				},
				Default = 2,
				Multi = false,
				Text = "Mini Map Pixel",
				Tooltip = "Ultra Sharp rất nặng, chỉ bật được khi máy đạt từ 180 FPS trở lên",
				Callback = function(value)
					if Reverting or not QualityLevels[value] or value == CurrentQuality then
						return
					end

					if value ~= ULTRA_NAME then
						applyQuality(value)
						return
					end

					-- Ultra Sharp: đo FPS trước khi cho bật
					task.spawn(function()
						notify("Dang do FPS de bat Ultra Sharp...")
						local fps = measureFPS(1.5)
						if fps >= MIN_FPS_ULTRA then
							applyQuality(value)
							notify(string.format("Ultra Sharp ON (%d FPS)", fps))
						else
							notify(string.format("FPS %d < %d, khong the bat Ultra Sharp", fps, MIN_FPS_ULTRA))
							Reverting = true
							pcall(function()
								QualityDropdown:SetValue(CurrentQuality)
							end)
							Reverting = false
						end
					end)
				end,
			})

			pcall(function()
				lib:OnUnload(stopMiniMap)
			end)
		end

