	-- ===== Unlock FPS (FFlags) =====
	do
		local FPSBox = tbl15.Misc:AddRightGroupbox("FPS", "gauge")
		local OriginalFlags = {}
		local TargetFps = 120

		local function stripPrefix(name)
			return (name:gsub("^DFInt", ""):gsub("^DFFlag", ""):gsub("^FFlag", ""):gsub("^FInt", ""):gsub("^FString", ""):gsub("^FLog", ""))
		end

		local function applyUnlock()
			local hasFFlag = type(setfflag) == "function"
			local hasCap = type(setfpscap) == "function"
			if not hasFFlag and not hasCap then
				pcall(fn18, "Unlock FPS: executor khong ho tro setfpscap lan setfflag.")
				return false
			end

			local applied = 0

			-- cach 1: setfpscap (hau het executor PC deu co)
			if hasCap then
				if pcall(setfpscap, TargetFps) then
					applied += 1
				end
			end

			if not hasFFlag then
				return applied > 0
			end

			local flags = {
				DFIntTaskSchedulerTargetFps = tostring(TargetFps),
				FFlagAuroraLimit60HzRenderSim = "False",
				FFlagDebugDisableVsync = "True",
				FFlagGameBasicSettingsFramerateCap = "False",
				DFFlagDisableTaskSchedulerTargetFpsLowerLimit = "True",
				FFlagTaskSchedulerTargetFpsIgnoreMin = "True",
				FFlagDebugGraphicsDisableDirect3D11Limit = "True",
			}

			-- cach 2: FFlags. Khong bat buoc getfflag tra ve gia tri (nhieu executor tra nil)
			for key, value in pairs(flags) do
				local cleanName = stripPrefix(key)
				if type(getfflag) == "function" and OriginalFlags[cleanName] == nil then
					local okGet, current = pcall(getfflag, cleanName)
					if okGet and current ~= nil then
						OriginalFlags[cleanName] = current
					end
				end
				if pcall(setfflag, cleanName, tostring(value)) then
					applied += 1
				end
			end
			if applied == 0 then
				pcall(fn18, "Unlock FPS: executor tu choi tat ca FFlag/setfpscap.")
			end
			return applied > 0
		end

		local function restoreFlags()
			if type(setfpscap) == "function" then
				pcall(setfpscap, 60)
			end
			if type(setfflag) == "function" then
				for name, value in pairs(OriginalFlags) do
					pcall(setfflag, name, tostring(value))
				end
			end
			table.clear(OriginalFlags)
		end

		FPSBox:AddToggle("UnlockFPS", {
			Text = "Unlock FPS",
			Default = false,
			Tooltip = "Go gioi han 60 FPS (FFlags). FPS hien tren watermark. Tat de tra ve gia tri cu",
			Callback = function(arg)
				tbl8.UnlockFPS = arg
				if arg then
					if not applyUnlock() then
						tbl8.UnlockFPS = false
						pcall(function()
							toggles.UnlockFPS:SetValue(false)
						end)
					end
				else
					restoreFlags()
				end
			end,
		})

		FPSBox:AddSlider("UnlockFPSTarget", {
			Text = "Target FPS",
			Default = 120,
			Min = 60,
			Max = 1000,
			Rounding = 0,
			Compact = true,
			Callback = function(value)
				TargetFps = value
				if tbl8.UnlockFPS then
					applyUnlock()
				end
			end,
		})
	end

