	do
		local function fn21(arg)
			if typeof(arg) ~= "UDim2" then
				return
			end
			return { arg.X.Scale, arg.X.Offset, arg.Y.Scale, arg.Y.Offset }
		end

		local function fn22(arg)
			if typeof(arg) ~= "table" then
				return
			end

			for i = 1, 4 do
				if typeof(arg[i]) ~= "number" then
					return
				end
			end

			return UDim2.new(arg[1], arg[2], arg[3], arg[4])
		end

		local function fn23(arg)
			local viewportSize = currentCamera.ViewportSize
			local n36 = arg.AbsolutePosition + arg.AbsoluteSize / 2
			local tbl16 = {}
			local n37 = n36.X / math.max(viewportSize.X, 1)
			local n38 = n36.Y / math.max(viewportSize.Y, 1)
			tbl16[1] = n37
			tbl16[2] = n38
			return tbl16
		end

		local function fn24(arg, arg2, position)
			if not arg or not arg.Parent then
				return
			end

			if position then
				arg.Position = position
			end

			local viewportSize = currentCamera.ViewportSize
			local absoluteSize = arg.AbsoluteSize
			local x = arg.AbsolutePosition.X
			local y = arg.AbsolutePosition.Y

			if typeof(arg2) == "table" and typeof(arg2[1]) == "number" and typeof(arg2[2]) == "number" then
				x = arg2[1] * viewportSize.X - absoluteSize.X / 2
				y = arg2[2] * viewportSize.Y - absoluteSize.Y / 2
			end

			local n36 = math.clamp(x, 6, math.max(6, viewportSize.X - absoluteSize.X - 6))
			local n37 = math.clamp(y, 6, math.max(6, viewportSize.Y - absoluteSize.Y - 6))
			local absolutePosition

			if arg.Parent:IsA("GuiObject") then
				absolutePosition = arg.Parent.AbsolutePosition
			else
				absolutePosition = Vector2.zero
			end

			arg.Position = UDim2.fromOffset(math.round(n36 - absolutePosition.X + arg.AnchorPoint.X * absoluteSize.X), math.round(n37 - absolutePosition.Y + arg.AnchorPoint.Y * absoluteSize.Y))
		end

		local function fn25(arg, arg2)
			if not arg or not arg.Parent or not arg2 then
				return
			end
			local viewportSize = currentCamera.ViewportSize
			local absoluteSize

			if arg.Parent:IsA("GuiObject") then
				absoluteSize = arg.Parent.AbsoluteSize
			else
				absoluteSize = viewportSize
			end

			local uiScale = arg:FindFirstChildOfClass("UIScale")
			uiScale = uiScale and uiScale.Scale or 1
			local n36 = (absoluteSize.Y * arg2.Y.Scale + arg2.Y.Offset) * uiScale
			local n37 = math.min(1, (viewportSize.X - 12) / math.max((absoluteSize.X * arg2.X.Scale + arg2.X.Offset) * uiScale, 1), (viewportSize.Y - 12) / math.max(n36, 1))
			local n38 = arg2.Y.Scale * n37
			local round = math.round
			local n39 = arg2.Y.Offset * n37
			arg.Size = UDim2.new(arg2.X.Scale * n37, math.round(arg2.X.Offset * n37), n38, round(n39))
		end

		local function fn26()
			local mainFrame = v19.MainFrame
			local sidebarWidth = v19:GetSidebarWidth()

			local tbl16 = {
				Position = mainFrame and fn21(mainFrame.Position),
				ScreenPosition = mainFrame and fn23(mainFrame),
				Size = mainFrame and fn21(mainFrame.Size),
				SidebarWidth = sidebarWidth,
				SidebarScale = sidebarWidth / math.max(mainFrame.Size.X.Offset, 1),
				WatermarkPosition = Watermark and Watermark.Label and fn21(Watermark.Label.Position),
				WatermarkScreenPosition = Watermark and Watermark.Label and fn23(Watermark.Label),
				MobileButtons = {},
			}

			for k, v20 in tbl7.ActiveDraggableButtons, nil, nil do
				if v20 and v20.Button and v20.Button.Parent then
					tbl16.MobileButtons[k] = { Position = fn21(v20.Button.Position), ScreenPosition = fn23(v20.Button) }
				end
			end

			return tbl16
		end

		local function fn27(arg)
			if typeof(arg) ~= "table" then
				return
			end
			local mainFrame = v19.MainFrame
			local v20 = fn22(arg.Size)
			local v21 = fn22(arg.Position)
			local v22 = fn22(arg.WatermarkPosition)
			fn25(mainFrame, v20)
			fn24(mainFrame, arg.ScreenPosition, v21)
			fn24(Watermark and Watermark.Label, arg.WatermarkScreenPosition, v22)
			local n36

			if typeof(arg.SidebarScale) == "number" then
				n36 = mainFrame.Size.X.Offset * arg.SidebarScale
			else
				n36 = arg.SidebarWidth
			end

			if typeof(n36) == "number" then
				v19:SetSidebarWidth(n36)
			end

			local tbl16 = {}

			for k in tbl7.ActiveDraggableButtons, nil, nil do
				table.insert(tbl16, k)
			end

			for _, v23 in tbl16, nil, nil do
				tbl12.RemoveMobileButton(v23)
			end

			if typeof(arg.MobileButtons) ~= "table" then
				return
			end

			for k, v23 in arg.MobileButtons, nil, nil do
				if typeof(v23) == "table" then
					local v24 = tbl12.AddMobileButton(k, fn22(v23.Position or v23))

					if v24 then
						fn24(v24.Button, v23.ScreenPosition)
					end
				end
			end
		end

		lib2:SetLibrary(lib)
		lib2:SetFolder("Resonance")
		lib3:SetLibrary(lib)
		local saveJSON = lib3.SaveJSON
		local loadJSON = lib3.LoadJSON

		lib3.SaveJSON = function(arg, arg2)
			local v20, v21, v22 = saveJSON(arg, arg2)
			if not v21 then
				return v20, v21, v22
			end
			local ok, result = pcall(HttpService.JSONDecode, HttpService, v20)
			if not ok or typeof(result) ~= "table" then
				return v20, v21, v22
			end
			result.ResonanceUI = fn26()
			local ok2, result2 = pcall(HttpService.JSONEncode, HttpService, result)
			if ok2 then
				return result2, true
			end
			return v20, v21, v22
		end

		lib3.LoadJSON = function(arg, arg2)
			local ok, result = pcall(HttpService.JSONDecode, HttpService, arg2)
			local v20, v21 = loadJSON(arg, arg2)

			if v20 and ok and typeof(result) == "table" and typeof(result.ResonanceUI) == "table" then
				task.defer(fn27, result.ResonanceUI)
			end

			return v20, v21
		end
	end

	lib3:IgnoreThemeSettings()

	lib3:SetIgnoreIndexes({
		"WhitelistDropdown",
		"ObjectGroup",
		"GroupNoclip",
		"GroupHighlight",
		"GroupFill",
		"GroupOutline",
	})

	lib3:SetFolder("Resonance/FTAP")
	lib3:BuildConfigSection(tbl15.Settings)
	lib3:LoadAutoloadConfig()

	if lib.IsMobile then
		toggles.AlwaysOnToggleAB:SetValue(true)
		toggles.AlwaysOnToggleAB:SetDisabled(true)
	end

	lib2:SetDefaultTheme({
    BackgroundColor = Color3.fromRGB(15, 15, 15),
    MainColor = Color3.fromRGB(25, 25, 25),
    AccentColor = Color3.fromRGB(255, 255, 255),   -- trước là (255, 255, 0)
    OutlineColor = Color3.fromRGB(70, 70, 70),
    FontColor = Color3.fromRGB(255, 255, 255),
    FontFace = "Code",
    })

	task.defer(function()
		local function fn21(arg)
			if not arg.Value or arg.Value == "None" then
				return nil
			end
			local v20 = table.clone(arg.Modifiers or {})
			table.sort(v20)
			local str5 = ":" .. arg.Value
			return table.concat(v20, "+") .. str5
		end

		for _, v20 in options, nil, nil do
			if v20.Type == "KeyPicker" and v20.OnChanged then
				local changed = v20.Changed
				local v21 = fn21(v20)
				local tbl16 = {}
				local value = v20.Value
				local mode = v20.Mode
				local clone = table.clone
				local modifiers = v20.Modifiers or {}
				local v22 = table.pack(clone(modifiers))
				tbl16[1] = value
				tbl16[2] = mode

				do
					local values = table.pack(table.unpack(v22, 1, v22.n))
					table.move(values, 1, values.n, 3, tbl16)
				end

				local flag12 = false

				v20:OnChanged(function(...)
					if changed then
						changed(...)
					end

					tbl12.UpdateKeybindMenu()
					local v23 = fn21(v20)
					local v24 = tbl16
					local tbl17 = {}
					local value2 = v20.Value
					local mode2 = v20.Mode
					local clone2 = table.clone
					local modifiers2 = v20.Modifiers or {}
					local v25 = table.pack(clone2(modifiers2))
					tbl17[1] = value2
					tbl17[2] = mode2

					do
						local values = table.pack(table.unpack(v25, 1, v25.n))
						table.move(values, 1, values.n, 3, tbl17)
					end

					tbl16 = tbl17
					if v23 == v21 then
						return
					end
					v21 = v23
					if flag12 or not v23 or flag11 then
						return
					end
					local tbl18 = {}

					for k, v26 in options, nil, nil do
						if v26 ~= v20 and v26.Type == "KeyPicker" and fn21(v26) == v23 then
							table.insert(tbl18, v26.Text or k)
						end
					end

					if #tbl18 > 0 then
						table.sort(tbl18)

						v19:AddDialog("KeybindConflict", {
							Title = "Keybind already assigned",
							Description = "This binding is also assigned to: " .. table.concat(tbl18, ", ") .. ". What would you like to do?",
							OutsideClickDismiss = false,
							FooterButtons = {
								{
									Title = "Cancel",
									Order = 1,
									Variant = "Secondary",
									Callback = function()
										if flag11 or fn21(v20) ~= v23 then
											return
										end
										flag12 = true
										v20:SetValue(v24)
										flag12 = false
									end,
								},
								{
									Title = "Replace",
									Order = 2,
									Callback = function()
										if flag11 or fn21(v20) ~= v23 then
											return
										end

										for _, v26 in options, nil, nil do
											if v26 ~= v20 and v26.Type == "KeyPicker" and fn21(v26) == v23 then
												v26:SetValue({ "None", v26.Mode, {} })
											end
										end
									end,
								},
								{ Title = "Keep Both", Order = 3, Variant = "Secondary" },
							},
						})
					end
				end)
			end
		end

		for _, v20 in toggles, nil, nil do
			if v20 and v20.OnChanged then
				v20:OnChanged(tbl12.UpdateEnabledToggleCount)
			end
		end

		tbl12.UpdateKeybindMenu()
		tbl12.UpdateEnabledToggleCount()
	end)

	do
		-- ==========================================
		-- COIN UI MOD: giữ icon gốc + viền neon có tia trắng chạy quanh KHUNG chứa coin
		-- (kiểu nhãn dán iPhone). Chạy ngay khi load, quét lại mỗi 3s để tránh
		-- bị game reset, unload UI sẽ trả giao diện coin về như cũ.
		-- ==========================================
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")

		local OLD_DECAL_ID = "8659337867"
		local REAPPLY_INTERVAL = 1 -- giây
		local SWEEP_TIME = 4 -- giây / 1 vòng quanh khung (lớn hơn = chạy chậm hơn)
		local STREAK_FRAC = 0.22 -- độ dài tia sáng (tỉ lệ chu vi khung)
		local LINE_THICKNESS = 2 -- lõi tia trắng
		local GLOW_THICKNESS = 5 -- quầng neon trong
		local HALO_THICKNESS = 10 -- quầng neon ngoài
		local PAD_X = 14 -- khoảng đệm viền so với chữ + coin (px), nhỏ hơn = viền ngắn hơn
		local PAD_Y = 6 -- khoảng đệm trên/dưới khi HUG_HEIGHT = true
		local HUG_HEIGHT = false -- true: viền ôm sát cả chiều cao chữ/coin; false: giữ chiều cao khung gốc

		local WHITE = Color3.new(1, 1, 1)

		local State = {
			Active = true,
			Cleaned = false,
			Images = {},
			Texts = {},
			Frames = {},
			Thread = nil,
			AddedConn = nil,
			RenderConn = nil,
		}

		-- ---------- tia sáng chạy quanh chu vi ----------
		local EDGES = {
			{ Axis = 0, Reverse = false }, -- trên: trái -> phải
			{ Axis = 90, Reverse = false }, -- phải: trên -> dưới
			{ Axis = 0, Reverse = true }, -- dưới: phải -> trái
			{ Axis = 90, Reverse = true }, -- trái: dưới -> trên
		}
		local LAYERS = {
			{ Thickness = HALO_THICKNESS, Transparency = 0.8 },
			{ Thickness = GLOW_THICKNESS, Transparency = 0.4 },
			{ Thickness = LINE_THICKNESS, Transparency = 0 },
		}

		local function edgeGeometry(i, T)
			if i == 1 then
				return UDim2.new(0, 0, 0, -T / 2), UDim2.new(1, 0, 0, T)
			elseif i == 2 then
				return UDim2.new(1, -T / 2, 0, 0), UDim2.new(0, T, 1, 0)
			elseif i == 3 then
				return UDim2.new(0, 0, 1, -T / 2), UDim2.new(1, 0, 0, T)
			end
			return UDim2.new(0, -T / 2, 0, 0), UDim2.new(0, T, 1, 0)
		end

		-- dải sáng tâm u (0..1 dọc theo cạnh), nửa rộng hw (cùng đơn vị)
		local function buildSeq(u, hw)
			if hw < 0.001 then
				hw = 0.001
			end
			local cand = { 0, u - hw, u, u + hw, 1 }
			table.sort(cand)
			local times = {}
			for _, t in ipairs(cand) do
				if t >= 0 and t <= 1 then
					local last = times[#times]
					if not last or t - last > 0.0001 then
						times[#times + 1] = t
					end
				end
			end
			if times[#times] < 1 then
				if 1 - times[#times] <= 0.0001 then
					times[#times] = 1
				else
					times[#times + 1] = 1
				end
			end
			local keys = {}
			for i, t in ipairs(times) do
				local alpha = math.max(0, 1 - math.abs(t - u) / hw)
				keys[i] = NumberSequenceKeypoint.new(t, math.clamp(1 - alpha, 0, 1))
			end
			return NumberSequence.new(keys)
		end

		local function destroyFrameFx(rec)
			if rec.Holder then
				pcall(function()
					rec.Holder:Destroy()
				end)
			end
			if rec.BaseStroke then
				pcall(function()
					rec.BaseStroke:Destroy()
				end)
			end
			rec.Holder = nil
			rec.BaseStroke = nil
			rec.Edges = {}
		end

		local function buildFrameFx(container, rec)
			destroyFrameFx(rec)

			local holder = Instance.new("Frame")
			holder.Name = "CoinSweepHolder"
			holder.BackgroundTransparency = 1
			holder.BorderSizePixel = 0
			holder.Size = UDim2.fromOffset(0, 0) -- sẽ được co lại theo coin + chữ trong updateSweep
			holder.Visible = false -- ẩn tới khi updateSweep đặt đúng kích thước (tránh khung to hiện rồi co chậm)
			holder.ZIndex = 100
			holder.Active = false
			pcall(function()
				holder.Interactable = false
			end)
			holder.Parent = container
			rec.Holder = holder

			-- viền mờ nền: gắn vào holder (co theo coin + chữ), bo góc giống khung gốc
			local corner = Instance.new("UICorner")
			local srcCorner = container:FindFirstChildOfClass("UICorner")
			corner.CornerRadius = srcCorner and srcCorner.CornerRadius or UDim.new(0, 8)
			corner.Parent = holder

			local base = Instance.new("UIStroke")
			base.Name = "CoinSweepBase"
			base.Color = WHITE
			base.Thickness = 1
			base.Transparency = 0.85
			base.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			base.Parent = holder
			rec.BaseStroke = base

			rec.Edges = {}
			for i, edge in ipairs(EDGES) do
				local gradients = {}
				for _, layer in ipairs(LAYERS) do
					local pos, size = edgeGeometry(i, layer.Thickness)
					local f = Instance.new("Frame")
					f.Name = "CoinSweepEdge" .. i
					f.BackgroundColor3 = WHITE
					f.BackgroundTransparency = layer.Transparency
					f.BorderSizePixel = 0
					f.Position = pos
					f.Size = size
					f.ZIndex = 100
					f.Active = false
					local g = Instance.new("UIGradient")
					g.Rotation = edge.Axis
					g.Transparency = NumberSequence.new(1)
					g.Parent = f
					f.Parent = holder
					table.insert(gradients, g)
				end
				rec.Edges[i] = { Reverse = edge.Reverse, Gradients = gradients }
			end
		end

		-- hệ số UIScale (nếu có) của khung và các cha của nó
		local function getUiScale(gui)
			local k = 1
			local p = gui
			while p and p:IsA("GuiObject") do
				local us = p:FindFirstChildOfClass("UIScale")
				if us then
					k = k * us.Scale
				end
				p = p.Parent
			end
			return k
		end

		-- vùng (px màn hình) ôm sát ảnh coin + chữ số của khung này
		local function contentBounds(container)
			local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
			local function add(x0, y0, x1, y1)
				if x0 < minX then minX = x0 end
				if y0 < minY then minY = y0 end
				if x1 > maxX then maxX = x1 end
				if y1 > maxY then maxY = y1 end
			end

			for obj, imgRec in pairs(State.Images) do
				if imgRec.Container == container and obj.Parent and obj.Visible and obj.AbsoluteSize.X >= 1 and obj.AbsoluteSize.Y >= 1 then
					local p, s = obj.AbsolutePosition, obj.AbsoluteSize
					add(p.X, p.Y, p.X + s.X, p.Y + s.Y)
				end
			end

			for obj in pairs(State.Texts) do
				if obj.Parent and obj.Visible and obj.Text ~= "" and obj:IsDescendantOf(container) then
					local p, s, tb = obj.AbsolutePosition, obj.AbsoluteSize, obj.TextBounds
					local tw = math.min(tb.X, s.X)
					local th = math.min(tb.Y, s.Y)
					local x0
					if obj.TextXAlignment == Enum.TextXAlignment.Left then
						x0 = p.X
					elseif obj.TextXAlignment == Enum.TextXAlignment.Right then
						x0 = p.X + s.X - tw
					else
						x0 = p.X + (s.X - tw) / 2
					end
					local y0
					if obj.TextYAlignment == Enum.TextYAlignment.Top then
						y0 = p.Y
					elseif obj.TextYAlignment == Enum.TextYAlignment.Bottom then
						y0 = p.Y + s.Y - th
					else
						y0 = p.Y + (s.Y - th) / 2
					end
					add(x0, y0, x0 + tw, y0 + th)
				end
			end

			if minX == math.huge then
				return nil
			end
			return minX, minY, maxX, maxY
		end

		local function updateSweep(container, rec)
			if not container.Visible then
				return
			end
			local cp, cs = container.AbsolutePosition, container.AbsoluteSize
			if cs.X < 4 or cs.Y < 4 then
				return
			end

			-- co viền lại: chỉ ôm coin + chữ, không kéo dài hết khung
			local x0, y0, x1, y1 = cp.X, cp.Y, cp.X + cs.X, cp.Y + cs.Y
			local bx0, by0, bx1, by1 = contentBounds(container)
			if bx0 then
				x0 = math.max(x0, bx0 - PAD_X)
				x1 = math.min(x1, bx1 + PAD_X)
				if HUG_HEIGHT then
					y0 = math.max(y0, by0 - PAD_Y)
					y1 = math.min(y1, by1 + PAD_Y)
				end
			end
			local k = getUiScale(container)
			if k <= 0 then
				k = 1
			end
			local holder = rec.Holder
			if holder then
				holder.Position = UDim2.fromOffset((x0 - cp.X) / k, (y0 - cp.Y) / k)
				holder.Size = UDim2.fromOffset((x1 - x0) / k, (y1 - y0) / k)
				holder.Visible = bx0 ~= nil -- chỉ hiện khi đã ôm đúng coin + chữ, không bao giờ hiện khung to
			end

			local w, h = x1 - x0, y1 - y0
			if w < 4 or h < 4 then
				return
			end

			local perimeter = 2 * (w + h)
			local s = ((os.clock() - rec.T0) / SWEEP_TIME % 1) * perimeter
			local hw = STREAK_FRAC * perimeter / 2

			for i, e in ipairs(rec.Edges) do
				local len, start
				if i == 1 then
					len, start = w, 0
				elseif i == 2 then
					len, start = h, w
				elseif i == 3 then
					len, start = w, w + h
				else
					len, start = h, 2 * w + h
				end

				-- chọn bản sao (vòng quanh) gần giữa cạnh nhất
				local a = s - start
				local best = a
				if math.abs(a + perimeter - len / 2) < math.abs(best - len / 2) then
					best = a + perimeter
				end
				if math.abs(a - perimeter - len / 2) < math.abs(best - len / 2) then
					best = a - perimeter
				end

				local u = best / len
				if e.Reverse then
					u = 1 - u
				end
				local seq = buildSeq(u, hw / len)
				for _, g in ipairs(e.Gradients) do
					g.Transparency = seq
				end
			end
		end

		-- khung có đang HIỆN thật sự không (nền không trong suốt, mọi cha đều hiện)
		local function isShown(gui)
			if gui.BackgroundTransparency >= 0.99 then
				return false
			end
			local size = gui.AbsoluteSize
			if size.X < 4 or size.Y < 4 then
				return false
			end
			local p = gui
			while p do
				if p:IsA("GuiObject") then
					if not p.Visible then
						return false
					end
				elseif p:IsA("LayerCollector") then
					if not p.Enabled then
						return false
					end
				end
				p = p.Parent
			end
			return true
		end

		local function ensureRender()
			if State.RenderConn or not State.Active then
				return
			end
			local nextShowCheck = 0
			State.RenderConn = RunService.RenderStepped:Connect(function()
				-- khung ẩn / trong suốt / bị xoá -> vứt viền
				for container, rec in pairs(State.Frames) do
					if not container.Parent or not isShown(container) then
						State.Frames[container] = nil
						destroyFrameFx(rec)
					else
						updateSweep(container, rec)
					end
				end

				-- khung vừa hiện lại -> bao viền (kiểm tra 5 lần/giây cho nhẹ)
				local now = os.clock()
				if now >= nextShowCheck then
					nextShowCheck = now
					for _, imgRec in pairs(State.Images) do
						local c = imgRec.Container
						if c and not State.Frames[c] and c.Parent and isShown(c) then
							local ok = pcall(function()
								local rec = { Holder = nil, BaseStroke = nil, Edges = {}, T0 = os.clock() }
								State.Frames[c] = rec
								buildFrameFx(c, rec)
								updateSweep(c, rec) -- co ngay lập tức
							end)
							if not ok then
								State.Frames[c] = nil
							end
						end
					end
				end
			end)
		end

		local function ensureFrameFx(container)
			local rec = State.Frames[container]
			if not rec then
				rec = { Holder = nil, BaseStroke = nil, Edges = {}, T0 = os.clock() }
				State.Frames[container] = rec
				buildFrameFx(container, rec)
				pcall(updateSweep, container, rec) -- co ngay lập tức
			elseif not rec.Holder or rec.Holder.Parent ~= container or not rec.BaseStroke or rec.BaseStroke.Parent ~= rec.Holder then
				-- bị game xoá -> tạo lại
				buildFrameFx(container, rec)
				pcall(updateSweep, container, rec) -- co ngay lập tức
			end
			ensureRender()
		end

		local function releaseFrame(container, rec)
			destroyFrameFx(rec)
			State.Frames[container] = nil
		end

		-- ---------- tìm KHUNG chứa đồng xu ----------
		local function isHuge(gui)
			local cam = workspace.CurrentCamera
			if not cam then
				return false
			end
			local vp = cam.ViewportSize
			local s = gui.AbsoluteSize
			return s.X > vp.X * 0.6 and s.Y > vp.Y * 0.6
		end

		-- khung gần nhất bao ảnh coin và có nền thật (BackgroundTransparency < 1)
		local function findContainer(img)
			local cur = img.Parent
			while cur and cur:IsA("GuiObject") do
				if cur.BackgroundTransparency < 0.99 and not isHuge(cur) then
					return cur
				end
				cur = cur.Parent
			end
			return nil
		end

		-- ---------- ảnh đồng xu (chỉ đổi ID, không xoay) ----------
		local function releaseImage(obj, rec, restore)
			for _, c in ipairs(rec.Conns) do
				c:Disconnect()
			end
			rec.Conns = {}
			State.Images[obj] = nil
		end

		local function trackImage(obj)
			local rec = State.Images[obj]
			if not rec then
				-- giữ nguyên icon gốc, chỉ theo dõi để biết khung chứa coin
				rec = { Conns = {} }
				State.Images[obj] = rec
				table.insert(
					rec.Conns,
					obj.AncestryChanged:Connect(function()
						if not obj:IsDescendantOf(game) then
							releaseImage(obj, rec, false)
						end
					end)
				)
			end

			-- khung chứa (viền chỉ được vẽ khi khung này đang hiện)
			rec.Container = findContainer(obj)
			if rec.Container and isShown(rec.Container) then
				ensureFrameFx(rec.Container)
			end
			ensureRender()
		end

		-- ---------- chữ coins ----------
		local function releaseText(obj, rec, restore)
			if rec.Stroke then
				pcall(function()
					rec.Stroke:Destroy()
				end)
			end
			if restore and obj.Parent then
				pcall(function()
					obj.TextColor3 = rec.OrigColor
				end)
			end
			State.Texts[obj] = nil
		end

		local function trackText(obj)
			local rec = State.Texts[obj]
			if not rec then
				rec = { OrigColor = obj.TextColor3, Stroke = nil }
				State.Texts[obj] = rec
			end
			if obj.TextColor3 ~= WHITE then
				obj.TextColor3 = WHITE
			end
			if not obj:FindFirstChild("TextBlackStroke") then
				local tStroke = Instance.new("UIStroke")
				tStroke.Name = "TextBlackStroke"
				tStroke.Thickness = 2
				tStroke.Color = Color3.fromRGB(0, 0, 0)
				tStroke.Parent = obj
				rec.Stroke = tStroke
			end
		end

		-- ---------- xử lý + quét ----------
		local function process(obj)
			if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
				if State.Images[obj] or obj.Name == "CoinImage" or string.find(obj.Image, OLD_DECAL_ID, 1, true) then
					trackImage(obj)
				end
			elseif obj:IsA("TextLabel") and (obj.Name == "Blank" or obj.Name == "Coins") then
				trackText(obj)
			end
		end

		local function scan(PlayerGui)
			local n = 0
			for _, obj in ipairs(PlayerGui:GetDescendants()) do
				if not State.Active then
					return
				end
				pcall(process, obj)
				n = n + 1
				if n % 400 == 0 then
					task.wait() -- chia nhỏ để không giật
				end
			end

			-- dọn các coin / khung đã biến mất khỏi PlayerGui
			for obj, rec in pairs(State.Images) do
				if not obj:IsDescendantOf(PlayerGui) then
					pcall(releaseImage, obj, rec, false)
				end
			end
			for obj, rec in pairs(State.Texts) do
				if not obj:IsDescendantOf(PlayerGui) then
					pcall(releaseText, obj, rec, false)
				end
			end
			local used = {}
			for _, imgRec in pairs(State.Images) do
				if imgRec.Container then
					used[imgRec.Container] = true
				end
			end
			for container, rec in pairs(State.Frames) do
				if not used[container] or not container:IsDescendantOf(PlayerGui) then
					pcall(releaseFrame, container, rec)
				end
			end
		end

		-- ---------- trả UI về như cũ khi unload ----------
		local function cleanup()
			if State.Cleaned then
				return
			end
			State.Cleaned = true
			State.Active = false
			if State.AddedConn then
				State.AddedConn:Disconnect()
				State.AddedConn = nil
			end
			if State.RenderConn then
				State.RenderConn:Disconnect()
				State.RenderConn = nil
			end
			for container, rec in pairs(State.Frames) do
				pcall(releaseFrame, container, rec)
			end
			for obj, rec in pairs(State.Images) do
				pcall(releaseImage, obj, rec, true)
			end
			for obj, rec in pairs(State.Texts) do
				pcall(releaseText, obj, rec, true)
			end
			if State.Thread then
				pcall(task.cancel, State.Thread)
				State.Thread = nil
			end
		end
		pcall(function()
			lib:OnUnload(cleanup)
		end)

		-- ---------- chạy ngay + lặp lại mỗi 3s ----------
		State.Thread = task.spawn(function()
			local PlayerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
			if not State.Active then
				return
			end

			-- UI coin mới xuất hiện thì xử lý ngay (defer để game kịp gán thuộc tính)
			State.AddedConn = PlayerGui.DescendantAdded:Connect(function(obj)
				if State.Active then
					pcall(process, obj)
					task.defer(function()
						if State.Active and obj.Parent then
							pcall(process, obj)
						end
					end)
				end
			end)

			while State.Active do
				pcall(scan, PlayerGui)
				task.wait(REAPPLY_INTERVAL)
			end
		end)
	end

	lib:OnUnload(function()
