sources.BlitzToys = [====[
local requireModule = ...

-- Blitz Toys: Wings / Spider Legs (mang tu Blitz sang Resonance)
-- Moi setting chi hien khi bat toggle chinh cua tinh nang do.
local BLITZ_CODE = [=====[
--[[ ===== Resonance <-> Blitz bridge (chay trong env rieng, khong dung global cua Resonance) ===== ]]
local ctx = __ctx
local L12 = ctx.tbl12
local L11 = ctx.tbl11

