-- _G rieng cho code Blitz: cac gia tri dong lay tu Resonance
local realG = (getgenv and getgenv()) or _G
local plotCache, plotAt = nil, 0
local function getOwnedPlot()
	local now = os.clock()
	if now - plotAt > 0.25 then
		plotAt = now
		local ok, r = pcall(L12.OwnedPlot, LocalPlayer)
		plotCache = ok and r or nil
	end
	return plotCache
end
local DYNAMIC = { UniversalPlayerRoot = true, UniversalPlayerHumanoid = true, UniverChar = true, PlotPlayerIsOwner = true, BrokenBarrier = true }
_G = setmetatable({}, {
	__index = function(_, k)
		if k == "UniversalPlayerRoot" then
			local _, root = L12.Char()
			return root
		elseif k == "UniversalPlayerHumanoid" then
			local _, _, hum = L12.Char()
			return hum
		elseif k == "UniverChar" then
			local char = L12.Char()
			return char
		elseif k == "PlotPlayerIsOwner" then
			return getOwnedPlot()
		elseif k == "BrokenBarrier" then
			return ctx.tbl9 and ctx.tbl9.IsBarrierBroken == true or false
		end
		return realG[k]
	end,
	__newindex = function(t, k, v)
		if DYNAMIC[k] then return end
		rawset(t, k, v)
	end,
})

-- Ham phu
GetPlayerCFrame = function()
	local _, root = L12.Char()
	return root and root.CFrame
end

TeleportPlayer = function(cf)
	if typeof(cf) == "Instance" and cf:IsA("BasePart") then cf = cf.CFrame end
	if typeof(cf) ~= "CFrame" then return end
	local _, root = L12.Char()
	if root then L12.Teleport(root, cf) end
end

local spawnStamp = 0
SpawnToy = function(args)
	local name = type(args) == "table" and args[1]
	if type(name) ~= "string" then return end
	if os.clock() - spawnStamp < 0.15 then return end
	spawnStamp = os.clock()
	task.spawn(function()
		L12.SpawnToy(name, args[2], 0, true)
	end)
end

RemovingPlotFlag = false
RemovePlotOwner = function()
	-- chi 1 luong xoa plot tai 1 thoi diem; luong den sau doi luong truoc xong roi thoat
	if RemovingPlotFlag then
		while RemovingPlotFlag do task.wait() end
		return
	end
	local owned = _G.PlotPlayerIsOwner
	if not owned then return end
	local plot = W.Plots:FindFirstChild(tostring(owned))
	if not plot then return end
	RemovingPlotFlag = true
	pcall(function()
		for _, child in pairs(plot.PlotSign:GetChildren()) do
			if not _G.PlotPlayerIsOwner then break end
			if child.Name == "Sign" then
				local MinusGrabPart = child.Minus.MinusGrabPart
				TeleportPlayer(MinusGrabPart.CFrame * CFrame.new(-5, 0, -5), 3)
				for i = 0, 15 do
					SNOWship(MinusGrabPart)
					task.wait()
				end
			end
		end
	end)
	RemovingPlotFlag = false
end

ClaimEmptyPlot = function()
	if _G.PlotPlayerIsOwner then return end
	local emptyPlot
	for _, child in pairs(workspace.Plots:GetChildren()) do
		for _, child2 in pairs(child:GetChildren()) do
			if child2.Name == "PlotSign" and not child2.ThisPlotsOwners:FindFirstChild("Value") then
				emptyPlot = child
			end
		end
	end
	if not emptyPlot then return end
	local PlotSign = emptyPlot.PlotSign
	for _, child in pairs(PlotSign:GetChildren()) do
		if _G.PlotPlayerIsOwner then break end
		if child.Name == "Sign" then
			local PlusGrabPart = child.Plus.PlusGrabPart
			TeleportPlayer(PlusGrabPart.CFrame * CFrame.new(-5, 0, -5), 3)
			for i = 0, 15 do
				SNOWship(PlusGrabPart)
				task.wait()
			end
		end
	end
end

--[[ ===== Helper goc tu Blitz (giu nguyen) ===== ]]

local function geniter(f, s, c)
	if type(f) ~= "function" then
		local mt = getmetatable(f)

		if type(mt) == "table" and mt.__iter then
			f, s, c = mt.__iter(f)
		elseif type(f) == "table" then
			f, s, c = next, f, nil
		end
	end

	return function()
		local r = table.pack(f(s, c))

		if r[1] == nil then
			return false
		end

		c = r[1]

		return true, table.unpack(r, 1, r.n)
	end
end
SFcQ = function(param24)
	if typeof(param24) == "Instance" then
		for _, child in pairs(param24:GetChildren()) do
			if child:IsA("BasePart") and child.CanQuery then
