do
	SNOWship = function(param130)
		if param130 and typeof(param130) == "Instance" then
			local value94 = LocalPlayer:DistanceFromCharacter(param130.Position)

			if LocalPlayer.Character then
				if LocalPlayer.Character:FindFirstChild("HumanoidRootPart") and value94 <= 30 then
					value42:FireServer(param130, lookAt(LocalPlayer.Character.HumanoidRootPart.Position, param130.Position))
				end
			end
		end
	end
end
do
	SNOWshipOnce = function(param134)
		if typeof(param134) ~= "Instance" then
			return
		end

		local value95 = LocalPlayer:DistanceFromCharacter(param134.Position)

		if LocalPlayer.Character then
			if LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
				if CheckNetworkOwnerShipOnPart(param134) then
					return true
				end

				if value95 <= 30 then
					value42:FireServer(param134, lookAt(LocalPlayer.Character.HumanoidRootPart.Position, param134.Position))
				end
			end
		end
	end
end
do
	Getdistancefromcharacter = function(param154)
		return LocalPlayer:DistanceFromCharacter(param154)
	end
end
GroupCollisionData = {}
SetCollisionObjectOff = function(param417)
	if not param417:IsA("Model") or param417:GetAttribute("ObjectCollisions") then
		return
	end

	local function value395(param418)
		local temp56 = {}

		for _, descendant in ipairs(param418:GetDescendants()) do
			if descendant:IsA("BasePart") then
				table.insert(temp56, descendant)
			end
		end

		return temp56
	end

	param417:SetAttribute("ObjectCollisions", true)

	local temp57 = {}
	local temp58 = {}
	local value396 = value395(param417)

	local function value397(param419)
		if temp57[param419] ~= nil then
			return
		end

		temp57[param419] = param419.CanCollide
		param419.CanCollide = false

		local connection = param419:GetPropertyChangedSignal("CanCollide"):Connect(function()
			if param419.CanCollide then
				param419.CanCollide = false
			end
		end)

		table.insert(temp58, connection)
	end

	for _, v in ipairs(value396) do
		value397(v)
	end

	table.insert(temp58, param417.DescendantAdded:Connect(function(descendant)
		if descendant:IsA("BasePart") then
			value397(descendant)
		end
	end))
	table.insert(GroupCollisionData, {
		Model = param417,
		OldValues = temp57,
		Connections = temp58
	})

	local connection

	connection = param417.Destroying:Connect(function()
		for _, v in ipairs(temp58) do
			v:Disconnect()
		end

		for i, v in ipairs(GroupCollisionData) do
			if v.Model == param417 then
				table.remove(GroupCollisionData, i)
			end
		end

		connection:Disconnect()
	end)
	table.insert(temp58, connection)
end
SetCollisionObjectOn = function(param420)
	if not param420:IsA("Model") or not param420:GetAttribute("ObjectCollisions") then
		return
	end

	for i, v in ipairs(GroupCollisionData) do
		if v.Model == param420 then
			for _, connection in ipairs(v.Connections) do
				connection:Disconnect()
			end

			for k, oldValue in pairs(v.OldValues) do
				if k and k.Parent then
					k.CanCollide = oldValue
				end
			end

			param420:SetAttribute("ObjectCollisions", false)
			table.remove(GroupCollisionData, i)

			return
		end
	end
end

--[[ ===== ToyKit: giu toy tren cao (moi toy cach 5 stud), check barrier, tra plot ===== ]]
ToyKit = {
	STEP = 5,       -- khoang cach giua 2 toy (studs)
	HEIGHT = 300,   -- do cao toy dau tien so voi plot/mat dat (studs)
	slots = {},
	pool = {},
	origin = nil,
	releasing = false,
	MAIN = { PalletLightBrown = "SoundPart", LadderLightBrown = "SoundPart", FireworkSparkler = "Stick" },
}

ToyKit.SlotPos = function(k)
	if not ToyKit.origin then
		local _, root = L12.Char()
		local base = root and root.Position or Vector3.zero
		local owned = _G.PlotPlayerIsOwner
		local plot = owned and W.Plots:FindFirstChild(tostring(owned))
		local area = plot and plot:FindFirstChild("PlotArea")
		if area then base = area.Position end
		ToyKit.origin = Vector3.new(base.X, base.Y + ToyKit.HEIGHT, base.Z)
	end
	return ToyKit.origin + Vector3.new(0, ToyKit.STEP * (k - 1), 0)
end

ToyKit.AllocSlot = function()
	local k = 1
	while ToyKit.slots[k] do k += 1 end
	ToyKit.slots[k] = true
	return k, ToyKit.SlotPos(k)
end

ToyKit.FreeSlot = function(k)
	if not k then return end
	ToyKit.slots[k] = nil
	if next(ToyKit.slots) == nil then ToyKit.origin = nil end
end

-- ===== vi tri spawn an toan: luon cach rim plot >= EDGE stud, dung o vi tri hop ly =====
ToyKit.EDGE = 10                 -- khoang cach toi thieu tu rim plot (studs)
ToyKit.STAND = Vector3.zero      -- vi tri dung (plot space, lech so voi tam), bi kep vao vung an toan
ToyKit.lastSpot = nil

ToyKit.GetArea = function()
	local owned = _G.PlotPlayerIsOwner
	local plot = owned and W.Plots:FindFirstChild(tostring(owned))
	return plot and plot:FindFirstChild("PlotArea")
end

ToyKit.Limits = function(area)
	return math.max(0, area.Size.X / 2 - ToyKit.EDGE), math.max(0, area.Size.Z / 2 - ToyKit.EDGE)
end

-- random = false: cho dung chinh (tam vung an toan); random = true: cho khac de doi cho (van cach rim >= EDGE)
ToyKit.SafeSpot = function(random)
	local area = ToyKit.GetArea()
	if not area then return nil end
	local hx, hz = ToyKit.Limits(area)
	local x, z
	if random and (hx > 0 or hz > 0) then
		for _ = 1, 8 do
			x, z = (math.random() * 2 - 1) * hx, (math.random() * 2 - 1) * hz
			if not ToyKit.lastSpot or (Vector3.new(x, 0, z) - ToyKit.lastSpot).Magnitude >= math.min(hx, hz) * 0.5 then break end
		end
		ToyKit.lastSpot = Vector3.new(x, 0, z)
	else
		x = math.clamp(ToyKit.STAND.X, -hx, hx)
		z = math.clamp(ToyKit.STAND.Z, -hz, hz)
	end
	return area.CFrame * CFrame.new(x, 0, z) + Vector3.new(0, -5, 0)
end

ToyKit.StandOK = function(root)
	local area = ToyKit.GetArea()
	if not area then return true end
	if not root then
		local _, r = L12.Char()
		root = r
	end
	if not root then return true end
	local rel = area.CFrame:PointToObjectSpace(root.Position)
	local hx, hz = ToyKit.Limits(area)
	return math.abs(rel.X) <= hx + 1 and math.abs(rel.Z) <= hz + 1
end

-- dang dung gan rim (hoac ngoai plot) thi dua ve cho dung an toan truoc khi spawn
ToyKit.EnsureStanding = function() end -- da tat: khong TP luc spawn (toy duoc keo len troi bang ToyKit.Hold, SpawnCF tu kep vao plot)

-- vi tri spawn toy: tren dau nguoi choi 6 stud, nhung luon kep vao vung cach rim >= EDGE
ToyKit.SpawnCF = function(r)
	-- spawn ngay tai cho dang dung (diem nhan plot), khong kep/dich vao cho khac
	return CFrame.new(r.Position + Vector3.new(0, 6, 0))
end

-- lay network owner, tat collision, dua toy len cao (slot rieng, cach nhau STEP stud) va giu bang AlignPosition
ToyKit.Hold = function(toy, owner, measure)
	local mainName = ToyKit.MAIN[toy.Name] or "SoundPart"
	local main, t0 = nil, os.clock()
	repeat main = toy:FindFirstChild(mainName) task.wait() until main or os.clock() - t0 > 1.5
	if not main then return nil end
	for _ = 1, 30 do
		if SNOWshipOnce(main) then break end
		task.wait(0.03)
	end
	if not CheckNetworkOwnerShipOnPart(main) then return nil end
	SetCollisionObjectOff(toy)
	toy:SetAttribute("Connected1", true)
	local info = measure and measure(toy, main) or nil
	local slot, pos = ToyKit.AllocSlot()
	local at = Instance.new("Attachment", main)
	at.Name = "ToyKitAt"
	local ap = Instance.new("AlignPosition", main)
	ap.Name = "ToyKitHold"
	ap.Mode = Enum.PositionAlignmentMode.OneAttachment
	ap.Attachment0 = at
	ap.ApplyAtCenterOfMass = true
	ap.MaxForce = math.huge
	ap.MaxVelocity = math.huge
	ap.Responsiveness = 200
	ap.Position = pos
	pcall(function() main.CFrame = CFrame.new(pos) end)
	return { toy = toy, main = main, at = at, ap = ap, slot = slot, owner = owner, info = info }
end

ToyKit.Count = function(owner, name)
	local n = 0
	for _, e in ipairs(ToyKit.pool) do
		if e.owner == owner and e.toy.Name == name and e.toy.Parent then n += 1 end
	end
	return n
end

ToyKit.CountParts = function(parts)
	local n = 0
	for _, v in pairs(parts) do
		local part = v.part
		if typeof(part) == "Instance" and part:IsA("BasePart") and part:FindFirstChild("Attachment") then n += 1 end
	end
	return n
end

-- spawn du `need` toy, moi toy spawn xong la dua len cao ngay. Chi tra true khi DU toy.
ToyKit.Fill = function(owner, name, need, alive, prep)
	if need <= 0 then return true end
	if not ctx.Extras.EnsureBarrier(alive) then return false end
	local have = ToyKit.Count(owner, name)
	local ownFail, nilSince = 0, nil
	while alive() and have < need and ownFail < 8 do
		if prep then pcall(prep) end
		local _, r = L12.Char()
		if not r then
			task.wait(0.2)
			continue
		end
		ToyKit.EnsureStanding()
		local _, r2 = L12.Char()
		local toy = L12.SpawnToy(name, ToyKit.SpawnCF(r2 or r), 0, true)
		if toy then
			nilSince = nil
			local e = alive() and ToyKit.Hold(toy, owner) or nil
			if e then
				ownFail = 0
				have += 1
				table.insert(ToyKit.pool, e)
			else
				if alive() then ownFail += 1 end
				pcall(function() DeleteToyRE:FireServer(toy) end)
				task.wait(0.15)
			end
		else
			-- spawn nil lien tuc > 8s: het slot / plot day
			nilSince = nilSince or os.clock()
			if os.clock() - nilSince > 8 then break end
			task.wait(0.2)
		end
	end
	if not alive() then
		ToyKit.ClearOwner(owner)
		return false
	end
	return have >= need
end

-- lay 1 toy da dua len cao ra dung (dua ve gan nguoi choi de tinh nang nay gan vao rig)
ToyKit.Take = function(owner, name)
	local i = 1
	while i <= #ToyKit.pool do
		local e = ToyKit.pool[i]
		if e.owner == owner and e.toy.Name == name then
			table.remove(ToyKit.pool, i)
			ToyKit.FreeSlot(e.slot)
			pcall(function() e.ap:Destroy() e.at:Destroy() end)
			if e.toy.Parent and e.main.Parent then
				local _, r = L12.Char()
				if r then pcall(function() e.main.CFrame = CFrame.new(r.Position + Vector3.new(0, 5, 0)) end) end
				return e.toy
			end
		else
			i += 1
		end
	end
end

-- xoa toy dang giu tren cao cua 1 tinh nang (prefix = true: khop theo tien to, vd moi session)
ToyKit.ClearOwner = function(owner, prefix)
	for i = #ToyKit.pool, 1, -1 do
		local e = ToyKit.pool[i]
		local match = e.owner == owner or (prefix and string.sub(e.owner, 1, #owner) == owner)
		if match then
			table.remove(ToyKit.pool, i)
			ToyKit.FreeSlot(e.slot)
			pcall(function() e.ap:Destroy() e.at:Destroy() end)
			if e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
		end
	end
end

-- Tat tinh nang -> xoa plot NGAY (neu khong con tinh nang nao khac dang dung plot)
ctx.Extras.ReleaseNow = function()
	if ctx.Extras.ActiveCount() > 0 then return end
	if ToyKit.releasing then return end
	if not _G.PlotPlayerIsOwner then return end
	ToyKit.releasing = true
	local home = GetPlayerCFrame()
	if value36 and value36.Value then
		home = CFrame.new(W.SpawnLocation.Position + Vector3.new(0, 5, 0))
	end
	pcall(RemovePlotOwner)
	if home then pcall(TeleportPlayer, home) end
	ToyKit.releasing = false
end

-- Tat do restart (Set(false) roi Set(true)): doi 1.5s, neu khong bat lai thi moi xoa plot
ctx.Extras.ReleaseLater = function()
	task.delay(1.5, function()
		if ctx.Extras.ActiveCount() == 0 then ctx.Extras.ReleaseNow() end
	end)
end

--[[ ===== Mech / Wings / Spider Legs (tu Blitz) ===== ]]
leftWing = nil
rightWing = nil
wings_partsTable = {}
wingsDistance = 10

local RunService2 = game:GetService("RunService")
local number28 = 0.5
local number29 = 0.07
local number30 = 25
local number31 = 25

wingsFollowMovement = false

local temp62 = {
	phase = 0,
	freq = 0.5,
	amp = 10,
	center = 15,
	flapping = false,
	cFreq = 1,
	cAmp = 30,
	cCenter = 8,
	showParts = false,
	segSpacing = 8,
	toyRotation = CFrame.identity
}

do
	local function value454(param458)
		local value455 = param458 % 1
		local value456

		if value455 < number28 then
			value456 = 0.5 * value455 / number28
		else
			value456 = 0.5 + 0.5 * (value455 - number28) / (1 - number28)
		end

		return math.cos(value456 * 2 * math.pi), math.sin(value456 * 2 * math.pi)
	end
	local function value457(param459, param460)
		local AssemblyLinearVelocity = param459.AssemblyLinearVelocity
		local Magnitude = Vector3.new(AssemblyLinearVelocity.X, 0, AssemblyLinearVelocity.Z).Magnitude
		local number32, number33, number34

		if not temp62.flapping then
			number32 = 0.3
			number33 = 0
			number34 = 15
		elseif not wingsFollowMovement then
			number32 = temp62.cFreq
			number33 = temp62.cAmp
			number34 = temp62.cCenter
		elseif AssemblyLinearVelocity.Y < -15 then
			number32 = 0.35
			number33 = 6
			number34 = 3
		elseif AssemblyLinearVelocity.Y > 6 then
			number32 = 2.4
			number33 = 60
			number34 = 8
		elseif Magnitude > 2 then
			local value458 = math.clamp(Magnitude / 40, 0, 1)

			number32 = 0.9 + 1.2 * value458
			number33 = 30 + 25 * value458
			number34 = 10 - 6 * value458
		else
			number32 = 0.45
			number33 = 8
			number34 = 18
		end

		local value459 = 1 - math.exp(-3 * param460)

		temp62.freq += (number32 - temp62.freq) * value459
		temp62.amp += (number33 - temp62.amp) * value459
		temp62.center += (number34 - temp62.center) * value459
		temp62.phase = (temp62.phase + temp62.freq * param460) % 1
	end
	local function value460(param461, param462, param463)
		local cFrame = param461 * CFrame.new(param463 * 2, 1.5, 0.5)

		param462.CFrame = cFrame
		param462.AssemblyLinearVelocity = Vector3.zero

		local temp63 = {}

		for _, v in ipairs(wings_partsTable) do
			if v.dir == param463 then
				table.insert(temp63, v)
			end
		end

		local value461 = temp62.amp / 60
		local number35 = 0
		local number36 = 0

		for i, v in ipairs(temp63) do
			local part = v.part

			if part.Parent then
				local value462, value463 = value454(temp62.phase - (i - 1) * number29)
				local value464 = (i - 1) / math.max(#temp63 - 1, 1)
				local value465 = temp62.center + value462 * temp62.amp * (1 + 0.15 * value464)
				local value466 = math.max(0, -value463) * number31 * (0.4 + 0.6 * value464) * value461
				local value467 = -value463 * number30 * (0.3 + 0.7 * value464) * value461
				local offset = v.offset

				if i == 1 then
					offset += wingsDistance - 2
				end

				cFrame = cFrame * CFrame.Angles(0, -param463 * math.rad(value466 - number36), param463 * math.rad(value465 - number35)) * CFrame.new(param463 * offset, 0, 0)
				number35 = value465
				number36 = value466
				part.CFrame = cFrame * CFrame.Angles(math.rad(value467), 0, 0) * CFrame.Angles(math.pi, 0, 0)
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
			end
		end
	end

	createWings = function()
		if leftWing and rightWing then
			return
		end

		local function createPart()
			local Part_ = Instance.new("Part")

			Part_.Size = Vector3.new(1, 1, 1)
			Part_.Anchored = false
			Part_.CanQuery = false
			Part_.CanCollide = false
			Part_.CanTouch = false
			Part_.Massless = true
			Part_.Material = Enum.Material.Neon
			Part_.Color = Color3.fromRGB(0, 170, 255)
			Part_.Transparency = temp62.showParts and 0.3 or 1

			local Attachment = Instance.new("Attachment", Part_)

			Attachment.Name = "Attachment"
			Attachment.CFrame = temp62.toyRotation

			local BodyVelocity = Instance.new("BodyVelocity", Part_)

			BodyVelocity.Velocity = Vector3.zero
			BodyVelocity.MaxForce = Vector3.new(100000, 100000, 100000)
			BodyVelocity.P = 1250
			Part_.Parent = workspace

			return Part_
		end

		leftWing = createPart()
		rightWing = createPart()

		for _, v in ipairs({
			1,
			-1
		}) do
			for i = 0, 5 do
				table.insert(wings_partsTable, {
					part = createPart(),
					offset = i + temp62.segSpacing,
					dir = v
				})
			end
		end

		flapWingsC2 = RunService2.Heartbeat:Connect(function(dt)
			if not leftWing or not rightWing then
				flapWingsC2:Disconnect()
				flapWingsC2 = nil

				return
			end

			if not _G.UniversalPlayerRoot then
				return
			end

			value457(_G.UniversalPlayerRoot, dt)

			local CFrame_ = _G.UniversalPlayerRoot.CFrame

			value460(CFrame_, rightWing, 1)
			value460(CFrame_, leftWing, -1)
		end)
	end
end

do
	flapWings = function()
		temp62.flapping = temp62.debugFlap ~= false
	end
end

do
	destroyWings = function()
		if flapWingsC then
			flapWingsC:Disconnect()
			flapWingsC = nil
		end

		if flapWingsC2 then
			flapWingsC2:Disconnect()
			flapWingsC2 = nil
		end

		temp62.flapping = false

		if leftWing then
			leftWing:Destroy()
			leftWing = nil
		end

		if rightWing then
