			rightWing = nil
		end

		for _, v in pairs(wings_partsTable) do
			if v.part then
				v.part:Destroy()
			end

			if v.gyro then
				v.gyro:Destroy()
			end
		end

		table.clear(wings_partsTable)
	end
end

