-- ===== 666 Star: FireworkSparkler xep tam tron o giua + tia ban tu tam ra xa 360 do =====
do
	local S = { radius = 10, height = 15, spin = 3, rayMax = 1000, raySpeed = 4, power = 200, cap = 100, rayPct = 70, flat = true, release = false, tpEvery = 5 }
	local toys, session, running, conn, homeCF, busy = {}, 0, false, nil, nil, false
	local rp = RaycastParams.new()
	rp.FilterType = Enum.RaycastFilterType.Exclude

	local function clearToys(del)
		if conn then conn:Disconnect() conn = nil end
		for _, v in ipairs(toys) do
			pcall(function() v.ap:Destroy() end)
			ToyKit.FreeSlot(v.slot)
			if del and v.toy.Parent then pcall(function() DeleteToyRE:FireServer(v.toy) end) end
		end
		table.clear(toys)
	end

	-- lay network owner + gan AlignPosition (giong Wings)
	-- lay owner + dua len cao (moi toy 1 slot, cach nhau 5 stud) cho den khi du toy moi xep hinh
	local function adopt(toy)
		local h = ToyKit.Hold(toy, "star")
		if not h then return false end
		h.ap.Responsiveness = S.power
		table.insert(toys, h)
		return true
	end

	local function formation()
		local t0, gy, gt = os.clock(), 0, 0
		conn = RunService.Heartbeat:Connect(function()
			local _, r = L12.Char()
			if not r then return end
			for i = #toys, 1, -1 do
				if not toys[i].main.Parent then table.remove(toys, i) end
			end
			local now = os.clock()
			if now - gt > 0.25 then -- do mat dat (tam la player)
				gt = now
				local ig = { r.Parent }
				for _, v in ipairs(toys) do ig[#ig + 1] = v.toy end
				rp.FilterDescendantsInstances = ig
				local h = W:Raycast(r.Position, Vector3.new(0, -1000, 0), rp)
				gy = h and h.Position.Y or (r.Position.Y - 3)
			end
			local t = now - t0
			local c = Vector3.new(r.Position.X, gy + S.height, r.Position.Z)
			local n = #toys
			local R = S.radius -- ban kinh tam tron
			local nRay = math.floor(n * S.rayPct / 100)
			local nCore = n - nRay
			local nOuter = math.ceil(nCore * 2 / 3) -- vong ngoai cua tam
			local nInner = nCore - nOuter -- vong trong cua tam
			local spin = t * S.spin
			local rot = CFrame.Angles(0, spin, 0)
			local tilt = S.flat and rot or CFrame.Angles(t * 0.9, spin, t * 0.6)
			for i, v in ipairs(toys) do
				local p
				if i <= nCore then -- tam tron (2 vong dong tam)
					v.ph = nil
					local a, rad
					if i <= nOuter then
						a = (i - 1) / nOuter * math.pi * 2
						rad = R
					else
						a = (i - nOuter - 1) / nInner * math.pi * 2
						rad = R * 0.5
					end
					p = c + rot:VectorToWorldSpace(Vector3.new(math.cos(a), 0, math.sin(a)) * rad)
				else -- tia ban tu mep tam ra xa, het tam thi quay lai tam
					local k = i - nCore
					local dir
					if S.flat then
						local a = k / nRay * math.pi * 2
						dir = Vector3.new(math.cos(a), 0, math.sin(a))
					else
						local y = 1 - 2 * (k - 0.5) / nRay
						local rr = math.sqrt(math.max(0, 1 - y * y))
						dir = Vector3.new(math.cos(k * 2.39996) * rr, y, math.sin(k * 2.39996) * rr)
					end
					local ph = (t * S.raySpeed + k * 0.618034) % 1 -- 0 = o tam, 1 = xa nhat
					p = c + tilt:VectorToWorldSpace(dir) * (R + (S.rayMax - R) * ph)
					if v.ph and ph < v.ph then -- vua het vong: dich thang ve tam, khong keo ve
						pcall(function() v.main.CFrame = CFrame.new(p) end)
					end
					v.ph = ph
				end
				v.ap.Position = p
				v.ap.Responsiveness = S.power
			end
		end)
	end

	-- chon vi tri ngau nhien khac trong plot de spawn (tranh chong cheo bi mat)
	local lastSpot
	local function randomPlotSpot() return ToyKit.SafeSpot(true) end -- cach rim >= ToyKit.EDGE

	local function run(token)
		local function ok() return running and token == session end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame
		WingsGoToSafeZone() -- claim plot + TP vao plot
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(0.1) w = w + 1 end
		local fails, own, spawned = 0, 0, 0
		lastSpot = nil
		while ok() and #toys < S.cap and fails < 2 and own < 6 do
			local _, r = L12.Char()
			if not r then break end
			local t = os.clock()
			ToyKit.EnsureStanding()
			local _, r2 = L12.Char()
			local toy = L12.SpawnToy("FireworkSparkler", ToyKit.SpawnCF(r2 or r), 0, true)
			if toy then
				if not adopt(toy) then
					own = own + 1
					pcall(function() DeleteToyRE:FireServer(toy) end)
				else
					spawned = spawned + 1
				end
			elseif os.clock() - t > 1.2 then
				fails = fails + 1 -- spawn that bai that su = het slot
			else
				task.wait(0.2)
			end
		end
		if not ok() then return end
		if #toys < S.cap and ctx.Extras then
			ctx.Extras.Notify("Chi spawn duoc " .. #toys .. "/" .. S.cap .. " toy (plot day / het slot) - xep hinh voi so toy co", "666 Star")
		end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		TeleportPlayer(homeCF) -- ve cho cu
		busy = false
		task.wait(0.3)
		if ok() then formation() end
	end

	Star666Section:AddToggle({
		Name = "666 Star",
		Default = false,
		Callback = function(on)
			session = session + 1
			running = on
			clearToys(true)
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then task.spawn(run, session) end
		end,
	})
	local function sl(name, min, max, def, inc, unit, key)
		Star666Section:AddSlider({ Name = name, Min = min, Max = max, Default = def, Increment = inc, ValueName = unit, Callback = function(v) S[key] = v end })
	end
	sl("Core Radius (tam tron)", 2, 100, S.radius, 1, "studs", "radius")
	sl("Star Height (above ground)", 0, 300, S.height, 1, "studs", "height")
	sl("Spin Speed", 0, 30, S.spin, 0.1, "rad/s", "spin")
	sl("Ray Max Range", 10, 5000, S.rayMax, 10, "studs", "rayMax")
	sl("Ray Speed", 0.1, 40, S.raySpeed, 0.1, "cycles/s", "raySpeed")
	sl("Ray Percent", 0, 95, S.rayPct, 5, "%", "rayPct")
	sl("Power", 10, 200, S.power, 5, "", "power")
	sl("Max Sparklers", 1, 300, S.cap, 1, "toys", "cap")
	Star666Section:AddToggle({ Name = "Flat Rays (360 ngang)", Default = true, Callback = function(v) S.flat = v end })
	Star666Section:AddToggle({ Name = "Release Plot When Done", Default = false, Callback = function(v) S.release = v end })
end


-- ===== WOTW v3: Tripod War of the Worlds =====
-- Than: dia bay rong (nap + mai doc + vanh day + bung doc len + co), lat bang pallet
-- Mat: 7 vong tron do (hinh hoa) tren mai doc phia truoc, vet do doc vanh, 3 den duoi bung (FireworkSparkler)
-- 2 sung duoi bung tu quay quet phia truoc, day cap rung ruc thong xuong
-- Chan: Spider Legs 3 chan, thon dan (doan tren boc giap day -> doan duoi manh), ban chan pallet
do
	local S = { budget = 600, hood = 2, eyeDetail = 1, gunBarrel = 2, gunTip = 1, rim = 3, lights = 3, tentacles = 6, legSegs = 5, legThick = 2, legSpread = 40,
		sweep = 70, gunSpeed = 1.2, tpEvery = 8, power = 200, release = false,
		glow = true, glowPower = 1 }
	local session, running, busy, homeCF = 0, false, false, nil
	local L = { legs = {}, thick = {}, collars = {}, pads = {}, body = {}, eye = {}, guns = {}, tent = {} }
	local follow, bodyConn, saved, curRoot, t0 = {}, nil, nil, nil, 0
	local glows = {}
	local MAIN = { PalletLightBrown = "SoundPart", LadderLightBrown = "SoundPart", FireworkSparkler = "Stick" }
	local UNIT = { Vector3.xAxis, Vector3.yAxis, Vector3.zAxis }
	local BODY_BASE = 2
	local UP = Vector3.yAxis

	local function dimsIdx(size)
		local v = { size.X, size.Y, size.Z }
		local li, ti = 1, 1
		for i = 2, 3 do
			if v[i] > v[li] then li = i end
			if v[i] < v[ti] then ti = i end
		end
		return li, ti, v
	end
	local function axisFix(e, longest) -- truc (nho nhat / dai nhat) cua toy -> Y cua base
		local idx = longest and e.longIdx or e.thinIdx
		if idx == 1 then return CFrame.Angles(0, 0, math.pi / 2) end
		if idx == 3 then return CFrame.Angles(-math.pi / 2, 0, 0) end
		return CFrame.identity
	end
	local function rotYto(idx) -- Y -> truc idx
		if idx == 1 then return CFrame.Angles(0, 0, -math.pi / 2) end
		if idx == 3 then return CFrame.Angles(math.pi / 2, 0, 0) end
		return CFrame.identity
	end
	local function baseCF(pos, up)
		local right = math.abs(up.Y) > 0.99 and Vector3.xAxis or Vector3.yAxis:Cross(up).Unit
		return CFrame.fromMatrix(pos, right, up)
	end

	local function clearAll()
		if bodyConn then bodyConn:Disconnect() bodyConn = nil end
		for _, g in ipairs(glows) do
			pcall(function() g.pl:Destroy() end)
			pcall(function() g.bb:Destroy() end)
		end
		table.clear(glows)
		for _, list in pairs(L) do
			for _, e in ipairs(list) do
				pcall(function() if e.ap then e.ap:Destroy() end end)
				ToyKit.FreeSlot(e.slot)
				if e.toy and e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
			end
			table.clear(list)
		end
		table.clear(follow)
		if saved then
			_G.SpiderLegs = false
			SpiderLegs.session += 1
			pcall(SpiderLegsDestroy)
			for k, v in pairs(saved) do SpiderLegs[k] = v end
			saved = nil
		end
	end

	-- lay owner + do kich thuoc, roi dua len cao (moi toy 1 slot, cach nhau 5 stud) cho den khi du toy moi lap rap
	local function adopt(toy)
		local h = ToyKit.Hold(toy, "wotw", function(t, main)
			local ok, bcf, bsz = pcall(function() return t:GetBoundingBox() end)
			if ok then
				return { mainOff = bcf:ToObjectSpace(main.CFrame), size = bsz }
			end
			return { mainOff = CFrame.identity, size = Vector3.new(1, 4, 1) }
		end)
		if not h then return nil end
		h.ap.Responsiveness = S.power
		local e = h
		e.mainOff, e.size = h.info.mainOff, h.info.size
		e.longIdx, e.thinIdx, e.dims = dimsIdx(e.size)
		return e
	end

	-- ===== hinh hoc dia bay (don vi = T, T la canh pallet) =====
	local function dirK(k)
		local ph = math.rad(-90 + 60 * k) -- k=0 la mat truoc (-Z)
		return Vector3.new(math.cos(ph), 0, math.sin(ph))
	end
	local function profile(A)
		local p = { A = A, aCap = A * 0.45, aN = math.max(0.9, A * 0.35) }
		p.yTop = 0
		p.yRimTop = p.yTop - (A - p.aCap) * math.tan(math.rad(28))
		p.yRimBot = p.yRimTop - 1
		p.yNeckTop = p.yRimBot - (A - p.aN) * math.tan(math.rad(30))
		p.yBot = p.yNeckTop - 1
		p.off = -p.yBot
		p.segs = {
			{ p.aCap, p.yTop, A, p.yRimTop },
			{ A, p.yRimTop, A, p.yRimBot },
			{ A, p.yRimBot, p.aN, p.yNeckTop },
			{ p.aN, p.yNeckTop, p.aN, p.yBot },
		}
		return p
	end
	-- diem + phap tuyen tai ty le f doc doan i (don vi T)
	local function segPoint(p, i, f)
		local s = p.segs[i]
		local da, dy = s[3] - s[1], s[4] - s[2]
		local len = math.sqrt(da * da + dy * dy)
		local ta, tv = da / len, dy / len
		return s[1] + da * f, s[2] + dy * f + p.off, -tv, ta, ta, tv -- a, y, nRad, nVert, tRad, tVert
	end
	local function genBody(T, A)
		local p = profile(A)
		local tiles = {}
		for si, s in ipairs(p.segs) do
			local da, dy = s[3] - s[1], s[4] - s[2]
			local len = math.sqrt(da * da + dy * dy)
			local rows = math.max(1, math.floor(len + 0.35))
			for k = 0, 5 do
				local d = dirK(k)
				local th = Vector3.new(-d.Z, 0, d.X)
				for r = 1, rows do
					local a, y, nr, nv = segPoint(p, si, (r - 0.5) / rows)
					local width = 1.1547 * a
					local cols = math.max(1, math.floor(width + 0.35))
					for c = 1, cols do
						local off = (c - 0.5 - cols / 2) * (width / cols)
						tiles[#tiles + 1] = {
							pos = (d * a + th * off + Vector3.new(0, y, 0)) * T,
							n = (d * nr + UP * nv).Unit,
						}
					end
				end
			end
		end
		local function fill(Ap, y, n)
			for i = -8, 8 do
				for j = -8, 8 do
					local q = Vector3.new(i, 0, j)
					local inside = true
					for k = 0, 5 do
						if math.abs(q:Dot(dirK(k))) > Ap then inside = false break end
					end
					if inside then tiles[#tiles + 1] = { pos = Vector3.new(i * T, y * T, j * T), n = n } end
				end
			end
		end
		fill(p.aCap + 0.15, p.yTop + p.off, UP)
		fill(p.aN - 0.2, p.yBot + p.off, -UP)
		return { list = tiles, p = p }
	end

	-- ===== layout (sau khi biet kich thuoc toy that) =====
	local function layout()
		local T = 6
		for _, e in ipairs(L.body) do
			local v = { e.size.X, e.size.Y, e.size.Z }
			table.sort(v, function(x, y) return x > y end)
			T = math.max(2, v[2])
			break
		end
		local spL, spW = 6, 0.6
		local sp = L.eye[1] or L.guns[1]
		if sp then
			spL = sp.dims[sp.longIdx]
			local v = { sp.size.X, sp.size.Y, sp.size.Z }
			table.sort(v)
			spW = math.max(0.4, v[2])
		end
		local g = genBody(T, S.hood)
		local p = g.p
		local B = Vector3.new(0, BODY_BASE, 0)
		-- vo than
		local idx = 0
		for _, e in ipairs(L.body) do
			local rel
			if e.data and e.data.mount then
				local pv = e.data.pivot
				rel = baseCF(pv + Vector3.new(0, 0.45 * T, 0), UP) * axisFix(e, false)
			else
				idx += 1
				local tl = g.list[idx]
				if tl then rel = baseCF(tl.pos + B, tl.n) * axisFix(e, false) end
			end
			if rel then e.fn = function() return curRoot * rel end end
		end
		-- mat: 7 vong tron do (hinh hoa) tren mai doc phia truoc
		local d0 = dirK(0)
		local a1, y1, nr1, nv1, tr1, tv1 = segPoint(p, 1, 0.5)
		local n1 = (d0 * nr1 + UP * nv1).Unit
		local upslope = -(d0 * tr1 + UP * tv1).Unit
		local c1 = (d0 * a1 + Vector3.new(0, y1, 0)) * T + B
		local gapC, rho = T * 0.62, T * 0.2
		local circ = { Vector2.new(0, 0) }
		for k = 0, 5 do
			local a = k / 6 * math.pi * 2
			circ[#circ + 1] = Vector2.new(math.cos(a), math.sin(a)) * gapC
		end
		-- vet do doc vanh + 3 den duoi bung
		local a2, y2 = segPoint(p, 2, 0.5)
		local a3, y3, nr3, nv3, tr3, tv3 = segPoint(p, 3, 0.5)
		local n3 = (d0 * nr3 + UP * nv3).Unit
		local c3 = (d0 * a3 + Vector3.new(0, y3, 0)) * T + B
		local frontK = { 0, 1, 5, 2, 4 }
		for _, e in ipairs(L.eye) do
			local dt = e.data
			local rel
			if dt.kind == "flower" then
				local cc = circ[dt.ci]
				local n = S.eyeDetail
				local ox, oy = 0, 0
				if n > 1 then
					local a = (dt.si - 1) / n * math.pi * 2
					ox, oy = math.cos(a) * rho, math.sin(a) * rho
				end
				local pt = c1 + Vector3.xAxis * (cc.X + ox) + upslope * (cc.Y + oy) + n1 * (spL * 0.35)
				rel = baseCF(pt, n1) * axisFix(e, true)
			elseif dt.kind == "rim" then
				local d = dirK(frontK[dt.i])
				local th = Vector3.new(-d.Z, 0, d.X)
				local pt = (d * (p.A * T + 0.4) + Vector3.new(0, y2 * T, 0)) + B
				rel = baseCF(pt, th) * axisFix(e, true)
			else -- light
				local off = (dt.i - 2) * T * 0.7
				local pt = c3 + Vector3.xAxis * off + n3 * (spL * 0.3)
				rel = baseCF(pt, n3) * axisFix(e, true)
			end
			e.fn = function() return curRoot * rel end
		end
		-- 2 sung duoi bung: nong bang thang + dau sang bang firework, quay quet quanh phia truoc
		local barrelLen = spL
		for _, e in ipairs(L.guns) do
			if e.data.kind == "barrel" then barrelLen = e.dims[e.longIdx] break end
		end
		for _, e in ipairs(L.guns) do
			local dt = e.data
			local sg, j, pivot, isTip = dt.sign, dt.j, dt.pivot, dt.kind == "tip"
			e.fn = function()
				local t = os.clock() - t0
				local ph = sg == 1 and 0 or math.pi
				local yaw = math.sin(t * S.gunSpeed + ph) * math.rad(S.sweep)
				local pitch = math.sin(t * S.gunSpeed * 0.7 + ph) * math.rad(12)
				local dir = (CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)):VectorToWorldSpace(Vector3.new(0, 0, -1))
				local u = dir:Cross(UP).Unit
				local v = dir:Cross(u)
				local pt
				if isTip then
					local a = (j - 1) / math.max(1, S.gunTip) * math.pi * 2
					local cross = S.gunTip > 1 and (u * math.cos(a) + v * math.sin(a)) * spW * 1.3 or Vector3.zero
					pt = pivot + dir * (S.gunBarrel * barrelLen * 0.95 + spL * 0.45) + cross
				else
					pt = pivot + dir * (barrelLen * 0.5 + (j - 1) * barrelLen * 0.95)
				end
				return curRoot * (baseCF(pt, dir) * axisFix(e, true))
			end
		end
		-- day cap rung ruc thong xuong tu bung
		local nT = #L.tent
		for i, e in ipairs(L.tent) do
			local ang = (i - 1) / math.max(1, nT) * math.pi * 2 + 0.4
			local d = Vector3.new(math.cos(ang), 0, math.sin(ang))
			local root0 = d * (a3 * 0.8 * T) + Vector3.new(0, y3 * T, 0) + B
			local len = e.dims[e.longIdx]
			e.fn = function()
				local t = os.clock() - t0
				local dir = Vector3.new(math.sin(t * 0.8 + i * 1.7) * 0.22, -1, math.cos(t * 0.6 + i * 2.3) * 0.22).Unit
				return curRoot * (baseCF(root0 + dir * (len * 0.5), dir) * axisFix(e, true))
			end
		end
		-- chan: bo ladder thon dan + vong giap + ban chan
		local segs = S.legSegs
		local r = 2
		do
			local le = L.legs[1]
			if le then
				local v = { le.size.X, le.size.Y, le.size.Z }
				table.sort(v)
				r = math.max(1.5, v[2] * 1.4)
			end
		end
		local function parentOf(data) return L.legs[(data.leg - 1) * segs + data.seg] end
		for _, e in ipairs(L.thick) do
			local par = parentOf(e.data)
			if par then
				local others = {}
				for i = 1, 3 do if i ~= par.longIdx then others[#others + 1] = i end end
				local off = e.data.k == 1 and UNIT[others[1]] * r or (UNIT[others[1]] * r * 0.5 + UNIT[others[2]] * r * 0.866)
				e.fn = function()
					if not par.main.Parent then return nil end
					return par.main.CFrame * par.mainOff:Inverse() * CFrame.new(off)
				end
			end
		end
		for _, e in ipairs(L.collars) do
			local par = parentOf(e.data)
			if par then
				local sh = UNIT[par.longIdx] * (e.data.at * par.dims[par.longIdx])
				e.fn = function()
					if not par.main.Parent then return nil end
					return par.main.CFrame * par.mainOff:Inverse() * CFrame.new(sh) * rotYto(par.longIdx) * axisFix(e, false)
				end
			end
		end
		for _, e in ipairs(L.pads) do
			local li = e.data.leg
			e.fn = function()
				local lg = SpiderLegs.legs[li]
				if not lg or not lg.foot then return nil end
				local up = lg.normal or SpiderLegs.surfaceUp or UP
				return baseCF(lg.foot + up * 0.4, up) * axisFix(e, false)
			end
		end
	end

	local function bindLeg(v, e)
		local att = v.part:FindFirstChild("Attachment")
		if not att then return end
		pcall(function() e.ap:Destroy() end)
		pcall(function() e.at:Destroy() end)
		e.ap = nil
		v.toy = e.toy
		local a2 = Instance.new("Attachment", e.main)
		SpiderLegsAlignToy(v, e.toy, e.main, a2)
		local ap = Instance.new("AlignPosition", e.main)
		ap.Name = "RigPosition"
		ap.Responsiveness = 200
		ap.MaxForce = math.huge
		ap.ApplyAtCenterOfMass = true
		ap.Attachment0 = a2
		ap.Attachment1 = att
		ap.Mode = Enum.PositionAlignmentMode.TwoAttachment
		local ao = Instance.new("AlignOrientation", e.main)
		ao.Name = "RigOrientation"
		ao.Attachment0 = a2
		ao.Attachment1 = att
		ao.Mode = Enum.OrientationAlignmentMode.TwoAttachment
		ao.RigidityEnabled = true
		ao.Enabled = true
	end

	local function holdFollower(e)
		pcall(function() e.at:Destroy() end)
		pcall(function() e.ap:Destroy() end)
		e.at = Instance.new("Attachment", e.main)
		e.ap = Instance.new("AlignPosition", e.main)
		e.ap.Mode = Enum.PositionAlignmentMode.OneAttachment
		e.ap.Attachment0 = e.at
		e.ap.ApplyAtCenterOfMass = true
		e.ap.MaxForce = math.huge
		e.ap.MaxVelocity = math.huge
		e.ap.Responsiveness = 200
		e.ao = Instance.new("AlignOrientation", e.main)
		e.ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
		e.ao.Attachment0 = e.at
		e.ao.MaxTorque = math.huge
		e.ao.Responsiveness = 200
		e.ao.RigidityEnabled = false
	end

	-- ===== mau phim + hieu ung sang (chi hien thi o client cua ban) =====
	local RED = Color3.fromRGB(255, 55, 70)

	local function paint(e, color, mat)
		pcall(function()
			for _, d in ipairs(e.toy:GetDescendants()) do
				if d:IsA("BasePart") then
					d.Color = color
					d.Material = mat
					if d:IsA("MeshPart") then d.TextureID = "" end
				elseif d:IsA("SpecialMesh") then
					d.TextureId = ""
				end
			end
		end)
	end

	-- den that + quang (3 vong dong tam gia lap bloom) + nhap nhay
	local function addGlow(e, color, range, bright, flare, speed)
		local main = e.main
		if not main or not main.Parent then return end
		paint(e, color, Enum.Material.Neon)
		local pl = Instance.new("PointLight")
		pl.Name = "WOTWGlow"
		pl.Color = color
		pl.Range = range
		pl.Brightness = bright
		pl.Shadows = false
		pl.Parent = main
		local bb = Instance.new("BillboardGui")
		bb.Name = "WOTWFlare"
		bb.Adornee = main
		bb.AlwaysOnTop = false
		bb.LightInfluence = 0
		bb.Size = UDim2.fromScale(flare, flare)
		for _, lv in ipairs({ { 1, 0.88 }, { 0.62, 0.65 }, { 0.3, 0.2 } }) do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(lv[1], lv[1])
			f.BackgroundColor3 = lv[1] < 0.5 and Color3.fromRGB(255, 200, 200) or color
			f.BackgroundTransparency = lv[2]
			f.BorderSizePixel = 0
			local uc = Instance.new("UICorner")
			uc.CornerRadius = UDim.new(1, 0)
			uc.Parent = f
			f.Parent = bb
		end
		bb.Parent = main
		glows[#glows + 1] = { pl = pl, bb = bb, base = bright, ph = math.random() * 6.28, sp = speed or 2 }
	end

	local function applyStyle()
		if S.glow then
			local gp = S.glowPower
			for _, e in ipairs(L.eye) do
				local dt = e.data or {}
				if dt.kind == "flower" then
					addGlow(e, RED, dt.ci == 1 and 16 or 11, 2.2 * gp, 4.5, 1.6)      -- 7 vong do (hoa) tren mai
				elseif dt.kind == "rim" then
					addGlow(e, Color3.fromRGB(255, 40, 50), 8, 1.4 * gp, 2.5, 3.5)    -- vet do doc vanh
				else
					addGlow(e, Color3.fromRGB(255, 80, 80), 14, 2.6 * gp, 6, 1.2)     -- 3 den duoi bung
				end
			end
			for _, e in ipairs(L.guns) do
				if e.data and e.data.kind == "tip" then
					addGlow(e, Color3.fromRGB(255, 120, 60), 18, 3.5 * gp, 7, 6)      -- dau sung (heat-ray)
				end
			end
		end
	end

	local function assemble()
		saved = {}
		for _, k in ipairs({ "legCount", "segCount", "spread", "frontSpread", "stepDistance", "stepHeight", "toyType", "autoFit" }) do saved[k] = SpiderLegs[k] end
		SpiderLegs.legCount = 3
		SpiderLegs.segCount = S.legSegs
		SpiderLegs.spread = S.legSpread
		SpiderLegs.frontSpread = S.legSpread
		SpiderLegs.stepDistance = math.max(7, S.legSpread * 0.6)
		SpiderLegs.stepHeight = 6
		SpiderLegs.toyType = "LadderLightBrown"
		SpiderLegs.autoFit = true
		_G.SpiderLegs = true
		SpiderLegs.session += 1
		SpiderLegsCreate()
		for i, e in ipairs(L.legs) do
			local v = SpiderLegs.parts[i]
			if v then bindLeg(v, e) end
		end
		pcall(SpiderLegsAutoHeight)
		local _, r = L12.Char()
		curRoot = r and r.CFrame or CFrame.new()
		-- diem treo sung (tinh theo T that) gan vao data truoc khi layout
		local T = 6
		for _, e in ipairs(L.body) do
			local v = { e.size.X, e.size.Y, e.size.Z }
			table.sort(v, function(x, y) return x > y end)
			T = math.max(2, v[2])
			break
		end
		local p = profile(S.hood)
		local a3, y3 = segPoint(p, 3, 0.5)
		local pivots = {}
		for _, sg in ipairs({ 1, -1 }) do
			local d = dirK(sg == 1 and 1 or 5)
			pivots[sg] = (d * (a3 * T) + Vector3.new(0, y3 * T - 0.9 * T, 0)) + Vector3.new(0, BODY_BASE, 0)
		end
		for _, e in ipairs(L.guns) do e.data.pivot = pivots[e.data.sign] end
		for _, e in ipairs(L.body) do
			if e.data and e.data.mount then e.data.pivot = pivots[e.data.mount] end
		end
		layout()
		for _, name in ipairs({ "body", "eye", "guns", "tent", "thick", "collars", "pads" }) do
			for _, e in ipairs(L[name]) do
				if e.fn then
					holdFollower(e)
					follow[#follow + 1] = e
				end
			end
		end
		local okS, errS = pcall(applyStyle)
		if not okS then warn("[WOTW] style: " .. tostring(errS)) end
		t0 = os.clock()
		bodyConn = RunService.Heartbeat:Connect(function()
			local _, rt = L12.Char()
			if not rt then return end
			curRoot = rt.CFrame
			local tt = os.clock() - t0
			for gi = #glows, 1, -1 do -- nhap nhay den
				local g = glows[gi]
				if not g.pl.Parent then
					table.remove(glows, gi)
				else
					g.pl.Brightness = g.base * (0.7 + 0.3 * math.sin(tt * g.sp + g.ph))
				end
			end
			for i = #follow, 1, -1 do
				local e = follow[i]
				if not e.main.Parent then
					table.remove(follow, i)
				else
					local ok, t = pcall(e.fn)
					if ok and t then
						local cf = t * e.mainOff
						e.ap.Position = cf.Position
						e.ao.CFrame = cf
					end
				end
			end
		end)
	end

	local lastSpot
	local function randomPlotSpot() return ToyKit.SafeSpot(true) end -- cach rim >= ToyKit.EDGE

	-- diem plot: pallet 5, thang 5, firework 20. Plot chua toi da S.budget diem.
	local COST = { PalletLightBrown = 5, LadderLightBrown = 5, FireworkSparkler = 20 }
	local function buildPlan()
		local plan, used = {}, 0
		local function add(name, list, data)
			local c = COST[name]
			if used + c > S.budget then return false end
			used += c
			plan[#plan + 1] = { name, list, data }
			return true
		end
		local segs = S.legSegs
		-- TANG 1 (thiet yeu): chan chinh, vo than, 7 vong mat (1 sparkler/vong), 2 sung (thang + dau sang), de sung
		for _ = 1, 3 * segs do add("LadderLightBrown", L.legs) end
		for _ = 1, #genBody(1, S.hood).list do add("PalletLightBrown", L.body) end
		for ci = 1, 7 do add("FireworkSparkler", L.eye, { kind = "flower", ci = ci, si = 1 }) end
		for _, sg in ipairs({ 1, -1 }) do
			for j = 1, S.gunBarrel do add("LadderLightBrown", L.guns, { kind = "barrel", sign = sg, j = j }) end
			for j = 1, S.gunTip do add("FireworkSparkler", L.guns, { kind = "tip", sign = sg, j = j }) end
		end
		for _, sg in ipairs({ 1, -1 }) do add("PalletLightBrown", L.body, { mount = sg }) end
		-- TANG 2 (re): ban chan, vong giap, day cap, day chan
		for leg = 1, 3 do add("PalletLightBrown", L.pads, { leg = leg }) end
		for leg = 1, 3 do add("PalletLightBrown", L.collars, { leg = leg, seg = 1, at = 0.3 }) end
		for _ = 1, S.tentacles do add("LadderLightBrown", L.tent) end
		for leg = 1, 3 do
			for seg = 1, segs do
				for k = 1, math.max(1, S.legThick - (seg - 1)) - 1 do add("LadderLightBrown", L.thick, { leg = leg, seg = seg, k = k }) end
			end
		end
		for leg = 1, 3 do
			add("PalletLightBrown", L.collars, { leg = leg, seg = 1, at = -0.3 })
			if segs >= 2 then add("PalletLightBrown", L.collars, { leg = leg, seg = 2, at = 0 }) end
		end
		-- TANG 3: firework phu (20 diem/cai) neu con diem
		for i = 1, S.rim do add("FireworkSparkler", L.eye, { kind = "rim", i = i }) end
		for i = 1, S.lights do add("FireworkSparkler", L.eye, { kind = "light", i = i }) end
		for si = 2, S.eyeDetail do
			for ci = 1, 7 do add("FireworkSparkler", L.eye, { kind = "flower", ci = ci, si = si }) end
		end
		return plan, used
	end

	local function run(token)
		local function ok() return running and token == session end
		if _G.SpiderLegs and not saved then
			if ctx.notify then ctx.notify("Tat Spider Legs truoc khi bat WOTW", "WOTW") end
			return
		end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame

		-- huy plot cu (neu co) roi claim lai + TP vao plot
		if _G.PlotPlayerIsOwner then
			pcall(RemovePlotOwner)
			local w = 0
			while ok() and _G.PlotPlayerIsOwner and w < 50 do task.wait(0.1) w += 1 end
		end
		if not ok() then return end
		WingsGoToSafeZone()
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(0.1) w += 1 end
		if not ok() then return end

		local plan, usedPts = buildPlan()
		local total = #plan
		if ctx.notify then ctx.notify("Ke hoach: " .. total .. " toy, " .. usedPts .. "/" .. S.budget .. " diem plot", "WOTW") end
		local spawned, i, nilSince, ownFail = 0, 1, nil, 0
		local lastNotify = 0
		lastSpot = nil
		-- spawn cho DEN KHI du part. Chi bo cuoc khi spawn nil lien tuc >8s (plot day / het slot)
		while ok() and i <= total and ownFail < 25 and not (nilSince and os.clock() - nilSince > 8) do
			local _, r = L12.Char()
			if not r then task.wait(0.2) continue end
			ToyKit.EnsureStanding()
			local _, r2 = L12.Char()
			local toy = L12.SpawnToy(plan[i][1], ToyKit.SpawnCF(r2 or r), 0, true)
			if toy then
				nilSince = nil
				local e = adopt(toy)
				if not e then
					ownFail += 1 -- khong lay duoc owner: xoa va thu lai cung part do
					pcall(function() DeleteToyRE:FireServer(toy) end)
					task.wait(0.15)
				else
					ownFail = 0
					e.data = plan[i][3]
					table.insert(plan[i][2], e)
					i += 1
					spawned += 1
					if spawned - lastNotify >= 30 and ctx.notify then
						lastNotify = spawned
						ctx.notify("Dang spawn: " .. spawned .. "/" .. total, "WOTW")
					end
				end
			else
				nilSince = nilSince or os.clock()
				task.wait(0.25)
			end
		end
		if not ok() then return end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		TeleportPlayer(homeCF)
		busy = false
		task.wait(0.4)
		if not ok() then return end
		local needLegs = 3 * S.legSegs
		if #L.legs < needLegs then
			if ctx.notify then ctx.notify("Thieu toy cho chan (" .. #L.legs .. "/" .. needLegs .. "). Giam Leg Segments roi bat lai", "WOTW") end
			running = false
			clearAll()
			return
		end
		if i <= total and ctx.notify then ctx.notify("Plot day / het slot: " .. spawned .. "/" .. total .. " - lap rap ban rut gon", "WOTW") end
		local okA, errA = pcall(assemble)
		if not okA then
			warn("[WOTW] assemble: " .. tostring(errA))
			if ctx.notify then ctx.notify("Loi lap rap: " .. tostring(errA), "WOTW") end
		end
	end

	WOTWSection:AddToggle({
		Name = "WOTW",
		Default = false,
		Callback = function(on)
			session += 1
			running = on
			clearAll()
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then task.spawn(run, session) end
		end,
	})
	local function sl(name, min, max, def, inc, unit, key)
		WOTWSection:AddSlider({ Name = name, Min = min, Max = max, Default = def, Increment = inc, ValueName = unit, Callback = function(v) S[key] = v end })
	end
	sl("Plot Points Budget", 100, 1500, S.budget, 10, "pts", "budget")
	sl("Hood Size (apothem, pallets)", 2, 5, S.hood, 1, "pallets", "hood")
	sl("Eye Sparklers per Circle (20pts each x7)", 1, 3, S.eyeDetail, 1, "toys", "eyeDetail")
	sl("Gun Barrel Ladders (each)", 1, 4, S.gunBarrel, 1, "ladders", "gunBarrel")
	sl("Gun Glow Tips (each, 20pts)", 1, 3, S.gunTip, 1, "toys", "gunTip")
	sl("Rim Stripe Sparklers (20pts)", 0, 5, S.rim, 1, "toys", "rim")
	sl("Belly Lights (20pts)", 0, 3, S.lights, 1, "toys", "lights")
	sl("Gun Sweep Angle", 10, 170, S.sweep, 5, "deg", "sweep")
	sl("Gun Sweep Speed", 0.2, 6, S.gunSpeed, 0.1, "rad/s", "gunSpeed")
	sl("Hanging Cables", 0, 8, S.tentacles, 1, "ladders", "tentacles")
	sl("Leg Segments", 2, 5, S.legSegs, 1, "ladders", "legSegs")
	sl("Leg Thickness (upper segment)", 1, 3, S.legThick, 1, "ladders", "legThick")
	sl("Leg Spread", 5, 90, S.legSpread, 1, "studs", "legSpread")
	sl("Power", 10, 200, S.power, 5, "", "power")
	WOTWSection:AddToggle({ Name = "Glow Effects (den do + flare)", Default = true, Callback = function(v) S.glow = v end })
	sl("Glow Intensity", 0.2, 3, S.glowPower, 0.1, "x", "glowPower")
	WOTWSection:AddToggle({ Name = "Release Plot When Done", Default = false, Callback = function(v) S.release = v end })
end

-- ===== TANK v4 (kieu T-90): chi pallet (than dai, thap phao to, XICH PALLET CHAY VONG), nong = thang, 2 ang ten firework. Treo 4 goc: nghieng theo dia hinh, tu can bang, leo tuong, lat qua mep =====
do
	local S = { speed = 35, turn = 2, budget = 600, goHome = true, release = false }
	local N, C, NL = 7, 3, 22 -- 7 hang dai x 3 cot rong, 22 manh xich / ben
	local session, running, busy, homeCF, conn = 0, false, false, nil, nil
	local ents = {}
	local RS, Plrs, PI = game:GetService("RunService"), game:GetService("Players"), math.pi
	local lp = Plrs.LocalPlayer
	local X, Y, Z = Vector3.xAxis, Vector3.yAxis, Vector3.zAxis
	local COST = { PalletLightBrown = 5, LadderLightBrown = 5, FireworkSparkler = 20 }
	local THF, THR = math.rad(32), math.rad(58)
	local TF, TR = math.rad(50), math.rad(68)
	local rp = RaycastParams.new()
	rp.FilterType = Enum.RaycastFilterType.Exclude
	rp.RespectCanCollide = true
	local function note(m) if ctx.notify then ctx.notify(m, "Tank") end end

	local function clear()
		if conn then conn:Disconnect() conn = nil end
		for _, e in ipairs(ents) do
			pcall(function() e.ap:Destroy() end)
			pcall(function() e.ao:Destroy() end)
			pcall(function() e.at:Destroy() end)
			ToyKit.FreeSlot(e.slot)
			if e.toy and e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
		end
		table.clear(ents)
	end

	local function adopt(toy)
		local e = ToyKit.Hold(toy, "tank", function(t, main)
			local ok, c, sz = pcall(function() return t:GetBoundingBox() end)
			if ok then return { off = c:ToObjectSpace(main.CFrame), size = sz } end
			return { off = CFrame.identity, size = Vector3.new(1, 4, 1) }
		end)
		if not e then return nil end
		e.mainOff = e.info.off
		local sz = e.info.size
		local v, idx = { sz.X, sz.Y, sz.Z }, { 1, 2, 3 }
		table.sort(idx, function(a, b)
			if v[a] ~= v[b] then return v[a] < v[b] end
			return a < b
		end)
		e.ti, e.mi, e.li = idx[1], idx[2], idx[3]
		e.thin, e.mid, e.long = v[e.ti], v[e.mi], v[e.li]
		e.ap.Responsiveness = 200
		return e
	end

	local function orient(e, L, N2)
		local t = {}
		t[e.li], t[e.ti] = L, N2
		local M = L:Cross(N2)
		t[e.mi] = M
		if t[1]:Cross(t[2]):Dot(t[3]) < 0 then t[e.mi] = -M end
		return CFrame.fromMatrix(Vector3.zero, t[1], t[2], t[3])
	end
	local function bb(e, pos, L, N2) return CFrame.new(pos) * orient(e, L, N2) end

	-- ===== 106 pallet + 6 thang + 2 sparkler = 530 + 30 + 40 = 600 diem =====
	local function plan()
		local p, used = {}, 0
		local function add(n, d)
			local c = COST[n]
			if used + c > S.budget then return false end
			used += c
			p[#p + 1] = { n, d }
			return true
		end
		local PA = "PalletLightBrown"
		for r = 0, N - 1 do for c = 0, C - 1 do add(PA, { k = "deck", c = c, r = r }) end end                       -- 21 than
		for ix = 0, 1 do for iz = 0, 1 do add(PA, { k = "tur", part = "top", ix = ix, iz = iz }) end end             -- 12 thap phao
		for _, part in ipairs({ "sl", "sr" }) do for iz = 0, 1 do add(PA, { k = "tur", part = part, iz = iz }) end end
		for ix = 0, 1 do add(PA, { k = "tur", part = "front", ix = ix }) end
		for ix = 0, 1 do add(PA, { k = "tur", part = "rear", ix = ix }) end
		for j = 1, 3 do for q = 1, 2 do add("LadderLightBrown", { k = "bar", j = j, q = q }) end end                -- 6 thang nong
		for i = 0, NL - 1 do                                                                                        -- 44 manh xich (chay vong)
			for _, sd in ipairs({ 1, -1 }) do add(PA, { k = "lnk", sd = sd, i = i }) end
		end
		for c = 0, C - 1 do add(PA, { k = "glac", c = c }) end                                                      -- mui + duoi doc
		for c = 0, C - 1 do add(PA, { k = "rear", c = c }) end
		for _, sx in ipairs({ 1, -1 }) do add("FireworkSparkler", { k = "ant", sx = sx }) end                       -- 2 ang ten
		for _, sd in ipairs({ 1, -1 }) do for r = 0, N - 1 do add(PA, { k = "iwall", sd = sd, r = r }) end end      -- 14 vach hong than
		for c = 0, C - 1 do add(PA, { k = "nose", c = c }) end
		for c = 0, C - 1 do add(PA, { k = "tail", c = c }) end
		add(PA, { k = "cup" })
		for ix = 0, 1 do add(PA, { k = "hatch", ix = ix }) end
		return p, used
	end

	local function assemble(home)
		local P, Ld
		for _, e in ipairs(ents) do
			if not P and e.toy.Name == "PalletLightBrown" then P = e end
			if not Ld and e.toy.Name == "LadderLightBrown" then Ld = e end
		end
		if not P then note("Thieu pallet de lap tank") return clear() end

		local pl, pw, pt = math.max(P.long, 1), math.max(P.mid, 1), math.max(P.thin, 0.2)
		local lL = Ld and math.max(Ld.long, 2) or pl
		local Wh, Lhull = C * pw, N * pl
		-- vong xich: dai hon than xe 1 pallet
		local R = pl * 0.55                      -- ban kinh dau cuoi vong xich
		local Lh = Lhull + pl                    -- do dai doan thang
		local Pr = 2 * Lh + 2 * PI * R
		local yc = -(R + pt / 2 + 0.1)           -- tam vong xich (mat tren xich ngay duoi san)
		local h0 = 2 * R + pt + 0.15             -- do cao san thap so voi mat dat (xich cham dat)
		local xo = Wh / 2 + pw / 2               -- tam xich
		-- thap phao
		local ht = 0.95 * pl
		local sphi = math.clamp(ht / pl, 0.3, 0.97)
		local cphi = math.sqrt(1 - sphi * sphi)
		local b = pt * 0.5 + 0.05
		local zt = -0.5 * pl
		local sTF, cTF, sTR, cTR = math.sin(TF), math.cos(TF), math.sin(TR), math.cos(TR)
		local sHF, cHF, sHR, cHR = math.sin(THF), math.cos(THF), math.sin(THR), math.cos(THR)
		local pg = Vector3.new(0, b + ht * 0.55, -(pl + pl * cTF / 2))

		local function cx(c) return (c - (C - 1) / 2) * pw end
		local function rz(r) return (r - (N - 1) / 2) * pl end
		local function trackPoint(s) -- z, y, nz, ny
			if s < Lh then return Lh / 2 - s, R, 0, 1 end
			if s < Lh + PI * R then
				local a = (s - Lh) / R
				return -Lh / 2 - R * math.sin(a), R * math.cos(a), -math.sin(a), math.cos(a)
			end
			if s < 2 * Lh + PI * R then return -Lh / 2 + (s - Lh - PI * R), -R, 0, -1 end
			local a = (s - 2 * Lh - PI * R) / R
			return Lh / 2 + R * math.sin(a), -R * math.cos(a), math.sin(a), -math.cos(a)
		end

		for i = #ents, 1, -1 do
			local e = ents[i]
			local d, k = e.d, e.d.k
			local V = Vector3.new
			if k == "deck" then e.static = bb(e, V(cx(d.c), 0, rz(d.r)), Z, Y)
			elseif k == "glac" then e.static = bb(e, V(cx(d.c), -pl * sHF / 2, -(Lhull / 2 + pl * cHF / 2)), V(0, -sHF, -cHF), V(0, cHF, -sHF))
			elseif k == "rear" then e.static = bb(e, V(cx(d.c), -pl * sHR / 2, Lhull / 2 + pl * cHR / 2), V(0, -sHR, cHR), V(0, cHR, sHR))
			elseif k == "nose" then e.static = bb(e, V(cx(d.c), -pl * sHF - pw / 2 + 0.3, -(Lhull / 2 + pl * cHF)), X, Z)
			elseif k == "tail" then e.static = bb(e, V(cx(d.c), -pl * sHR - pw / 2 + 0.3, Lhull / 2 + pl * cHR), X, Z)
			elseif k == "iwall" then e.static = bb(e, V(d.sd * Wh / 2, -pw / 2, rz(d.r)), Z, X)
			elseif k == "hatch" then e.static = bb(e, V((d.ix - 0.5) * pw, pt * 1.2, rz(N - 2)), Z, Y)
			elseif k == "lnk" then
				-- manh xich: chay vong theo tr cua tung ben (xe quay => 2 xich chay nguoc chieu)
				local x, right = d.sd * xo, d.sd == 1
				local base = d.i / NL * Pr
				local par = (d.i % 2 == 0) and 0 or 0.15 -- le/chan lech nhe tranh chong mat
				e.fn = function(st)
					local s = (base + (right and st.trR or st.trL)) % Pr
					local z, y, nz, ny = trackPoint(s)
					local nv = Vector3.new(0, ny, nz)
					return CFrame.new(x, yc + y + ny * par, z + nz * par) * orient(e, Vector3.new(0, -nz, ny), nv)
				end
			elseif k == "cup" then
				local loc = bb(e, V(-pw * 0.5, b + ht + pt * 1.1, -pl * 0.2), Z, Y)
				e.fn = function(st) return st.tcf * loc end
			elseif k == "ant" then
				local loc = bb(e, V(d.sx * pw * 0.8, b + ht + e.long / 2 - 0.2, pl * 0.7), Y, X)
				e.fn = function(st) return st.tcf * loc end
			elseif k == "tur" then
				local loc
				if d.part == "top" then
					loc = bb(e, V((d.ix - 0.5) * pw, b + ht, (d.iz - 0.5) * pl), Z, Y)
				elseif d.part == "sl" or d.part == "sr" then
					local sg = d.part == "sr" and 1 or -1
					loc = bb(e, V(sg * (pw + pl * cphi / 2), b + ht / 2, (d.iz - 0.5) * pl), V(sg * cphi, -sphi, 0), V(sg * sphi, cphi, 0))
				elseif d.part == "front" then
					loc = bb(e, V((d.ix - 0.5) * pw, b + ht - pl * sTF / 2, -(pl + pl * cTF / 2)), V(0, -sTF, -cTF), V(0, cTF, -sTF))
				else
					loc = bb(e, V((d.ix - 0.5) * pw, b + ht - pl * sTR / 2, pl + pl * cTR / 2), V(0, -sTR, cTR), V(0, cTR, sTR))
				end
				e.fn = function(st) return st.tcf * loc end
			elseif k == "bar" then
				local loc = CFrame.new(0, 0, -(lL * (d.j - 1) + lL * 0.3)) * orient(e, Z, d.q == 1 and X or Y)
				e.fn = function(st) return st.gcf * loc end
			else
				table.remove(ents, i)
				pcall(function() DeleteToyRE:FireServer(e.toy) end)
				continue
			end
			pcall(function() e.at:Destroy() end)
			e.at = Instance.new("Attachment")
			e.at.Parent = e.main
			e.ap.Attachment0 = e.at
			e.ap.Responsiveness = 200
			e.ao = Instance.new("AlignOrientation")
			e.ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
			e.ao.Attachment0 = e.at
			e.ao.MaxTorque = math.huge
			e.ao.Responsiveness = 200
			e.ao.RigidityEnabled = false
			e.ao.Parent = e.main
			e.p0 = e.ap.Position
		end
		if #ents == 0 then note("Khong du toy de lap tank") return clear() end

		-- ===== vat ly: 4 diem treo (tia theo truc -nrm), nghieng theo dia hinh, leo tuong =====
		local OFF = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } } -- { trai/phai, sau/truoc }: c1 trai-sau, c2 phai-sau, c3 trai-truoc, c4 phai-truoc
		local hx, hz = xo, Lhull / 2
		local reach = Lh / 2 + R
		local hmid = h0 * 0.6
		local lastRef = 0
		local function refresh()
			local ig = {}
			if lp.Character then ig[#ig + 1] = lp.Character end
			for _, p in ipairs(Plrs:GetPlayers()) do
				if p ~= lp and p.Character then ig[#ig + 1] = p.Character end
			end
			for _, c in ipairs(workspace:GetChildren()) do
				if c.Name:find("SpawnedInToys$") then ig[#ig + 1] = c end
			end
			for _, e in ipairs(ents) do
				if e.toy.Parent then ig[#ig + 1] = e.toy end
			end
			rp.FilterDescendantsInstances = ig
		end
		refresh()
		local _, root = L12.Char()
		local cl = workspace.CurrentCamera.CFrame.LookVector
		local fw = Vector3.new(cl.X, 0, cl.Z)
		fw = fw.Magnitude > 1e-3 and fw.Unit or Vector3.new(0, 0, -1)
		local nrm = Vector3.yAxis
		local base0 = (S.goHome and home) and home.Position or (root and root.Position or Vector3.zero)
		local hit0 = workspace:Raycast(base0 + Vector3.new(0, 3, 0), Vector3.new(0, -60, 0), rp)
		local pos = hit0 and hit0.Position or base0
		local dist, turnAcc = 0, 0
		local st = { ty = 0, tp = 0, trL = 0, trR = 0, tcf = CFrame.identity, gcf = CFrame.identity }
		local t0, warned = os.clock(), false

		-- keo nrm ve n2 nhung giu 'right' (chi pitch/roll), cap nhat fw
		local function retilt(n2, rate, right)
			local n3 = nrm:Lerp(n2, math.min(1, rate)).Unit
			local rr = right - n3 * right:Dot(n3)
			if rr.Magnitude < 1e-3 then return end
			nrm = n3
			fw = nrm:Cross(rr.Unit)
		end
		-- chuc mui xuong (a > 0) hoac chuc duoi xuong (a < 0): quay quanh 'right'
		local function pitchDown(a)
			local cs, sn = math.cos(a), math.sin(a)
			local n0, f0 = nrm, fw
			nrm = (n0 * cs + f0 * sn).Unit
			fw = (f0 * cs - n0 * sn).Unit
		end
		-- nghieng sang phai (a > 0) hoac trai (a < 0): quay quanh fw
		local function rollRight(a, right)
			local n2 = (nrm * math.cos(a) + right * math.sin(a)).Unit
			nrm = n2
			fw = (fw - n2 * fw:Dot(n2)).Unit
		end

		local function step(dt)
			dt = math.min(dt, .1)
			local ch = lp.Character
			local hum, rt = ch and ch:FindFirstChildOfClass("Humanoid"), ch and ch:FindFirstChild("HumanoidRootPart")
			if not (hum and rt) then return end
			local now = os.clock()
			if now - lastRef > .5 then lastRef = now refresh() end
			local cam = workspace.CurrentCamera

			-- lai kieu tank: W/S tien lui, A/D quay theo camera
			local md, cl2 = hum.MoveDirection, cam.CFrame.LookVector
			local flat = Vector3.new(cl2.X, 0, cl2.Z)
			flat = flat.Magnitude > 1e-3 and flat.Unit or Vector3.new(0, 0, -1)
			local f, r = md:Dot(flat), md:Dot(flat:Cross(Vector3.yAxis))
			local turn = -r * dt * S.turn
			turnAcc -= turn
			fw = CFrame.fromAxisAngle(nrm, turn):VectorToWorldSpace(fw)
			fw = (fw - nrm * fw:Dot(nrm)).Unit
			local right = fw:Cross(nrm)
			local mv = f * S.speed * dt
			local sg = mv >= 0 and 1 or -1

			-- gap tuong/vat can ngay truoc mui: nghieng len de leo (khong bam tran nha)
			if mv ~= 0 then
				local w = workspace:Raycast(pos + nrm * hmid, fw * sg * (reach + 2.5), rp)
				if w and w.Normal.Y > -0.25 then
					local ang = math.acos(math.clamp(nrm:Dot(w.Normal), -1, 1))
					if ang > 0.05 then
						retilt(w.Normal, dt * 3.5, right)
						right = fw:Cross(nrm)
						if ang > 0.5 then mv = 0 end
					end
				end
			end
			if mv ~= 0 then dist += mv end

			-- 4 tia treo (bat dau cao 6, dai 22): nghieng theo dia hinh / tu can bang khi mat diem tua
			local np = pos + fw * mv
			local c, cnt = {}, 0
			for i, o in ipairs(OFF) do
				local org = np + nrm * 6 + right * (o[1] * hx) + fw * (o[2] * hz)
				local h = workspace:Raycast(org, -nrm * 22, rp)
				if h then c[i] = h.Position cnt += 1 end
			end
			local function heightFrom()
				local mx, sum, n2 = -1e9, 0, 0
				for i = 1, 4 do
					if c[i] then
						local dd = (c[i] - np):Dot(nrm)
						sum += dd n2 += 1
						if dd > mx then mx = dd end
					end
				end
				return mx * 0.6 + (sum / n2) * 0.4
			end
			local function settle(hh)
				hh = math.clamp(hh * math.min(1, dt * 12), -80 * dt, 80 * dt)
				pos = np + nrm * hh
			end

			if cnt >= 3 then
				local nn
				if cnt == 4 then
					nn = (c[4] - c[1]):Cross(c[3] - c[2])
				else
					local pts = {}
					for i = 1, 4 do if c[i] then pts[#pts + 1] = c[i] end end
					nn = (pts[2] - pts[1]):Cross(pts[3] - pts[1])
				end
				if nn.Magnitude > 1e-3 then
					nn = nn.Unit
					if nn:Dot(nrm) < 0 then nn = -nn end
					if nn:Dot(nrm) > 0 then retilt(nn, dt * 9, right) end
				end
				settle(heightFrom())
			elseif cnt > 0 then
				-- thieu diem tua: chuc mui/duoi/nghieng cho den khi cham (lat qua mep, ha xuong sau doi)
				local missF = not c[3] and not c[4]
				local missB = not c[1] and not c[2]
				local missL = not c[1] and not c[3]
				local missR = not c[2] and not c[4]
				if missF and not missB then pitchDown(1.6 * dt)
				elseif missB and not missF then pitchDown(-1.6 * dt) end
				if missL and not missR then rollRight(-1.4 * dt, right)
				elseif missR and not missL then rollRight(1.4 * dt, right) end
				settle(heightFrom())
			else
				-- mat het tia (chim/lo): ban tia tu tren cao xuong keo xe len lai mat dat
				local rh = workspace:Raycast(pos + nrm * 100, -nrm * 400, rp)
				if rh and rh.Normal:Dot(nrm) > 0 then
					pos = rh.Position
					retilt(rh.Normal, 1, right)
				else
					pos = np
				end
			end

			right = fw:Cross(nrm)
			local H = CFrame.fromMatrix(pos + nrm * h0, right, nrm, -fw)

			-- thap phao + nong ngam theo camera
			local lv = H:VectorToObjectSpace(cam.CFrame.LookVector)
			local tyT = math.atan2(-lv.X, -lv.Z)
			local dy = (tyT - st.ty + PI) % (2 * PI) - PI
			st.ty += math.clamp(dy, -4 * dt, 4 * dt)
			local tpT = math.clamp(math.asin(math.clamp(lv.Y, -1, 1)), -.2, .6)
			st.tp += math.clamp(tpT - st.tp, -2 * dt, 2 * dt)
			st.trR, st.trL = dist - turnAcc * xo, dist + turnAcc * xo
			st.tcf = CFrame.new(0, 0, zt) * CFrame.Angles(0, st.ty, 0)
			st.gcf = st.tcf * CFrame.new(pg) * CFrame.Angles(st.tp, 0, 0)

			local pcf = H * st.tcf * CFrame.new(0, b + ht + 3.2, 0)
			if pcf.Position == pcf.Position then
				rt.CFrame = pcf
				rt.AssemblyLinearVelocity = Vector3.zero
				rt.AssemblyAngularVelocity = Vector3.zero
			end

			local k = math.clamp((now - t0) / 1.4, 0, 1)
			local ease = k * k * (3 - 2 * k)
			for i = #ents, 1, -1 do
				local e = ents[i]
				if not e.main.Parent then
					table.remove(ents, i)
				else
					local cf = H * (e.static or e.fn(st)) * e.mainOff
					local p = cf.Position
					if p == p then
						e.ap.Position = ease < 1 and e.p0:Lerp(p, ease) or p
						e.ao.CFrame = cf
					end
				end
			end
		end

		conn = RS.Heartbeat:Connect(function(dt)
			local ok, err = pcall(step, dt)
			if not ok and not warned then
				warned = true
				warn("[Tank] " .. tostring(err))
			end
		end)
	end

	local function run(token)
		local function ok() return running and token == session end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame
		if _G.PlotPlayerIsOwner then
			pcall(RemovePlotOwner)
			local w = 0
			while ok() and _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		end
		if not ok() then return end
		WingsGoToSafeZone()
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		if not ok() then return end

		local pl, used = plan()
		note("Ke hoach: " .. #pl .. " toy, " .. used .. "/" .. S.budget .. " diem plot")
		local i, n, nilSince, fail = 1, 0, nil, 0
		while ok() and i <= #pl and fail < 25 and not (nilSince and os.clock() - nilSince > 8) do
			local _, r = L12.Char()
			if not r then task.wait(.2) continue end
			local toy = L12.SpawnToy(pl[i][1], ToyKit.SpawnCF(r), 0, true)
			if toy then
				nilSince = nil
				local e = adopt(toy)
				if e then
					fail, e.d = 0, pl[i][2]
					ents[#ents + 1] = e
					i, n = i + 1, n + 1
					if n % 40 == 0 then note("Dang spawn: " .. n .. "/" .. #pl) end
				else
					fail += 1
					pcall(function() DeleteToyRE:FireServer(toy) end)
					task.wait(.15)
				end
			else
				nilSince = nilSince or os.clock()
				task.wait(.25)
			end
		end
		if not ok() then return end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		if S.goHome and homeCF then
			local back = false
			for _ = 1, 8 do
				TeleportPlayer(homeCF)
				task.wait(.15)
				local _, r = L12.Char()
				if r and (r.Position - homeCF.Position).Magnitude < 10 then back = true break end
			end
			note(back and "Da TP ve cho cu" or "TP ve cho cu that bai - tank van build tai cho cu")
		end
		busy = false
		task.wait(.4)
		if not ok() then return end
		if i <= #pl then note("Plot day: " .. n .. "/" .. #pl .. " toy - lap rap ban rut gon") end
		local okA, err = pcall(assemble, homeCF)
		if not okA then warn("[Tank] " .. tostring(err)) note("Loi lap rap: " .. tostring(err)) end
	end

	TankSection:AddToggle({
		Name = "Tank",
		Default = false,
		Callback = function(on)
			session += 1
			running = on
			clear()
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then task.spawn(run, session) end
		end,
	})
	TankSection:AddSlider({ Name = "Speed", Min = 10, Max = 100, Default = S.speed, Increment = 5, ValueName = "studs/s", Callback = function(v) S.speed = v end })
end

-- ===== TESLA ROADSTER: 4 BallBasketBall lam banh, Campfire lam ong bo, pallet lam than, 4 FireworkSparkler trail khi lat 360 =====
-- Xe mini: 2 pallet (hinh chu nhat) + 4 bong o 4 goc; them 2 campfire, 8 sparkler, 2 ladder
do
	local S = { kmh = 120, turn = 1.9, jump = 60, grav = 120, budget = 600, goHome = true, release = false, hud = true }
	local COST = { PalletLightBrown = 5, LadderLightBrown = 5, BALL = 15, Campfire = 20, FireworkSparkler = 20 }
	local BALL_NAMES = { "BallBasketBall", "BallBasketball", "BasketBall", "Basketball" }
	local ballName = nil
	local session, running, busy, homeCF, conn, jumpConn = 0, false, false, nil, nil, nil
	local ents = {}
	local RunSvc, Plrs, UIS, PI = game:GetService("RunService"), game:GetService("Players"), game:GetService("UserInputService"), math.pi
	local lp = Plrs.LocalPlayer
	local X, Y, Z = Vector3.xAxis, Vector3.yAxis, Vector3.zAxis
	local V = Vector3.new
	local rp = RaycastParams.new()
	rp.FilterType = Enum.RaycastFilterType.Exclude
	rp.RespectCanCollide = true
	local hud, jumpQ, carS = nil, false, 5
	local GMAX = 300
	local LAMP_HEAD = 1   -- doi thanh -1 neu dau hong cua 2 sparkler ben phai bi nguoc
	local LAMP_TURNS = 2   -- so lan quay PHAI 90 do cua 2 sparkler ben phai (2 lan = 180 do; 0 = nhu cu, 1 = 90 do)
	local function note(m) if ctx.notify then ctx.notify(m, "Tesla Roadster") end end

	-- ================= HUD: dong ho toc do kieu Tesla (km/h that = studs/s / ti le xe * 3.6) =================
	local function buildHud()
		local TS = game:GetService("TweenService")
		local g = Instance.new("ScreenGui")
		g.Name = "TeslaRoadsterHUD"
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 20
		g.Enabled = S.hud
		local okp = pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not okp or not g.Parent then g.Parent = lp:WaitForChild("PlayerGui") end

		-- kich thuoc theo man hinh (mobile nho hon); dat o BEN PHAI man hinh (sua GAUGE_POS neu muon doi cho)
		local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
		local SZ = math.floor(math.clamp(vp.Y * 0.32, 170, 250))
		local R0 = SZ / 2
		local GAUGE_POS = UDim2.new(1, -16, 0.55, 0)
		local white, dim, red = Color3.fromRGB(240, 240, 244), Color3.fromRGB(95, 95, 102), Color3.fromRGB(232, 38, 30)
		local off = Color3.fromRGB(78, 78, 88)

		-- wrap: khung ngoai (khong cat), UIScale tao hieu ung bung ra tu mep phai
		local wrap = Instance.new("Frame")
		wrap.Name = "GaugeWrap"
		wrap.BackgroundTransparency = 1
		wrap.AnchorPoint = Vector2.new(1, 0.5)
		wrap.Position = GAUGE_POS
		wrap.Size = UDim2.fromOffset(SZ, SZ + 56)
		wrap.Parent = g
		local sc = Instance.new("UIScale")
		sc.Scale = 0.55
		sc.Parent = wrap

		-- root: CanvasGroup de fade ca dong ho; nen mo kieu kinh (trong suot ~0.38 + gradient)
		local root = Instance.new("CanvasGroup")
		root.Name = "Gauge"
		root.Size = UDim2.fromOffset(SZ, SZ)
		root.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		root.BackgroundTransparency = 0.38
		root.GroupTransparency = 1
		root.BorderSizePixel = 0
		root.Parent = wrap
		local cr = Instance.new("UICorner") cr.CornerRadius = UDim.new(0.5, 0) cr.Parent = root
		local gr = Instance.new("UIGradient")
		gr.Rotation = 90
		gr.Color = ColorSequence.new(Color3.fromRGB(46, 46, 58), Color3.fromRGB(6, 6, 10))
		gr.Parent = root
		local sk = Instance.new("UIStroke") sk.Thickness = 2.5 sk.Color = Color3.fromRGB(120, 120, 135) sk.Transparency = 0.45 sk.Parent = root

		-- vong sang mong ben trong cho co chieu sau
		local ring = Instance.new("Frame")
		ring.AnchorPoint = Vector2.new(0.5, 0.5)
		ring.Position = UDim2.fromScale(0.5, 0.5)
		ring.Size = UDim2.fromScale(0.8, 0.8)
		ring.BackgroundTransparency = 1
		ring.Parent = root
		local rc = Instance.new("UICorner") rc.CornerRadius = UDim.new(0.5, 0) rc.Parent = ring
		local rs = Instance.new("UIStroke") rs.Thickness = 1 rs.Color = Color3.fromRGB(255, 255, 255) rs.Transparency = 0.88 rs.Parent = ring

		local function holder(angDeg)
			local h = Instance.new("Frame")
			h.BackgroundTransparency = 1
			h.AnchorPoint = Vector2.new(0.5, 0.5)
			h.Position = UDim2.fromScale(0.5, 0.5)
			h.Size = UDim2.fromScale(1, 1)
			h.Rotation = angDeg
			h.Parent = root
			return h
		end
		local function label(txt, size, font, col, pos, sz2)
			local lb = Instance.new("TextLabel")
			lb.BackgroundTransparency = 1
			lb.AnchorPoint = Vector2.new(0.5, 0.5)
			lb.Position = pos
			lb.Size = sz2 or UDim2.fromOffset(120, size + 4)
			lb.Font = font
			lb.TextSize = size
			lb.TextColor3 = col
			lb.Text = txt
			lb.Parent = root
			return lb
		end

		-- vach chia: se sang dan theo toc do (ticks[i].i = vach thu i, moc = i * 10 km/h)
		local ticks = {}
		for i = 0, 30 do
			local major = i % 5 == 0
			local ang = -135 + 270 * i / 30
			local h = holder(ang)
			local t = Instance.new("Frame")
			t.BorderSizePixel = 0
			t.AnchorPoint = Vector2.new(0.5, 0)
			t.Position = UDim2.new(0.5, 0, 0, 8)
			t.Size = UDim2.fromOffset(major and 3 or 1, major and 16 or 8)
			t.BackgroundColor3 = off
			t.BackgroundTransparency = 0.35
			t.Parent = h
			ticks[#ticks + 1] = { f = t, i = i }
			if major then
				local th, rr = math.rad(ang), R0 - 38
				label(tostring(i * 10), 12, Enum.Font.GothamMedium, Color3.fromRGB(200, 200, 206),
					UDim2.fromOffset(R0 + math.sin(th) * rr, R0 - math.cos(th) * rr), UDim2.fromOffset(34, 16))
			end
		end

		label("TESLA", 12, Enum.Font.GothamBold, Color3.fromRGB(150, 150, 158), UDim2.fromScale(0.5, 0.27))
		local num = label("0", 44, Enum.Font.GothamBold, white, UDim2.fromScale(0.5, 0.66), UDim2.fromOffset(130, 48))
		label("km/h", 13, Enum.Font.GothamMedium, Color3.fromRGB(170, 170, 178), UDim2.fromScale(0.5, 0.81))

		local gears = {}
		for i, k in ipairs({ "P", "R", "D" }) do
			gears[k] = label(k, 15, Enum.Font.GothamBold, dim, UDim2.fromScale(0.5 + (i - 2) * 0.09, 0.92), UDim2.fromOffset(20, 18))
		end

		local nh = holder(-135)
		local needle = Instance.new("Frame")
		needle.BorderSizePixel = 0
		needle.AnchorPoint = Vector2.new(0.5, 0)
		needle.Position = UDim2.new(0.5, 0, 0, 14)
		needle.Size = UDim2.fromOffset(3, R0 - 14)
		needle.BackgroundColor3 = red
		needle.Parent = nh
		local nl = Instance.new("UIGradient")
		nl.Rotation = 90
		nl.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.7) })
		nl.Parent = needle
		local hub = Instance.new("Frame")
		hub.AnchorPoint = Vector2.new(0.5, 0.5)
		hub.Position = UDim2.fromScale(0.5, 0.5)
		hub.Size = UDim2.fromOffset(14, 14)
		hub.BackgroundColor3 = Color3.fromRGB(30, 30, 34)
		hub.BorderSizePixel = 0
		hub.Parent = root
		local hc = Instance.new("UICorner") hc.CornerRadius = UDim.new(0.5, 0) hc.Parent = hub
		local hs = Instance.new("UIStroke") hs.Color = red hs.Thickness = 2 hs.Parent = hub

		-- chu "AIR - FLIP 360" nhap nhay phia tren dong ho
		local flip = Instance.new("TextLabel")
		flip.BackgroundTransparency = 1
		flip.AnchorPoint = Vector2.new(0.5, 1)
		flip.Position = UDim2.new(0.5, 0, 0, -4)
		flip.Size = UDim2.fromOffset(180, 20)
		flip.Font = Enum.Font.GothamBold
		flip.TextSize = 15
		flip.TextColor3 = Color3.fromRGB(255, 190, 60)
		flip.Text = "AIR  -  FLIP 360"
		flip.Visible = false
		flip.Parent = wrap

		-- TRIP / goi y nam DUOI dong ho (vi dong ho sat mep phai nen khong de ben canh nua)
		local trip = Instance.new("TextLabel")
		trip.BackgroundTransparency = 1
		trip.AnchorPoint = Vector2.new(0.5, 0)
		trip.Position = UDim2.new(0.5, 0, 0, SZ + 8)
		trip.Size = UDim2.fromOffset(SZ, 18)
		trip.Font = Enum.Font.GothamMedium
		trip.TextSize = 13
		trip.TextColor3 = Color3.fromRGB(205, 205, 212)
		trip.TextStrokeTransparency = 0.6
		trip.Text = "TRIP 0.00 km"
		trip.Parent = wrap
		local hint = trip:Clone()
		hint.Position = UDim2.new(0.5, 0, 0, SZ + 28)
		hint.Text = "SPACE / JUMP: FLIP"
		hint.TextColor3 = Color3.fromRGB(150, 150, 158)
		hint.Parent = wrap

		local H = {
			gui = g, needle = nh, num = num, gears = gears, flip = flip, trip = trip, shown = 0,
			white = white, dim = dim, red = red, off = off, ticks = ticks, lit = -1, sweep = true, t = 0,
		}

		-- animation vao: bung ra tu mep phai + hien dan, sau do kim quet 0 -> max -> 0 nhu xe that
		TS:Create(sc, TweenInfo.new(0.7, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
		TS:Create(root, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { GroupTransparency = 0 }):Play()
		task.spawn(function()
			pcall(function()
				task.wait(0.4)
				local up = TS:Create(nh, TweenInfo.new(0.8, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Rotation = 135 })
				up:Play() up.Completed:Wait()
				local dn = TS:Create(nh, TweenInfo.new(1.0, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut), { Rotation = -135 })
				dn:Play() dn.Completed:Wait()
			end)
			H.sweep = false
		end)
		return H
	end

	local function hudUpdate(dt, v, air, dist)
		if not hud then return end
		hud.t += dt
		local val
		if hud.sweep then
			-- dang quet mo man: lay gia tri theo goc kim (tween dang lo viec xoay kim)
			val = math.clamp((hud.needle.Rotation + 135) / 270, 0, 1) * GMAX
			hud.shown = val
		else
			local kmh = math.abs(v) / carS * 3.6
			hud.shown += (kmh - hud.shown) * math.min(1, dt * 9)
			hud.needle.Rotation = -135 + 270 * math.clamp(hud.shown / GMAX, 0, 1)
			val = hud.shown
		end
		hud.num.Text = tostring(math.floor(val + 0.5))
		-- so chuyen dan sang do khi vao vung do
		hud.num.TextColor3 = hud.white:Lerp(hud.red, math.clamp((val - 200) / 80, 0, 1))
		-- vach chia sang dan theo toc do (chi cap nhat khi doi moc)
		local lit = math.floor(val / 10 + 0.0001)
		if lit ~= hud.lit then
			hud.lit = lit
			for _, tk in ipairs(hud.ticks) do
				local on = tk.i <= lit
				tk.f.BackgroundColor3 = on and ((tk.i * 10 > 240) and hud.red or hud.white) or hud.off
				tk.f.BackgroundTransparency = on and 0 or 0.35
			end
		end
		local gsel = v > 0.5 and "D" or (v < -0.5 and "R" or "P")
		for k, lb in pairs(hud.gears) do lb.TextColor3 = (k == gsel) and hud.white or hud.dim end
		hud.flip.Visible = air
		if air then hud.flip.TextTransparency = 0.1 + 0.3 * (0.5 + 0.5 * math.sin(hud.t * 12)) end
		hud.trip.Text = string.format("TRIP %.2f km", dist / carS / 1000)
	end

	local function clear()
		if conn then conn:Disconnect() conn = nil end
		if jumpConn then jumpConn:Disconnect() jumpConn = nil end
		if hud then pcall(function() hud.gui:Destroy() end) hud = nil end
		for _, e in ipairs(ents) do
			pcall(function() e.ap:Destroy() end)
			pcall(function() e.ao:Destroy() end)
			pcall(function() e.at:Destroy() end)
			pcall(function() if e.trail then e.trail:Destroy() end end)
			pcall(function() if e.smoke then e.smoke:Destroy() end end)
			ToyKit.FreeSlot(e.slot)
			if e.toy and e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
		end
		table.clear(ents)
	end

	-- ================= spawn / adopt =================
	-- quet ReplicatedStorage tim ten toy that (chua cac tu khoa, khong phan biet hoa thuong)
	local scanCache = {}
	local function scanNames(...)
		local subs = { ... }
		local key = table.concat(subs, "|")
		if scanCache[key] then return scanCache[key] end
		local out, seen = {}, {}
		pcall(function()
			for _, d in ipairs(game:GetService("ReplicatedStorage"):GetDescendants()) do
				if d:IsA("Model") and not seen[d.Name] then
					local ln, ok = d.Name:lower(), true
					for _, sub in ipairs(subs) do
						if not ln:find(sub, 1, true) then ok = false break end
					end
					if ok then seen[d.Name] = true out[#out + 1] = d.Name end
				end
			end
		end)
		scanCache[key] = out
		return out
	end
	local function candidates(kind)
		local list, seen = {}, {}
		local function add(n) if n and not seen[n] then seen[n] = true list[#list + 1] = n end end
		if kind == "BALL" then
			for _, n in ipairs(BALL_NAMES) do add(n) end
			for _, n in ipairs(scanNames("basketball")) do add(n) end
		end
		return list
	end
	local chosen = {}
	local function spawnOne(nm, cf)
		if nm ~= "BALL" then return L12.SpawnToy(nm, cf, 0, true) end
		if chosen[nm] then return L12.SpawnToy(chosen[nm], cf, 0, true) end
		for _, cand in ipairs(candidates(nm)) do
			local ok, tt = pcall(L12.SpawnToy, cand, cf, 0, true)
			if ok and tt then chosen[nm] = cand return tt end
		end
		return nil
	end

	-- danh sach phan "chinh" de lay network owner & giu (thu lan luot den khi duoc)
	local function mainCandidates(toy)
		local list, seen = {}, {}
		local function add(n)
			if n and not seen[n] then
				local c = toy:FindFirstChild(n)
				if c and c:IsA("BasePart") then seen[n] = true list[#list + 1] = n end
			end
		end
		toy:WaitForChild("SoundPart", 0.4)
		add(ToyKit.MAIN[toy.Name])
		add("SoundPart")
		add("VehicleSeat")
		add("Main")
		if toy.PrimaryPart then add(toy.PrimaryPart.Name) end
		for _, c in ipairs(toy:GetChildren()) do
			if c:IsA("BasePart") and c:FindFirstChild("PartOwner") then add(c.Name) end
		end
		for _, c in ipairs(toy:GetChildren()) do
			if c:IsA("BasePart") and #list < 6 then add(c.Name) end
		end
		return list
	end

	local function adopt(toy)
		local function measure(t2, main)
			local ok, c, sz = pcall(function() return t2:GetBoundingBox() end)
			if ok then return { off = c:ToObjectSpace(main.CFrame), size = sz, upL = c:VectorToObjectSpace(Y) } end
			return { off = CFrame.identity, size = Vector3.new(1, 4, 1), upL = Y }
		end
		local e
		for _, mn in ipairs(mainCandidates(toy)) do
			if not toy.Parent then break end
			ToyKit.MAIN[toy.Name] = mn
			e = ToyKit.Hold(toy, "tesla", measure)
			if e then break end
		end
		if not e then return nil end
		e.mainOff = e.info.off
		local sz = e.info.size
		local v, idx = { sz.X, sz.Y, sz.Z }, { 1, 2, 3 }
		table.sort(idx, function(a, b)
			if v[a] ~= v[b] then return v[a] < v[b] end
			return a < b
		end)
		e.ti, e.mi, e.li = idx[1], idx[2], idx[3]
		e.thin, e.mid, e.long = v[e.ti], v[e.mi], v[e.li]
		e.ap.Responsiveness = 200
		return e
	end

	-- huong plate: truc dai doc L, truc mong doc N2
	local function orient(e, L, N2)
		local t = {}
		t[e.li], t[e.ti] = L, N2
		local M = L:Cross(N2)
		t[e.mi] = M
		if t[1]:Cross(t[2]):Dot(t[3]) < 0 then t[e.mi] = -M end
		return CFrame.fromMatrix(Vector3.zero, t[1], t[2], t[3])
	end
	local function bb(e, pos, L, N2) return CFrame.new(pos) * orient(e, L, N2) end

	-- xoay toy sao cho "tren" tu nhien cua no (luc spawn) huong ve U
	local function alignUp(e, U)
		local a = e.info.upL
		local d = math.clamp(a:Dot(U), -1, 1)
		if d > 0.9999 then return CFrame.identity end
		local axis = a:Cross(U)
		if axis.Magnitude < 1e-4 then
			axis = a:Cross(X)
			if axis.Magnitude < 1e-3 then axis = a:Cross(Z) end
		end
		return CFrame.fromAxisAngle(axis.Unit, math.acos(d))
	end
	local function extentUp(e)
		local a, s2 = e.info.upL, e.info.size
		return math.abs(a.X) * s2.X + math.abs(a.Y) * s2.Y + math.abs(a.Z) * s2.Z
	end

	-- ===== ke hoach: 4 bong, 2 campfire, 4 sparkler, con lai pallet =====
	local function plan()
		local p, used = {}, 0
		local function add(n, d)
			local c = COST[n]
			if used + c > S.budget then return false end
			used += c
			p[#p + 1] = { n, d }
			return true
		end
		for i = 1, 4 do add("BALL", { k = "wheel", i = i }) end
		for i = 1, 2 do add("PalletLightBrown", { k = "body", i = i }) end
		for i = 1, 2 do add("Campfire", { k = "pipe", i = i }) end
		for i = 1, 4 do add("FireworkSparkler", { k = "trail", i = i }) end
		for i = 1, 4 do add("FireworkSparkler", { k = "lamp", i = i }) end   -- 2 den pha + 2 den hau
		for i = 1, 2 do add("LadderLightBrown", { k = "rail", i = i }) end   -- 2 thanh hong
		return p, used
	end

	local function wire(e)
		pcall(function() e.at:Destroy() end)
		e.at = Instance.new("Attachment")
		e.at.Parent = e.main
		e.ap.Attachment0 = e.at
		e.ap.Responsiveness = 200
		e.ao = Instance.new("AlignOrientation")
		e.ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
		e.ao.Attachment0 = e.at
		e.ao.MaxTorque = math.huge
		e.ao.Responsiveness = 200
		e.ao.RigidityEnabled = false
		e.ao.Parent = e.main
		e.p0 = e.ap.Position
	end

	local function assemble(home)
		local wheels, pipes, trails, pallets, lamps, rails = {}, {}, {}, {}, {}, {}
		for _, e in ipairs(ents) do
			local k = e.d.k
			if k == "wheel" then wheels[#wheels + 1] = e
			elseif k == "pipe" then pipes[#pipes + 1] = e
			elseif k == "trail" then trails[#trails + 1] = e
			elseif k == "lamp" then lamps[#lamps + 1] = e
			elseif k == "rail" then rails[#rails + 1] = e
			else pallets[#pallets + 1] = e end
		end
		if #wheels < 4 then note("Khong spawn du 4 banh (BallBasketBall) - kiem tra ten toy / plot") return clear() end
		if #pallets < 2 then note("Thieu 2 pallet de lap xe") return clear() end

		local D = 0
		for _, e in ipairs(wheels) do D += math.max(e.info.size.X, e.info.size.Y, e.info.size.Z) end
		D = math.clamp(D / #wheels, 1.5, 9)
		local s = D / 0.68                       -- ti le dung doi km/h (banh that 0.68 m)
		carS = s
		local P = pallets[1]
		local pl, pw, pt = math.max(P.long, 1), math.max(P.mid, 1), math.max(P.thin, 0.2)

		-- 2 pallet noi dau-duoi thanh hinh chu nhat L x W; 4 bong o 4 goc
		local L, W = 2 * pl, pw
		local y0 = D * 0.5                        -- san xe ngang truc banh
		local top = y0 + pt / 2
		local wx, wz = W / 2 + D * 0.2, L / 2 - D * 0.3
		local Lc = L
		local pivotY = y0
		for i, e in ipairs(pallets) do
			local sz = (i == 1) and -1 or 1
			e.loc = bb(e, V(0, y0, sz * pl / 2), Z, Y)
		end
		for i = #pallets, 3, -1 do
			local e = pallets[i]
			for j = #ents, 1, -1 do if ents[j] == e then table.remove(ents, j) break end end
			ToyKit.FreeSlot(e.slot)
			pcall(function() DeleteToyRE:FireServer(e.toy) end)
		end

		-- banh
		local WP = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }
		for i, e in ipairs(wheels) do
			local sx, sz = WP[i][1], WP[i][2]
			e.fn = function(st)
				local yaw = (sz < 0) and -st.steer or 0
				return CFrame.new(sx * wx, D / 2, sz * wz) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(st.spin, 0, 0)
			end
		end
		-- 2 ong bo (Campfire) o duoi xe, phun lua ra sau
		local Up = V(0, 0.3, 1).Unit
		for i, e in ipairs(pipes) do
			local sx = (i == 1) and -1 or 1
			local base = V(sx * W * 0.25, top, L / 2 - 0.3)
			e.loc = CFrame.new(base + Up * (extentUp(e) / 2)) * alignUp(e, Up)
		end
		-- den pha (truoc) / den hau (sau): ben trai dung thang; ben phai nam ngang, dau hong huong sang phai (+X)
		for i, e in ipairs(lamps) do
			local sx = (i % 2 == 1) and -1 or 1
			local sz = (i <= 2) and -1 or 1
			local zz = sz * (L / 2 - 0.4)
			if sx == 1 then
				e.loc = CFrame.new(V(W * 0.25 + e.long / 2, top + 0.5, zz)) * CFrame.Angles(0, -math.rad(90) * LAMP_TURNS, 0) * orient(e, X * LAMP_HEAD, Y)
			else
				e.loc = CFrame.new(V(-W * 0.42, top + extentUp(e) / 2, zz)) * alignUp(e, Y)
			end
		end
		-- 2 thanh hong (da bo can truoc/sau)
		for i, e in ipairs(rails) do
			local sx = (i == 1) and -1 or 1
			e.loc = bb(e, V(sx * (W / 2 - e.mid / 2), top + e.thin / 2, 0), Z, Y)
		end
		-- 4 sparkler duoi 4 banh: chi hien khi lat (trail + khoi)
		local PK = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }
		for i, e in ipairs(trails) do
			local sx, sz = PK[i][1], PK[i][2]
			local R = alignUp(e, Y)
			local live = CFrame.new(sx * wx, -D * 0.15, sz * wz) * R
			local park = CFrame.new(sx * W * 0.15, y0 - pt - 0.3, sz * L * 0.3) * R
			e.fn = function(st) return st.flip and live or park end
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Position, a1.Position = V(0, 0.8, 0), V(0, -0.8, 0)
			a0.Parent, a1.Parent = e.main, e.main
			local tr = Instance.new("Trail")
			tr.Attachment0, tr.Attachment1 = a0, a1
			tr.Lifetime = 0.9
			tr.LightEmission = 1
			tr.FaceCamera = true
			tr.Color = ColorSequence.new(Color3.fromRGB(255, 240, 150), Color3.fromRGB(255, 90, 20))
			tr.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) })
			tr.Enabled = false
			tr.Parent = e.main
			local pe = Instance.new("ParticleEmitter")
			pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
			pe.Rate = 70
			pe.Lifetime = NumberRange.new(0.8, 1.5)
			pe.Speed = NumberRange.new(1, 4)
			pe.SpreadAngle = Vector2.new(180, 180)
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.2), NumberSequenceKeypoint.new(1, 4.5) })
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) })
			pe.Color = ColorSequence.new(Color3.fromRGB(255, 200, 120), Color3.fromRGB(110, 110, 110))
			pe.LightEmission = 0.5
			pe.Enabled = false
			pe.Parent = e.main
			e.trail, e.smoke = tr, pe
		end

		for _, e in ipairs(ents) do wire(e) end
		if #ents == 0 then note("Khong du toy de lap xe") return clear() end

		-- ===== vat ly / lai xe =====
		local hx, hz = wx, wz
		local OFF = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }
		local lastRef = 0
		local function refresh()
			local ig = {}
			if lp.Character then ig[#ig + 1] = lp.Character end
			for _, p in ipairs(Plrs:GetPlayers()) do
				if p ~= lp and p.Character then ig[#ig + 1] = p.Character end
			end
			for _, c in ipairs(workspace:GetChildren()) do
				if c.Name:find("SpawnedInToys$") then ig[#ig + 1] = c end
			end
			for _, e in ipairs(ents) do
				if e.toy.Parent then ig[#ig + 1] = e.toy end
			end
			rp.FilterDescendantsInstances = ig
		end
		refresh()
		local _, root = L12.Char()
		local cl = workspace.CurrentCamera.CFrame.LookVector
		local fw = Vector3.new(cl.X, 0, cl.Z)
		fw = fw.Magnitude > 1e-3 and fw.Unit or V(0, 0, -1)
		local nrm = Y
		local base0 = (S.goHome and home) and home.Position or (root and root.Position or Vector3.zero)
		local hit0 = workspace:Raycast(base0 + V(0, 3, 0), V(0, -60, 0), rp)
		local pos = hit0 and hit0.Position or base0
		local speed, vy, air, flipT, flipDur, dist = 0, 0, false, 0, 1, 0
		local st = { spin = 0, steer = 0, flip = false, ang = 0 }
		local t0, warned = os.clock(), false

		if S.hud then
			hud = buildHud()
		end
		jumpQ = false
		jumpConn = UIS.JumpRequest:Connect(function() jumpQ = true end)

		local function retilt(n2, rate, right)
			local n3 = nrm:Lerp(n2, math.min(1, rate)).Unit
			local rr = right - n3 * right:Dot(n3)
			if rr.Magnitude < 1e-3 then return end
			nrm = n3
			fw = nrm:Cross(rr.Unit)
		end

		local function step(dt)
			dt = math.min(dt, 0.1)
			local ch = lp.Character
			local hum, rt = ch and ch:FindFirstChildOfClass("Humanoid"), ch and ch:FindFirstChild("HumanoidRootPart")
			if not (hum and rt) then return end
			local now = os.clock()
			if now - lastRef > 0.5 then lastRef = now refresh() end
			local cam = workspace.CurrentCamera
			local md, cl2 = hum.MoveDirection, cam.CFrame.LookVector
			local flat = Vector3.new(cl2.X, 0, cl2.Z)
			flat = flat.Magnitude > 1e-3 and flat.Unit or V(0, 0, -1)
			local f, r = math.clamp(md:Dot(flat), -1, 1), math.clamp(md:Dot(flat:Cross(Y)), -1, 1)
			local vmax = math.clamp(S.kmh / 3.6 * s, 10, 420)

			-- ga / phanh (tang toc kieu xe dien: 0-100km/h ~2s o ti le that)
			if not air then
				local tv = f * (f >= 0 and vmax or vmax * 0.3)
				local rate
				if math.abs(f) < 0.05 then rate = 3 * s
				elseif tv * speed < 0 or math.abs(tv) < math.abs(speed) then rate = 24 * s
				else rate = 13 * s * (1 - 0.65 * math.abs(speed) / vmax) end
				speed += math.clamp(tv - speed, -rate * dt, rate * dt)
			end
			-- danh lai (cang nhanh cang it gat)
			local sf = math.clamp(math.abs(speed) / (3 * s), 0, 1) / (1 + 1.2 * math.abs(speed) / vmax)
			local turn = -r * S.turn * sf * (speed >= 0 and 1 or -1) * dt * (air and 0.4 or 1)
			fw = CFrame.fromAxisAngle(nrm, turn):VectorToWorldSpace(fw)
			fw = (fw - nrm * fw:Dot(nrm)).Unit
			local right = fw:Cross(nrm)
			st.steer += (r * 0.5 - st.steer) * math.min(1, dt * 8)

			-- nhay: bay len + lat 360 (backflip)
			if jumpQ then
				jumpQ = false
				if not air and st.ang == 0 then
					air, vy = true, S.jump
					flipDur = 2 * S.jump / S.grav
					flipT = 0
					st.flip = true
				end
			end

			local mv = speed * dt
			if air then
				vy -= S.grav * dt
				flipT += dt
				st.ang = math.min(2 * PI, 2 * PI * flipT / flipDur)
				pos = pos + fw * mv + Y * vy * dt
				if vy < 0 then
					local h = workspace:Raycast(pos + Y * 6, -Y * 80, rp)
					if h and pos.Y <= h.Position.Y + 0.3 then
						pos = Vector3.new(pos.X, h.Position.Y, pos.Z)
						air, vy, st.flip = false, 0, false
					end
				end
			else
				if st.ang > 0 then
					st.ang = math.min(2 * PI, st.ang + dt * 10)
					if st.ang >= 2 * PI then st.ang = 0 end
				end
				if mv ~= 0 then
					local sg = mv >= 0 and 1 or -1
					local w = workspace:Raycast(pos + nrm * (0.5 * s), fw * sg * (Lc / 2 + math.abs(mv) + 1), rp)
					if w and w.Normal.Y < 0.6 then speed, mv = 0, 0 end
				end
				local np = pos + fw * mv
				local c, cnt = {}, 0
				for i, o in ipairs(OFF) do
					local org = np + nrm * 6 + right * (o[1] * hx) + fw * (o[2] * hz)
					local h = workspace:Raycast(org, -nrm * 22, rp)
					if h then c[i] = h.Position cnt += 1 end
				end
				local function heightFrom()
					local mx, sum, n2 = -1e9, 0, 0
					for i = 1, 4 do
						if c[i] then
							local dd = (c[i] - np):Dot(nrm)
							sum += dd n2 += 1
							if dd > mx then mx = dd end
						end
					end
					return mx * 0.6 + (sum / n2) * 0.4
				end
				local function settle(hh)
					hh = math.clamp(hh * math.min(1, dt * 12), -80 * dt, 80 * dt)
					pos = np + nrm * hh
				end
				if cnt >= 3 then
					local nn
					if cnt == 4 then
						nn = (c[4] - c[1]):Cross(c[3] - c[2])
					else
						local pts = {}
						for i = 1, 4 do if c[i] then pts[#pts + 1] = c[i] end end
						nn = (pts[2] - pts[1]):Cross(pts[3] - pts[1])
					end
					if nn.Magnitude > 1e-3 then
						nn = nn.Unit
						if nn:Dot(nrm) < 0 then nn = -nn end
						if nn:Dot(nrm) > 0 then retilt(nn, dt * 9, right) end
					end
					settle(heightFrom())
				elseif cnt > 0 then
					settle(heightFrom())
				else
					local rh = workspace:Raycast(pos + nrm * 100, -nrm * 400, rp)
					if rh and rh.Normal:Dot(nrm) > 0 then
						pos = rh.Position
						retilt(rh.Normal, 1, right)
					else
						pos = np
					end
				end
			end
			dist += math.abs(mv)
			st.spin = (st.spin - mv / (D / 2)) % (2 * PI)

			right = fw:Cross(nrm)
			local H = CFrame.fromMatrix(pos, right, nrm, -fw)
			if st.ang ~= 0 then
				H = H * CFrame.new(0, pivotY, 0) * CFrame.Angles(st.ang, 0, 0) * CFrame.new(0, -pivotY, 0)
			end

			-- nguoi choi ngoi tren 2 pallet
			local pcf = H * CFrame.new(0, top + 3.0, -L * 0.2)
			if pcf.Position == pcf.Position then
				rt.CFrame = pcf
				rt.AssemblyLinearVelocity = Vector3.zero
				rt.AssemblyAngularVelocity = Vector3.zero
			end

			local k = math.clamp((now - t0) / 1.4, 0, 1)
			local ease = k * k * (3 - 2 * k)
			for i = #ents, 1, -1 do
				local e = ents[i]
				if not e.main.Parent then
					table.remove(ents, i)
				else
					local cf = H * (e.loc or e.fn(st)) * e.mainOff
					local p = cf.Position
					if p == p then
						e.ap.Position = ease < 1 and e.p0:Lerp(p, ease) or p
						e.ao.CFrame = cf
					end
					if e.trail and e.trail.Enabled ~= st.flip then
						e.trail.Enabled = st.flip
						e.smoke.Enabled = st.flip
					end
				end
			end
			hudUpdate(dt, speed, air, dist)
		end

		conn = RunSvc.Heartbeat:Connect(function(dt)
			local ok, err = pcall(step, dt)
			if not ok and not warned then
				warned = true
				warn("[Tesla] " .. tostring(err))
			end
		end)
	end

	local function run(token)
		local function ok() return running and token == session end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame
		if _G.PlotPlayerIsOwner then
			pcall(RemovePlotOwner)
			local w = 0
			while ok() and _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		end
		if not ok() then return end
		WingsGoToSafeZone()
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		if not ok() then return end

		local pl, used = plan()
		note("Ke hoach: " .. #pl .. " toy, " .. used .. "/" .. S.budget .. " diem plot")
		local i, n, nilSince, fail = 1, 0, nil, 0
		while ok() and i <= #pl and fail < 25 and not (nilSince and os.clock() - nilSince > 8) do
			local _, r = L12.Char()
			if not r then task.wait(.2) continue end
			local toy = spawnOne(pl[i][1], ToyKit.SpawnCF(r))
			if toy then
				nilSince = nil
				local e = adopt(toy)
				if e then
					fail, e.d = 0, pl[i][2]
					ents[#ents + 1] = e
					i, n = i + 1, n + 1
					if n % 30 == 0 then note("Dang spawn: " .. n .. "/" .. #pl) end
				else
					pcall(function() DeleteToyRE:FireServer(toy) end)
					fail += 1
					task.wait(.15)
				end
			else
				nilSince = nilSince or os.clock()
				task.wait(.25)
			end
		end
		if not ok() then return end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		if S.goHome and homeCF then
			local back = false
			for _ = 1, 8 do
				TeleportPlayer(homeCF)
				task.wait(.15)
				local _, r = L12.Char()
				if r and (r.Position - homeCF.Position).Magnitude < 10 then back = true break end
			end
			note(back and "Da TP ve cho cu" or "TP ve cho cu that bai - xe van build tai cho cu")
		end
		busy = false
		task.wait(.4)
		if not ok() then return end
		if i <= #pl then note("Plot day: " .. n .. "/" .. #pl .. " toy - lap rap ban rut gon") end
		local okA, err = pcall(assemble, homeCF)
		if not okA then warn("[Tesla] " .. tostring(err)) note("Loi lap rap: " .. tostring(err)) end
	end

	TeslaSection:AddToggle({
		Name = "Tesla Roadster",
		Default = false,
		Callback = function(on)
			session += 1
			running = on
			clear()
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then task.spawn(run, session) end
		end,
	})
	TeslaSection:AddSlider({ Name = "Max Speed", Min = 30, Max = 300, Default = S.kmh, Increment = 5, ValueName = "km/h", Callback = function(v) S.kmh = v end })
	TeslaSection:AddSlider({ Name = "Jump Power (Space = bay + lat 360)", Min = 25, Max = 120, Default = S.jump, Increment = 5, ValueName = "", Callback = function(v) S.jump = v end })
	TeslaSection:AddSlider({ Name = "Steering", Min = 0.8, Max = 3.5, Default = S.turn, Increment = 0.1, ValueName = "x", Callback = function(v) S.turn = v end })
	TeslaSection:AddToggle({ Name = "Speedometer HUD", Default = true, Callback = function(v) S.hud = v if hud then hud.gui.Enabled = v end end })
	TeslaSection:AddToggle({ Name = "Release Plot When Done", Default = false, Callback = function(v) S.release = v end })
	TeslaSection:AddLabel("4 bong x15 + 2 pallet x5 + 2 campfire x20 + 8 sparkler x20 + 2 ladder x5")
end
-- ===== BUCKET EXCAVATOR (may xuc banh gau khong lo): xich pallet nhu Tank + than may + co (cot & can) + BANH GAU KHONG LO quay duoc =====
-- Lai bang phim (PC) / nut tren man hinh (mobile), KHONG theo camera: W/S tien lui, A/D quay may, T/G nang-ha (can + cot), X bat/tat quay banh
do
	local S = { speed = 28, turn = 1.2, spin = 3, spinOn = true, budget = 600, goHome = true, release = false, hud = true }
	local N, C, NL, NS = 5, 3, 16, 14      -- than 5 hang x 3 cot, 16 manh xich / ben, 14 doan vanh banh
	local MB = 3                           -- so thang noi nhau tao 1 thanh can (x2 thanh)
	local session, running, busy, homeCF, conn = 0, false, false, nil, nil
	local ents = {}
	local RS, Plrs, UIS, PI = game:GetService("RunService"), game:GetService("Players"), game:GetService("UserInputService"), math.pi
	local lp = Plrs.LocalPlayer
	local X, Y, Z = Vector3.xAxis, Vector3.yAxis, Vector3.zAxis
	local V = Vector3.new
	local COST = { PalletLightBrown = 5, LadderLightBrown = 5 }
	local rp = RaycastParams.new()
	rp.FilterType = Enum.RaycastFilterType.Exclude
	rp.RespectCanCollide = true
	local function note(m) if ctx.notify then ctx.notify(m, "Excavator") end end

	-- ================= input: phim PC + nut mobile (khong phu thuoc camera) =================
	local keys, held, inConns, padGui = {}, {}, {}, nil
	local KEYMAP = {
		[Enum.KeyCode.W] = "fwd", [Enum.KeyCode.Up] = "fwd",
		[Enum.KeyCode.S] = "back", [Enum.KeyCode.Down] = "back",
		[Enum.KeyCode.A] = "left", [Enum.KeyCode.Left] = "left",
		[Enum.KeyCode.D] = "right", [Enum.KeyCode.Right] = "right",
		[Enum.KeyCode.T] = "bup", [Enum.KeyCode.G] = "bdown",
	}
	local function axis(neg, pos)
		local v = 0
		if keys[pos] or held[pos] then v += 1 end
		if keys[neg] or held[neg] then v -= 1 end
		return v
	end
	local spinBtn = nil
	local function refreshSpinBtn()
		if spinBtn then spinBtn.BackgroundColor3 = S.spinOn and Color3.fromRGB(40, 150, 70) or Color3.fromRGB(20, 20, 26) end
	end
	local function buildPad()
		if not UIS.TouchEnabled then return end
		local g = Instance.new("ScreenGui")
		g.Name = "ExcavatorPad"
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 20
		local okp = pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not okp or not g.Parent then g.Parent = lp:WaitForChild("PlayerGui") end
		local function mk(parent, txt, pos, w, h, act, toggle)
			local b = Instance.new("TextButton")
			b.AutoButtonColor = false
			b.Size = UDim2.fromOffset(w, h)
			b.Position = pos
			b.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
			b.BackgroundTransparency = 0.3
			b.Text = txt
			b.TextColor3 = Color3.fromRGB(240, 240, 244)
			b.Font = Enum.Font.GothamBold
			b.TextSize = 18
			b.Parent = parent
			local cr = Instance.new("UICorner") cr.CornerRadius = UDim.new(0.2, 0) cr.Parent = b
			local sk = Instance.new("UIStroke") sk.Thickness = 1.5 sk.Color = Color3.fromRGB(150, 150, 165) sk.Transparency = 0.4 sk.Parent = b
			if toggle then
				b.Activated:Connect(function() S.spinOn = not S.spinOn refreshSpinBtn() end)
			else
				b.InputBegan:Connect(function(i)
					if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
						held[act] = i
						b.BackgroundTransparency = 0.05
					end
				end)
				b.InputEnded:Connect(function(i)
					if held[act] == i then held[act] = nil b.BackgroundTransparency = 0.3 end
				end)
			end
			return b
		end
		local s, gap = 58, 6
		local pad = Instance.new("Frame")
		pad.BackgroundTransparency = 1
		pad.AnchorPoint = Vector2.new(1, 0.5)
		pad.Position = UDim2.new(1, -14, 0.5, 20)
		pad.Size = UDim2.fromOffset(3 * s + 2 * gap, 3 * s + 2 * gap)
		pad.Parent = g
		local st2 = s + gap
		mk(pad, "▲", UDim2.fromOffset(st2, 0), s, s, "fwd")
		mk(pad, "◀", UDim2.fromOffset(0, st2), s, s, "left")
		mk(pad, "▶", UDim2.fromOffset(2 * st2, st2), s, s, "right")
		mk(pad, "▼", UDim2.fromOffset(st2, 2 * st2), s, s, "back")
		local side = Instance.new("Frame")
		side.BackgroundTransparency = 1
		side.AnchorPoint = Vector2.new(0, 0.5)
		side.Position = UDim2.new(0, 14, 0.4, 0)
		side.Size = UDim2.fromOffset(100, 3 * 48 + 2 * gap)
		side.Parent = g
		mk(side, "LIFT ▲", UDim2.fromOffset(0, 0), 100, 48, "bup")
		mk(side, "LIFT ▼", UDim2.fromOffset(0, 48 + gap), 100, 48, "bdown")
		spinBtn = mk(side, "SPIN", UDim2.fromOffset(0, 2 * (48 + gap)), 100, 48, nil, true)
		refreshSpinBtn()
		padGui = g
	end
	-- ================= HUD phim PC: hien bang phim khi bat Excavator, phim sang len khi dang bam =================
	local hudGui, hudPanel, hudStatus, capBtns = nil, nil, nil, {}
	local CAP_OFF, CAP_ON = Color3.fromRGB(28, 28, 36), Color3.fromRGB(40, 150, 70)
	local function refreshCaps()
		for act, b in pairs(capBtns) do
			local on
			if act == "spin" then on = S.spinOn else on = keys[act] or held[act] end
			b.BackgroundColor3 = on and CAP_ON or CAP_OFF
			b.BackgroundTransparency = on and 0.05 or 0.25
		end
	end
	local function destroyHud()
		if hudGui then pcall(function() hudGui:Destroy() end) end
		hudGui, hudPanel, hudStatus = nil, nil, nil
		table.clear(capBtns)
	end
	local function buildHud()
		destroyHud()
		if not UIS.KeyboardEnabled then return end
		local g = Instance.new("ScreenGui")
		g.Name = "ExcavatorKeys"
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 20
		local okp = pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not okp or not g.Parent then g.Parent = lp:WaitForChild("PlayerGui") end
		local K, GAP, PAD, SEP = 44, 5, 12, 22
		local blockW = 3 * K + 2 * GAP
		local panel = Instance.new("Frame")
		panel.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
		panel.BackgroundTransparency = 0.25
		panel.AnchorPoint = Vector2.new(0.5, 1)
		panel.Position = UDim2.new(0.5, 0, 1, -22)
		panel.Size = UDim2.fromOffset(2 * blockW + SEP + 2 * PAD, 26 + 2 * K + GAP + 20 + 2 * PAD)
		panel.Visible = S.hud
		panel.Parent = g
		local pc = Instance.new("UICorner") pc.CornerRadius = UDim.new(0, 10) pc.Parent = panel
		local ps = Instance.new("UIStroke") ps.Thickness = 1.5 ps.Color = Color3.fromRGB(150, 150, 165) ps.Transparency = 0.5 ps.Parent = panel
		local function txt(parent, text, x, y, w, h, size, color, align)
			local l = Instance.new("TextLabel")
			l.BackgroundTransparency = 1
			l.Position = UDim2.fromOffset(x, y)
			l.Size = UDim2.fromOffset(w, h)
			l.Text = text
			l.TextColor3 = color or Color3.fromRGB(200, 200, 210)
			l.Font = Enum.Font.GothamMedium
			l.TextSize = size
			l.TextXAlignment = align or Enum.TextXAlignment.Center
			l.Parent = parent
			return l
		end
		txt(panel, "EXCAVATOR - PHIM DIEU KHIEN", PAD, 6, 2 * blockW + SEP - 90, 16, 12, Color3.fromRGB(240, 240, 244), Enum.TextXAlignment.Left)
		hudStatus = txt(panel, "Dang lap rap...", PAD + 2 * blockW + SEP - 100, 6, 100, 16, 12, Color3.fromRGB(255, 200, 80), Enum.TextXAlignment.Right)
		local function cap(label, x, y, w, act)
			local b = Instance.new("TextButton")
			b.AutoButtonColor = false
			b.Position = UDim2.fromOffset(x, y)
			b.Size = UDim2.fromOffset(w, K)
			b.BackgroundColor3 = CAP_OFF
			b.BackgroundTransparency = 0.25
			b.Text = label
			b.TextColor3 = Color3.fromRGB(240, 240, 244)
			b.Font = Enum.Font.GothamBold
			b.TextSize = 18
			b.Parent = panel
			local cr = Instance.new("UICorner") cr.CornerRadius = UDim.new(0.2, 0) cr.Parent = b
			local sk = Instance.new("UIStroke") sk.Thickness = 1.5 sk.Color = Color3.fromRGB(150, 150, 165) sk.Transparency = 0.4 sk.Parent = b
			if act == "spin" then
				b.Activated:Connect(function() S.spinOn = not S.spinOn refreshSpinBtn() end)
			else
				b.InputBegan:Connect(function(i)
					if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then held[act] = i end
				end)
				b.InputEnded:Connect(function(i) if held[act] == i then held[act] = nil end end)
			end
			capBtns[act] = b
		end
		local top = 26 + PAD - 6
		local x1 = PAD
		local st = K + GAP
		-- khoi WASD (di chuyen)
		cap("W", x1 + st, top, K, "fwd")
		cap("A", x1, top + st, K, "left")
		cap("S", x1 + st, top + st, K, "back")
		cap("D", x1 + 2 * st, top + st, K, "right")
		txt(panel, "W/S: Tien - Lui     A/D: Quay may", x1 - 2, top + 2 * st, blockW + 4, 16, 11)
		-- khoi T / G / X (can + banh gau)
		local x2 = PAD + blockW + SEP
		cap("T", x2, top, K, "bup")
		cap("G", x2 + st, top, K, "bdown")
		cap("X", x2 + 2 * st, top, K, "spin")
		txt(panel, "Nang can", x2 - 6, top + K + 2, K + 12, 14, 11)
		txt(panel, "Ha can", x2 + st - 6, top + K + 2, K + 12, 14, 11)
		txt(panel, "Quay banh", x2 + 2 * st - 8, top + K + 2, K + 16, 14, 11)
		txt(panel, "(co the dung phim mui ten)", x2 - 2, top + 2 * st, blockW + 4, 16, 11, Color3.fromRGB(150, 150, 165))
		hudGui, hudPanel = g, panel
		refreshCaps()
	end

	local function startInput()
		inConns[#inConns + 1] = UIS.InputBegan:Connect(function(i)
			if UIS:GetFocusedTextBox() then return end
			local a = KEYMAP[i.KeyCode]
			if a then keys[a] = true
			elseif i.KeyCode == Enum.KeyCode.X then S.spinOn = not S.spinOn refreshSpinBtn() end
		end)
		inConns[#inConns + 1] = UIS.InputEnded:Connect(function(i)
			local a = KEYMAP[i.KeyCode]
			if a then keys[a] = nil end
			for act, obj in pairs(held) do if obj == i then held[act] = nil end end
		end)
		inConns[#inConns + 1] = RS.RenderStepped:Connect(refreshCaps)
		if hudStatus then hudStatus.Text = "San sang" hudStatus.TextColor3 = Color3.fromRGB(90, 220, 120) end
		buildPad()
	end
	local function stopInput()
		for _, c in ipairs(inConns) do pcall(function() c:Disconnect() end) end
		table.clear(inConns)
		table.clear(keys)
		table.clear(held)
		if padGui then pcall(function() padGui:Destroy() end) padGui = nil end
		spinBtn = nil
	end

	local function clear()
		if conn then conn:Disconnect() conn = nil end
		stopInput()
		destroyHud()
		for _, e in ipairs(ents) do
			pcall(function() e.ap:Destroy() end)
			pcall(function() e.ao:Destroy() end)
			pcall(function() e.at:Destroy() end)
			ToyKit.FreeSlot(e.slot)
			if e.toy and e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
		end
		table.clear(ents)
	end

	-- ================= spawn / adopt (giong Tank) =================
	local function adopt(toy)
		local e = ToyKit.Hold(toy, "excavator", function(t, main)
			local ok, c, sz = pcall(function() return t:GetBoundingBox() end)
			if ok then return { off = c:ToObjectSpace(main.CFrame), size = sz } end
			return { off = CFrame.identity, size = Vector3.new(1, 4, 1) }
		end)
		if not e then return nil end
		e.mainOff = e.info.off
		local sz = e.info.size
		local v, idx = { sz.X, sz.Y, sz.Z }, { 1, 2, 3 }
		table.sort(idx, function(a, b)
			if v[a] ~= v[b] then return v[a] < v[b] end
			return a < b
		end)
		e.ti, e.mi, e.li = idx[1], idx[2], idx[3]
		e.thin, e.mid, e.long = v[e.ti], v[e.mi], v[e.li]
		e.ap.Responsiveness = 200
		return e
	end

	-- huong plate: truc dai doc L, truc mong doc N2
	local function orient(e, L, N2)
		local t = {}
		t[e.li], t[e.ti] = L, N2
		local M = L:Cross(N2)
		t[e.mi] = M
		if t[1]:Cross(t[2]):Dot(t[3]) < 0 then t[e.mi] = -M end
		return CFrame.fromMatrix(Vector3.zero, t[1], t[2], t[3])
	end
	local function bb(e, pos, L, N2) return CFrame.new(pos) * orient(e, L, N2) end

	-- ===== ke hoach (theo do uu tien, het diem plot thi bo phan cuoi): ~570 diem =====
	local function plan()
		local p, used = {}, 0
		local function add(n, d)
			local c = COST[n]
			if used + c > S.budget then return false end
			used += c
			p[#p + 1] = { n, d }
			return true
		end
		local PA, LA = "PalletLightBrown", "LadderLightBrown"
		for r = 0, N - 1 do for c = 0, C - 1 do add(PA, { k = "deck", c = c, r = r }) end end                         -- 15 san
		for i = 0, NL - 1 do for _, sd in ipairs({ 1, -1 }) do add(PA, { k = "lnk", sd = sd, i = i }) end end          -- 32 xich
		for i = 0, NS - 1 do add(PA, { k = "rim", i = i }) end                                                         -- 14 vanh banh
		for i = 0, NS - 1 do add(PA, { k = "bkt", i = i }) end                                                         -- 14 gau
		for _, sx in ipairs({ 1, -1 }) do for j = 1, 2 do add(LA, { k = "mast", sx = sx, j = j }) end end              -- 4 cot
		for _, sx in ipairs({ 1, -1 }) do for j = 1, MB do add(LA, { k = "boom", sx = sx, j = j }) end end             -- 6 can
		for _, sd in ipairs({ 1, -1 }) do for _, r in ipairs({ N - 2, N - 1 }) do for ly = 0, 1 do add(PA, { k = "hwall", sd = sd, r = r, ly = ly }) end end end -- 8 tuong
		for _, r in ipairs({ N - 2, N - 1 }) do for c = 0, C - 1 do add(PA, { k = "roof", c = c, r = r }) end end      -- 6 mai
		for k = 0, 3 do for j = 1, 2 do add(LA, { k = "spk", a = k, j = j }) end end                                    -- 8 nan hoa
		add(PA, { k = "hub" })
		for c = 0, C - 1 do for ly = 0, 1 do add(PA, { k = "cw", c = c, ly = ly }) end end                            -- 6 doi trong
		return p, used
	end

	local function assemble(home)
		local P, Ld
		for _, e in ipairs(ents) do
			if not P and e.toy.Name == "PalletLightBrown" then P = e end
			if not Ld and e.toy.Name == "LadderLightBrown" then Ld = e end
		end
		if not P then note("Thieu pallet de lap may xuc") return clear() end

		local pl, pw, pt = math.max(P.long, 1), math.max(P.mid, 1), math.max(P.thin, 0.2)
		local lL = Ld and math.max(Ld.long, 2) or pl
		local Wh, Lhull = C * pw, N * pl
		-- xich (nhu Tank)
		local R = pl * 0.55
		local Lh = Lhull + pl
		local Pr = 2 * Lh + 2 * PI * R
		local yc = -(R + pt / 2 + 0.1)
		local h0 = 2 * R + pt + 0.15
		local xo = Wh / 2 + pw / 2
		local function cx(c) return (c - (C - 1) / 2) * pw end
		local function rz(r) return (r - (N - 1) / 2) * pl end
		local function trackPoint(s)
			if s < Lh then return Lh / 2 - s, R, 0, 1 end
			if s < Lh + PI * R then
				local a = (s - Lh) / R
				return -Lh / 2 - R * math.sin(a), R * math.cos(a), -math.sin(a), math.cos(a)
			end
			if s < 2 * Lh + PI * R then return -Lh / 2 + (s - Lh - PI * R), -R, 0, -1 end
			local a = (s - 2 * Lh - PI * R) / R
			return Lh / 2 + R * math.sin(a), -R * math.cos(a), math.sin(a), -math.cos(a)
		end

		-- than may (nha dieu khien o phia sau), cot + can o phia truoc
		local yTopDeck = pt / 2
		local yRoof = yTopDeck + 2 * pw + pt          -- mat tren mai
		local zHouse = (rz(N - 2) + rz(N - 1)) / 2
		local zFront = rz(N - 2) - pl / 2
		local zMast = zFront + pl * 0.25
		local Pv = V(0, yRoof + 2 * lL, zMast)        -- diem xoay cua can
		local Lb = MB * lL                            -- do dai can
		-- banh gau
		local Rc = pl / (2 * math.sin(PI / NS))       -- ban kinh dinh (canh vanh = 1 pallet)
		local apo = Rc * math.cos(PI / NS)
		local Ro = Rc + pl * 0.9                      -- ban kinh ngoai (tinh ca gau)
		local TILT = 0.35                             -- gau nghieng ve huong quay (rad)
		local Hp = h0 + Pv.Y                          -- do cao diem xoay so voi mat dat
		local bp0 = math.asin(math.clamp((Ro * 1.05 - Hp) / Lb, -0.95, 0.6))
		local bpMin, bpMax = math.max(bp0 - 0.6, -1.2), math.min(bp0 + 0.9, 1.1)
		local u0 = (bp0 - bpMin) / (bpMax - bpMin)    -- vi tri nang ban dau (0 = thap nhat, 1 = cao nhat)
		local MAST_RANGE = lL * 1.2                    -- cot truot len toi da them bay nhieu khi nang het co

		for i = #ents, 1, -1 do
			local e = ents[i]
			local d, k = e.d, e.d.k
			if k == "deck" then e.static = bb(e, V(cx(d.c), 0, rz(d.r)), Z, Y)
			elseif k == "hwall" then e.static = bb(e, V(d.sd * (Wh / 2 - pt / 2), yTopDeck + pw / 2 + d.ly * pw, rz(d.r)), Z, X)
			elseif k == "roof" then e.static = bb(e, V(cx(d.c), yRoof - pt / 2, rz(d.r)), Z, Y)
			elseif k == "cw" then e.static = bb(e, V(cx(d.c), d.ly * pt * 1.2, Lhull / 2 + pl * 0.4), Z, Y)
			elseif k == "mast" then
				local loc = bb(e, V(d.sx * pw * 0.65, yRoof + lL * (d.j - 0.5), zMast), Y, X)
				e.fn = function(st) return st.mcf * loc end
			elseif k == "lnk" then
				local x, right = d.sd * xo, d.sd == 1
				local base = d.i / NL * Pr
				local par = (d.i % 2 == 0) and 0 or 0.15
				e.fn = function(st)
					local s = (base + (right and st.trR or st.trL)) % Pr
					local z, y, nz, ny = trackPoint(s)
					local nv = V(0, ny, nz)
					return CFrame.new(x, yc + y + ny * par, z + nz * par) * orient(e, V(0, -nz, ny), nv)
				end
			elseif k == "boom" then
				local loc = CFrame.new(d.sx * pw * 0.65, 0, -(lL * (d.j - 0.5))) * orient(e, Z, X)
				e.fn = function(st) return st.bcf * loc end
			elseif k == "rim" then
				local phi = 2 * PI * d.i / NS
				local Rd, T = V(0, math.cos(phi), math.sin(phi)), V(0, -math.sin(phi), math.cos(phi))
				local loc = bb(e, Rd * apo, T, Rd)
				e.fn = function(st) return st.wcf * loc end
			elseif k == "bkt" then
				local phib = 2 * PI * (d.i + 0.5) / NS
				local psi = phib + TILT
				local D, Nn = V(0, math.cos(psi), math.sin(psi)), V(0, -math.sin(psi), math.cos(psi))
				local loc = bb(e, V(0, Rc * math.cos(phib), Rc * math.sin(phib)) + D * (pl * 0.4), D, Nn)
				e.fn = function(st) return st.wcf * loc end
			elseif k == "spk" then
				local th = d.a * PI / 2
				local D = V(0, math.cos(th), math.sin(th))
				local loc = bb(e, D * (lL * (d.j - 0.5)), D, X)
				e.fn = function(st) return st.wcf * loc end
			elseif k == "hub" then
				local loc = bb(e, Vector3.zero, Z, X)
				e.fn = function(st) return st.wcf * loc end
			else
				table.remove(ents, i)
				pcall(function() DeleteToyRE:FireServer(e.toy) end)
				continue
			end
			pcall(function() e.at:Destroy() end)
			e.at = Instance.new("Attachment")
			e.at.Parent = e.main
			e.ap.Attachment0 = e.at
			e.ap.Responsiveness = 200
			e.ao = Instance.new("AlignOrientation")
			e.ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
			e.ao.Attachment0 = e.at
			e.ao.MaxTorque = math.huge
			e.ao.Responsiveness = 200
			e.ao.RigidityEnabled = false
			e.ao.Parent = e.main
			e.p0 = e.ap.Position
		end
		if #ents == 0 then note("Khong du toy de lap may xuc") return clear() end

		-- ===== vat ly: 4 diem treo, nghieng theo dia hinh (nhu Tank) =====
		local OFF = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }
		local hx, hz = xo, Lhull / 2
		local reach = Lh / 2 + R
		local hmid = h0 * 0.6
		local lastRef = 0
		local function refresh()
			local ig = {}
			if lp.Character then ig[#ig + 1] = lp.Character end
			for _, p in ipairs(Plrs:GetPlayers()) do
				if p ~= lp and p.Character then ig[#ig + 1] = p.Character end
			end
			for _, c in ipairs(workspace:GetChildren()) do
				if c.Name:find("SpawnedInToys$") then ig[#ig + 1] = c end
			end
			for _, e in ipairs(ents) do
				if e.toy.Parent then ig[#ig + 1] = e.toy end
			end
			rp.FilterDescendantsInstances = ig
		end
		refresh()
		local _, root = L12.Char()
		local cl = workspace.CurrentCamera.CFrame.LookVector
		local fw = V(cl.X, 0, cl.Z)
		fw = fw.Magnitude > 1e-3 and fw.Unit or V(0, 0, -1)
		local nrm = Y
		local base0 = (S.goHome and home) and home.Position or (root and root.Position or Vector3.zero)
		local hit0 = workspace:Raycast(base0 + V(0, 3, 0), V(0, -60, 0), rp)
		local pos = hit0 and hit0.Position or base0
		local dist, turnAcc = 0, 0
		local vel, tvel = 0, 0
		local st = { trL = 0, trR = 0, u = u0, bp = bp0, wa = 0, ws = 0, mcf = CFrame.identity, bcf = CFrame.identity, wcf = CFrame.identity }
		local t0, warned = os.clock(), false

		local function retilt(n2, rate, right)
			local n3 = nrm:Lerp(n2, math.min(1, rate)).Unit
			local rr = right - n3 * right:Dot(n3)
			if rr.Magnitude < 1e-3 then return end
			nrm = n3
			fw = nrm:Cross(rr.Unit)
		end
		local function pitchDown(a)
			local cs, sn = math.cos(a), math.sin(a)
			local n0, f0 = nrm, fw
			nrm = (n0 * cs + f0 * sn).Unit
			fw = (f0 * cs - n0 * sn).Unit
		end
		local function rollRight(a, right)
			local n2 = (nrm * math.cos(a) + right * math.sin(a)).Unit
			nrm = n2
			fw = (fw - n2 * fw:Dot(n2)).Unit
		end

		startInput()

		local function step(dt)
			dt = math.min(dt, .1)
			local ch = lp.Character
			local hum, rt = ch and ch:FindFirstChildOfClass("Humanoid"), ch and ch:FindFirstChild("HumanoidRootPart")
			if not (hum and rt) then return end
			local now = os.clock()
			if now - lastRef > .5 then lastRef = now refresh() end

			-- lai theo phim / nut (khong theo camera), tang-giam toc mem cho nang
			local f, r = axis("back", "fwd"), axis("left", "right")
			vel += (f * S.speed - vel) * math.min(1, dt * 2.5)
			tvel += (r * S.turn - tvel) * math.min(1, dt * 5)
			local turn = -tvel * dt
			turnAcc -= turn
			fw = CFrame.fromAxisAngle(nrm, turn):VectorToWorldSpace(fw)
			fw = (fw - nrm * fw:Dot(nrm)).Unit
			local right = fw:Cross(nrm)
			local mv = vel * dt
			local sg = mv >= 0 and 1 or -1

			-- nang / ha can, quay banh gau
			st.u = math.clamp(st.u + axis("bdown", "bup") * 0.35 * dt, 0, 1)
			st.bp = bpMin + st.u * (bpMax - bpMin)
			-- banh gau: tang toc DAN khi bat (spool-up), giam toc dan khi tat (spool-down)
			local wt = S.spinOn and S.spin or 0
			local acc = (wt > st.ws) and (0.6 + 0.25 * S.spin) or 1.2
			st.ws += math.clamp(wt - st.ws, -acc * dt, acc * dt)
			st.wa = (st.wa + st.ws * dt) % (2 * PI)

			if math.abs(mv) > 1e-4 then
				local w = workspace:Raycast(pos + nrm * hmid, fw * sg * (reach + 2.5), rp)
				if w and w.Normal.Y > -0.25 then
					local ang = math.acos(math.clamp(nrm:Dot(w.Normal), -1, 1))
					if ang > 0.05 then
						retilt(w.Normal, dt * 3.5, right)
						right = fw:Cross(nrm)
						if ang > 0.5 then mv, vel = 0, 0 end
					end
				end
			end
			if mv ~= 0 then dist += mv end

			local np = pos + fw * mv
			local c, cnt = {}, 0
			for i, o in ipairs(OFF) do
				local org = np + nrm * 6 + right * (o[1] * hx) + fw * (o[2] * hz)
				local h = workspace:Raycast(org, -nrm * 22, rp)
				if h then c[i] = h.Position cnt += 1 end
			end
			local function heightFrom()
				local mx, sum, n2 = -1e9, 0, 0
				for i = 1, 4 do
					if c[i] then
						local dd = (c[i] - np):Dot(nrm)
						sum += dd n2 += 1
						if dd > mx then mx = dd end
					end
				end
				return mx * 0.6 + (sum / n2) * 0.4
			end
			local function settle(hh)
				hh = math.clamp(hh * math.min(1, dt * 12), -80 * dt, 80 * dt)
				pos = np + nrm * hh
			end

			if cnt >= 3 then
				local nn
				if cnt == 4 then
					nn = (c[4] - c[1]):Cross(c[3] - c[2])
				else
					local pts = {}
					for i = 1, 4 do if c[i] then pts[#pts + 1] = c[i] end end
					nn = (pts[2] - pts[1]):Cross(pts[3] - pts[1])
				end
				if nn.Magnitude > 1e-3 then
					nn = nn.Unit
					if nn:Dot(nrm) < 0 then nn = -nn end
					if nn:Dot(nrm) > 0 then retilt(nn, dt * 9, right) end
				end
				settle(heightFrom())
			elseif cnt > 0 then
				local missF = not c[3] and not c[4]
				local missB = not c[1] and not c[2]
				local missL = not c[1] and not c[3]
				local missR = not c[2] and not c[4]
				if missF and not missB then pitchDown(1.6 * dt)
				elseif missB and not missF then pitchDown(-1.6 * dt) end
				if missL and not missR then rollRight(-1.4 * dt, right)
				elseif missR and not missL then rollRight(1.4 * dt, right) end
				settle(heightFrom())
			else
				local rh = workspace:Raycast(pos + nrm * 100, -nrm * 400, rp)
				if rh and rh.Normal:Dot(nrm) > 0 then
					pos = rh.Position
					retilt(rh.Normal, 1, right)
				else
					pos = np
				end
			end

			right = fw:Cross(nrm)
			local H = CFrame.fromMatrix(pos + nrm * h0, right, nrm, -fw)

			st.trR, st.trL = dist - turnAcc * xo, dist + turnAcc * xo
			local mOff = (st.u - u0) * MAST_RANGE
			st.mcf = CFrame.new(0, mOff, 0)
			st.bcf = CFrame.new(Pv + V(0, mOff, 0)) * CFrame.Angles(st.bp, 0, 0)
			st.wcf = st.bcf * CFrame.new(0, 0, -Lb) * CFrame.Angles(st.wa, 0, 0)

			-- nguoi lai ngoi tren mai nha dieu khien
			local pcf = H * CFrame.new(0, yRoof + 3.2, zHouse)
			if pcf.Position == pcf.Position then
				rt.CFrame = pcf
				rt.AssemblyLinearVelocity = Vector3.zero
				rt.AssemblyAngularVelocity = Vector3.zero
			end

			local k = math.clamp((now - t0) / 1.4, 0, 1)
			local ease = k * k * (3 - 2 * k)
			for i = #ents, 1, -1 do
				local e = ents[i]
				if not e.main.Parent then
					table.remove(ents, i)
				else
					local cf = H * (e.static or e.fn(st)) * e.mainOff
					local p = cf.Position
					if p == p then
						e.ap.Position = ease < 1 and e.p0:Lerp(p, ease) or p
						e.ao.CFrame = cf
					end
				end
			end
		end

		conn = RS.Heartbeat:Connect(function(dt)
			local ok, err = pcall(step, dt)
			if not ok and not warned then
				warned = true
				warn("[Excavator] " .. tostring(err))
			end
		end)
	end

	local function run(token)
		local function ok() return running and token == session end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame
		if _G.PlotPlayerIsOwner then
			pcall(RemovePlotOwner)
			local w = 0
			while ok() and _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		end
		if not ok() then return end
		WingsGoToSafeZone()
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		if not ok() then return end

		local pl, used = plan()
		note("Ke hoach: " .. #pl .. " toy, " .. used .. "/" .. S.budget .. " diem plot")
		local i, n, nilSince, fail = 1, 0, nil, 0
		while ok() and i <= #pl and fail < 25 and not (nilSince and os.clock() - nilSince > 8) do
			local _, r = L12.Char()
			if not r then task.wait(.2) continue end
			local toy = L12.SpawnToy(pl[i][1], ToyKit.SpawnCF(r), 0, true)
			if toy then
				nilSince = nil
				local e = adopt(toy)
				if e then
					fail, e.d = 0, pl[i][2]
					ents[#ents + 1] = e
					i, n = i + 1, n + 1
					if n % 40 == 0 then note("Dang spawn: " .. n .. "/" .. #pl) end
				else
					fail += 1
					pcall(function() DeleteToyRE:FireServer(toy) end)
					task.wait(.15)
				end
			else
				nilSince = nilSince or os.clock()
				task.wait(.25)
			end
		end
		if not ok() then return end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		if S.goHome and homeCF then
			local back = false
			for _ = 1, 8 do
				TeleportPlayer(homeCF)
				task.wait(.15)
				local _, r = L12.Char()
				if r and (r.Position - homeCF.Position).Magnitude < 10 then back = true break end
			end
			note(back and "Da TP ve cho cu" or "TP ve cho cu that bai - may xuc van build tai cho cu")
		end
		busy = false
		task.wait(.4)
		if not ok() then return end
		if i <= #pl then note("Plot day: " .. n .. "/" .. #pl .. " toy - lap rap ban rut gon") end
		local okA, err = pcall(assemble, homeCF)
		if not okA then warn("[Excavator] " .. tostring(err)) note("Loi lap rap: " .. tostring(err)) end
	end

	ExcavatorSection:AddToggle({
		Name = "Bucket Excavator",
		Default = false,
		Callback = function(on)
			session += 1
			running = on
			clear()
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then buildHud() task.spawn(run, session) end
		end,
	})
	ExcavatorSection:AddToggle({ Name = "Show Key Hints (PC)", Default = true, Callback = function(v) S.hud = v if hudPanel then hudPanel.Visible = v end end })
	ExcavatorSection:AddSlider({ Name = "Drive Speed", Min = 5, Max = 80, Default = S.speed, Increment = 1, ValueName = "studs/s", Callback = function(v) S.speed = v end })
	ExcavatorSection:AddSlider({ Name = "Turn Speed", Min = 0.3, Max = 3, Default = S.turn, Increment = 0.1, ValueName = "rad/s", Callback = function(v) S.turn = v end })
	ExcavatorSection:AddSlider({ Name = "Wheel Spin Speed", Min = 0, Max = 12, Default = S.spin, Increment = 0.5, ValueName = "rad/s", Callback = function(v) S.spin = v end })
	ExcavatorSection:AddToggle({ Name = "Wheel Spin", Default = true, Callback = function(v) S.spinOn = v refreshSpinBtn() end })
	ExcavatorSection:AddToggle({ Name = "Release Plot When Done", Default = false, Callback = function(v) S.release = v end })
	ExcavatorSection:AddLabel("PC: W/S tien-lui, A/D quay, T/G nang-ha (can + cot), X bat/tat quay banh. Mobile: nut tren man hinh. ~570 diem plot")
end

-- ===== DRAGON MODE v2: rong beo (than/chan/co/dau bang bong tron, chan to), bay vo canh, duoi dai, dau nhin theo chuot + phun lua bang firework =====
-- Toy dung: BALL (BallBasketBall: than, 4 chan beo, co, dau) + Ladder (ham co rang, xuong canh, duoi, sung, gai) + Pallet (mang canh, mui duoi) + FireworkSparkler (mat + tia phun lua) + Campfire (tuy chon)
-- Diem plot: Ball 15, Pallet 5, Ladder 5, Campfire 20, FireworkSparkler 20. Ke hoach tu cat theo uu tien khi vuot budget (mac dinh 580).
-- Dieu khien: W/S tien-lui, A/D quay, Space = cat canh/bay len, Shift/C/Q = ha xuong, F = bay/ha canh, di CHUOT = dau rong quay theo, R (giu) = phun lua toi diem chuot.
-- Mobile: nut tren man hinh, ngam theo giua man hinh (HUD don sac den-trang, co tam ngam).
do
	local S = {
		walk = 32, fly = 80, climb = 45, turn = 2.2, flap = 1, range = 70, rate = 3.5, fat = 1, look = true,
		budget = 580, goHome = true, release = false, hud = true, ride = false, hide = true,
	}
	local COST = { PalletLightBrown = 5, LadderLightBrown = 5, BALL = 15, Campfire = 20, FireworkSparkler = 20 }
	local BALL_NAMES = { "BallBasketBall", "BallBasketball", "BasketBall", "Basketball" }
	local scanCache, chosen = {}, {}
	-- quet ReplicatedStorage tim ten toy that (chua cac tu khoa, khong phan biet hoa thuong)
	local function scanNames(...)
		local subs = { ... }
		local key = table.concat(subs, "|")
		if scanCache[key] then return scanCache[key] end
		local out, seen = {}, {}
		pcall(function()
			for _, d in ipairs(game:GetService("ReplicatedStorage"):GetDescendants()) do
				if d:IsA("Model") and not seen[d.Name] then
					local ln, ok = d.Name:lower(), true
					for _, sub in ipairs(subs) do
						if not ln:find(sub, 1, true) then ok = false break end
					end
					if ok then seen[d.Name] = true out[#out + 1] = d.Name end
				end
			end
		end)
		scanCache[key] = out
		return out
	end
	local function ballCandidates()
		local list, seen = {}, {}
		local function add(n) if n and not seen[n] then seen[n] = true list[#list + 1] = n end end
		for _, n in ipairs(BALL_NAMES) do add(n) end
		for _, n in ipairs(scanNames("basketball")) do add(n) end
		return list
	end
	local function spawnOne(nm, cf)
		if nm ~= "BALL" then return L12.SpawnToy(nm, cf, 0, true) end
		if chosen[nm] then return L12.SpawnToy(chosen[nm], cf, 0, true) end
		for _, cand in ipairs(ballCandidates()) do
			local ok, tt = pcall(L12.SpawnToy, cand, cf, 0, true)
			if ok and tt then chosen[nm] = cand return tt end
		end
		return nil
	end
	local session, running, busy, homeCF, conn = 0, false, false, nil, nil
	local ents = {}
	local RunSvc, Plrs, UIS, PI = game:GetService("RunService"), game:GetService("Players"), game:GetService("UserInputService"), math.pi
	local lp = Plrs.LocalPlayer
	local X, Y, Z = Vector3.xAxis, Vector3.yAxis, Vector3.zAxis
	local V = Vector3.new
	local CF, ANG = CFrame.new, CFrame.Angles
	local rp = RaycastParams.new()
	rp.FilterType = Enum.RaycastFilterType.Exclude
	rp.RespectCanCollide = true
	local function note(m) if ctx.notify then ctx.notify(m, "Dragon") end end

	-- trang thai dung chung giua input / HUD / vong lap
	local G = { flying = false, fire = false, ready = false, platform = false, vy = 0, used = 0, char = nil }
	local keys, held, inConns = {}, {}, {}
	local KEYMAP = {
		[Enum.KeyCode.W] = "fwd", [Enum.KeyCode.Up] = "fwd",
		[Enum.KeyCode.S] = "back", [Enum.KeyCode.Down] = "back",
		[Enum.KeyCode.A] = "left", [Enum.KeyCode.Left] = "left",
		[Enum.KeyCode.D] = "right", [Enum.KeyCode.Right] = "right",
		[Enum.KeyCode.Space] = "up", [Enum.KeyCode.E] = "up",
		[Enum.KeyCode.LeftShift] = "down", [Enum.KeyCode.C] = "down", [Enum.KeyCode.Q] = "down",
		[Enum.KeyCode.R] = "fire",
	}
	local function axis(neg, pos)
		local v = 0
		if keys[pos] or held[pos] then v += 1 end
		if keys[neg] or held[neg] then v -= 1 end
		return v
	end
	local function isDown(a) return (keys[a] or held[a]) and true or false end
	local function setFly(v)
		if not G.ready or v == G.flying then return end
		G.flying = v
		if v then G.vy = math.max(G.vy or 0, S.climb * 0.9) end -- bat dau cat canh: nhun len
	end

	local function startInput()
		inConns[#inConns + 1] = UIS.InputBegan:Connect(function(i)
			if UIS:GetFocusedTextBox() then return end
			local a = KEYMAP[i.KeyCode]
			if a then
				keys[a] = true
				if a == "up" and not G.flying then setFly(true) end
			elseif i.KeyCode == Enum.KeyCode.F then
				setFly(not G.flying)
			end
		end)
		inConns[#inConns + 1] = UIS.InputEnded:Connect(function(i)
			local a = KEYMAP[i.KeyCode]
			if a then keys[a] = nil end
			for act, obj in pairs(held) do
				if obj == i or (i.UserInputType == Enum.UserInputType.MouseButton1 and obj.UserInputType == Enum.UserInputType.MouseButton1) then
					held[act] = nil
				end
			end
		end)
	end
	local function stopInput()
		for _, c in ipairs(inConns) do pcall(function() c:Disconnect() end) end
		table.clear(inConns)
		table.clear(keys)
		table.clear(held)
	end

	-- an avatar (chi phia local; nguoi khac van thay avatar nam trong than rong)
	local hidden = {}
	local function hideAvatar(on)
		if on then
			local ch = lp.Character
			if not ch then return end
			for _, d in ipairs(ch:GetDescendants()) do
				if (d:IsA("BasePart") or d:IsA("Decal")) and hidden[d] == nil then
					hidden[d] = d.Transparency
					d.Transparency = 1
				end
			end
		else
			for d, t in pairs(hidden) do pcall(function() d.Transparency = t end) end
			table.clear(hidden)
		end
	end

	-- ================= HUD don sac (den / trang) =================
	local hud = nil
	local BG, FG, DIM = Color3.fromRGB(10, 10, 10), Color3.fromRGB(245, 245, 245), Color3.fromRGB(140, 140, 140)
	local function destroyHud()
		if hud and hud.gui then pcall(function() hud.gui:Destroy() end) end
		hud = nil
	end
	local function buildHud()
		destroyHud()
		local g = Instance.new("ScreenGui")
		g.Name = "DragonHUD"
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 20
		g.Enabled = S.hud
		local okp = pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not okp or not g.Parent then g.Parent = lp:WaitForChild("PlayerGui") end
		local H = { gui = g }

		local function corner(o, r)
			local c = Instance.new("UICorner")
			c.CornerRadius = r or UDim.new(0, 8)
			c.Parent = o
		end
		local function stroke(o, th, tr)
			local s = Instance.new("UIStroke")
			s.Color = FG
			s.Thickness = th or 1.5
			s.Transparency = tr or 0.25
			s.Parent = o
			return s
		end
		local function label(parent, txt, size, pos, sz, color, align, font)
			local l = Instance.new("TextLabel")
			l.BackgroundTransparency = 1
			l.Text = txt
			l.TextSize = size
			l.Font = font or Enum.Font.GothamMedium
			l.TextColor3 = color or FG
			l.TextXAlignment = align or Enum.TextXAlignment.Left
			l.Position = pos
			l.Size = sz
			l.Parent = parent
			return l
		end

		-- bang trang thai (trai, giua man hinh)
		local panel = Instance.new("Frame")
		panel.Name = "Status"
		panel.AnchorPoint = Vector2.new(0, 0.5)
		panel.Position = UDim2.new(0, 14, 0.5, 0)
		panel.Size = UDim2.fromOffset(178, 148)
		panel.BackgroundColor3 = BG
		panel.BackgroundTransparency = 0.3
		panel.BorderSizePixel = 0
		panel.Parent = g
		corner(panel, UDim.new(0, 10))
		stroke(panel, 1.5, 0.3)
		label(panel, "DRAGON", 16, UDim2.fromOffset(12, 8), UDim2.fromOffset(150, 20), FG, nil, Enum.Font.GothamBold)
		local function row(name, y)
			label(panel, name, 12, UDim2.fromOffset(12, y), UDim2.fromOffset(60, 16), DIM)
			return label(panel, "-", 13, UDim2.fromOffset(72, y), UDim2.fromOffset(94, 16), FG, Enum.TextXAlignment.Right, Enum.Font.GothamBold)
		end
		H.mode, H.alt, H.spd, H.pts = row("MODE", 36), row("ALT", 56), row("SPEED", 76), row("POINTS", 96)
		label(panel, "FIRE", 12, UDim2.fromOffset(12, 120), UDim2.fromOffset(40, 16), DIM)
		local barBg = Instance.new("Frame")
		barBg.Position = UDim2.fromOffset(52, 126)
		barBg.Size = UDim2.fromOffset(114, 5)
		barBg.BackgroundColor3 = DIM
		barBg.BackgroundTransparency = 0.6
		barBg.BorderSizePixel = 0
		barBg.Parent = panel
		corner(barBg, UDim.new(0.5, 0))
		H.bar = Instance.new("Frame")
		H.bar.Size = UDim2.fromScale(0, 1)
		H.bar.BackgroundColor3 = FG
		H.bar.BorderSizePixel = 0
		H.bar.Parent = barBg
		corner(H.bar, UDim.new(0.5, 0))

		-- goi y phim (chi hien khi co ban phim)
		if UIS.KeyboardEnabled then
			local hint = label(g, "W S  MOVE      A D  TURN      SPACE  UP      SHIFT  DOWN      F  FLY / LAND      MOUSE  AIM      R  FIRE", 12,
				UDim2.new(0.5, 0, 1, -10), UDim2.fromOffset(780, 16), DIM, Enum.TextXAlignment.Center)
			hint.AnchorPoint = Vector2.new(0.5, 1)
		end

		-- tam ngam (theo chuot tren PC, giua man hinh tren mobile)
		local ret = Instance.new("Frame")
		ret.Name = "Reticle"
		ret.AnchorPoint = Vector2.new(0.5, 0.5)
		ret.Size = UDim2.fromOffset(30, 30)
		ret.BackgroundTransparency = 1
		ret.Position = UDim2.fromScale(0.5, 0.5)
		ret.Parent = g
		corner(ret, UDim.new(0.5, 0))
		H.retStroke = stroke(ret, 1.5, 0.35)
		local dot = Instance.new("Frame")
		dot.AnchorPoint = Vector2.new(0.5, 0.5)
		dot.Position = UDim2.fromScale(0.5, 0.5)
		dot.Size = UDim2.fromOffset(4, 4)
		dot.BackgroundColor3 = FG
		dot.BorderSizePixel = 0
		dot.Parent = ret
		corner(dot, UDim.new(0.5, 0))
		H.ret = ret

		-- nut bam
		local btns, strokes = {}, {}
		local function mkBtn(name, txt, size, pos, anchor, round)
			local b = Instance.new("TextButton")
			b.Name = name
			b.AutoButtonColor = false
			b.Text = txt
			b.Font = Enum.Font.GothamBold
			b.TextSize = 14
			b.TextColor3 = FG
			b.BackgroundColor3 = BG
			b.BackgroundTransparency = 0.25
			b.BorderSizePixel = 0
			b.AnchorPoint = anchor or Vector2.new(0, 1)
			b.Position = pos
			b.Size = size
			b.Parent = g
			corner(b, round and UDim.new(0.5, 0) or UDim.new(0, 8))
			strokes[name] = stroke(b, 1.5, 0.2)
			btns[name] = b
			return b
		end
		local function paint(b, on)
			b.BackgroundColor3 = on and FG or BG
			b.TextColor3 = on and BG or FG
			b.BackgroundTransparency = on and 0.05 or 0.25
		end
		local function hold(b, act)
			b.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
					held[act] = i
				end
			end)
		end

		-- d-pad (trai duoi)
		local s54 = UDim2.fromOffset(54, 54)
		hold(mkBtn("fwd", "\u{25B2}", s54, UDim2.new(0, 74, 1, -78)), "fwd")
		hold(mkBtn("left", "\u{25C0}", s54, UDim2.new(0, 16, 1, -20)), "left")
		hold(mkBtn("back", "\u{25BC}", s54, UDim2.new(0, 74, 1, -20)), "back")
		hold(mkBtn("right", "\u{25B6}", s54, UDim2.new(0, 132, 1, -20)), "right")

		-- cum nut phai duoi: FIRE (to), FLY, UP, DOWN
		local fire = mkBtn("fire", "FIRE", UDim2.fromOffset(88, 88), UDim2.new(1, -20, 1, -20), Vector2.new(1, 1), true)
		fire.TextSize = 18
		hold(fire, "fire")
		local fly = mkBtn("fly", "FLY", UDim2.fromOffset(62, 62), UDim2.new(1, -118, 1, -24), Vector2.new(1, 1), true)
		fly.Activated:Connect(function() setFly(not G.flying) end)
		hold(mkBtn("up", "UP", UDim2.fromOffset(66, 46), UDim2.new(1, -32, 1, -176), Vector2.new(1, 1)), "up")
		hold(mkBtn("down", "DOWN", UDim2.fromOffset(66, 46), UDim2.new(1, -32, 1, -118), Vector2.new(1, 1)), "down")
		-- nut UP tren man hinh cung cat canh khi dang di bo
		btns.up.InputBegan:Connect(function(i)
			if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not G.flying then setFly(true) end
		end)

		function H.update(info)
			H.mode.Text = info.mode
			H.alt.Text = string.format("%d", info.alt)
			H.spd.Text = string.format("%d", info.spd)
			H.pts.Text = info.pts
			if info.mx then
				H.ret.Position = UDim2.fromOffset(info.mx, info.my)
				H.ret.Size = UDim2.fromOffset(30 + 16 * info.fireK, 30 + 16 * info.fireK)
				H.retStroke.Thickness = 1.5 + 2 * info.fireK
				H.ret.Visible = S.look or info.fireK > 0.05
			end
			H.bar.Size = UDim2.fromScale(math.clamp(info.fireK, 0, 1), 1)
			paint(fire, info.fireK > 0.5)
			strokes.fire.Thickness = 1.5 + 3 * info.fireK
			paint(fly, G.flying)
			for _, n in ipairs({ "fwd", "left", "back", "right", "up", "down" }) do
				local a = n
				paint(btns[n], keys[a] or held[a])
			end
		end
		hud = H
		return H
	end
	local function hudMsg(m) if hud then hud.mode.Text = m end end

	local function clear()
		if conn then conn:Disconnect() conn = nil end
		stopInput()
		destroyHud()
		for _, e in ipairs(ents) do
			pcall(function() e.ap:Destroy() end)
			pcall(function() e.ao:Destroy() end)
			pcall(function() e.at:Destroy() end)
			ToyKit.FreeSlot(e.slot)
			if e.toy and e.toy.Parent then pcall(function() DeleteToyRE:FireServer(e.toy) end) end
		end
		table.clear(ents)
		pcall(function() if G.imp then G.imp.part:Destroy() end end)
		G.imp = nil
		pcall(hideAvatar, false)
		if G.platform then
			local _, _, hum = L12.Char()
			if hum then pcall(function() hum.PlatformStand = false end) end
		end
		G.platform, G.ready, G.flying, G.fire, G.vy, G.char = false, false, false, false, 0, nil
	end

	-- ================= spawn / adopt (giong Tesla: thu lan luot cac part chinh de lay network owner) =================
	local function mainCandidates(toy)
		local list, seen = {}, {}
		local function add(n)
			if n and not seen[n] then
				local c = toy:FindFirstChild(n)
				if c and c:IsA("BasePart") then seen[n] = true list[#list + 1] = n end
			end
		end
		toy:WaitForChild("SoundPart", 0.4)
		add(ToyKit.MAIN[toy.Name])
		add("SoundPart")
		add("Stick")
		add("Main")
		if toy.PrimaryPart then add(toy.PrimaryPart.Name) end
		for _, c in ipairs(toy:GetChildren()) do
			if c:IsA("BasePart") and c:FindFirstChild("PartOwner") then add(c.Name) end
		end
		for _, c in ipairs(toy:GetChildren()) do
			if c:IsA("BasePart") and #list < 6 then add(c.Name) end
		end
		return list
	end

	local function adopt(toy)
		local function measure(t2, main)
			local ok, c, sz = pcall(function() return t2:GetBoundingBox() end)
			if ok then return { off = c:ToObjectSpace(main.CFrame), size = sz, upL = c:VectorToObjectSpace(Y) } end
			return { off = CFrame.identity, size = Vector3.new(1, 4, 1), upL = Y }
		end
		local e
		for _, mn in ipairs(mainCandidates(toy)) do
			if not toy.Parent then break end
			ToyKit.MAIN[toy.Name] = mn
			e = ToyKit.Hold(toy, "dragon", measure)
			if e then break end
		end
		if not e then return nil end
		e.mainOff = e.info.off
		local sz = e.info.size
		local v, idx = { sz.X, sz.Y, sz.Z }, { 1, 2, 3 }
		table.sort(idx, function(a, b)
			if v[a] ~= v[b] then return v[a] < v[b] end
			return a < b
		end)
		e.ti, e.mi, e.li = idx[1], idx[2], idx[3]
		e.thin, e.mid, e.long = v[e.ti], v[e.mi], v[e.li]
		e.ap.Responsiveness = 200
		return e
	end

	-- huong plate: truc dai doc L, truc mong doc N2 (tra ve CFrame chi co xoay)
	local function orient(e, L, N2)
		local t = {}
		t[e.li], t[e.ti] = L, N2
		local M = L:Cross(N2)
		t[e.mi] = M
		if t[1]:Cross(t[2]):Dot(t[3]) < 0 then t[e.mi] = -M end
		return CFrame.fromMatrix(Vector3.zero, t[1], t[2], t[3])
	end
	-- xoay toy sao cho "tren" tu nhien cua no huong ve U
	local function alignUp(e, U)
		local a = e.info.upL
		local d = math.clamp(a:Dot(U), -1, 1)
		if d > 0.9999 then return CFrame.identity end
		local ax = a:Cross(U)
		if ax.Magnitude < 1e-4 then
			ax = a:Cross(X)
			if ax.Magnitude < 1e-3 then ax = a:Cross(Z) end
		end
		return CFrame.fromAxisAngle(ax.Unit, math.acos(d))
	end
	local function extentUp(e)
		local a, s2 = e.info.upL, e.info.size
		return math.abs(a.X) * s2.X + math.abs(a.Y) * s2.Y + math.abs(a.Z) * s2.Z
	end
	local function mirror(cf) -- doi xung qua mat phang YZ (canh trai tu canh phai)
		local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
		return CFrame.new(-x, y, z, r00, -r01, -r02, -r10, r11, r12, -r20, r21, r22)
	end

	local function wire(e)
		pcall(function() e.at:Destroy() end)
		e.at = Instance.new("Attachment")
		e.at.Parent = e.main
		e.ap.Attachment0 = e.at
		e.ap.Responsiveness = 200
		e.ao = Instance.new("AlignOrientation")
		e.ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
		e.ao.Attachment0 = e.at
		e.ao.MaxTorque = math.huge
		e.ao.Responsiveness = 200
		e.ao.RigidityEnabled = false
		e.ao.Parent = e.main
		e.p0 = e.ap.Position
	end

	-- ===== KE HOACH + TINH DIEM (theo do uu tien; het budget thi bo phan cuoi) =====
	-- BALL 15, Pallet 5, Ladder 5, Campfire 20, Firework 20  (BALL = BallBasketBall, tron nen than/chan/co/dau bau, het vuong)
	--   than 8 bong (2 / tram x 4) = 120 | 4 chan beo (dui + ban chan = 8 bong) = 120 | co 3 bong = 45 | dau 2 bong = 30
	--   ham tren + ham duoi (2 ladder, rang) = 10 | 2 mat firework = 40 | 3 firework phun lua = 60
	--   2 canh (2 ladder + 4 pallet moi ben) = 60 | duoi 2 bong + 5 ladder + 2 pallet mui = 65 | 2 sung = 10 | 4 gai lung = 20
	--   TONG = 580 (nang Point Budget len 600 de them 1 campfire o mieng)
	local function plan()
		local p, used = {}, 0
		local function add(n, d)
			local c = COST[n]
			if used + c > S.budget then return false end
			used += c
			p[#p + 1] = { n, d }
			return true
		end
		local PA, LA, FW, CP, BL = "PalletLightBrown", "LadderLightBrown", "FireworkSparkler", "Campfire", "BALL"
		for i = 1, 4 do for _, sd in ipairs({ 1, -1 }) do add(BL, { k = "tb", s = sd, i = i }) end end   -- than: 2 bong / tram
		for n = 1, 4 do add(BL, { k = "lu", i = n }) add(BL, { k = "ll", i = n }) end                    -- 4 chan beo: dui + ban chan
		for j = 1, 3 do add(BL, { k = "nk", i = j }) end                                                  -- co
		add(BL, { k = "hd", i = 1 }) add(BL, { k = "hd", i = 2 })                                         -- so + mom
		add(LA, { k = "uj", i = 1 }) add(LA, { k = "lj", i = 1 })                                         -- ham tren / ham duoi (rang)
		for _, sd in ipairs({ 1, -1 }) do add(FW, { k = "ey", s = sd, i = 1 }) end                        -- mat (tia lua)
		for i = 1, 3 do add(FW, { k = "br", i = i }) end                                                  -- phun lua
		for j = 1, 2 do for _, sd in ipairs({ 1, -1 }) do add(LA, { k = "wb", s = sd, i = j }) end end   -- xuong canh
		for m = 1, 4 do for _, sd in ipairs({ 1, -1 }) do add(PA, { k = "wp", s = sd, i = m }) end end   -- mang canh
		for i = 1, 2 do add(BL, { k = "tp", i = i }) end                                                  -- goc duoi (bong)
		for _, sd in ipairs({ 1, -1 }) do add(LA, { k = "hn", s = sd, i = 1 }) end                        -- sung
		for i = 1, 5 do add(LA, { k = "tq", i = i }) end                                                  -- duoi (ladder)
		for i = 1, 4 do add(LA, { k = "sp", i = i }) end                                                  -- gai lung
		for _, sd in ipairs({ 1, -1 }) do add(PA, { k = "tip", s = sd, i = 1 }) end                       -- mui duoi
		add(CP, { k = "fm", i = 1 })                                                                      -- lua o mieng (chi khi budget >= 600)
		return p, used
	end

	-- xoay toy: truc dai doc `dir`, truc mong vuong goc voi dir (gan nhat voi `upv`)
	local function along(e, dir, upv)
		local n2 = upv - dir * dir:Dot(upv)
		if n2.Magnitude < 1e-3 then n2 = X - dir * dir:Dot(X) end
		if n2.Magnitude < 1e-3 then n2 = Z - dir * dir:Dot(Z) end
		return orient(e, dir, n2.Unit)
	end

	local function assemble(home)
		-- gom toy theo vai tro
		local R, P, Ld, balls = {}, nil, nil, {}
		local BALLK = { tb = true, lu = true, ll = true, nk = true, hd = true, tp = true }
		for _, e in ipairs(ents) do
			local d = e.d
			if not P and e.toy.Name == "PalletLightBrown" then P = e end
			if not Ld and e.toy.Name == "LadderLightBrown" then Ld = e end
			if BALLK[d.k] then balls[#balls + 1] = e end
			local t = R[d.k]
			if not t then t = {} R[d.k] = t end
			if d.s then
				local ts = t[d.s]
				if not ts then ts = {} t[d.s] = ts end
				ts[d.i] = e
			else
				t[d.i] = e
			end
		end
		if #ents == 0 then note("Khong du toy de lap rong") return clear() end
		if #balls == 0 then note("Khong spawn duoc bong (BallBasketBall) - than rong se thieu, kiem tra ten toy / plot") end
		local function get(k, s, i)
			local t = R[k]
			if not t then return nil end
			if s then
				t = t[s]
				if not t then return nil end
			end
			return t[i or 1]
		end

		-- kich thuoc theo toy that: u = duong kinh bong (don vi chinh), pallet/ladder chi dung cho canh, duoi, ham, sung, gai
		local u = 0
		for _, e in ipairs(balls) do u += math.max(e.info.size.X, e.info.size.Y, e.info.size.Z) end
		if #balls > 0 then u = u / #balls else u = (P and P.mid or 3) * 0.6 end
		u = math.clamp(u, 1.2, 8)
		local pl = P and math.clamp(P.long, 1.5, 14) or u * 2
		local pw = P and math.clamp(P.mid, 1.5, 14) or u * 1.6
		local lL = Ld and math.clamp(Ld.long, 2, 16) or u * 2.5
		local lt = Ld and math.clamp(Ld.thin, 0.2, 3) or 0.4

		-- bo cuc co the (don vi u): 4 tram than x 2 bong, chan to nam duoi hong, co cong ve truoc
		local sp = u * 0.88
		local zs = { -1.5 * sp, -0.5 * sp, 0.5 * sp, 1.5 * sp }
		local hipY, l1, stand = -u * 0.15, u * 0.95, u * 1.45
		local groundOff = -hipY + stand
		local zFH, zRH = -sp * 1.15, sp * 1.15
		local LEG = { { 1, zFH, 0 }, { -1, zFH, PI }, { 1, zRH, PI }, { -1, zRH, 0 } } -- FR, FL, BR, BL (trot cheo)
		local nb = V(0, u * 0.3, -sp * 1.3)       -- goc co (tren nguc)
		local Ln = u * 2.4
		local NT = { 0.26, 0.54, 0.80 }           -- vi tri 3 bong co doc duong cong
		local reach = u * 2.4
		local probe = sp * 1.3

		local nbr = 0
		for _ in pairs(R.br or {}) do nbr += 1 end
		nbr = math.max(nbr, 1)

		-- diem that su da dung
		local usedReal = 0
		for _, e in ipairs(ents) do usedReal += e.cost or 0 end
		G.used = usedReal

		-- hieu ung lua cho cac firework phun: Trail + hat lua + tia lua. Chi bat khi phun.
		for _, e in pairs(R.br or {}) do
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Position, a1.Position = V(0, 0.6, 0), V(0, -0.6, 0)
			a0.Parent, a1.Parent = e.main, e.main
			local tr = Instance.new("Trail")
			tr.Attachment0, tr.Attachment1 = a0, a1
			tr.Lifetime = 0.5
			tr.LightEmission = 1
			tr.FaceCamera = true
			tr.Color = ColorSequence.new(Color3.fromRGB(255, 235, 140), Color3.fromRGB(255, 70, 10))
			tr.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
			tr.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 2.2), NumberSequenceKeypoint.new(1, 0) })
			tr.Enabled = false
			tr.Parent = e.main
			local pe = Instance.new("ParticleEmitter")
			pe.Texture = "rbxasset://textures/particles/fire_main.dds"
			pe.Rate = 160
			pe.Lifetime = NumberRange.new(0.3, 0.6)
			pe.Speed = NumberRange.new(3, 10)
			pe.SpreadAngle = Vector2.new(28, 28)
			pe.LightEmission = 1
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 3), NumberSequenceKeypoint.new(1, 0) })
			pe.Color = ColorSequence.new(Color3.fromRGB(255, 220, 90), Color3.fromRGB(255, 60, 0))
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) })
			pe.Enabled = false
			pe.Parent = e.main
			local em = Instance.new("ParticleEmitter")
			em.Texture = "rbxasset://textures/particles/sparkles_main.dds"
			em.Rate = 70
			em.Lifetime = NumberRange.new(0.4, 0.9)
			em.Speed = NumberRange.new(10, 26)
			em.SpreadAngle = Vector2.new(45, 45)
			em.LightEmission = 1
			em.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.7), NumberSequenceKeypoint.new(1, 0) })
			em.Color = ColorSequence.new(Color3.fromRGB(255, 240, 160), Color3.fromRGB(255, 120, 20))
			em.Enabled = false
			em.Parent = e.main
			e.trail, e.fx, e.em = tr, pe, em
		end

		for _, e in ipairs(ents) do wire(e) end

		-- diem chay khi lua cham muc tieu (chi hien o may minh): lua + khoi + anh sang
		do
			pcall(function() if G.imp then G.imp.part:Destroy() end end)
			local ip = Instance.new("Part")
			ip.Name = "DragonImpact"
			ip.Anchored, ip.CanCollide, ip.CanQuery, ip.CanTouch = true, false, false, false
			ip.Transparency = 1
			ip.Size = V(1, 1, 1)
			ip.Parent = workspace
			local f1 = Instance.new("ParticleEmitter")
			f1.Texture = "rbxasset://textures/particles/fire_main.dds"
			f1.Rate = 90
			f1.Lifetime = NumberRange.new(0.4, 0.9)
			f1.Speed = NumberRange.new(4, 12)
			f1.SpreadAngle = Vector2.new(70, 70)
			f1.LightEmission = 1
			f1.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 4), NumberSequenceKeypoint.new(1, 0) })
			f1.Color = ColorSequence.new(Color3.fromRGB(255, 200, 70), Color3.fromRGB(255, 50, 0))
			f1.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) })
			f1.Enabled = false
			f1.Parent = ip
			local f2 = Instance.new("ParticleEmitter")
			f2.Texture = "rbxasset://textures/particles/smoke_main.dds"
			f2.Rate = 25
			f2.Lifetime = NumberRange.new(0.9, 1.6)
			f2.Speed = NumberRange.new(3, 8)
			f2.SpreadAngle = Vector2.new(35, 35)
			f2.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 2), NumberSequenceKeypoint.new(1, 7) })
			f2.Color = ColorSequence.new(Color3.fromRGB(70, 60, 55))
			f2.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 1) })
			f2.Enabled = false
			f2.Parent = ip
			local lg = Instance.new("PointLight")
			lg.Color = Color3.fromRGB(255, 140, 50)
			lg.Range = 18
			lg.Brightness = 3
			lg.Enabled = false
			lg.Parent = ip
			G.imp = { part = ip, fire = f1, smoke = f2, light = lg }
		end

		-- ===== raycast filter =====
		local lastRef = 0
		local function refresh()
			local ig = {}
			if lp.Character then ig[#ig + 1] = lp.Character end
			for _, p in ipairs(Plrs:GetPlayers()) do
				if p ~= lp and p.Character then ig[#ig + 1] = p.Character end
			end
			for _, c in ipairs(workspace:GetChildren()) do
				if c.Name:find("SpawnedInToys$") then ig[#ig + 1] = c end
			end
			for _, e in ipairs(ents) do
				if e.toy.Parent then ig[#ig + 1] = e.toy end
			end
			if G.imp and G.imp.part then ig[#ig + 1] = G.imp.part end
			rp.FilterDescendantsInstances = ig
		end
		refresh()
		local function groundAt(p)
			local r = workspace:Raycast(V(p.X, p.Y + 6, p.Z), V(0, -900, 0), rp)
			return r and r.Position.Y or nil
		end

		-- ===== trang thai =====
		local _, root = L12.Char()
		local cl = workspace.CurrentCamera.CFrame.LookVector
		local fw0 = V(cl.X, 0, cl.Z)
		fw0 = fw0.Magnitude > 1e-3 and fw0.Unit or V(0, 0, -1)
		local h = math.atan2(-fw0.X, -fw0.Z)                 -- forward = (-sin h, 0, -cos h)
		local base0 = (S.goHome and home) and home.Position or (root and root.Position or Vector3.zero)
		local g0 = groundAt(base0)
		local pos = V(base0.X, (g0 or base0.Y) + groundOff, base0.Z)
		local speed, pitch, roll = 0, 0, 0
		G.vy, G.flying, G.fire = 0, false, false
		local st = {
			gait = 0, ph = 0, fr = 0.5, am = 0.06, foldK = 1, flyK = 0, amp = 0, bob = 0,
			a0 = -0.25, a1 = 0, a2 = 0, sw = 1.1, el = 1.0,
			jaw = 0, fireK = 0, charge = 0, tailAmp = 0.1, tph = 0, tpit = 0.2, hp = 0,
			yaw = 0, pit = -0.18, speed = 0, dip = 0, burst = 0, wasFly = false, wasGround = true,
			A = Vector3.zero, hasA = false, headL = nb + V(0, Ln * 0.7, -Ln * 0.6),
			fireOn = false, hit = false, impL = Vector3.zero,
		}
		local t0, warned = os.clock(), false

		-- ===== TU THE (tinh lai moi frame, toa do cuc bo cua than; Hc = CFrame than trong the gioi) =====
		local function pose(t, Hc)
			local e
			local f = st.flyK
			local fat = S.fat
			local tx, legX = u * 0.45 * fat, u * 0.62 * fat
			local ch = st.charge
			local breath = math.sin(t * 1.7)
			local pull = ch * (1 - st.jaw)                        -- hit vao truoc khi phun (nguc phong, dau ngua len)

			-- than: 4 tram x 2 bong, tho nhip nhang + phong nguc khi nap hoi
			local spread = 1 + 0.025 * breath + 0.14 * ch
			for i = 1, 4 do
				local lift = (0.02 * breath + (i <= 2 and 0.07 or 0.03) * ch) * u
				for _, sd in ipairs({ 1, -1 }) do
					e = get("tb", sd, i)
					if e then e.loc = CF(sd * tx * spread, lift, zs[i]) end
				end
			end

			-- 4 chan beo: dui + ban chan (bong), IK 2 doan, trot cheo khi di / gap lai khi bay / nhun xuong khi ha canh
			local amp = st.amp
			local crouch = st.dip - st.bob * (1 - f)
			for n = 1, 4 do
				local c = LEG[n]
				local ph = st.gait + c[3]
				local stride = u * 0.75 * amp
				local lift = math.max(0, math.sin(ph)) * u * 0.5 * amp
				local dz = (stride * math.cos(ph)) * (1 - f) + (u * 0.55) * f
				local dy = (-stand + lift + crouch) * (1 - f) + (-u * 0.95) * f
				local mag = math.max(math.sqrt(dz * dz + dy * dy), 1e-3)
				local tz, ty = dz / mag, dy / mag
				local dd = math.clamp(mag, u * 0.4, 2 * l1 - u * 0.05)
				local hk = math.sqrt(math.max(l1 * l1 - dd * dd / 4, 0))
				local pz, py = -ty, tz
				if pz > 0 then pz, py = -pz, -py end           -- goi luon cong ve truoc
				local kz, ky = tz * dd / 2 + pz * hk, ty * dd / 2 + py * hk
				local fz, fy = tz * dd, ty * dd
				local hx, hz = c[1] * legX, c[2]
				e = get("lu", nil, n)
				if e then e.loc = CF(hx, hipY + ky * 0.62, hz + kz * 0.62) end
				e = get("ll", nil, n)
				if e then e.loc = CF(hx * (1 + 0.06 * (1 - f)), hipY + fy + u * 0.5, hz + fz) end
			end

			-- co (3 bong doc duong cong) + dau nhin dung huong chuot
			local yaw, pit = st.yaw, st.pit
			local up = Ln * (0.70 - 0.35 * f) + pit * u * 0.3 + u * 0.35 * pull
			local fwd = Ln * (0.60 + 0.30 * f) - u * 0.3 * pull + u * 0.35 * st.jaw
			local P0 = nb
			local P2 = (CF(nb) * ANG(0, yaw * 0.55, 0) * CF(0, up, -fwd)).Position
			local P1 = (CF(nb) * ANG(0, yaw * 0.3, 0) * CF(0, up * 1.15, -fwd * 0.08)).Position
			for j = 1, 3 do
				e = get("nk", nil, j)
				if e then
					local tt = NT[j]
					local a, b = (1 - tt) * (1 - tt), 2 * (1 - tt) * tt
					e.loc = CF(P0 * a + P1 * b + P2 * (tt * tt))
				end
			end
			st.headL = P2

			-- dau: so + mom (bong), ham tren / ham duoi (ladder co rang, ham duoi mo khi phun), mat, sung
			local HF = CF(P2) * ANG(0, yaw, 0) * ANG(pit + st.hp + 0.3 * pull, 0, 0)
			e = get("hd", nil, 1) if e then e.loc = HF end
			e = get("hd", nil, 2) if e then e.loc = HF * CF(0, -0.2 * u, -0.78 * u) end
			local jawA = st.jaw * 0.5 + st.charge * 0.06
			e = get("uj", nil, 1)
			if e then
				local fore = math.min(e.long, 2.4 * u)
				e.loc = HF * CF(0, -0.1 * u, -fore + e.long / 2) * orient(e, Z, Y)
			end
			e = get("lj", nil, 1)
			if e then
				local fore = math.min(e.long, 2.05 * u)
				local JF = HF * CF(0, -0.45 * u, -0.1 * u) * ANG(-jawA, 0, 0)
				e.loc = JF * CF(0, 0, -fore + e.long / 2) * orient(e, Z, Y)
			end
			for _, sd in ipairs({ 1, -1 }) do
				e = get("ey", sd, 1)
				if e then e.loc = HF * CF(sd * 0.3 * u, 0.3 * u, -0.25 * u - extentUp(e) / 2) * alignUp(e, -Z) end
				e = get("hn", sd, 1)
				if e then
					local dir = V(sd * 0.3, 0.55 + 0.05 * breath, 0.8).Unit
					e.loc = HF * CF(V(sd * 0.3 * u, 0.3 * u, 0.1 * u) + dir * (e.long * 0.4)) * along(e, dir, Y)
				end
			end
			e = get("fm", nil, 1)
			if e then e.loc = HF * CF(0, -0.3 * u + extentUp(e) / 2, -1.2 * u) * alignUp(e, Y) end

			-- PHUN LUA: tu mieng ra dung diem chuot (dau da quay toi do), cac firework ban di-ve doc tia lua
			local MO = HF * CF(0, -0.28 * u, -1.8 * u)
			local mp = MO.Position
			local headFwd = HF.LookVector
			local dirL, len = headFwd, S.range
			st.hit = false
			if st.hasA then
				local toT = Hc:PointToObjectSpace(st.A) - mp
				local dist = toT.Magnitude
				local tu = dist > 1e-3 and toT / dist or headFwd
				local err = math.acos(math.clamp(headFwd:Dot(tu), -1, 1))
				local w = math.clamp(1 - (err - 0.05) / 0.35, 0, 1)    -- dau gan dung huong thi tia lua khop chinh xac vao muc tieu
				local dv = headFwd * (1 - w) + tu * w
				if dv.Magnitude > 1e-3 then dirL = dv.Unit end
				len = S.range * (1 - w) + math.min(S.range, dist) * w
				st.hit = w > 0.5 and dist <= S.range * 1.02
			end
			local on = G.fire and st.charge > 0.7
			st.fireOn = on
			st.impL = mp + dirL * len
			local side = dirL:Cross(Y)
			if side.Magnitude < 0.1 then side = X end
			side = side.Unit
			local upv = side:Cross(dirL).Unit
			for i, be in pairs(R.br or {}) do
				if on then
					local uu = (t * S.rate + (i - 1) / nbr) % 1
					local s = uu < 0.5 and uu * 2 or (1 - uu) * 2
					local lat = (i - (nbr + 1) / 2) * 0.08 * len * s
					local vert = math.sin(t * 17 + i * 2.1) * 0.03 * len * s
					be.loc = CF(mp + dirL * (len * s) + side * lat + upv * vert) * along(be, dirL, upv)
				else
					be.loc = HF * CF((i - (nbr + 1) / 2) * 0.22 * u, -0.1 * u, -0.5 * u) * orient(be, Z, Y)
				end
				if be.trail and be.trail.Enabled ~= on then
					be.trail.Enabled = on
					be.fx.Enabled = on
					if be.em then be.em.Enabled = on end
				end
			end

			-- gai lung (ladder nam doc song lung, ngat ve sau, gon song khi bay)
			for i = 1, 4 do
				e = get("sp", nil, i)
				if e then
					local wob = 0.07 * math.sin(t * 2.2 - i * 0.7) * (0.3 + f)
					local dir = V(0, math.sin(0.5 + wob), math.cos(0.5 + wob))
					local base = V(0, u * 0.45 + 0.02 * u * breath, (-1.2 + (i - 1) * 0.8) * u)
					e.loc = CF(base + dir * (e.long * 0.35)) * along(e, dir, X)
				end
			end

			-- 2 canh: xuong canh (ladder) + mang (pallet) co tre pha de gon song
			local b1, b2 = lL, lL
			local F0 = CF(tx * 0.9, 0.42 * u, -0.45 * u) * ANG(0, 0, st.a0) * ANG(0, -st.sw, 0)
			local F1 = F0 * CF(b1, 0, 0) * ANG(0, -st.el, st.a1)
			local F2 = F1 * CF(b2, 0, 0) * ANG(0, -st.el * 0.8, st.a2)
			for _, sd in ipairs({ 1, -1 }) do
				local function fix(cf) return sd == 1 and cf or mirror(cf) end
				local w1, w2 = get("wb", sd, 1), get("wb", sd, 2)
				if w1 then w1.loc = fix(F0 * CF(b1 / 2, 0, 0) * orient(w1, X, Y)) end
				if w2 then w2.loc = fix(F1 * CF(b2 / 2, 0, 0) * orient(w2, X, Y)) end
				for m = 1, 4 do
					local pe = get("wp", sd, m)
					if pe then
						local x = (m - 0.5) * pw
						local fr, xl
						if x < b1 then fr, xl = F0, x
						elseif x < b1 + b2 then fr, xl = F1, x - b1
						else fr, xl = F2, x - b1 - b2 end
						pe.loc = fix(fr * CF(xl, 0, pl / 2 + lt) * orient(pe, Z, Y))
					end
				end
			end

			-- duoi: 2 bong goc + 5 ladder, vay theo song; mui duoi 2 pallet
			local cft = CF(0, u * 0.02, zs[4])
			for idx = 1, 7 do
				local yawT = st.tailAmp * math.sin(st.tph - idx * 0.55) * (0.3 + idx / 8)
				cft = cft * ANG(st.tpit / 8, yawT, 0)
				if idx <= 2 then
					cft = cft * CF(0, 0, u * 0.8)
					e = get("tp", nil, idx)
					if e then e.loc = cft end
				else
					e = get("tq", nil, idx - 2)
					local step = (e and e.long or lL) * 0.92
					if e then e.loc = cft * CF(0, 0, step / 2) * orient(e, Z, X) end
					cft = cft * CF(0, 0, step)
				end
			end
			for _, sd in ipairs({ 1, -1 }) do
				e = get("tip", sd, 1)
				if e then e.loc = cft * ANG(0, sd * 0.5, 0) * CF(sd * pw * 0.2, 0, pl * 0.5) * orient(e, Z, Y) end
			end
		end

		-- ===== vong lap chinh: di bo / bay / ngam chuot =====
		local function step(dt)
			dt = math.min(dt, 0.1)
			local now = os.clock()
			local t = now - t0
			if now - lastRef > 1 then lastRef = now refresh() end
			local _, rt, hum = L12.Char()
			if lp.Character ~= G.char then
				G.char, G.platform = lp.Character, false
				if S.hide then hideAvatar(true) end
			end
			if hum and not G.platform then hum.PlatformStand = true G.platform = true end

			local fI, tI, uI = axis("back", "fwd"), axis("right", "left"), axis("down", "up")
			G.fire = isDown("fire")
			local vyPrev = G.vy

			-- quay + toc do
			h += tI * S.turn * dt * (G.flying and 0.85 or 1)
			local fw = V(-math.sin(h), 0, -math.cos(h))
			local tgt
			if G.flying then tgt = fI * (fI > 0 and S.fly or S.fly * 0.35)
			else tgt = fI * (fI > 0 and S.walk or S.walk * 0.55) end
			speed += (tgt - speed) * math.min(1, dt * (G.flying and 1.4 or 5))
			local mv = speed * dt
			if math.abs(mv) > 1e-4 then
				local w = workspace:Raycast(pos, fw * (mv > 0 and 1 or -1) * (reach + math.abs(mv)), rp)
				if w and w.Normal.Y < 0.65 then speed, mv = 0, 0 end
			end
			pos += fw * mv

			-- do cao: bay (leo/ha) hoac di bo (bam dat, roi tu do)
			local gy = groundAt(pos)
			local gf, gb = groundAt(pos + fw * probe), groundAt(pos - fw * probe)
			if G.flying then
				G.vy += (uI * S.climb - G.vy) * math.min(1, dt * 3)
				pos = V(pos.X, pos.Y + G.vy * dt, pos.Z)
				if gy and pos.Y < gy + groundOff then
					pos = V(pos.X, gy + groundOff, pos.Z)
					if G.vy < 0 then G.vy = 0 end
					if uI < 0 then G.flying = false end
				end
			elseif gy then
				local want = gy + groundOff
				if pos.Y > want + 0.4 then
					G.vy = math.max(G.vy - 120 * dt, -60)
					pos = V(pos.X, math.max(want, pos.Y + G.vy * dt), pos.Z)
				else
					G.vy = 0
					pos = V(pos.X, pos.Y + (want - pos.Y) * math.min(1, dt * 14), pos.Z)
				end
			else
				G.vy = math.max(G.vy - 120 * dt, -60)
				pos = V(pos.X, pos.Y + G.vy * dt, pos.Z)
			end
			local grounded = (not G.flying) and gy ~= nil and (pos.Y - (gy + groundOff) < 1.2)

			-- cat canh: nhun xuong roi bat len; ha canh: nhun giam chan
			if G.flying and not st.wasFly and st.wasGround then st.dip = u * 0.42 st.burst = 1 end
			if grounded and not st.wasGround and vyPrev < -14 then
				st.dip = math.max(st.dip, math.clamp(-vyPrev / 70, 0.15, 1) * u * 0.5)
			end
			st.wasFly, st.wasGround = G.flying, grounded
			st.dip += (0 - st.dip) * math.min(1, dt * 6.5)
			st.burst += (0 - st.burst) * math.min(1, dt * 1.6)

			-- nghieng than: bay = theo van toc doc + banking; di bo = theo doc nghieng dia hinh
			local pT
			if G.flying then pT = math.clamp(G.vy / 55, -0.75, 0.75) - math.clamp(speed / S.fly, -1, 1) * 0.12
			elseif gf and gb then pT = math.atan2(gf - gb, probe * 2)
			else pT = 0 end
			pitch += (pT - pitch) * math.min(1, dt * 5)
			local rT = G.flying and (tI * 0.55 * math.clamp(0.35 + math.abs(speed) / S.fly, 0, 1)) or 0
			roll += (rT - roll) * math.min(1, dt * 4)

			-- hoat anh
			st.speed = speed
			st.amp = math.clamp(math.abs(speed) / 6, 0, 1) * (1 - st.flyK)
			st.gait += speed * dt / (u * 1.5) * 2 * PI
			st.foldK += ((grounded and 1 or 0) - st.foldK) * math.min(1, dt * (grounded and 3 or 7))
			st.flyK += ((G.flying and 1 or 0) - st.flyK) * math.min(1, dt * 4)
			local fr, am
			if G.flying then
				if G.vy > 6 then fr, am = 2.3, 0.95            -- leo: vo canh manh
				elseif G.vy < -10 then fr, am = 0.6, 0.18      -- luon: dang canh
				elseif math.abs(speed) > 10 then fr, am = 1.5, 0.7
				else fr, am = 1.9, 0.85 end                    -- bay do (hover)
			elseif grounded then fr, am = 0.5, 0.06
			else fr, am = 0.9, 0.35 end                        -- dang roi: xoe canh
			fr += st.burst * 1.3
			am = math.min(1.1, am + st.burst * 0.25)
			st.fr += (fr - st.fr) * math.min(1, dt * 3)
			st.am += (am - st.am) * math.min(1, dt * 4)
			st.ph = (st.ph + dt * 2 * PI * st.fr * S.flap) % (2 * PI)
			local fk = st.foldK
			local A = st.am * (1 - fk)
			st.a0 = (0.18 + A * math.sin(st.ph)) * (1 - fk) + 0.08 * fk
			st.a1 = A * 0.55 * math.sin(st.ph - 0.9)
			st.a2 = A * 0.75 * math.sin(st.ph - 1.8)
			st.sw = 0.2 * (1 - fk) + 1.1 * fk
			st.el = 0.12 * (1 + math.cos(st.ph)) * (1 - fk) + 1.0 * fk
			local sk = math.clamp(math.abs(speed) / math.max(S.walk, 1), 0, 1.5)
			st.tailAmp += ((0.1 + 0.1 * math.min(sk, 1)) - st.tailAmp) * math.min(1, dt * 3)
			st.tph += dt * (2 + 4 * math.min(sk, 1))
			st.tpit += (((G.flying and -0.05 or 0.2) + (G.flying and -G.vy / 400 or 0)) - st.tpit) * math.min(1, dt * 3)
			st.hp += ((G.flying and math.clamp(G.vy / 120, -0.3, 0.3) or 0) - st.hp) * math.min(1, dt * 4)
			st.charge = math.clamp(st.charge + dt * (G.fire and 3.5 or -3), 0, 1)
			st.jaw += (((G.fire and st.charge > 0.7) and 1 or 0) - st.jaw) * math.min(1, dt * 9)
			st.fireK += ((G.fire and 1 or 0) - st.fireK) * math.min(1, dt * 8)

			-- tu the than trong the gioi (khong phu thuoc pose)
			local bob = G.flying and math.sin(t * 2.2) * 0.35 or (math.abs(math.sin(st.gait)) * 0.1 * u * st.amp)
			st.bob = bob
			local H = CF(pos + V(0, bob - st.dip, 0)) * ANG(0, h, 0) * ANG(pitch, 0, roll + math.sin(st.gait) * 0.03 * st.amp)

			-- ngam: chuot (PC) / giua man hinh (mobile) -> diem 3D bang raycast; dau quay toi do
			local cam = workspace.CurrentCamera
			local mx, my = 0, 0
			st.hasA = false
			if cam then
				local vp = cam.ViewportSize
				mx, my = vp.X / 2, vp.Y / 2
				if UIS.MouseEnabled then
					local m = UIS:GetMouseLocation()
					mx, my = m.X, m.Y
				end
				local ray = cam:ViewportPointToRay(mx, my)
				local rr = workspace:Raycast(ray.Origin, ray.Direction * 1500, rp)
				st.A = rr and rr.Position or (ray.Origin + ray.Direction * 500)
				st.hasA = true
			end
			local aimK = G.fire and 1 or (S.look and 0.55 or 0)
			local tyaw, tpit = 0, -0.18
			if st.hasA then
				local dl = H:PointToObjectSpace(st.A) - st.headL
				local hz = math.sqrt(dl.X * dl.X + dl.Z * dl.Z)
				local yT = math.clamp(math.atan2(-dl.X, -dl.Z), -1.45, 1.45)
				local pT2 = math.clamp(math.atan2(dl.Y, math.max(hz, 0.5)), -0.85, 0.95)
				tyaw = yT * aimK
				tpit = pT2 * aimK + (-0.18) * (1 - aimK)
			end
			tyaw += math.sin(t * 0.6) * 0.07 * (1 - aimK)          -- dung yen: dau lia nhe nhu dang canh chung
			tpit += math.sin(t * 0.9 + 1) * 0.04 * (1 - aimK)
			local sm = math.min(1, dt * (G.fire and 14 or 7))
			st.yaw += (tyaw - st.yaw) * sm
			st.pit += (tpit - st.pit) * sm

			pose(t, H)

			-- nguoi lai: nam trong than (an) hoac ngoi tren lung
			if rt then
				local rcf = H * (S.ride and CF(0, u * 0.5 + 3, -u * 0.3) or CF(0, 0, 0))
				if rcf.Position == rcf.Position then
					rt.CFrame = rcf
					rt.AssemblyLinearVelocity = Vector3.zero
					rt.AssemblyAngularVelocity = Vector3.zero
				end
			end

			-- day toy theo tu the (spawn xong 1.4s dau: bay tu tu len cho)
			local k = math.clamp((now - t0) / 1.4, 0, 1)
			local ease = k * k * (3 - 2 * k)
			for i = #ents, 1, -1 do
				local en = ents[i]
				if not en.main.Parent then
					table.remove(ents, i)
				else
					local l = en.static or en.loc
					if l then
						local c = H * l * en.mainOff
						local p = c.Position
						if p == p then
							en.ap.Position = ease < 1 and en.p0:Lerp(p, ease) or p
							en.ao.CFrame = c
						end
					end
				end
			end

			-- diem chay o cho lua cham
			local imp = G.imp
			if imp and imp.part.Parent then
				local hit = st.fireOn and st.hit
				if hit then imp.part.Position = (H * CF(st.impL)).Position end
				imp.fire.Enabled, imp.smoke.Enabled, imp.light.Enabled = hit, hit, hit
			end

			if hud then
				hud.update({
					mode = G.flying and "FLY" or (grounded and "WALK" or "FALL"),
					alt = gy and math.max(0, pos.Y - groundOff - gy) or 0,
					spd = math.abs(speed),
					pts = G.used .. "/" .. S.budget,
					fireK = st.fireK,
					mx = mx, my = my,
				})
			end
		end

		G.ready = true
		hudMsg("READY")
		conn = RunSvc.Heartbeat:Connect(function(dt)
			local ok, err = pcall(step, dt)
			if not ok and not warned then
				warned = true
				warn("[Dragon] " .. tostring(err))
			end
		end)
	end

	local function run(token)
		local function ok() return running and token == session end
		local _, root = L12.Char()
		if not root then return end
		busy, homeCF = true, root.CFrame
		if _G.PlotPlayerIsOwner then
			pcall(RemovePlotOwner)
			local w = 0
			while ok() and _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		end
		if not ok() then return end
		WingsGoToSafeZone()
		local w = 0
		while ok() and not _G.PlotPlayerIsOwner and w < 50 do task.wait(.1) w += 1 end
		if not ok() then return end

		local pl, used = plan()
		G.used = used
		note("Ke hoach: " .. #pl .. " toy, " .. used .. "/" .. S.budget .. " diem plot")
		local i, n, nilSince, fail, ballMiss, noBall = 1, 0, nil, 0, 0, false
		while ok() and i <= #pl and fail < 25 and not (nilSince and os.clock() - nilSince > 8) do
			local _, r = L12.Char()
			if not r then task.wait(.2) continue end
			if noBall and pl[i][1] == "BALL" then i += 1 continue end
			local toy = spawnOne(pl[i][1], ToyKit.SpawnCF(r))
			if toy then
				nilSince, ballMiss = nil, 0
				local e = adopt(toy)
				if e then
					fail, e.d, e.cost = 0, pl[i][2], COST[pl[i][1]]
					ents[#ents + 1] = e
					i, n = i + 1, n + 1
					hudMsg("BUILD " .. n .. "/" .. #pl)
					if n % 40 == 0 then note("Dang spawn: " .. n .. "/" .. #pl) end
				else
					fail += 1
					pcall(function() DeleteToyRE:FireServer(toy) end)
					task.wait(.15)
				end
			else
				if pl[i][1] == "BALL" and not chosen["BALL"] then
					ballMiss += 1
					if ballMiss >= 12 then noBall, nilSince = true, nil note("Khong tim thay toy bong - bo qua cac phan bang bong") end
				else
					nilSince = nilSince or os.clock()
				end
				task.wait(.25)
			end
		end
		if not ok() then return end
		if S.release and _G.PlotPlayerIsOwner then pcall(RemovePlotOwner) end
		if S.goHome and homeCF then
			local back = false
			for _ = 1, 8 do
				TeleportPlayer(homeCF)
				task.wait(.15)
				local _, r = L12.Char()
				if r and (r.Position - homeCF.Position).Magnitude < 10 then back = true break end
			end
			note(back and "Da TP ve cho cu" or "TP ve cho cu that bai - rong van build tai cho cu")
		end
		busy = false
		task.wait(.4)
		if not ok() then return end
		if i <= #pl then note("Plot day: " .. n .. "/" .. #pl .. " toy - lap rap ban rut gon") end
		local okA, err = pcall(assemble, homeCF)
		if not okA then warn("[Dragon] " .. tostring(err)) note("Loi lap rap: " .. tostring(err)) end
	end

	-- ================= UI (tab Toys) =================
	DragonSection:AddToggle({
		Name = "Dragon Mode",
		Default = false,
		Callback = function(on)
			session += 1
			running = on
			clear()
			if not on and busy and homeCF then TeleportPlayer(homeCF) busy = false end
			if on then
				buildHud()
				startInput()
				task.spawn(run, session)
			end
		end,
	})
	DragonSection:AddSlider({ Name = "Walk Speed", Min = 8, Max = 80, Default = S.walk, Increment = 1, ValueName = "studs/s", Callback = function(v) S.walk = v end })
	DragonSection:AddSlider({ Name = "Fly Speed", Min = 20, Max = 220, Default = S.fly, Increment = 5, ValueName = "studs/s", Callback = function(v) S.fly = v end })
	DragonSection:AddSlider({ Name = "Climb Speed", Min = 10, Max = 100, Default = S.climb, Increment = 5, ValueName = "studs/s", Callback = function(v) S.climb = v end })
	DragonSection:AddSlider({ Name = "Turn Speed", Min = 0.5, Max = 4, Default = S.turn, Increment = 0.1, ValueName = "rad/s", Callback = function(v) S.turn = v end })
	DragonSection:AddSlider({ Name = "Wing Flap Speed", Min = 0.4, Max = 2.5, Default = S.flap, Increment = 0.1, ValueName = "x", Callback = function(v) S.flap = v end })
	DragonSection:AddSlider({ Name = "Body Fatness", Min = 0.7, Max = 1.6, Default = S.fat, Increment = 0.05, ValueName = "x", Callback = function(v) S.fat = v end })
	DragonSection:AddSlider({ Name = "Fire Range", Min = 20, Max = 160, Default = S.range, Increment = 5, ValueName = "studs", Callback = function(v) S.range = v end })
	DragonSection:AddSlider({ Name = "Fire Speed", Min = 1, Max = 8, Default = S.rate, Increment = 0.5, ValueName = "out-back/s", Callback = function(v) S.rate = v end })
	DragonSection:AddSlider({ Name = "Point Budget", Min = 100, Max = 600, Default = S.budget, Increment = 5, ValueName = "pts", Callback = function(v) S.budget = v end })
	DragonSection:AddToggle({ Name = "Ride On Back", Default = false, Callback = function(v) S.ride = v end })
	DragonSection:AddToggle({ Name = "Head Follows Mouse", Default = true, Callback = function(v) S.look = v end })
	DragonSection:AddToggle({ Name = "Hide Avatar (local)", Default = true, Callback = function(v) S.hide = v if G.ready then hideAvatar(v) end end })
	DragonSection:AddToggle({ Name = "Dragon HUD", Default = true, Callback = function(v) S.hud = v if hud then hud.gui.Enabled = v end end })
	DragonSection:AddToggle({ Name = "Release Plot When Done", Default = false, Callback = function(v) S.release = v end })
	DragonSection:AddLabel("W/S tien-lui, A/D quay, Space = cat canh/bay len, Shift/C/Q = ha, F = bay/ha canh. Di chuot: dau rong quay theo (mobile: giua man hinh). Giu R = hit hoi roi phun lua toi dung diem chuot. Doi Point Budget thi tat/bat lai. Tong ~580 diem plot (Bong 15, Pallet 5, Ladder 5, Firework 20; budget 600 them lua o mieng)")
end
]=====]

local M = {}

local function decimals(inc)
	if not inc or inc >= 1 then return 0 end
	local s = (string.format("%.4f", inc):gsub("0+$", ""))
	local d = s:match("%.(%d*)$")
	return d and #d or 0
end

function M.Init(ctx)
	assert(type(loadstring) == "function" and type(setfenv) == "function", "Executor khong ho tro loadstring/setfenv")

	local Flags = {}
	local initQueue = {}
	local masterOff = {}

	-- ===== Extras: trang thai dung chung cho cac tinh nang toys (barrier, tra plot) =====
	local Extras = { active = {}, progOff = false, barrierBusy = false }
	ctx.Extras = Extras
	function Extras.Notify(msg, title)
		if ctx.notify then pcall(ctx.notify, msg, title) end
	end
	function Extras.Activate(key) Extras.active[key] = true end
	function Extras.Deactivate(key) Extras.active[key] = nil end
	function Extras.ActiveCount()
		local n = 0
		for _ in pairs(Extras.active) do n += 1 end
		return n
	end
	-- Check barrier da xoa chua; chua thi xoa roi moi cho tao toys. true = barrier da xoa.
	function Extras.EnsureBarrier(alive)
		local t9, t12 = ctx.tbl9, ctx.tbl12
		if t9.IsBarrierBroken then return true end
		-- co luong khac dang xoa barrier: doi no xong (tranh spawn Boombox 2 lan)
		while Extras.barrierBusy do
			task.wait(0.1)
			if alive and not alive() then return false end
			if t9.IsBarrierBroken then return true end
		end
		Extras.barrierBusy = true
		Extras.Notify("Please break the barrier", "Toys")
		local broken = false
		for _ = 1, 4 do
			if alive and not alive() then break end
			pcall(t12.IsBarrierBroken)
			if t9.IsBarrierBroken then
				broken = true
				break
			end
			task.wait(0.5)
		end
		Extras.barrierBusy = false
		if broken then Extras.Notify("Da xoa barrier", "Toys") end
		return broken
	end
	-- BLITZ_CODE ghi de 2 ham nay (can RemovePlotOwner cua no)
	function Extras.ReleaseNow() end
	function Extras.ReleaseLater() end

	local ignore
	pcall(function() ignore = requireModule("SaveManager").Ignore end)

	local function makeProxy(real, map)
		return setmetatable({}, {
			__index = function(_, k)
				if k == "Set" or k == "SetValue" then
					return function(_, v)
						if map and map.toDisplay[v] ~= nil then v = map.toDisplay[v] end
						-- Set(false) tu code (restart/tu dong tat): danh dau de khong xoa plot ngay khi dang restart
						if v == false then Extras.progOff = true end
						pcall(function() real:SetValue(v) end)
						Extras.progOff = false
					end
				elseif k == "Value" then
					local v = real.Value
					if map and map.toName[v] ~= nil then v = map.toName[v] end
					return v
				end
				return real[k]
			end,
		})
	end

	-- Tao 1 groupbox: toggle chinh + DependencyBox chua moi setting (chi hien khi bat)
	local function makeSection(box, key, masterName, blitzName)
		local sec = {}
		local masterCb, masterTaken = nil, false
		if not blitzName then
			-- toggle chinh chi mo setting; tat no thi dung build
			masterCb = function(v)
				if not v then
					local p = Flags.mechmaker_toggle
					if p then p:Set(false) end
				end
			end
		end
		local function id(name, flag)
			return "Bz" .. key .. "_" .. ((flag or name):gsub("[^%w_]", ""))
		end

		local masterId = "Bz" .. key .. "Master"
		if ignore then ignore[masterId] = true end
		local master
		local masterGen, masterOn = 0, false
		master = box:AddToggle(masterId, {
			Text = masterName,
			Default = false,
			Callback = function(v)
				if not masterCb then return end
				masterGen = masterGen + 1
				local gen = masterGen
				if v then
					Extras.Activate(key)
					local function alive()
						return masterGen == gen and master ~= nil and master.Value == true
					end
					-- bat tinh nang: check barrier, chua xoa thi xoa roi moi tao toys
					if not Extras.EnsureBarrier(alive) then
						if alive() then
							Extras.Notify("Please break the barrier - disable " .. masterName, masterName)
							pcall(function() master:SetValue(false) end)
						end
						return
					end
					if not alive() then return end
					masterOn = true
					masterCb(true)
				else
					Extras.Deactivate(key)
					if masterOn then
						masterOn = false
						masterCb(false)
					end
					-- tat tinh nang: xoa plot ngay (restart tu code thi doi 1.5s xem co bat lai khong)
					if Extras.progOff then
						Extras.ReleaseLater()
					else
						task.spawn(Extras.ReleaseNow)
					end
				end
			end,
		})
		local dep = box:AddDependencyBox()
		dep:SetupDependencies({ { master, true } })
		table.insert(masterOff, function()
			if masterCb then pcall(masterCb, false) end
		end)

		function sec:AddToggle(o)
			if blitzName and o.Name == blitzName and not masterTaken then
				masterTaken = true
				masterCb = o.Callback
				local p = makeProxy(master)
				if o.Flag then Flags[o.Flag] = p end
				return p
			end
			local cb = o.Callback
			local def = o.Default and true or false
			local real = dep:AddToggle(id(o.Name, o.Flag), {
				Text = o.Name,
				Default = def,
				Callback = function(v) if cb then cb(v) end end,
			})
			if cb and o.Flag ~= "mechmaker_toggle" then table.insert(initQueue, function() cb(def) end) end
			local p = makeProxy(real)
			if o.Flag then Flags[o.Flag] = p end
			return p
		end

		function sec:AddSlider(o)
			local inc = o.Increment or 1
			local dec = decimals(inc)
			local min, max = o.Min or 0, o.Max or 100
			local def = math.clamp(tonumber(o.Default) or min, min, max)
			local cb = o.Callback
			local function fix(v)
				v = math.floor(v / inc + 0.5) * inc
				return tonumber(string.format("%." .. dec .. "f", v)) or v
			end
			local real = dep:AddSlider(id(o.Name, o.Flag), {
				Text = o.Name,
				Default = def,
				Min = min,
				Max = max,
				Rounding = dec,
				Suffix = o.ValueName and (" " .. o.ValueName) or "",
				Callback = function(v) if cb then cb(fix(v)) end end,
			})
			if cb then table.insert(initQueue, function() cb(fix(def)) end) end
			local p = makeProxy(real)
			if o.Flag then Flags[o.Flag] = p end
			return p
		end

		function sec:AddDropdown(o)
			local values, toName, toDisplay = {}, {}, {}
			for _, opt in ipairs(o.Options or {}) do
				local name, shown
				if type(opt) == "table" then
					name = opt.Name
					shown = opt.FakeName or opt.Name
				else
					name = tostring(opt)
					shown = name
				end
				table.insert(values, shown)
				toName[shown] = name
				toDisplay[name] = shown
			end
			local cb = o.Callback
			local shownDefault = toDisplay[o.Default] or values[1]
			local real = dep:AddDropdown(id(o.Name, o.Flag), {
				Values = values,
				Default = table.find(values, shownDefault) or 1,
				Multi = false,
				Text = o.Name,
				Callback = function(v) if cb then cb(toName[v] or v) end end,
			})
			if cb then table.insert(initQueue, function() cb(toName[shownDefault] or shownDefault) end) end
			local map = { toName = toName, toDisplay = toDisplay }
			local p = makeProxy(real, map)
			if o.Flag then Flags[o.Flag] = p end
			return p
		end

		function sec:AddLabel(text)
			return dep:AddLabel(text, true)
		end

		return sec
	end

	local Toys = ctx.Toys
	-- Muc Extras (tab Toys): Wings / Spider Legs / 666 Star / WOTW (WOW cu)
	-- Extras: moi tinh nang 1 groupbox xep DOC
	local function sec(n, i, k) return makeSection(Toys:AddLeftGroupbox(n, i), k, n, n) end
	local wingsSec, spiderSec = sec("Wings Maker", "bird", "Wings"), sec("Spider Legs", "bug", "Spider")
	local starSec, wotwSec, tankSec = sec("666 Star", "star", "Star666"), sec("WOTW", "bot", "WOTW"), sec("Tank", "shield", "Tank")
	local teslaSec = sec("Tesla Roadster", "car", "Tesla")
	local excSec = sec("Bucket Excavator", "construction", "Excavator")
	local dragonSec = sec("Dragon Mode", "flame", "Dragon")

	pcall(function() if makefolder and isfolder and not isfolder("Resonance") then makefolder("Resonance") end end)

	local result = {
		Folder = "Resonance",
		Flags = setmetatable(Flags, {
			__index = function(_, k)
				if k == "BHouseBarrier" then
					return {
						Value = false,
						Set = function(_, v)
							local tg = ctx.toggles and ctx.toggles.BreakBarrierT
							if tg then tg:SetValue(v) end
						end,
					}
				end
			end,
		}),
		MakeNotification = function(_, o)
			if ctx.notify then ctx.notify(tostring(o.Content or ""), o.Name) end
		end,
	}

	local env = setmetatable({
		__ctx = ctx,
		result = result,
		WingsAuraSection = wingsSec,
		Star666Section = starSec,
		WOTWSection = wotwSec,
		TankSection = tankSec,
		TeslaSection = teslaSec,
		ExcavatorSection = excSec,
		DragonSection = dragonSec,
		Auras_Tab = { AddSection = function() return spiderSec end },
	}, { __index = (getfenv and getfenv()) or _G })

	local chunk, err = loadstring(BLITZ_CODE, "@Resonance/BlitzToys/Core")
	assert(chunk, err)
	setfenv(chunk, env)
	chunk()

	for _, fn in ipairs(initQueue) do
		local ok, e = pcall(fn)
		if not ok then warn("[BlitzToys] init: " .. tostring(e)) end
	end

	local function shutdown()
		for _, off in ipairs(masterOff) do off() end
	end
	if ctx.lib and ctx.lib.OnUnload then
		pcall(function() ctx.lib:OnUnload(shutdown) end)
	end
	return { Shutdown = shutdown }
end

return M
]====]
sources.Bootstrap = [====[
local sources = ...
local env = getgenv and getgenv() or _G
if env.ResonanceRunning or env.ResonanceStarting then
    warn("Resonance is already running or starting")
    return
end
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
local gateInfo = { tester = false, openAll = false, blacklisted = false }
-- ===== Tester gate: loadstring(link tester.lua) -> ten trong do duoc choi; "1001" = mo cho moi nguoi =====
do
    local TESTER_URL = "https://raw.githubusercontent.com/nkhang00012-svg/script/refs/heads/main/tester.lua"
    local KICK_MSG = "BANNED 😂"
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer or Players.PlayerAdded:Wait()
    local body
    for _ = 1, 3 do
        local fetched, res = pcall(function()
            return game:HttpGet(TESTER_URL .. "?t=" .. tostring(os.time()))
        end)
        if fetched and type(res) == "string" and #res > 0 then
            body = res
            break
        end
        task.wait(1)
    end
    if not body then
        warn("Resonance: khong tai duoc tester.lua, script khong chay")
        return
    end
    local me = string.lower(lp.Name)
    local allowAll, isTester, isBlacklisted = false, false, false
    local function markText(text)
        for line in string.gmatch(tostring(text), "[^\r\n]+") do
            line = string.lower(string.match(line, "^%s*(.-)%s*$"))
            line = string.gsub(line, "^@", "")
            if line ~= "" and string.sub(line, 1, 2) ~= "--" and string.sub(line, 1, 1) ~= "#" then
                if string.sub(line, 1, 1) == "!" then
                    -- dong "!ten" trong tester.lua = blacklist
                    if string.gsub(string.sub(line, 2), "^@", "") == me then isBlacklisted = true end
                else
                    if line == "1001" then allowAll = true end
                    if line == me then isTester = true end
                end
            end
        end
    end
    -- 1) tester.lua la code Lua: chay bang loadstring, ket qua tra ve la danh sach
    local fn = loadstring(body, "@Resonance/Tester")
    if fn then
        local ran, res = pcall(fn, lp)
        if not ran then
            warn("Resonance: tester.lua bi loi: " .. tostring(res))
            return
        end
        if type(res) == "table" then
            for k, v in pairs(res) do
                if type(v) == "string" or type(v) == "number" then markText(v) end
                if type(k) == "string" and v == true then markText(k) end -- {hxjxvp = true}
            end
        elseif type(res) == "string" or type(res) == "number" then
            markText(res)
        end
    else
        -- 2) tester.lua la van ban thuong (moi dong 1 ten): doc tu text
        markText(body)
    end
    warn("[Tester] user=" .. lp.Name .. " | tester=" .. tostring(isTester) .. " | openAll(1001)=" .. tostring(allowAll))
    gateInfo.tester, gateInfo.openAll, gateInfo.blacklisted = isTester, allowAll, isBlacklisted
    if isBlacklisted then KICK_MSG = "Bạn đã bị BLACKLIST" end
    if isBlacklisted or not (allowAll or isTester) then
        pcall(function() lp:Kick(KICK_MSG) end)
        task.wait(1)
        pcall(function() game:Shutdown() end) -- du phong neu Kick bi chan
        task.wait(2)
        error(KICK_MSG, 0)
    end
end
-- ===== Nulltrust: don sach lag + intro UI 10s (chay truoc khi vao menu chinh) =====
env.ResonanceStarting = true
do
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local TextService = game:GetService("TextService")
    local ContentProvider = game:GetService("ContentProvider")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local lp = Players.LocalPlayer or Players.PlayerAdded:Wait()

    -- 1) Xoa sach line lag + cac thu gay lag con sot lai
    local function purgeLag()
        pcall(function()
            local ge = ReplicatedStorage:FindFirstChild("GrabEvents")
            local destroyLine = ge and ge:FindFirstChild("DestroyGrabLine")
            local ch = lp.Character
            local root = ch and ch:FindFirstChild("HumanoidRootPart")
            if destroyLine and root then destroyLine:FireServer(root) end
        end)
        pcall(function()
            for _, v in ipairs(workspace:GetChildren()) do
                if v.Name == "GrabParts" then v:Destroy() end
            end
        end)
        pcall(function()
            for _, plr in ipairs(Players:GetPlayers()) do
                local c = plr.Character
                if c then
                    for _, d in ipairs(c:GetDescendants()) do
                        if d.Name == "GrabParts" or d:IsA("Beam") or d:IsA("Trail") then
                            d:Destroy()
                        end
                    end
                end
            end
        end)
        pcall(collectgarbage, "collect")
    end

    -- 2) Intro 10s: o vuong (decal N) -> keo dai (decal Null) -> chu Project NullTrust + bang kiem tra ben phai
    local function playIntro()
        local ID_N    = "rbxassetid://92129311226501" -- decal 1: chu N
        local ID_NULL = "rbxassetid://73708807548743" -- decal 2: Null
        local H       = 120   -- canh o vuong ban dau = chieu cao o sau khi keo
        local W_FINAL = 300   -- chieu rong o sau khi keo dai (chinh theo ti le anh Null)
        local GAP     = 24
        local PLAIN   = "Project NullTrust"
        local TEXT_SIZE = 34

        local INTRO_TOTAL = 10   -- tong thoi gian intro (giay)
        local T_EXPAND    = 1.7  -- luc o bat dau keo dai
        local T_TYPE      = 2.7  -- luc chu bat dau hien
        local T_FADE      = INTRO_TOTAL - 1.3  -- luc UI load bat dau bien mat + o thu lai thanh vuong

        local parentGui = (type(gethui) == "function" and gethui()) or game:GetService("CoreGui")
        pcall(function()
            local old = parentGui:FindFirstChild("NullTrustIntro")
            if old then old:Destroy() end
        end)

        local sg = Instance.new("ScreenGui")
        sg.Name = "NullTrustIntro"
        sg.IgnoreGuiInset = true
        sg.ResetOnSpawn = false
        sg.DisplayOrder = 2147483647
        sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        if type(protectgui) == "function" then pcall(protectgui, sg) end
        sg.Parent = parentGui

        local function tw(obj, t, props, style, dir)
            local tween = TweenService:Create(obj, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
            tween:Play()
            return tween
        end

        local textW = TextService:GetTextSize(PLAIN, TEXT_SIZE, Enum.Font.GothamBold, Vector2.new(1000, 100)).X + 6
        local total = W_FINAL + GAP + textW

        local overlay = Instance.new("Frame")
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.BackgroundColor3 = Color3.new(0, 0, 0)
        overlay.BackgroundTransparency = 1
        overlay.BorderSizePixel = 0
        overlay.Parent = sg

        local row = Instance.new("Frame")
        row.AnchorPoint = Vector2.new(0, 0.5)
        row.Size = UDim2.fromOffset(total, H)
        row.Position = UDim2.new(0.5, -H / 2, 0.5, 0)
        row.BackgroundTransparency = 1
        row.Parent = overlay

        local box = Instance.new("Frame")
        box.AnchorPoint = Vector2.new(0.5, 0.5)
        box.Position = UDim2.fromOffset(H / 2, H / 2)
        box.Size = UDim2.fromOffset(H * 0.6, H * 0.6)
        box.BackgroundColor3 = Color3.fromRGB(14, 14, 22)
        box.BackgroundTransparency = 1
        box.BorderSizePixel = 0
        box.ClipsDescendants = true
        box.Parent = row
        local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(0, 20); corner.Parent = box
        local stroke = Instance.new("UIStroke")
        stroke.Color = Color3.fromRGB(255, 255, 255)
        stroke.Thickness = 2
        stroke.Transparency = 1
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = box

        local function newImage(id, w)
            local img = Instance.new("ImageLabel")
            img.BackgroundTransparency = 1
            img.Image = id
            img.ImageTransparency = 1
            img.ScaleType = Enum.ScaleType.Fit
            img.Size = UDim2.fromOffset(w, H)
            img.Position = UDim2.fromOffset(0, 0)
            img.BorderSizePixel = 0
            img.Parent = box
            return img
        end
        local decalN = newImage(ID_N, H)
        local decalNull = newImage(ID_NULL, W_FINAL)

        local label = Instance.new("TextLabel")
        label.AnchorPoint = Vector2.new(0, 0.5)
        label.Position = UDim2.new(0, W_FINAL + GAP + 16, 0.5, 0)
        label.Size = UDim2.fromOffset(textW, TEXT_SIZE + 12)
        label.BackgroundTransparency = 1
        label.Font = Enum.Font.GothamBold
        label.TextSize = TEXT_SIZE
        label.RichText = false
        label.Text = PLAIN
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextTransparency = 1
        label.MaxVisibleGraphemes = 0
        label.ZIndex = 2
        label.Parent = row

        -- Chu trang sang + bong den chay ben trong kieu lava lamp
        local layers = { { obj = label, dx = 0, dy = 0, hidden = 0 } }
        local shadow = label:Clone()
        shadow.TextColor3 = Color3.new(0, 0, 0)
        shadow.ZIndex = 1
        shadow.Parent = row
        layers[#layers + 1] = { obj = shadow, dx = 2, dy = 3, hidden = 0.55 }

        local blobDefs = {
            { rot = 20,  speed = 0.9,  phase = 0.0, w = 0.16, spin = 25 },
            { rot = -35, speed = 0.65, phase = 1.7, w = 0.2,  spin = 35 },
            { rot = 70,  speed = 1.1,  phase = 3.1, w = 0.13, spin = 20 },
            { rot = 5,   speed = 0.5,  phase = 4.6, w = 0.24, spin = 30 },
        }
        local blobs = {}
        for _, d in ipairs(blobDefs) do
            local b = label:Clone()
            b.TextColor3 = Color3.new(0, 0, 0)
            b.ZIndex = 3
            local g = Instance.new("UIGradient")
            g.Rotation = d.rot
            g.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(math.max(0.01, 0.5 - d.w), 1),
                NumberSequenceKeypoint.new(0.5, 0.02),
                NumberSequenceKeypoint.new(math.min(0.99, 0.5 + d.w), 1),
                NumberSequenceKeypoint.new(1, 1),
            })
            g.Parent = b
            b.Parent = row
            layers[#layers + 1] = { obj = b, dx = 0, dy = 0, hidden = 0 }
            blobs[#blobs + 1] = { grad = g, def = d }
        end
        for _, l in ipairs(layers) do
            l.obj.TextTransparency = 1
            l.obj.MaxVisibleGraphemes = 0
            l.obj.Position = UDim2.new(0, W_FINAL + GAP + 16 + l.dx, 0.5, l.dy)
        end
        local animConn

        -- ===== Bang thong tin load / kiem tra (ben phai) =====
        local COL_OK, COL_BAD, COL_WAIT = Color3.fromRGB(150, 255, 180), Color3.fromRGB(255, 120, 120), Color3.fromRGB(190, 190, 190)
        local PANEL_W, ROW_H = 340, 24
        local fadeItems = {}
        local function addFade(obj, prop, shown)
            obj[prop] = 1
            fadeItems[#fadeItems + 1] = { obj = obj, prop = prop, shown = shown }
        end
        local function fadePanel(toShown, t)
            for _, it in ipairs(fadeItems) do
                tw(it.obj, t, { [it.prop] = toShown and it.shown or 1 }, Enum.EasingStyle.Sine)
            end
        end

        local moduleNames = { "Library", "ThemeManager", "SaveManager", "Icons", "Main", "BlitzToys", "Bootstrap", "Notices" }
        local loaded = false
        local steps = {
            { name = "Loading script", dur = 0.9, run = function()
                local c = 0
                for _ in pairs(sources) do c = c + 1 end
                return c .. " modules", true
            end },
            { name = "Verifying script", dur = 1.0, run = function()
                for _, n in ipairs(moduleNames) do
                    if type(sources[n]) ~= "string" or #sources[n] == 0 then return "missing " .. n, false end
                end
                return "OK", true
            end },
            { name = "Checking executor", dur = 0.8, run = function()
                local okE, nameE = pcall(function()
                    if type(identifyexecutor) == "function" then return (identifyexecutor()) end
                end)
                if okE and type(nameE) == "string" and nameE ~= "" then return string.sub(nameE, 1, 12), true end
                return "Unknown", true
            end },
            { name = "Checking whitelist", dur = 1.1, run = function()
                if gateInfo.tester then return "Whitelisted", true end
                if gateInfo.openAll then return "Open access", true end
                return "Unverified", false
            end },
            { name = "Checking blacklist", dur = 1.0, run = function()
                if gateInfo.blacklisted then return "Blacklisted", false end
                return "Clear", true
            end },
            { name = "Clearing lag", dur = 0.9, run = function()
                purgeLag()
                return "Cleared", true
            end },
            { name = "Loading assets", dur = 0.8, run = function()
                local w = os.clock()
                while not loaded and os.clock() - w < 1.5 do task.wait() end
                if loaded then return "OK", true end
                return "Timeout", false
            end },
            { name = "Preparing menu", dur = 1.0, run = function()
                return "Ready", true
            end },
        }

        local panelH = 40 + #steps * ROW_H + 12 + 6 + 18
        local panel = Instance.new("Frame")
        panel.Size = UDim2.fromOffset(PANEL_W, panelH)
        panel.BackgroundColor3 = Color3.fromRGB(14, 14, 22)
        panel.BorderSizePixel = 0
        panel.Parent = overlay
        local pc = Instance.new("UICorner"); pc.CornerRadius = UDim.new(0, 14); pc.Parent = panel
        local ps = Instance.new("UIStroke")
        ps.Color = Color3.fromRGB(255, 255, 255); ps.Thickness = 2; ps.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        ps.Parent = panel
        addFade(panel, "BackgroundTransparency", 0.4)
        addFade(ps, "Transparency", 0)

        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
        if vp.X >= total + 96 + 2 * PANEL_W then
            panel.AnchorPoint = Vector2.new(1, 0.5)
            panel.Position = UDim2.new(1, -28, 0.5, 0)
        else
            panel.AnchorPoint = Vector2.new(1, 1)
            panel.Position = UDim2.new(1, -12, 1, -12)
            local sc = Instance.new("UIScale"); sc.Scale = 0.7; sc.Parent = panel
        end

        local function newText(parent, text, x, y, w, h, size, font, align)
            local t = Instance.new("TextLabel")
            t.BackgroundTransparency = 1
            t.Position = UDim2.fromOffset(x, y)
            t.Size = UDim2.fromOffset(w, h)
            t.Font = font
            t.TextSize = size
            t.Text = text
            t.TextColor3 = Color3.new(1, 1, 1)
            t.TextXAlignment = align or Enum.TextXAlignment.Left
            t.TextTruncate = Enum.TextTruncate.AtEnd
            t.Parent = parent
            return t
        end

        local header = newText(panel, "NULLTRUST  //  SYSTEM CHECK", 14, 12, PANEL_W - 28, 18, 13, Enum.Font.GothamBold)
        addFade(header, "TextTransparency", 0)

        local rowUi = {}
        for i, st in ipairs(steps) do
            local y = 40 + (i - 1) * ROW_H
            local icon = newText(panel, "[   ]", 14, y, 46, ROW_H, 13, Enum.Font.Code)
            local nm = newText(panel, st.name, 64, y, 150, ROW_H, 13, Enum.Font.Code)
            local rs = newText(panel, "", 214, y, PANEL_W - 214 - 14, ROW_H, 13, Enum.Font.Code, Enum.TextXAlignment.Right)
            icon.TextColor3 = COL_WAIT
            addFade(icon, "TextTransparency", 0)
            addFade(nm, "TextTransparency", 0)
            addFade(rs, "TextTransparency", 0)
            icon.Visible, nm.Visible, rs.Visible = false, false, false
            rowUi[i] = { icon = icon, nm = nm, rs = rs }
        end

        local barY = 40 + #steps * ROW_H + 12
        local track = Instance.new("Frame")
        track.Position = UDim2.fromOffset(14, barY)
        track.Size = UDim2.fromOffset(PANEL_W - 28 - 48, 6)
        track.BorderSizePixel = 0
        track.BackgroundColor3 = Color3.new(1, 1, 1)
        track.Parent = panel
        local tc = Instance.new("UICorner"); tc.CornerRadius = UDim.new(1, 0); tc.Parent = track
        addFade(track, "BackgroundTransparency", 0.8)
        local fill = Instance.new("Frame")
        fill.Size = UDim2.new(0, 0, 1, 0)
        fill.BorderSizePixel = 0
        fill.BackgroundColor3 = Color3.new(1, 1, 1)
        fill.Parent = track
        local fc = Instance.new("UICorner"); fc.CornerRadius = UDim.new(1, 0); fc.Parent = fill
        addFade(fill, "BackgroundTransparency", 0)
        local pct = newText(panel, "0%", PANEL_W - 14 - 44, barY - 8, 44, 22, 13, Enum.Font.Code, Enum.TextXAlignment.Right)
        addFade(pct, "TextTransparency", 0)

        -- tai truoc 2 decal (toi da 1.5s), chay song song
        task.spawn(function()
            pcall(function() ContentProvider:PreloadAsync({ decalN, decalNull }) end)
            loaded = true
        end)
        local tp = os.clock()
        while not loaded and os.clock() - tp < 1.5 do task.wait() end

        local t0 = os.clock()
        local closing = false
        local function at(t)
            local d = t - (os.clock() - t0)
            if d > 0 then task.wait(d) end
        end

        -- Luong bang kiem tra
        task.spawn(function()
            at(0.9)
            if closing then return end
            fadePanel(true, 0.5)
            at(1.3)
            local spin = { "[ | ]", "[ / ]", "[ - ]", "[ \\ ]" }
            for i, st in ipairs(steps) do
                if closing then return end
                local ui = rowUi[i]
                ui.icon.Visible, ui.nm.Visible, ui.rs.Visible = true, true, true
                local started = os.clock()
                local okRun, res, good = pcall(st.run)
                if not okRun then res, good = "error", false end
                local f = 0
                while os.clock() - started < st.dur and not closing do
                    f = f + 1
                    ui.icon.Text = spin[(f % 4) + 1]
                    task.wait(0.08)
                end
                if closing then return end
                ui.icon.Text = good and "[OK ]" or "[ ! ]"
                ui.icon.TextColor3 = good and COL_OK or COL_BAD
                ui.rs.Text = tostring(res)
                ui.rs.TextColor3 = good and COL_OK or COL_BAD
                tw(fill, 0.35, { Size = UDim2.new(i / #steps, 0, 1, 0) })
                pct.Text = math.floor(i / #steps * 100) .. "%"
            end
            header.Text = "NULLTRUST  //  READY"
        end)

        -- Pha 1: hien o vuong + decal N
        tw(overlay, 0.45, { BackgroundTransparency = 0.25 }, Enum.EasingStyle.Sine)
        tw(box, 0.55, { Size = UDim2.fromOffset(H, H), BackgroundTransparency = 0.4 }, Enum.EasingStyle.Back)
        tw(stroke, 0.4, { Transparency = 0 }, Enum.EasingStyle.Sine)
        tw(decalN, 0.45, { ImageTransparency = 0 }, Enum.EasingStyle.Sine)

        -- Pha 2: keo dai o vuong, N chuyen muot thanh Null
        at(T_EXPAND)
        local T = 1.0
        local ease = TweenInfo.new(T, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut)
        TweenService:Create(box, ease, { Size = UDim2.fromOffset(W_FINAL, H), Position = UDim2.fromOffset(W_FINAL / 2, H / 2) }):Play()
        TweenService:Create(row, ease, { Position = UDim2.new(0.5, -total / 2, 0.5, 0) }):Play()
        task.delay(T * 0.12, function()
            tw(decalNull, T * 0.6, { ImageTransparency = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        end)
        task.delay(T * 0.22, function()
            tw(decalN, T * 0.45, { ImageTransparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        end)

        -- Pha 3: chu Project NullTrust (trang sang + bong den lava lamp)
        at(T_TYPE)
        for _, l in ipairs(layers) do
            l.obj.TextTransparency = l.hidden
            tw(l.obj, 0.5, { Position = UDim2.new(0, W_FINAL + GAP + l.dx, 0.5, l.dy) })
        end
        local animStart = os.clock()
        animConn = RunService.RenderStepped:Connect(function()
            local t = os.clock() - animStart
            for _, b in ipairs(blobs) do
                local d = b.def
                b.grad.Offset = Vector2.new(math.sin(t * d.speed + d.phase) * 0.85, math.cos(t * d.speed * 0.7 + d.phase) * 0.1)
                b.grad.Rotation = d.rot + math.sin(t * d.speed * 0.8 + d.phase) * d.spin
            end
        end)
        local n = #PLAIN
        for i = 1, n do
            for _, l in ipairs(layers) do l.obj.MaxVisibleGraphemes = i end
            task.wait(0.7 / n)
        end
        for _, l in ipairs(layers) do l.obj.MaxVisibleGraphemes = -1 end

        -- Pha 4: UI load bien mat -> o keo dai thu lai thanh o VUONG decal 1 (chu N), giu nguyen cho menu chinh phong to ra
        at(T_FADE)
        closing = true
        fadePanel(false, 0.4)
        for _, l in ipairs(layers) do
            tw(l.obj, 0.3, { TextTransparency = 1 }, Enum.EasingStyle.Sine)
        end
        task.delay(0.35, function()
            if animConn then animConn:Disconnect() animConn = nil end
        end)

        -- decal N dung giua o (de o co thu nho van nam chinh giua)
        decalN.AnchorPoint = Vector2.new(0.5, 0.5)
        decalN.Position = UDim2.fromScale(0.5, 0.5)

        local SQ = TweenInfo.new(0.85, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut)
        TweenService:Create(box, SQ, { Size = UDim2.fromOffset(H, H), Position = UDim2.fromOffset(H / 2, H / 2), BackgroundTransparency = 0.15 }):Play()
        TweenService:Create(row, SQ, { Size = UDim2.fromOffset(H, H), Position = UDim2.new(0.5, -H / 2, 0.5, 0) }):Play()
        tw(decalNull, 0.35, { ImageTransparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        task.delay(0.25, function()
            tw(decalN, 0.45, { ImageTransparency = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        end)

        at(INTRO_TOTAL)
        if animConn then animConn:Disconnect() end
        for _, l in ipairs(layers) do pcall(function() l.obj:Destroy() end) end
        pcall(function() panel:Destroy() end)

        -- KHONG destroy sg: giu o vuong lai de Library phong to thanh menu chinh khi menu mo
        env.NullTrustIntroHandoff = {
            sg = sg, overlay = overlay, row = row, box = box,
            stroke = stroke, corner = corner, decalN = decalN,
        }
    end

    -- Anti lag TỨC THÌ (không chờ intro / main UI): tắt script vẽ line + sticky
    local function disableLagScripts()
        pcall(function()
            local ps = lp:FindFirstChild("PlayerScripts")
            if ps then
                for _, n in ipairs({ "CharacterAndBeamMove", "StickyPartsTouchDetection" }) do
                    local s = ps:FindFirstChild(n)
                    if s then s.Enabled = false end
                end
            end
        end)
    end
    env.NullTrustDisableLagScripts = disableLagScripts
    disableLagScripts()
    purgeLag()

    local introActive = true
    env.NullTrustIntroPlaying = true
    task.spawn(function()
        while introActive do
            purgeLag()
            task.wait(0.3)
        end
    end)
    -- Intro chỉ là hiệu ứng: chạy song song để Main load + bật anti ngay,
    -- menu chỉ chờ intro xong mới mở.
    task.spawn(function()
        if not env.NullTrustSkipIntro then
            local okIntro, errIntro = pcall(playIntro)
            if not okIntro then
                warn("NullTrust intro error: " .. tostring(errIntro))
                pcall(function()
                    local g = (type(gethui) == "function" and gethui()) or game:GetService("CoreGui")
                    local old = g:FindFirstChild("NullTrustIntro")
                    if old then old:Destroy() end
                end)
                env.NullTrustIntroHandoff = nil
            end
        end
        introActive = false
        purgeLag()
        env.NullTrustIntroPlaying = false
    end)
end
local cleanup
local function registerCleanup(fn) cleanup = fn end
local cache = {}
local loading = {}
local function requireModule(name)
    if cache[name] then return cache[name] end
    assert(not loading[name], "Circular module dependency: " .. tostring(name))
    assert(type(sources[name]) == "string", "Missing module: " .. tostring(name))
    loading[name] = true
    local chunk, message = loadstring(sources[name], "@Resonance/" .. name)
    assert(chunk, message)
    local ok, result = pcall(chunk, requireModule)
    loading[name] = nil
    assert(ok, result)
    assert(type(result) == "table", "Invalid module: " .. name)
    cache[name] = result
    return result
end
local reloadPath
local ok, result = xpcall(function()
    if type(writefile) == "function" and type(readfile) == "function" then
        local success = pcall(function()
            local lines = {"local sources = {}"}
            for _, name in ipairs({"Library", "ThemeManager", "SaveManager", "Icons", "Main", "BlitzToys", "Bootstrap", "Notices"}) do
                lines[#lines + 1] = string.format("sources[%q] = %q", name, sources[name])
            end
            lines[#lines + 1] = 'local run, message = loadstring(sources.Bootstrap, "@Resonance/Bootstrap"); assert(run, message); return run(sources)'
            writefile("ResonanceRestored.lua", table.concat(lines, "\n"))
            assert(type(readfile("ResonanceRestored.lua")) == "string")
        end)
        if success then reloadPath = "ResonanceRestored.lua" end
    end
    local chunk, message = loadstring(sources.Main, "@Resonance/Main")
    assert(chunk, message)
    return chunk(requireModule, reloadPath, registerCleanup)
end, function(message)
    if debug and debug.traceback then return debug.traceback(tostring(message), 2) end
    return tostring(message)
end)
env.ResonanceStarting = false
do
    -- Neu menu khong mo (loi / AutoShow tat) thi mo mo o vuong roi xoa de khong bi ket tren man hinh
    local function dropHandoff()
        local h = env.NullTrustIntroHandoff
        if not h or h.Consumed then return end
        h.Consumed = true
        env.NullTrustIntroHandoff = nil
        pcall(function()
            local TS = game:GetService("TweenService")
            local ti = TweenInfo.new(0.4, Enum.EasingStyle.Sine)
            TS:Create(h.overlay, ti, { BackgroundTransparency = 1 }):Play()
            TS:Create(h.box, ti, { BackgroundTransparency = 1 }):Play()
            TS:Create(h.stroke, ti, { Transparency = 1 }):Play()
            TS:Create(h.decalN, ti, { ImageTransparency = 1 }):Play()
        end)
        task.delay(0.5, function() pcall(function() h.sg:Destroy() end) end)
    end
    if not ok then dropHandoff() else task.delay(8, dropHandoff) end
end
if not ok then
    pcall(function()
        local ps = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerScripts")
        for _, n in ipairs({ "CharacterAndBeamMove", "StickyPartsTouchDetection" }) do
            local s = ps and ps:FindFirstChild(n)
            if s then s.Enabled = true end
        end
    end)
    if cleanup then pcall(cleanup) end
    env.ResonanceRunning = false
    warn("Resonance initialization failed: " .. tostring(result))
    return nil, result
end
return result
]====]
